insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-o-et-l') and slug = 'le-son-l'), $html$<p>Écoute bien : on entend le son <strong>[l]</strong> dans « lune », « lait », « ballon », « Lamine ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>l · L</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>la · li · lo · al · il · ol</strong></p><p>Des mots : <strong>la · lit · lot · Lola · Lili</strong></p><p>Une phrase : <strong>Lola a le lit de tata.</strong></p><h2>J’écris</h2><p>Je trace une grande boucle qui monte, puis redescend : l.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [l].</li><li>Cherche [l] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
