insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-p-d-m-et-b') and slug = 'le-son-b'), $html$<p>Écoute bien : on entend le son <strong>[b]</strong> dans « ballon », « bébé », « baobab », « Binta ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>b · B</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ba · bi · bo · be · ab · ob</strong></p><p>Des mots : <strong>bol · bobo · Babi · lobe</strong></p><p>Une phrase : <strong>Babi a le bol de papa.</strong></p><h2>J’écris</h2><p>Je trace un grand trait qui monte haut, puis un rond en bas, à droite : b.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [b].</li><li>Cherche [b] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div><div class="callout"><p class="callout-title">Je retiens</p><p><strong>b</strong> a son rond en bas à droite, <strong>d</strong> en bas à gauche, <strong>p</strong> a son trait sous la ligne.</p></div>$html$);
