insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-present-de-l-indicatif') and slug = 'les-verbes-du-1er-groupe-au-present'), $html$<p>Les verbes du 1<sup>er</sup> groupe se terminent par <strong>-er</strong> à l’infinitif : jouer, chanter, danser.</p>
