insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-present-de-l-indicatif') and slug = 'les-verbes-etre-et-avoir-au-present'), $html$<table><thead><tr><th scope="col">être</th><th scope="col">avoir</th></tr></thead><tbody><tr><td>je suis</td><td>j’ai</td></tr><tr><td>tu es</td><td>tu as</td></tr><tr><td>il est</td><td>il a</td></tr><tr><td>nous sommes</td><td>nous avons</td></tr><tr><td>vous êtes</td><td>vous avez</td></tr><tr><td>ils sont</td><td>ils ont</td></tr></tbody></table>
