insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-passe-compose') and slug = 'le-passe-compose'), $html$<p>Le <strong>passé composé</strong> sert à raconter ce qui est déjà fait. Il se forme avec <strong>avoir</strong> (ou être) au présent et le <strong>participe passé</strong> du verbe.</p>
