insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-imperatif-et-le-futur-simple') and slug = 'l-imperatif-present-et-le-futur-simple'), $html$<p>L’<strong>impératif</strong> sert à donner un ordre : il a trois personnes et pas de sujet. Le <strong>futur</strong> dit ce qui se passera plus tard.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null), 12, 'ponctuation-et-accords', 'Ponctuation et accords', 'La ponctuation, l’accord du verbe avec son sujet, les lettres finales muettes.', 12, 'published', 'Orthographe', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
