insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'ponctuation-et-accords') and slug = 'la-ponctuation-et-l-accord-du-verbe'), $html$<ul><li>Le point (.) termine une phrase ; le point d’interrogation (?) une question ; le point d’exclamation (!) un cri ou une émotion.</li><li>La virgule (,) sépare des mots dans une liste.</li><li>Le verbe s’accorde avec son sujet : il joue, ils jouent.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null), 13, 'les-homophones-et-le-feminin-des-adjectifs', 'Les homophones et le féminin des adjectifs', 'Distinguer a et à, et et est ; écrire le féminin des adjectifs ; écrire sous la dictée.', 13, 'published', 'Orthographe', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-homophones-et-le-feminin-des-adjectifs'), 1, 'a-ou-a-et-ou-est', 'a ou à ? et ou est ?', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-homophones-et-le-feminin-des-adjectifs') and slug = 'a-ou-a-et-ou-est'), $html$<table><thead><tr><th scope="col">Mot</th><th scope="col">Astuce</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>a (verbe avoir)</td><td>je peux dire « avait »</td><td>Il a un vélo.</td></tr><tr><td>à</td><td>je ne peux pas dire « avait »</td><td>Il va à l’école.</td></tr><tr><td>est (verbe être)</td><td>je peux dire « était »</td><td>Le ciel est bleu.</td></tr><tr><td>et</td><td>je peux dire « et puis »</td><td>Awa et Fatou jouent.</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-homophones-et-le-feminin-des-adjectifs'), 2, 'le-feminin-des-adjectifs', 'Le féminin des adjectifs', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-homophones-et-le-feminin-des-adjectifs') and slug = 'le-feminin-des-adjectifs'), $html$<ul><li>En général, on ajoute « e » : petit → petite, joli → jolie.</li><li>Si l’adjectif finit déjà par « e », il ne change pas : un mouton maigre, une chèvre maigre.</li></ul>
