insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE1' and p.series_id is null) and c.slug = 'ecrire-des-textes') and slug = 'ecrire-un-petit-texte'), $html$<ul><li>Je réfléchis : qu’est-ce que je veux raconter, décrire ou expliquer ?</li><li>J’écris un premier jet.</li><li>Je relis avec la fiche de vérification : majuscules, points, accords, mots du temps ou de lieu.</li><li>Je recopie proprement.</li></ul>
