insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-nombres-jusqu-a-500') and slug = 'lire-ecrire-et-decomposer-les-nombres-jusqu-a-500'), $html$<p>Un nombre de trois chiffres a des <strong>centaines</strong>, des <strong>dizaines</strong> et des <strong>unités</strong>.</p>
