insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-nombres-jusqu-a-500') and slug = 'pairs-impairs-double-et-moitie'), $html$<ul><li>Un nombre <strong>pair</strong> se termine par 0, 2, 4, 6 ou 8 : on peut le partager en deux parts égales.</li><li>Un nombre <strong>impair</strong> se termine par 1, 3, 5, 7 ou 9.</li><li>Le <strong>double</strong> de 12 est 24 (12 + 12) ; la <strong>moitié</strong> de 24 est 12.</li></ul>
