insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'la-multiplication') and slug = 'multiplier-un-nombre'), $html$<ul><li>Je multiplie d’abord les unités, puis les dizaines, puis les centaines.</li><li>Si un produit dépasse 9, j’écris les unités et je retiens les dizaines.</li><li>Avec deux chiffres au multiplicateur, je fais deux lignes, la deuxième décalée d’un rang (0).</li></ul>
