insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'la-division') and slug = 'partager-la-division'), $html$<p>Diviser, c’est <strong>partager en parts égales</strong>. 12 ÷ 3 = 4 : 12 mangues partagées entre 3 enfants, chacun en a 4.</p>
