insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'la-division') and slug = 'les-nombres-divisibles-par-2-et-par-5'), $html$<ul><li>Un nombre est divisible par 2 s’il est pair (il se termine par 0, 2, 4, 6, 8).</li><li>Un nombre est divisible par 5 s’il se termine par 0 ou 5.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null), 8, 'lignes-et-droites', 'Lignes et droites', 'Lignes droites, brisées et courbes ; droites horizontales, verticales et obliques ; droites sécantes, perpendiculaires et parallèles ; l’angle droit.', 8, 'published', 'Activités géométriques', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Cahier d’exercices de mathématiques CE1, PAAME (MEN, édition 2024, conforme au CEB)","url":"https://senprof.education.sn/PAAME/","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'lignes-et-droites'), 1, 'lignes-droites-brisees-et-courbes', 'Lignes droites, brisées et courbes', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'lignes-et-droites') and slug = 'lignes-droites-brisees-et-courbes'), $html$<ul><li>Une ligne <strong>droite</strong> se trace avec la règle.</li><li>Une ligne <strong>brisée</strong> est faite de plusieurs segments droits.</li><li>Une ligne <strong>courbe</strong> n’a pas de partie droite.</li><li>Une droite <strong>horizontale</strong> est couchée, une droite <strong>verticale</strong> est debout (comme le fil à plomb), une droite <strong>oblique</strong> est penchée.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'lignes-et-droites'), 2, 'droites-secantes-perpendiculaires-et-paralleles', 'Droites sécantes, perpendiculaires et parallèles', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'lignes-et-droites') and slug = 'droites-secantes-perpendiculaires-et-paralleles'), $html$<ul><li>Deux droites <strong>sécantes</strong> se coupent en un point.</li><li>Deux droites <strong>perpendiculaires</strong> se coupent en formant un <strong>angle droit</strong> (on le vérifie avec l’équerre).</li><li>Deux droites <strong>parallèles</strong> ne se coupent jamais, même si on les prolonge : elles restent toujours à la même distance.</li></ul>
