insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-carre-et-le-rectangle') and slug = 'le-carre-et-le-rectangle'), $html$<table><thead><tr><th scope="col">Figure</th><th scope="col">Côtés</th><th scope="col">Angles</th></tr></thead><tbody><tr><td>carré</td><td>4 côtés de même longueur</td><td>4 angles droits</td></tr><tr><td>rectangle</td><td>2 grands côtés égaux (longueurs) et 2 petits côtés égaux (largeurs)</td><td>4 angles droits</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-carre-et-le-rectangle'), 2, 'diagonales-et-medianes', 'Diagonales et médianes', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-carre-et-le-rectangle') and slug = 'diagonales-et-medianes'), $html$<ul><li>Les <strong>diagonales</strong> relient deux sommets opposés. Dans un carré et dans un rectangle, elles ont la même longueur et se coupent en leur milieu.</li><li>Les <strong>médianes</strong> relient les milieux de deux côtés opposés.</li></ul>
