insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-etres-vivants-respirent') and slug = 'respirer'), $html$<ul><li>L’homme et beaucoup d’animaux respirent par le nez : l’air va dans les poumons.</li><li>Le poisson respire dans l’eau grâce à ses branchies.</li><li>La plante respire aussi, par ses feuilles.</li></ul>
