insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-produits-et-les-objets-de-la-maison'), 1, 'combustibles-et-produits-courants', 'Combustibles et produits courants', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-produits-et-les-objets-de-la-maison') and slug = 'combustibles-et-produits-courants'), $html$<ul><li>Les <strong>combustibles</strong> brûlent et donnent de la chaleur : bois, charbon de bois, gaz, pétrole, essence. Ils sont dangereux près du feu.</li><li>Produits courants : l’eau mouille et dissout le sucre ; l’huile ne se mélange pas à l’eau ; le coton absorbe l’eau ; le plastique est imperméable.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-produits-et-les-objets-de-la-maison'), 2, 'utiliser-et-entretenir-des-objets-simples', 'Utiliser et entretenir des objets simples', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'les-produits-et-les-objets-de-la-maison') and slug = 'utiliser-et-entretenir-des-objets-simples'), $html$<ul><li>Lampe de poche : on met les piles dans le bon sens et on l’éteint après usage.</li><li>Foyer amélioré : il consomme moins de bois que le foyer traditionnel.</li><li>Fer à repasser, radio, thermomètre, montre : on les utilise avec soin et on les nettoie.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null), 13, 'l-eau-potable', 'L’eau potable', 'S’approvisionner en eau potable, la protéger, la purifier et l’économiser.', 13, 'published', 'Vivre dans son milieu', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-eau-potable'), 1, 'avoir-de-l-eau-propre-et-l-economiser', 'Avoir de l’eau propre et l’économiser', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-eau-potable') and slug = 'avoir-de-l-eau-propre-et-l-economiser'), $html$<ul><li>L’eau potable vient du robinet, du forage ou d’un puits protégé.</li><li>Je la transporte et la conserve dans des récipients propres et couverts.</li><li>Pour purifier l’eau : la laisser reposer (décantation), la filtrer, ajouter quelques gouttes d’eau de Javel.</li><li>J’économise l’eau : je ferme bien le robinet, je signale les fuites.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null), 14, 'l-hygiene-et-l-alimentation', 'L’hygiène et l’alimentation', 'Hygiène du corps, des vêtements, de la classe et de la maison ; ordures et eaux usées ; manger sainement.', 14, 'published', 'Vivre dans son milieu', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-hygiene-et-l-alimentation'), 1, 'etre-propre-et-garder-son-milieu-propre', 'Être propre et garder son milieu propre', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-hygiene-et-l-alimentation') and slug = 'etre-propre-et-garder-son-milieu-propre'), $html$<ul><li>Je me lave tous les jours, je me brosse les dents, je coupe mes ongles.</li><li>Je me lave les mains avec du savon avant de manger et après les toilettes.</li><li>Je jette les ordures dans la poubelle ; on ne jette pas les eaux usées dans la rue.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-hygiene-et-l-alimentation'), 2, 'manger-sainement', 'Manger sainement', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'l-hygiene-et-l-alimentation') and slug = 'manger-sainement'), $html$<ul><li>Des aliments pour avoir de l’énergie : mil, riz, maïs.</li><li>Des aliments pour grandir : poisson, viande, œufs, lait, niébé.</li><li>Des aliments pour se protéger des maladies : fruits et légumes.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null), 15, 'proteger-l-environnement', 'Protéger l’environnement', 'Les formes de dégradation du milieu proche et les moyens simples de le restaurer et de le sauvegarder.', 15, 'published', 'Vivre dans son milieu', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'proteger-l-environnement'), 1, 'proteger-notre-milieu', 'Protéger notre milieu', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'proteger-l-environnement') and slug = 'proteger-notre-milieu'), $html$<ul><li>Formes de dégradation : arbres coupés, sol emporté par le vent ou l’eau, feux de brousse, ordures, tables cassées.</li><li>Ce qu’on peut faire : planter et arroser des arbres, ramasser les ordures, entretenir les toilettes et le mobilier de l’école.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null), 16, 'respecter-les-autres', 'Respecter les autres', 'Règles de politesse et de bon voisinage, respect des plus faibles et des adultes.', 16, 'published', 'Vivre ensemble', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'respecter-les-autres'), 1, 'la-politesse-et-le-respect', 'La politesse et le respect', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'respecter-les-autres') and slug = 'la-politesse-et-le-respect'), $html$<ul><li>Je dis bonjour, s’il vous plaît, merci, pardon.</li><li>Je cède ma place à une personne âgée, j’aide un camarade handicapé.</li><li>Je respecte le repos des voisins et je n’insulte personne.</li><li>J’obéis à mes parents, à mes maîtres et aux adultes.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null), 17, 'le-civisme', 'Le civisme', 'Respecter les symboles de la Nation, les forces de l’ordre, les autorités et les règlements.', 17, 'published', 'Vivre ensemble', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-civisme'), 1, 'respecter-les-symboles-de-la-nation-et-les-regles', 'Respecter les symboles de la Nation et les règles', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'le-civisme') and slug = 'respecter-les-symboles-de-la-nation-et-les-regles'), $html$<ul><li>Les symboles : le drapeau vert, or, rouge avec une étoile verte ; l’hymne national ; la devise « Un Peuple – Un But – Une Foi » ; la fête de l’indépendance le 4 avril.</li><li>Les forces de l’ordre nous protègent : policier, gendarme, sapeur-pompier, militaire.</li><li>Je respecte le règlement de l’école et le code de la route.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null), 18, 'respecter-les-differences', 'Respecter les différences', 'Respecter les garçons et les filles, les personnes handicapées, les opinions et les cultures des autres.', 18, 'published', 'Vivre ensemble', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'respecter-les-differences'), 1, 'nous-sommes-tous-differents', 'Nous sommes tous différents', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE1' and p.series_id is null) and c.slug = 'respecter-les-differences') and slug = 'nous-sommes-tous-differents'), $html$<ul><li>Garçons et filles ont les mêmes droits : aller à l’école, jouer, être respectés.</li><li>On ne se moque pas de quelqu’un parce qu’il est petit, malade, handicapé ou pauvre.</li><li>Au Sénégal, des personnes d’ethnies et de religions différentes vivent ensemble dans la paix.</li><li>Chacun a le droit de donner son avis.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null), 1, 'prendre-la-parole', 'Prendre la parole', 'Raconter, décrire, expliquer et échanger à l’oral avec les bons mots et les bons gestes.', 1, 'published', 'Communication orale', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null) and c.slug = 'prendre-la-parole'), 1, 'bien-parler-devant-les-autres', 'Bien parler devant les autres', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null) and c.slug = 'prendre-la-parole') and slug = 'bien-parler-devant-les-autres'), $html$<ul><li>Je prépare ce que je vais dire et je l’organise : début, milieu, fin.</li><li>Je parle fort, lentement, en regardant mon public.</li><li>Mes gestes et mon visage accompagnent ce que je dis.</li><li>J’écoute les questions et j’y réponds poliment.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null), 2, 'recits-descriptions-et-consignes', 'Récits, descriptions et consignes', 'Consolider la lecture des textes narratifs, descriptifs et injonctifs étudiés au CE1.', 2, 'published', 'Lecture', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
