insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null) and c.slug = 'recits-descriptions-et-consignes') and slug = 'reconnaitre-le-type-d-un-texte'), $html$<table><thead><tr><th scope="col">Type</th><th scope="col">Il sert à…</th><th scope="col">Je reconnais…</th></tr></thead><tbody><tr><td>narratif</td><td>raconter</td><td>des personnages, des événements, des mots du temps</td></tr><tr><td>descriptif</td><td>faire voir</td><td>des adjectifs, des mots de lieu, des comparaisons</td></tr><tr><td>injonctif</td><td>faire agir</td><td>des étapes, l’impératif ou l’infinitif</td></tr></tbody></table>
