insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null) and c.slug = 'la-phrase-nominale-et-les-articles') and slug = 'phrase-nominale-articles-definis-et-indefinis'), $html$<ul><li>Une <strong>phrase nominale</strong> n’a pas de verbe : « Fermeture de l’école à midi. »</li><li>Articles <strong>définis</strong> (quelque chose de connu) : le, la, l’, les.</li><li>Articles <strong>indéfinis</strong> (quelque chose de non précisé) : un, une, des.</li></ul>
