insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-dictionnaire-et-les-mots') and slug = 'synonymes-homonymes-et-familles-de-mots'), $html$<ul><li><strong>Synonymes</strong> : mots de sens proche (content, joyeux).</li><li><strong>Homonymes</strong> : mots qui se prononcent pareil mais n’ont pas le même sens (verre, vert, ver).</li><li><strong>Famille de mots</strong> : mots formés à partir du même mot (terre, terrain, enterrer).</li><li><strong>Expressions imagées</strong> : noir comme du charbon, dur comme du fer, avoir une faim de loup.</li></ul>
