insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CE2' and p.series_id is null) and c.slug = 'ecrire-une-lettre-une-affiche-et-un-poeme') and slug = 'ecrire-relire-reecrire'), $html$<ul><li>Je lis bien la consigne : qu’est-ce que je dois écrire et pour qui ?</li><li>J’écris un premier jet en suivant la fiche de critères (éléments de la lettre, de l’affiche ou du poème).</li><li>Je relis : sens, ponctuation, accords, orthographe.</li><li>Je réécris au propre et je lis mon texte à la classe.</li></ul>
