insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE2' and p.series_id is null) and c.slug = 'la-multiplication') and slug = 'multiplier-par-un-ou-deux-chiffres'), $html$<ul><li>Multiplier par 10, 100, 1 000 : on ajoute 1, 2 ou 3 zéros (24 × 100 = 2 400).</li><li>Multiplier par 25 : 12 × 25 = 300.</li><li>Avec deux chiffres au multiplicateur : 1 245 × 23 = 1 245 × 3 + 1 245 × 20 = 3 735 + 24 900 = 28 635.</li></ul>
