insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE2' and p.series_id is null) and c.slug = 'la-division') and slug = 'diviser-de-grands-nombres'), $html$<ul><li>Je cherche combien de fois le diviseur est contenu dans les premiers chiffres du dividende.</li><li>Je multiplie, je soustrais, j’abaisse le chiffre suivant.</li><li>Je vérifie : diviseur × quotient + reste = dividende.</li></ul>
