insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE2' and p.series_id is null) and c.slug = 'donnees-et-questions-d-un-probleme') and slug = 'lire-et-organiser-un-probleme'), $html$<ul><li>Je lis l’énoncé deux fois.</li><li>Je souligne les données utiles et je barre les données inutiles.</li><li>Je cherche s’il manque une donnée.</li><li>Je repère la question finale et les questions intermédiaires.</li></ul>
