insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CE2' and p.series_id is null) and c.slug = 'demarche-et-enonce-d-un-probleme') and slug = 'resoudre-pas-a-pas-et-inventer-un-enonce'), $html$<ul><li>Démarche progressive : je pars des données et je calcule étape par étape jusqu’à la question finale.</li><li>Pour inventer un énoncé, je choisis une situation (marché, école), des données et une question.</li></ul>
