insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'l-idee-de-progres') and slug = 'les-progres-de-l-homme'), $html$<table><thead><tr><th scope="col">Autrefois</th><th scope="col">Aujourd’hui</th></tr></thead><tbody><tr><td>chasse, pêche et cueillette pour se nourrir</td><td>agriculture, élevage, pêche avec des moteurs</td></tr><tr><td>outils en pierre, puis en fer</td><td>machines, tracteurs</td></tr><tr><td>feu de bois pour cuire et s’éclairer</td><td>gaz, électricité, panneaux solaires</td></tr><tr><td>cases en paille</td><td>maisons en ciment</td></tr><tr><td>guérisseurs et plantes</td><td>hôpitaux et médicaments (et toujours certaines plantes)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 2, 'faits-et-personnages-de-l-histoire-locale', 'Faits et personnages de l’histoire locale', 'Les événements marquants et les personnages célèbres de sa localité dans l’histoire des royaumes du Sénégal.', 2, 'published', 'Histoire', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'faits-et-personnages-de-l-histoire-locale'), 1, 'l-histoire-de-ma-localite', 'L’histoire de ma localité', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'faits-et-personnages-de-l-histoire-locale') and slug = 'l-histoire-de-ma-localite'), $html$<ul><li>Événements marquants : batailles, fondation de villages, sécheresses, épidémies, années de famine ou d’abondance.</li><li>Personnages marquants : rois et reines, chefs religieux et coutumiers, résistants, héros de la localité.</li><li>Exemples : Lat Dior au Cayor, la reine Ndatté Yalla au Walo, Aline Sitoé Diatta en Casamance, El Hadji Omar dans le Fouta.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 3, 'les-royaumes-du-senegal-d-autrefois', 'Les royaumes du Sénégal d’autrefois', 'Royaume et empire ; les principaux royaumes du Sénégal sur la carte.', 3, 'published', 'Histoire', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-royaumes-du-senegal-d-autrefois'), 1, 'royaumes-et-empires', 'Royaumes et empires', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-royaumes-du-senegal-d-autrefois') and slug = 'royaumes-et-empires'), $html$<ul><li>Un <strong>royaume</strong> est un territoire dirigé par un roi ; des chefs lui doivent obéissance (vassalité).</li><li>Un <strong>empire</strong> est plus grand : il domine plusieurs royaumes.</li><li>Principaux royaumes : Tékrour, Fouta, Djolof, Cayor, Baol, Walo, Sine, Saloum, Niani, Gabou, royaumes de Casamance, et la « république » lébou du Cap-Vert.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 4, 'le-djolof-le-gabou-et-les-royaumes-successeurs', 'Le Djolof, le Gabou et les royaumes successeurs', 'L’organisation politique, sociale et économique du Djolof et de ses successeurs, du Gabou et des royaumes du sud.', 4, 'published', 'Histoire', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-djolof-le-gabou-et-les-royaumes-successeurs'), 1, 'du-grand-djolof-aux-royaumes-du-cayor-du-baol-du-walo-du-sine-et-du-saloum', 'Du grand Djolof aux royaumes du Cayor, du Baol, du Walo, du Sine et du Saloum', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-djolof-le-gabou-et-les-royaumes-successeurs') and slug = 'du-grand-djolof-aux-royaumes-du-cayor-du-baol-du-walo-du-sine-et-du-saloum'), $html$<ul><li>Le Djolof, fondé par Ndiadiane Ndiaye, réunissait plusieurs royaumes. Son roi était le Bourba.</li><li>Après la bataille de Danki (XVI<sup>e</sup> siècle), le Cayor devient indépendant, puis d’autres royaumes s’en séparent.</li><li>Rois : damel au Cayor, teigne au Baol, brak au Walo, bour au Sine et au Saloum.</li><li>Économie : agriculture (mil), élevage, artisanat, commerce.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-djolof-le-gabou-et-les-royaumes-successeurs'), 2, 'le-gabou-et-les-royaumes-du-sud-et-de-l-est', 'Le Gabou et les royaumes du sud et de l’est', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-djolof-le-gabou-et-les-royaumes-successeurs') and slug = 'le-gabou-et-les-royaumes-du-sud-et-de-l-est'), $html$<ul><li>Le <strong>Gabou</strong>, royaume mandingue, dirigé par un mansa, s’étendait vers la Guinée-Bissau.</li><li>Au sud : les royaumes diolas de Casamance, organisés autour des villages et des rois-prêtres.</li><li>À l’est : les royaumes mandingues et peuls, le Boundou.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 5, 's-orienter-et-lire-une-carte', 'S’orienter et lire une carte', 'Les moyens de s’orienter ; limites, légende et signes conventionnels d’un plan ou d’une carte.', 5, 'published', 'Géographie', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 's-orienter-et-lire-une-carte'), 1, 'lire-une-carte', 'Lire une carte', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 's-orienter-et-lire-une-carte') and slug = 'lire-une-carte'), $html$<ul><li>Une carte représente un territoire vu de dessus, en plus petit.</li><li>Le nord est en haut de la carte.</li><li>La <strong>légende</strong> explique les couleurs et les signes : bleu pour l’eau, points pour les villes, traits pour les routes ou les frontières.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 6, 'ma-region-relief-eau-climat-et-vegetation', 'Ma région : relief, eau, climat et végétation', 'Les caractéristiques physiques de sa région.', 6, 'published', 'Géographie', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'ma-region-relief-eau-climat-et-vegetation'), 1, 'le-milieu-physique-de-ma-region', 'Le milieu physique de ma région', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'ma-region-relief-eau-climat-et-vegetation') and slug = 'le-milieu-physique-de-ma-region'), $html$<table><thead><tr><th scope="col">Élément</th><th scope="col">Ce que j’observe</th></tr></thead><tbody><tr><td>relief</td><td>plaine, plateau, dunes, collines, vallée</td></tr><tr><td>eau</td><td>fleuve, rivière, marigot, lac, mer</td></tr><tr><td>climat</td><td>quantité de pluie, vents, température</td></tr><tr><td>végétation</td><td>steppe au nord, savane au centre, forêt au sud, mangrove près de la mer</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 7, 'les-activites-et-la-vie-des-hommes', 'Les activités et la vie des hommes', 'Agriculture, élevage, pêche, tourisme ; mouvements des populations et types d’habitat.', 7, 'published', 'Géographie', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-activites-et-la-vie-des-hommes'), 1, 'agriculture-elevage-peche-et-tourisme', 'Agriculture, élevage, pêche et tourisme', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-activites-et-la-vie-des-hommes') and slug = 'agriculture-elevage-peche-et-tourisme'), $html$<table><thead><tr><th scope="col">Activité</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>agriculture</td><td>cultures vivrières (mil, riz, maïs, niébé) et industrielles (arachide, coton) ; techniques traditionnelles (hilaire, daba) ou modernes (tracteur)</td></tr><tr><td>élevage</td><td>bovins, ovins, caprins, chevaux, ânes ; transhumance et embouche</td></tr><tr><td>pêche</td><td>artisanale en pirogue ou industrielle ; ligne, filet, nasse</td></tr><tr><td>tourisme</td><td>plages, parcs (Niokolo-Koba), culture ; hôtels et campements</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-activites-et-la-vie-des-hommes'), 2, 'les-mouvements-de-population-et-l-habitat', 'Les mouvements de population et l’habitat', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-activites-et-la-vie-des-hommes') and slug = 'les-mouvements-de-population-et-l-habitat'), $html$<ul><li><strong>Exode rural</strong> : des jeunes quittent les villages pour la ville.</li><li><strong>Transhumance</strong> : les éleveurs se déplacent avec leurs troupeaux à la recherche de pâturages.</li><li>Types d’habitat : case, maison en dur, villa, immeuble, mais aussi baraques et bidonvilles.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 8, 'le-corps-humain', 'Le corps humain', 'Organisation du corps, les cinq sens, la peau, le squelette, les muscles, la croissance.', 8, 'published', 'Initiation scientifique et technologique', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-corps-humain'), 1, 'les-cinq-sens-et-la-peau', 'Les cinq sens et la peau', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-corps-humain') and slug = 'les-cinq-sens-et-la-peau'), $html$<table><thead><tr><th scope="col">Sens</th><th scope="col">Organe</th><th scope="col">Hygiène</th></tr></thead><tbody><tr><td>la vue</td><td>les yeux</td><td>ne pas fixer le soleil, lire à la lumière</td></tr><tr><td>l’ouïe</td><td>les oreilles</td><td>pas de bruit trop fort, pas d’objet pointu</td></tr><tr><td>l’odorat</td><td>le nez</td><td>se moucher</td></tr><tr><td>le goût</td><td>la langue</td><td>se brosser les dents</td></tr><tr><td>le toucher</td><td>la peau</td><td>se laver, se protéger du soleil</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-corps-humain'), 2, 'le-squelette-les-muscles-et-la-croissance', 'Le squelette, les muscles et la croissance', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'le-corps-humain') and slug = 'le-squelette-les-muscles-et-la-croissance'), $html$<ul><li>Le <strong>squelette</strong> soutient le corps ; les <strong>articulations</strong> (coude, genou) permettent de plier.</li><li>Les <strong>muscles</strong> font bouger les os.</li><li>L’enfant grandit : sa taille et son poids augmentent. Le bébé rampe, puis marche à quatre pattes, puis se tient debout.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 9, 'les-animaux', 'Les animaux', 'Organisation du corps de quelques animaux, leur utilité et leur mode de vie.', 9, 'published', 'Initiation scientifique et technologique', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-animaux'), 1, 'comment-vivent-les-animaux', 'Comment vivent les animaux', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-animaux') and slug = 'comment-vivent-les-animaux'), $html$<table><thead><tr><th scope="col">Caractère</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>régime alimentaire</td><td>herbivore (vache), carnivore (lion), omnivore (poule)</td></tr><tr><td>déplacement</td><td>marche (chèvre), nage (poisson), vol (oiseau), reptation (serpent)</td></tr><tr><td>respiration</td><td>poumons (chat) ou branchies (poisson)</td></tr><tr><td>reproduction</td><td>vivipare : le petit naît vivant (vache) ; ovipare : il naît d’un œuf (poule)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 10, 'les-plantes', 'Les plantes', 'Les parties de la plante, sa croissance, sa nutrition, sa respiration et son utilité.', 10, 'published', 'Initiation scientifique et technologique', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
