insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'les-plantes') and slug = 'la-vie-des-plantes'), $html$<ul><li>Parties : racines, tronc ou tige, branches, feuilles, fleurs, fruits, écorce.</li><li>Croissance : la graine germe, la plante se développe, fleurit puis donne des fruits.</li><li>Nutrition : la plante puise l’eau et les éléments du sol par ses racines ; la sève circule dans la tige.</li><li>Elle respire par ses feuilles.</li></ul>
