insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'utiliser-et-fabriquer-des-objets-technologiques') and slug = 'le-circuit-electrique-et-les-objets-fabriques'), $html$<ul><li>Une lampe de poche fonctionne avec des piles : la pile, les fils et l’ampoule forment un <strong>circuit</strong>.</li><li>Circuit <strong>fermé</strong> : l’ampoule s’allume. Circuit <strong>ouvert</strong> : elle s’éteint.</li><li>Les objets s’entretiennent : nettoyage, graissage, dépoussiérage.</li><li>On peut fabriquer des jouets : voiturette en fil de fer, toupie, cerf-volant.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null), 12, 'se-proteger-contre-le-paludisme', 'Se protéger contre le paludisme', 'Causes, signes, prévention et traitement du paludisme.', 12, 'published', 'Vivre dans son milieu', '[{"title":"Guide pédagogique, enseignement élémentaire, 2e étape CE1-CE2 (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%202.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
