insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'se-proteger-contre-le-paludisme') and slug = 'le-paludisme'), $html$<ul><li>Le paludisme est transmis par la piqûre d’un moustique, l’<strong>anophèle</strong> femelle.</li><li>Les moustiques se multiplient dans les eaux stagnantes.</li><li>Signes : fièvre, maux de tête, vomissements, fatigue.</li><li>Se protéger : dormir sous une moustiquaire imprégnée, supprimer les eaux stagnantes, utiliser des insecticides.</li></ul>
