insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'se-proteger-contre-le-sida') and slug = 'le-sida-se-proteger'), $html$<ul><li>Le sida est une maladie causée par un virus, le VIH, qui affaiblit les défenses du corps.</li><li>Il peut se transmettre par le sang : objets pointus ou tranchants déjà utilisés (lames, aiguilles), tatouages.</li><li>Il ne se transmet pas en jouant, en mangeant ensemble ou en se serrant la main.</li></ul>
