insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'environnement-et-population') and slug = 'proteger-l-environnement'), $html$<table><thead><tr><th scope="col">Problème</th><th scope="col">Solutions</th></tr></thead><tbody><tr><td>désertification, déforestation</td><td>reboisement, brise-vent, foyers améliorés</td></tr><tr><td>érosion</td><td>diguettes, plantations</td></tr><tr><td>feux de brousse</td><td>pare-feu, sensibilisation</td></tr><tr><td>ordures, eaux usées, péril fécal</td><td>poubelles, puisards, toilettes</td></tr><tr><td>bruit, fumées</td><td>respect des règles, contrôle des véhicules</td></tr></tbody></table>
