insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'environnement-et-population') and slug = 'les-problemes-de-population'), $html$<ul><li>Problèmes : manque d’hygiène, malnutrition, maladies, logements trop petits (promiscuité), enfants non scolarisés, pauvreté.</li><li>Solutions : informer et sensibiliser, aller à l’école, se soigner, bien se nourrir, garder un milieu propre.</li></ul>
