insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'droits-et-devoirs') and slug = 'mes-droits-et-mes-devoirs'), $html$<table><thead><tr><th scope="col">Mes droits</th><th scope="col">Mes devoirs</th></tr></thead><tbody><tr><td>m’exprimer, donner mon avis</td><td>respecter l’avis des autres</td></tr><tr><td>être protégé, être en sécurité</td><td>ne pas faire de mal aux autres</td></tr><tr><td>aller à l’école, être informé</td><td>travailler et respecter le règlement</td></tr><tr><td>être respecté dans ma dignité</td><td>être solidaire, hospitalier, discret</td></tr></tbody></table>
