insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CE2' and p.series_id is null) and c.slug = 'la-paix-et-les-valeurs') and slug = 'vivre-en-paix'), $html$<ul><li>Idéaux de paix : tolérance, respect des différences (religion, ethnie, opinion), solidarité, liberté, égalité, démocratie.</li><li>Valeurs de notre milieu : la <em>teranga</em> (hospitalité), la solidarité, l’humilité, la politesse, le courage, le respect des anciens, la mesure (<em>kersa</em>).</li><li>En cas de dispute, on discute calmement ou on demande l’aide d’un médiateur.</li></ul>
