insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM1' and p.series_id is null) and c.slug = 'le-dialogue') and slug = 'lire-et-ecrire-un-dialogue'), $html$<ul><li>Les guillemets « » ouvrent et ferment le dialogue.</li><li>Un tiret marque chaque changement de personne qui parle.</li><li>Les verbes de parole disent qui parle et comment : demanda, répondit, cria, murmura.</li></ul>
