insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM1' and p.series_id is null) and c.slug = 'la-nature-des-mots') and slug = 'reconnaitre-la-nature-des-mots'), $html$<table><thead><tr><th scope="col">Nature</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>nom</td><td>Dakar, école, mangue</td></tr><tr><td>déterminant</td><td>le, une, mon, ce, trois</td></tr><tr><td>adjectif qualificatif</td><td>grand, rouge, gentil</td></tr><tr><td>pronom</td><td>il, nous, la, leur</td></tr><tr><td>verbe</td><td>manger, être, courir</td></tr><tr><td>adverbe (invariable)</td><td>vite, bien, très, hier</td></tr><tr><td>préposition (invariable)</td><td>à, de, dans, sur, avec, pour</td></tr></tbody></table>
