insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-accords') and slug = 'accorder-le-groupe-nominal-et-le-verbe'), $html$<ul><li>Dans le groupe nominal, le déterminant et l’adjectif s’accordent avec le nom : de belles fleurs rouges.</li><li>Le verbe s’accorde avec son sujet, même s’il est loin : Les enfants de mon voisin jouent.</li><li>Avec être, le participe passé s’accorde avec le sujet : Les filles sont parties.</li></ul>
