insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-homophones-grammaticaux') and slug = 'ne-pas-confondre-les-homophones'), $html$<table><thead><tr><th scope="col">Homophones</th><th scope="col">Astuce</th></tr></thead><tbody><tr><td>on / ont</td><td>ont = avaient ; on = il</td></tr><tr><td>ce / se</td><td>se est devant un verbe pronominal (il se lave) ; ce devant un nom (ce livre)</td></tr><tr><td>ces / ses</td><td>ses = les siens ; ces = ceux-là</td></tr><tr><td>a / à ; et / est ; son / sont ; ou / où</td><td>je remplace par avait, était, étaient, ou bien</td></tr></tbody></table>
