insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM1' and p.series_id is null) and c.slug = 'le-vocabulaire-et-le-dictionnaire') and slug = 'enrichir-son-vocabulaire'), $html$<ul><li><strong>Synonymes</strong> : mots de sens proche (peur, crainte, frayeur).</li><li><strong>Contraires</strong> : mots de sens opposé (heureux / malheureux).</li><li><strong>Famille de mots</strong> : même radical (dent, dentiste, dentifrice).</li><li><strong>Préfixes</strong> (re-, dé-, in-) et <strong>suffixes</strong> (-eur, -age, -able) forment de nouveaux mots.</li></ul>
