insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'operations-sur-les-nombres-decimaux') and slug = 'additionner-et-soustraire-des-decimaux'), $html$<ul><li>J’aligne les virgules les unes sous les autres.</li><li>Je complète avec des zéros si besoin.</li><li>Je place la virgule au résultat sous les autres virgules.</li></ul>
