insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'operations-sur-les-nombres-decimaux') and slug = 'multiplier-et-diviser-des-decimaux'), $html$<ul><li>Multiplier un décimal par un entier : je calcule sans la virgule, puis je remets autant de chiffres après la virgule : 2,35 × 4 = 9,40.</li><li>Multiplier par 10, 100, 1 000 : la virgule avance de 1, 2 ou 3 rangs vers la droite.</li><li>Diviser un décimal par un entier : je mets la virgule au quotient quand j’abaisse le premier chiffre décimal : 9,6 ÷ 3 = 3,2.</li></ul>
