insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-fractions') and slug = 'fractions-ordinaires-et-fractions-decimales'), $html$<ul><li>Dans 3/5, 5 est le <strong>dénominateur</strong> (le nombre de parts égales) et 3 le <strong>numérateur</strong> (les parts prises).</li><li>Une <strong>fraction décimale</strong> a pour dénominateur 10, 100, 1 000 : 7/10 = 0,7 ; 25/100 = 0,25.</li></ul>
