insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-fractions') and slug = 'comparer-et-simplifier-des-fractions'), $html$<ul><li>Même dénominateur : la plus grande fraction a le plus grand numérateur (5/8 &gt; 3/8).</li><li>Même numérateur : la plus grande a le plus petit dénominateur (1/3 &gt; 1/4).</li><li>Simplifier : je divise le numérateur et le dénominateur par un même nombre : 6/8 = 3/4.</li></ul>
