insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'calculer-avec-les-fractions') and slug = 'additionner-et-soustraire-des-fractions'), $html$<ul><li>Avec le même dénominateur, j’additionne (ou je soustrais) les numérateurs : 2/7 + 3/7 = 5/7.</li><li>Sinon, je réduis d’abord au même dénominateur : 1/2 + 1/4 = 2/4 + 1/4 = 3/4.</li></ul>
