insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'calculer-avec-les-fractions') and slug = 'fraction-d-une-grandeur'), $html$<ul><li>Les 3/4 de 800 F : 800 ÷ 4 = 200 ; 200 × 3 = 600 F.</li><li>Si les 2/5 d’un champ font 40 m², 1/5 fait 20 m² et le champ fait 100 m².</li></ul>
