insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'droites-et-angles') and slug = 'tracer-des-droites-et-reconnaitre-des-angles'), $html$<ul><li>Deux droites <strong>sécantes</strong> se coupent ; si elles forment un angle droit, elles sont <strong>perpendiculaires</strong>.</li><li>Deux droites <strong>parallèles</strong> ne se coupent jamais.</li><li>Un angle <strong>aigu</strong> est plus petit qu’un angle droit ; un angle <strong>obtus</strong> est plus grand.</li></ul>
