insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'comprendre-l-enonce-d-un-probleme') and slug = 'lire-et-organiser-l-enonce'), $html$<ul><li>Je lis l’énoncé deux fois et je le redis avec mes mots.</li><li>Je souligne les données utiles, je barre les inutiles, je cherche s’il en manque.</li><li>Je repère la consigne et la question finale, puis les questions intermédiaires.</li></ul>
