insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'tableaux-schemas-et-graphiques') and slug = 'utiliser-tableaux-et-graphiques'), $html$<ul><li>Un <strong>tableau</strong> range les données en lignes et en colonnes.</li><li>Une <strong>facture</strong> indique la quantité, le prix unitaire, le montant et le total.</li><li>Un <strong>graphique</strong> (diagramme en bâtons, courbe) montre des comparaisons ou une évolution.</li></ul>
