insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM1' and p.series_id is null) and c.slug = 'demarches-de-resolution') and slug = 'resoudre-et-verifier'), $html$<ul><li><strong>Démarche progressive</strong> : je pars des données vers la question.</li><li><strong>Démarche régressive</strong> : je pars du résultat et je fais les opérations inverses.</li><li>Je peux inventer un énoncé à partir d’un calcul, et chercher l’erreur dans une solution.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null), 1, 'la-prehistoire-et-la-protohistoire-au-senegal', 'La préhistoire et la protohistoire au Sénégal', 'Les premiers habitants, les outils de pierre, les amas coquilliers et les mégalithes.', 1, 'published', 'Histoire', '[{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Chapitres indicatifs : programme officiel détaillé de l’étape 3 non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'la-prehistoire-et-la-protohistoire-au-senegal'), 1, 'les-traces-des-premiers-habitants', 'Les traces des premiers habitants', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'la-prehistoire-et-la-protohistoire-au-senegal') and slug = 'les-traces-des-premiers-habitants'), $html$<ul><li>La <strong>préhistoire</strong> est la période avant l’écriture. Les hommes taillaient des outils en pierre, chassaient, pêchaient et cueillaient.</li><li>Au <strong>néolithique</strong>, ils ont commencé à cultiver, à élever des animaux et à fabriquer des poteries.</li><li>Dans le delta du Saloum, les <strong>amas coquilliers</strong> (montagnes de coquillages) montrent que des hommes y vivaient de la pêche.</li><li>Les <strong>cercles mégalithiques</strong> de Sénégambie (Sine Ngayène, Wanar) sont des monuments de pierres dressées, inscrits au patrimoine mondial.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null), 2, 'l-empire-du-ghana-et-le-tekrour', 'L’empire du Ghana et le Tékrour', 'L’empire du Ghana, le commerce de l’or, le Tékrour et l’arrivée de l’islam.', 2, 'published', 'Histoire', '[{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Chapitres indicatifs : programme officiel détaillé de l’étape 3 non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'l-empire-du-ghana-et-le-tekrour'), 1, 'l-empire-du-ghana', 'L’empire du Ghana', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'l-empire-du-ghana-et-le-tekrour') and slug = 'l-empire-du-ghana'), $html$<ul><li>Le Ghana (ou Wagadou) était un grand empire soninké situé entre le fleuve Sénégal et le Niger.</li><li>Il était riche grâce à l’or, échangé contre le sel apporté du nord par les caravanes du Sahara.</li><li>Sa capitale était Koumbi Saleh.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'l-empire-du-ghana-et-le-tekrour'), 2, 'le-tekrour-et-l-islam', 'Le Tékrour et l’islam', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'l-empire-du-ghana-et-le-tekrour') and slug = 'le-tekrour-et-l-islam'), $html$<ul><li>Le Tékrour, dans la vallée du fleuve Sénégal, est l’un des plus anciens royaumes du pays.</li><li>Son roi War Jaabi adopta l’islam au XI<sup>e</sup> siècle.</li><li>L’islam s’est ensuite répandu par les commerçants, les marabouts et le mouvement almoravide.</li></ul>
