insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'le-senegal-sur-la-carte') and slug = 'situation-et-organisation-du-senegal'), $html$<ul><li>Le Sénégal est en Afrique de l’Ouest, au bord de l’océan Atlantique.</li><li>Ses voisins : la Mauritanie au nord, le Mali à l’est, la Guinée et la Guinée-Bissau au sud ; la Gambie est enclavée dans le pays.</li><li>Il est découpé en 14 régions, elles-mêmes divisées en départements, arrondissements et communes.</li></ul>
