insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-etats-de-l-eau') and slug = 'l-eau-change-d-etat'), $html$<table><thead><tr><th scope="col">Changement</th><th scope="col">De… à…</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>solidification</td><td>liquide → solide</td><td>l’eau devient glace au congélateur</td></tr><tr><td>fusion</td><td>solide → liquide</td><td>la glace fond au soleil</td></tr><tr><td>évaporation</td><td>liquide → gaz</td><td>le linge sèche</td></tr><tr><td>condensation</td><td>gaz → liquide</td><td>la buée sur une bouteille fraîche</td></tr></tbody></table>
