insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'l-air-et-la-combustion') and slug = 'le-feu-a-besoin-d-air'), $html$<ul><li>L’air est invisible mais il existe : il gonfle un ballon, fait tourner les éoliennes.</li><li>Une bougie sous un verre retourné s’éteint : le feu a besoin de l’air (du dioxygène) pour brûler.</li><li>Pour qu’il y ait un feu, il faut un combustible, de l’air et de la chaleur.</li></ul>
