insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-plantes-a-fleurs') and slug = 'de-la-fleur-a-la-graine'), $html$<ul><li>La <strong>fleur</strong> contient les étamines (qui produisent le pollen) et le pistil.</li><li>Le pollen est transporté par le vent ou les insectes (abeilles) : c’est la <strong>pollinisation</strong>.</li><li>La fleur devient un <strong>fruit</strong> qui contient des <strong>graines</strong>.</li><li>Une graine germe s’il y a de l’eau, de l’air et une bonne température.</li></ul>
