insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-aliments-et-leur-conservation') and slug = 'conserver-les-aliments'), $html$<table><thead><tr><th scope="col">Technique</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>séchage</td><td>poisson séché (guedj), viande séchée (kilichi), mangues séchées</td></tr><tr><td>fumage</td><td>poisson fumé (kéthiakh)</td></tr><tr><td>salage</td><td>poisson salé</td></tr><tr><td>froid</td><td>réfrigérateur, congélateur</td></tr><tr><td>conserves</td><td>boîtes, bocaux, sucre (confitures)</td></tr></tbody></table>
