insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'l-electricite') and slug = 'circuit-conducteurs-et-isolants'), $html$<ul><li>Un circuit électrique comprend une source (pile), des fils, un interrupteur et une ampoule.</li><li>Les métaux sont <strong>conducteurs</strong> ; le plastique, le bois sec et le caoutchouc sont <strong>isolants</strong>.</li><li>Le courant de la maison (220 V) peut tuer : on ne touche pas les fils dénudés et on ne met rien dans les prises.</li></ul>
