insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'la-securite-routiere') and slug = 'circuler-en-securite'), $html$<ul><li>Je marche sur le trottoir ou, s’il n’y en a pas, sur le bord gauche de la route, face aux voitures.</li><li>Je traverse au passage piéton, quand le feu des piétons est vert, après avoir regardé à gauche puis à droite.</li><li>Je ne joue pas au bord de la route ; je ne monte pas dans un véhicule surchargé.</li></ul>
