insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM1' and p.series_id is null) and c.slug = 'les-dechets-et-la-pollution') and slug = 'reduire-trier-recycler'), $html$<ul><li>Les sachets plastiques mettent des centaines d’années à disparaître ; ils tuent les animaux qui les avalent et bouchent les canalisations.</li><li>Brûler les ordures dégage des fumées toxiques.</li><li>On peut <strong>réduire</strong> (sac en tissu), <strong>réutiliser</strong> (bouteilles), <strong>recycler</strong> (plastique, métal, papier) et faire du compost avec les épluchures.</li></ul>
