insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-fonctions-dans-la-phrase') and slug = 'le-sujet-les-complements-d-objet-et-l-attribut'), $html$<table><thead><tr><th scope="col">Fonction</th><th scope="col">Question à poser</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>sujet</td><td>qui est-ce qui ? qu’est-ce qui ? + verbe</td><td><strong>Les pêcheurs</strong> reviennent.</td></tr><tr><td>COD (complément d’objet direct)</td><td>verbe + qui ? quoi ?</td><td>Ils vendent <strong>le poisson</strong>.</td></tr><tr><td>COI (complément d’objet indirect)</td><td>verbe + à qui ? de quoi ?</td><td>Ils parlent <strong>aux clients</strong>.</td></tr><tr><td>COS (complément d’objet second)</td><td>deuxième complément d’objet</td><td>Ils donnent du poisson <strong>à leur mère</strong>.</td></tr><tr><td>attribut du sujet</td><td>après un verbe d’état (être, paraître, sembler, devenir…)</td><td>La mer est <strong>calme</strong>.</td></tr></tbody></table>
