insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-present-de-l-indicatif'), 2, 'verbes-en-eler-eter-yer', 'Verbes en -eler, -eter, -yer', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-present-de-l-indicatif') and slug = 'verbes-en-eler-eter-yer'), $html$<ul><li>la plupart des verbes en -eler et -eter doublent la consonne devant un e muet : j’appelle, je jette, nous appelons ;</li><li>quelques-uns prennent un accent grave : j’achète, je gèle, il pèle ;</li><li>les verbes en -oyer et -uyer changent y en i devant un e muet : j’envoie, j’essuie, nous envoyons ;</li><li>les verbes en -ayer peuvent garder le y ou prendre i : je paie ou je paye.</li></ul>
