insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-accords') and slug = 'l-accord-de-l-adjectif-qualificatif'), $html$<p>L’adjectif s’accorde en genre et en nombre avec le nom qu’il qualifie.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-accords'), 2, 'l-accord-du-participe-passe', 'L’accord du participe passé', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-accords') and slug = 'l-accord-du-participe-passe'), $html$<ul><li>avec <strong>être</strong>, le participe passé s’accorde avec le sujet : Les filles sont arrivées ;</li><li>avec <strong>avoir</strong>, il ne s’accorde pas avec le sujet ; il s’accorde avec le COD seulement si celui-ci est placé avant le verbe : J’ai cueilli des mangues. Les mangues que j’ai cueillies.</li><li>employé seul, il s’accorde comme un adjectif : des portes fermées.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null), 12, 'les-homophones-grammaticaux', 'Les homophones grammaticaux', 'a/à, et/est, son/sont, ces/ses, leur/leurs, quel(s)/qu’elle(s), ou/où…', 12, 'published', 'Orthographe', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-homophones-grammaticaux'), 1, 'distinguer-les-homophones', 'Distinguer les homophones', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-homophones-grammaticaux') and slug = 'distinguer-les-homophones'), $html$<table><thead><tr><th scope="col">Homophones</th><th scope="col">Astuce</th></tr></thead><tbody><tr><td>a / à</td><td>a = avait (verbe avoir) ; sinon à</td></tr><tr><td>et / est</td><td>est = était ; et = et puis</td></tr><tr><td>son / sont</td><td>sont = étaient ; son = le sien</td></tr><tr><td>ces / ses</td><td>ses = les siens ; ces = ceux-là</td></tr><tr><td>ou / où</td><td>ou = ou bien ; où indique le lieu ou le temps</td></tr><tr><td>leur / leurs</td><td>leur devant un verbe est invariable (pronom) ; devant un nom pluriel : leurs</td></tr><tr><td>quel(s) / qu’elle(s)</td><td>qu’elle = que + elle (on peut remplacer par « qu’il »)</td></tr></tbody></table>
