insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'mots-invariables-et-ponctuation'), 1, 'les-adverbes-en-ment-et-les-prepositions', 'Les adverbes en -ment et les prépositions', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'mots-invariables-et-ponctuation') and slug = 'les-adverbes-en-ment-et-les-prepositions'), $html$<ul><li>on forme l’adverbe sur le féminin de l’adjectif : lent → lente → lentement ;</li><li>adjectifs en -ant → -amment, en -ent → -emment : courant → couramment, prudent → prudemment ;</li><li>les <strong>prépositions</strong> (à, de, dans, par, pour, sans, sous, sur, avec, chez…) sont invariables.</li></ul>
