insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'mots-invariables-et-ponctuation') and slug = 'la-ponctuation'), $html$<table><thead><tr><th scope="col">Signe</th><th scope="col">Emploi</th></tr></thead><tbody><tr><td>point .</td><td>fin d’une phrase déclarative</td></tr><tr><td>virgule ,</td><td>sépare des éléments d’une énumération ou des propositions</td></tr><tr><td>point-virgule ;</td><td>sépare deux propositions liées par le sens</td></tr><tr><td>deux-points :</td><td>annonce une explication, une énumération ou des paroles</td></tr><tr><td>points de suspension …</td><td>phrase inachevée, hésitation</td></tr><tr><td>guillemets « »</td><td>encadrent des paroles rapportées</td></tr></tbody></table>
