insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-sens-des-mots') and slug = 'sens-propre-sens-figure-et-contexte'), $html$<p>Un même mot peut avoir plusieurs sens. C’est le <strong>contexte</strong> (la phrase) qui permet de choisir le bon.</p>
