insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CM2' and p.series_id is null) and c.slug = 'rediger-un-texte') and slug = 'preparer-et-ecrire-une-redaction'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire attentivement le sujet et souligner les mots importants : que faut-il raconter, décrire ou expliquer ?</li><li>Chercher des idées au brouillon et les classer.</li><li>Faire un plan : introduction, développement (plusieurs paragraphes), conclusion.</li><li>Rédiger en phrases complètes, avec des mots de liaison (d’abord, ensuite, puis, enfin, car, mais).</li><li>Relire pour corriger l’orthographe, les accords et la ponctuation.</li></ol></div>
