insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-grands-nombres') and slug = 'decomposer-et-comparer-les-grands-nombres'), $html$<div class="example"><p class="callout-title">Exemple</p><p>3 405 270 = 3 000 000 + 400 000 + 5 000 + 200 + 70.</p><p>Dans 3 405 270, le chiffre des centaines de mille est 4 ; le nombre de milliers est 3 405.</p></div>
