insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-caracteres-de-divisibilite') and slug = 'divisibilite-par-2-5-10-4-et-25'), $html$<table><thead><tr><th scope="col">Un nombre est divisible par…</th><th scope="col">si…</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>2</td><td>il est pair : son chiffre des unités est 0, 2, 4, 6 ou 8</td><td>126 ; 3 058</td></tr><tr><td>5</td><td>son chiffre des unités est 0 ou 5</td><td>235 ; 1 480</td></tr><tr><td>10</td><td>son chiffre des unités est 0</td><td>750</td></tr><tr><td>4</td><td>le nombre formé par ses deux derniers chiffres est divisible par 4</td><td>1 316 (16 = 4 × 4)</td></tr><tr><td>25</td><td>il se termine par 00, 25, 50 ou 75</td><td>1 275</td></tr></tbody></table>
