insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-caracteres-de-divisibilite') and slug = 'divisibilite-par-3-et-par-9'), $html$<div class="callout"><p class="callout-title">À retenir</p><p>Un nombre est divisible par 3 si la somme de ses chiffres est divisible par 3 ; il est divisible par 9 si cette somme est divisible par 9.</p></div>
