insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-nombres-decimaux') and slug = 'lire-et-ecrire-les-nombres-decimaux'), $html$<p>Un nombre décimal a une <strong>partie entière</strong> et une <strong>partie décimale</strong>, séparées par une virgule.</p>
