insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-quadrilateres-et-le-triangle') and slug = 'parallelogramme-et-trapeze'), $html$<ul><li><strong>parallélogramme</strong> : quadrilatère dont les côtés opposés sont parallèles et de même longueur ; ses diagonales se coupent en leur milieu ;</li><li><strong>trapèze</strong> : quadrilatère qui a deux côtés parallèles, appelés grande base et petite base ; la distance entre les bases est la hauteur ;</li><li>un trapèze rectangle a un angle droit ; un trapèze isocèle a ses deux côtés non parallèles égaux.</li></ul>
