insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-cercle-et-les-polygones') and slug = 'les-polygones'), $html$<p>Un <strong>polygone</strong> est une figure fermée formée de segments. On le nomme selon son nombre de côtés.</p>
