insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'symetrie-translation-agrandissement-et-reduction') and slug = 'symetrie-axiale-et-translation'), $html$<p>Deux figures sont <strong>symétriques</strong> par rapport à une droite (l’axe) si elles se superposent quand on plie le long de cet axe. Une figure a un <strong>axe de symétrie</strong> si ses deux moitiés se superposent par pliage.</p>
