insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-aires') and slug = 'aires-du-carre-du-rectangle-et-du-triangle'), $html$<table><thead><tr><th scope="col">Figure</th><th scope="col">Aire</th><th scope="col">Dimension à partir de l’aire</th></tr></thead><tbody><tr><td>carré</td><td>A = c × c</td><td>c = le nombre qui, multiplié par lui-même, donne A</td></tr><tr><td>rectangle</td><td>A = L × l</td><td>L = A ÷ l</td></tr><tr><td>triangle</td><td>A = b × h ÷ 2</td><td>b = A × 2 ÷ h ; h = A × 2 ÷ b</td></tr></tbody></table>
