insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-aires') and slug = 'aires-du-parallelogramme-du-losange-du-trapeze-et-du-disque'), $html$<table><thead><tr><th scope="col">Figure</th><th scope="col">Aire</th></tr></thead><tbody><tr><td>parallélogramme</td><td>A = b × h</td></tr><tr><td>losange</td><td>A = D × d ÷ 2 (produit des diagonales divisé par 2)</td></tr><tr><td>trapèze</td><td>A = (B + b) × h ÷ 2</td></tr><tr><td>disque de rayon r</td><td>A = r × r × 3,14</td></tr></tbody></table>
