insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'comprendre-l-enonce-d-un-probleme') and slug = 'consignes-question-finale-et-questions-intermediaires'), $html$<p>La <strong>question finale</strong> est ce qu’on cherche à la fin. Pour y arriver, il faut souvent répondre d’abord à des <strong>questions intermédiaires</strong>, qui ne sont pas toujours écrites.</p>
