insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'tableaux-schemas-et-graphiques') and slug = 'lire-un-graphique-et-faire-un-schema'), $html$<ul><li>un <strong>diagramme en bâtons</strong> compare des quantités (élèves par classe) ;</li><li>une <strong>courbe</strong> montre une évolution dans le temps (température, pluie) ;</li><li>un <strong>schéma</strong> (segments, dessins) aide à comprendre un partage ou un trajet.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null), 23, 'demarches-de-resolution-et-verification', 'Démarches de résolution et vérification', 'Démarche progressive ou régressive, inventer un énoncé, repérer une erreur, vérifier une solution.', 23, 'published', 'Résolution de problèmes', '[{"title":"Cahier d’exercices de mathématiques CM2, PAAME (MEN, édition 2024, conforme au CEB)","url":"https://senprof.education.sn/PAAME/","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
