insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'demarches-de-resolution-et-verification') and slug = 'demarche-progressive-et-demarche-regressive'), $html$<table><thead><tr><th scope="col">Démarche</th><th scope="col">Principe</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>progressive</td><td>on part des données pour aller vers la question</td><td>J’ai 5 000 F, j’achète 2 livres à 1 500 F : il me reste 5 000 − 3 000 = 2 000 F.</td></tr><tr><td>régressive</td><td>on part du résultat et on « remonte » en faisant les opérations inverses</td><td>Il me reste 2 000 F après avoir dépensé 3 000 F : j’avais 2 000 + 3 000 = 5 000 F.</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'demarches-de-resolution-et-verification'), 2, 'inventer-un-enonce-trouver-une-erreur-verifier', 'Inventer un énoncé, trouver une erreur, vérifier', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'CM2' and p.series_id is null) and c.slug = 'demarches-de-resolution-et-verification') and slug = 'inventer-un-enonce-trouver-une-erreur-verifier'), $html$<ul><li>à partir d’une opération (3 × 750 = 2 250), on peut <strong>inventer un énoncé</strong> : « Trois cahiers à 750 F coûtent… » ;</li><li>pour <strong>trouver une erreur</strong>, on refait chaque étape et on vérifie l’opération choisie et les unités ;</li><li>pour <strong>vérifier</strong> un résultat, on fait l’opération inverse ou on estime un ordre de grandeur.</li></ul>
