insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-grands-empires-du-soudan-occidental') and slug = 'les-empires-du-ghana-du-mali-et-du-songhai'), $html$<table><thead><tr><th scope="col">Empire</th><th scope="col">Repères</th><th scope="col">Grands personnages</th></tr></thead><tbody><tr><td>Ghana (Wagadou)</td><td>riche grâce au commerce de l’or ; capitale Koumbi Saleh ; affaibli par les Almoravides au XI<sup>e</sup> siècle</td><td>les Kaya Maghan, rois « maîtres de l’or »</td></tr><tr><td>Mali</td><td>fondé après la bataille de Kirina (vers 1235) ; charte du Kouroukan Fouga</td><td>Soundjata Keïta ; Kankou Moussa, célèbre pour son pèlerinage à La Mecque (1324)</td></tr><tr><td>Songhaï</td><td>capitale Gao ; très vaste ; détruit par l’armée marocaine à Tondibi (1591)</td><td>Sonni Ali Ber ; Askia Mohammed</td></tr></tbody></table>
