insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-royaumes-du-senegal') and slug = 'le-tekrour-et-l-empire-du-djolof'), $html$<ul><li>le <strong>Tékrour</strong>, dans la vallée du fleuve Sénégal, est l’un des plus anciens royaumes ; son roi War Jaabi se convertit à l’islam au XI<sup>e</sup> siècle ;</li><li>l’empire du <strong>Djolof</strong> est fondé par Ndiadiane Ndiaye ; son roi porte le titre de Bourba ; il domine le Walo, le Cayor, le Baol, le Sine et le Saloum.</li></ul>
