insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-traite-negriere') and slug = 'la-traite-atlantique-et-ses-consequences'), $html$<p>Du XVI<sup>e</sup> au XIX<sup>e</sup> siècle, des millions d’Africains ont été capturés, vendus et déportés vers l’Amérique, où ils travaillaient comme esclaves dans les plantations.</p>
