insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-conquete-coloniale-et-les-resistances') and slug = 'la-conquete-coloniale'), $html$<p>Au XIX<sup>e</sup> siècle, la France conquiert le Sénégal à partir de Saint-Louis. Le gouverneur <strong>Louis Faidherbe</strong> (à partir de 1854) mène la conquête : postes militaires, routes, culture de l’arachide.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-conquete-coloniale-et-les-resistances'), 2, 'les-resistants', 'Les résistants', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-conquete-coloniale-et-les-resistances') and slug = 'les-resistants'), $html$<table><thead><tr><th scope="col">Résistant</th><th scope="col">Région</th><th scope="col">Ce qu’il faut retenir</th></tr></thead><tbody><tr><td>Lat Dior Ngoné Latyr Diop</td><td>Cayor</td><td>s’oppose au chemin de fer ; meurt au combat à Dékheulé (1886)</td></tr><tr><td>El Hadji Omar Tall</td><td>Fouta, Haut-Sénégal</td><td>assiège Médine (1857) ; fonde un empire au Soudan</td></tr><tr><td>Maba Diakhou Bâ</td><td>Rip, Saloum</td><td>meurt à la bataille de Somb (1867)</td></tr><tr><td>Alboury Ndiaye</td><td>Djolof</td><td>dernier Bourba ; meurt en exil (1901)</td></tr><tr><td>Mamadou Lamine Dramé</td><td>Haut-Sénégal</td><td>mène la résistance soninké (1885-1887)</td></tr><tr><td>Cheikh Ahmadou Bamba</td><td>Baol</td><td>résistance pacifique ; exilé au Gabon (1895-1902)</td></tr><tr><td>Aline Sitoé Diatta</td><td>Casamance</td><td>refuse les réquisitions ; arrêtée en 1943, morte en exil</td></tr></tbody></table>
