insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'de-la-colonisation-a-l-independance-du-senegal') and slug = 'le-senegal-colonial'), $html$<ul><li>1895 : création de l’Afrique-Occidentale française (AOF) ; Dakar en devient la capitale en 1902 ;</li><li>les habitants des <strong>Quatre communes</strong> (Saint-Louis, Gorée, Rufisque, Dakar) avaient des droits de citoyens ;</li><li>1914 : Blaise Diagne est le premier Africain élu député à l’Assemblée nationale française ;</li><li>les <strong>tirailleurs sénégalais</strong> ont combattu pendant les deux guerres mondiales ; le 1<sup>er</sup> décembre 1944, des tirailleurs qui réclamaient leur dû sont massacrés à Thiaroye.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'de-la-colonisation-a-l-independance-du-senegal'), 2, 'l-independance-et-le-senegal-independant', 'L’indépendance et le Sénégal indépendant', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'de-la-colonisation-a-l-independance-du-senegal') and slug = 'l-independance-et-le-senegal-independant'), $html$<p>En 1959, le Sénégal et le Soudan français forment la Fédération du Mali, indépendante le 20 juin 1960. Elle éclate le 20 août 1960. Le Sénégal célèbre sa fête de l’indépendance le <strong>4 avril</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 6, 'le-senegal-situation-et-milieu-physique', 'Le Sénégal : situation et milieu physique', 'Situation, frontières, relief, climat, cours d’eau et végétation du Sénégal.', 6, 'published', 'Géographie', '[{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Chapitres indicatifs : programme officiel détaillé de l’étape 3 non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-senegal-situation-et-milieu-physique'), 1, 'situation-frontieres-et-relief', 'Situation, frontières et relief', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-senegal-situation-et-milieu-physique') and slug = 'situation-frontieres-et-relief'), $html$<p>Le Sénégal est situé à l’extrême ouest de l’Afrique ; la pointe des Almadies, à Dakar, est le point le plus occidental du continent. Sa superficie est de 196 722 km².</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-senegal-situation-et-milieu-physique'), 2, 'climat-cours-d-eau-et-vegetation', 'Climat, cours d’eau et végétation', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'le-senegal-situation-et-milieu-physique') and slug = 'climat-cours-d-eau-et-vegetation'), $html$<ul><li>deux saisons : la saison des pluies ou <strong>hivernage</strong> (de juin-juillet à octobre) et la saison sèche ;</li><li>il pleut de moins en moins du sud (Casamance, plus de 1 000 mm par an) vers le nord (moins de 300 mm) ;</li><li>vents : alizé maritime (frais et humide), harmattan (chaud et sec, venu du Sahara), mousson (apporte la pluie).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 7, 'la-population-et-les-regions-du-senegal', 'La population et les régions du Sénégal', 'Population, répartition, régions administratives et villes.', 7, 'published', 'Géographie', '[{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Chapitres indicatifs : programme officiel détaillé de l’étape 3 non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-population-et-les-regions-du-senegal'), 1, 'la-population-et-les-regions', 'La population et les régions', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-population-et-les-regions-du-senegal') and slug = 'la-population-et-les-regions'), $html$<p>Le Sénégal compte environ <strong>18 millions d’habitants</strong> (recensement de 2023). La population est jeune et inégalement répartie : elle se concentre à l’ouest, surtout dans la région de Dakar, très peuplée sur une petite surface ; l’est est peu peuplé.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 8, 'les-activites-economiques-du-senegal', 'Les activités économiques du Sénégal', 'Agriculture, élevage, pêche, mines, industrie, commerce, transports et tourisme.', 8, 'published', 'Géographie', '[{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Chapitres indicatifs : programme officiel détaillé de l’étape 3 non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-activites-economiques-du-senegal'), 1, 'agriculture-elevage-et-peche', 'Agriculture, élevage et pêche', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-activites-economiques-du-senegal') and slug = 'agriculture-elevage-et-peche'), $html$<table><thead><tr><th scope="col">Activité</th><th scope="col">Productions et zones</th></tr></thead><tbody><tr><td>agriculture</td><td>arachide et mil (bassin arachidier), riz (vallée du fleuve, Casamance), coton (sud-est), légumes (Niayes)</td></tr><tr><td>élevage</td><td>bovins, ovins, caprins ; surtout dans le Ferlo ; la Tabaski augmente la demande de moutons</td></tr><tr><td>pêche</td><td>artisanale (pirogues de Kayar, Joal, Mbour, Saint-Louis) et industrielle ; le poisson est la première exportation</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-activites-economiques-du-senegal'), 2, 'mines-industrie-commerce-et-services', 'Mines, industrie, commerce et services', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-activites-economiques-du-senegal') and slug = 'mines-industrie-commerce-et-services'), $html$<ul><li><strong>mines</strong> : phosphates (Taïba), or (Sabodala), zircon ; le pays produit aussi du pétrole et du gaz depuis 2024 ;</li><li><strong>industries</strong> : huileries, industries chimiques, cimenteries, agroalimentaire ;</li><li><strong>transports</strong> : port de Dakar, aéroport international Blaise Diagne, routes et autoroutes, Train express régional (TER) ;</li><li><strong>tourisme</strong> : Saly, Cap Skirring, Saint-Louis, Gorée, delta du Saloum.</li></ul>
