insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'l-afrique-et-le-monde') and slug = 'les-continents-les-oceans-et-l-afrique'), $html$<ul><li>les continents : Afrique, Amérique, Asie, Europe, Océanie (et l’Antarctique) ;</li><li>les océans : Atlantique, Pacifique, Indien, Arctique, Austral ;</li><li>l’Afrique compte 54 pays ; on y trouve le plus grand désert chaud (Sahara), le plus long fleuve (le Nil) et le Kilimandjaro (5 895 m), son plus haut sommet.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 10, 'la-digestion-et-la-nutrition', 'La digestion et la nutrition', 'L’appareil digestif et la transformation des aliments.', 10, 'published', 'Initiation scientifique et technologique', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
