insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-digestion-et-la-nutrition') and slug = 'l-appareil-digestif-et-la-digestion'), $html$<table><thead><tr><th scope="col">Organe</th><th scope="col">Rôle</th></tr></thead><tbody><tr><td>bouche (dents, salive)</td><td>broie les aliments ; la salive commence la digestion de l’amidon</td></tr><tr><td>œsophage</td><td>conduit les aliments vers l’estomac</td></tr><tr><td>estomac</td><td>brasse les aliments avec le suc gastrique</td></tr><tr><td>intestin grêle</td><td>termine la digestion (bile du foie, suc du pancréas) ; les nutriments passent dans le sang (absorption)</td></tr><tr><td>gros intestin</td><td>réabsorbe l’eau ; forme les excréments</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 11, 'la-respiration-et-la-circulation', 'La respiration et la circulation', 'L’appareil respiratoire, les échanges gazeux, le cœur et la circulation sanguine.', 11, 'published', 'Initiation scientifique et technologique', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
