insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-respiration-et-la-circulation') and slug = 'la-respiration'), $html$<p>L’air entre par le nez ou la bouche, passe dans la trachée, les bronches, puis arrive dans les <strong>poumons</strong>, jusqu’aux alvéoles pulmonaires.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-respiration-et-la-circulation'), 2, 'le-c-ur-et-la-circulation-du-sang', 'Le cœur et la circulation du sang', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-respiration-et-la-circulation') and slug = 'le-c-ur-et-la-circulation-du-sang'), $html$<p>Le <strong>cœur</strong> est un muscle qui fonctionne comme une pompe : il envoie le sang dans tout le corps par les <strong>artères</strong> ; le sang revient au cœur par les <strong>veines</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 12, 'les-etres-vivants-et-leurs-milieux', 'Les êtres vivants et leurs milieux', 'Êtres du milieu terrestre et du milieu aquatique, adaptations et chaînes alimentaires.', 12, 'published', 'Initiation scientifique et technologique', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-etres-vivants-et-leurs-milieux'), 1, 'milieu-terrestre-et-milieu-aquatique', 'Milieu terrestre et milieu aquatique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-etres-vivants-et-leurs-milieux') and slug = 'milieu-terrestre-et-milieu-aquatique'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Milieu terrestre</th><th scope="col">Milieu aquatique</th></tr></thead><tbody><tr><td>exemples</td><td>lion, chèvre, baobab, criquet</td><td>poisson, crevette, nénuphar, algue</td></tr><tr><td>respiration</td><td>poumons (mammifères, oiseaux), trachées (insectes)</td><td>branchies (poissons)</td></tr><tr><td>déplacement</td><td>pattes, ailes, reptation</td><td>nageoires, corps profilé</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-etres-vivants-et-leurs-milieux'), 2, 'les-chaines-alimentaires', 'Les chaînes alimentaires', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-etres-vivants-et-leurs-milieux') and slug = 'les-chaines-alimentaires'), $html$<p>Une <strong>chaîne alimentaire</strong> montre « qui mange qui » : herbe → criquet → poule → chacal. La flèche signifie « est mangé par ».</p>
