insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'outils-et-objets-technologiques') and slug = 'les-outils-et-les-machines-simples'), $html$<p>Un <strong>outil</strong> prolonge la main de l’homme pour faire un travail plus facilement.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'outils-et-objets-technologiques'), 2, 'le-circuit-electrique', 'Le circuit électrique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'outils-et-objets-technologiques') and slug = 'le-circuit-electrique'), $html$<p>Un <strong>circuit électrique</strong> simple comprend une source (pile, batterie, panneau solaire), des fils, un interrupteur et un récepteur (ampoule, moteur). La lampe ne s’allume que si le circuit est <strong>fermé</strong>.</p>
