insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-symboles-de-la-republique') and slug = 'drapeau-hymne-et-devise'), $html$<table><thead><tr><th scope="col">Symbole</th><th scope="col">Description</th></tr></thead><tbody><tr><td>drapeau</td><td>trois bandes verticales égales : vert, or, rouge, avec une étoile verte à cinq branches au centre de la bande or</td></tr><tr><td>hymne national</td><td>« Le Lion rouge » : paroles de Léopold Sédar Senghor (« Pincez tous vos koras, frappez les balafons… »)</td></tr><tr><td>devise</td><td>« Un Peuple – Un But – Une Foi »</td></tr><tr><td>armoiries</td><td>elles portent notamment un lion et un baobab</td></tr></tbody></table>
