insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-institutions-de-la-republique') and slug = 'le-president-le-gouvernement-et-l-assemblee-nationale'), $html$<table><thead><tr><th scope="col">Institution</th><th scope="col">Rôle</th></tr></thead><tbody><tr><td>Président de la République</td><td>élu au suffrage universel direct pour 5 ans ; garant de la Constitution, chef de l’État et des armées ; il nomme le Premier ministre</td></tr><tr><td>Gouvernement</td><td>le Premier ministre et les ministres appliquent la politique de la nation</td></tr><tr><td>Assemblée nationale</td><td>les députés votent les lois et le budget et contrôlent l’action du Gouvernement</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-institutions-de-la-republique'), 2, 'le-pouvoir-judiciaire', 'Le pouvoir judiciaire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'les-institutions-de-la-republique') and slug = 'le-pouvoir-judiciaire'), $html$<p>Le <strong>pouvoir judiciaire</strong> est indépendant des autres pouvoirs. Il est exercé par le Conseil constitutionnel, la Cour suprême, la Cour des comptes, les cours et les tribunaux.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 16, 'vivre-en-communaute', 'Vivre en communauté', 'Droits et devoirs de l’enfant, organisations communautaires et confessionnelles, le sport.', 16, 'published', 'Vivre ensemble', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'vivre-en-communaute'), 1, 'droits-et-devoirs-de-l-enfant', 'Droits et devoirs de l’enfant', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'vivre-en-communaute') and slug = 'droits-et-devoirs-de-l-enfant'), $html$<p>La Convention internationale des droits de l’enfant (1989), que le Sénégal a ratifiée, protège tous les enfants de moins de 18 ans.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'vivre-en-communaute'), 2, 'les-organisations-communautaires', 'Les organisations communautaires', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'vivre-en-communaute') and slug = 'les-organisations-communautaires'), $html$<ul><li><strong>organisations communautaires</strong> : associations sportives et culturelles (ASC), groupements de promotion féminine, groupements d’intérêt économique (GIE), associations de parents d’élèves ;</li><li><strong>organisations confessionnelles</strong> : dahiras, associations caritatives religieuses comme Caritas, qui aident les plus pauvres ;</li><li><strong>organisations sportives</strong> : le Comité international olympique (CIO) organise les Jeux olympiques ; Dakar accueille en 2026 les Jeux olympiques de la jeunesse, les premiers en Afrique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 17, 'la-degradation-du-milieu-et-des-ressources', 'La dégradation du milieu et des ressources', 'Déforestation, feux de brousse, érosion, désertification, surpêche, déchets ; comment protéger le milieu.', 17, 'published', 'Vivre dans son milieu', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-degradation-du-milieu-et-des-ressources'), 1, 'les-causes-et-les-consequences-de-la-degradation', 'Les causes et les conséquences de la dégradation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-degradation-du-milieu-et-des-ressources') and slug = 'les-causes-et-les-consequences-de-la-degradation'), $html$<table><thead><tr><th scope="col">Problème</th><th scope="col">Causes</th><th scope="col">Conséquences</th></tr></thead><tbody><tr><td>déforestation</td><td>coupe du bois, charbon de bois, défrichement</td><td>disparition des animaux, sols nus, avancée du désert</td></tr><tr><td>feux de brousse</td><td>imprudence, chasse, défrichement</td><td>destruction de la végétation et des récoltes</td></tr><tr><td>érosion</td><td>vent et ruissellement sur des sols nus</td><td>perte des terres cultivables</td></tr><tr><td>surpêche</td><td>trop de pirogues et de chalutiers, filets interdits</td><td>raréfaction du poisson</td></tr><tr><td>pollution</td><td>sachets plastiques, ordures, eaux usées</td><td>maladies, mort d’animaux</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-degradation-du-milieu-et-des-ressources'), 2, 'proteger-le-milieu', 'Protéger le milieu', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'la-degradation-du-milieu-et-des-ressources') and slug = 'proteger-le-milieu'), $html$<ul><li>reboiser (Journée nationale de l’arbre, Grande Muraille verte) et utiliser des foyers améliorés ;</li><li>faire des pare-feu et ne jamais allumer de feu en brousse ;</li><li>fixer les dunes avec des filaos (Niayes) et construire des diguettes contre l’érosion ;</li><li>respecter le repos biologique et les tailles minimales de pêche ;</li><li>réduire, trier et recycler les déchets ; ne pas jeter de sachets plastiques.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null), 18, 'alimentation-sante-et-carences-nutritionnelles', 'Alimentation, santé et carences nutritionnelles', 'Les groupes d’aliments, la ration équilibrée et les maladies dues aux carences.', 18, 'published', 'Vivre dans son milieu', '[{"title":"Leçons de CM2 de PROMET, plateforme du Ministère de l’Éducation nationale","url":"https://apprendre.education.sn/accueil/9","kind":"official"},{"title":"Guide du CFEE (Ministère de l’Éducation nationale) : domaines et sous-domaines évalués","url":"https://editsoftsenegal.com/download/guide-du-cfee.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'alimentation-sante-et-carences-nutritionnelles'), 1, 'une-alimentation-equilibree', 'Une alimentation équilibrée', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ESVS' and l.code = 'CM2' and p.series_id is null) and c.slug = 'alimentation-sante-et-carences-nutritionnelles') and slug = 'une-alimentation-equilibree'), $html$<table><thead><tr><th scope="col">Groupe d’aliments</th><th scope="col">Rôle</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>aliments énergétiques</td><td>donnent de l’énergie</td><td>mil, riz, maïs, manioc, huile, sucre</td></tr><tr><td>aliments de construction</td><td>font grandir et réparent le corps</td><td>poisson, viande, œufs, lait, niébé, arachide</td></tr><tr><td>aliments de protection</td><td>protègent contre les maladies</td><td>fruits (mangue, orange, pain de singe), légumes, feuilles</td></tr></tbody></table>
