insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '6E' and p.series_id is null) and c.slug = 'reperage-sur-la-sphere') and slug = 'latitude-et-longitude'), $html$<ul><li>la Terre tourne autour de l’axe des pôles (Nord et Sud) ;</li><li>l’<strong>équateur</strong> est le grand cercle perpendiculaire à cet axe ; les <strong>parallèles</strong> sont les cercles parallèles à l’équateur ;</li><li>les <strong>méridiens</strong> sont les demi-grands cercles qui joignent les pôles ; le méridien origine passe par Greenwich ;</li><li>la <strong>latitude</strong> se mesure de 0° à 90° Nord ou Sud ; la <strong>longitude</strong> de 0° à 180° Est ou Ouest.</li></ul>
