insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '6E' and p.series_id is null) and c.slug = 'le-conte') and slug = 'lire-et-comprendre-un-conte'), $html$<ul><li>Le conte commence souvent par une formule : « Il était une fois… », « Leeboon… » en wolof.</li><li>Il suit un <strong>schéma narratif</strong> : situation initiale, élément déclencheur, péripéties, dénouement, situation finale.</li><li>Les personnages sont souvent des animaux (Leuk-le-Lièvre, Bouki-l’Hyène) ou des humains face au merveilleux.</li><li>Le conte transmet une <strong>morale</strong> ou une leçon de vie.</li></ul>
