insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '6E' and p.series_id is null) and c.slug = 'greetings-and-introductions') and slug = 'hello-my-name-is'), $html$<table><thead><tr><th scope="col">English</th><th scope="col">Français</th></tr></thead><tbody><tr><td>Hello! / Hi! / Good morning!</td><td>Bonjour !</td></tr><tr><td>What’s your name? — My name is Awa.</td><td>Comment t’appelles-tu ? — Je m’appelle Awa.</td></tr><tr><td>How are you? — I’m fine, thank you.</td><td>Comment vas-tu ? — Je vais bien, merci.</td></tr><tr><td>Where are you from? — I’m from Senegal.</td><td>D’où viens-tu ? — Je viens du Sénégal.</td></tr><tr><td>Goodbye! / See you!</td><td>Au revoir ! / À bientôt !</td></tr></tbody></table>
