insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '6E' and p.series_id is null) and c.slug = 'numbers-the-alphabet-and-colours') and slug = 'numbers-letters-and-colours'), $html$<ul><li>1 one, 2 two, 3 three, 4 four, 5 five, 6 six, 7 seven, 8 eight, 9 nine, 10 ten ;</li><li>11 eleven, 12 twelve, 13 thirteen, 20 twenty, 30 thirty, 100 one hundred ;</li><li>the alphabet: A (ei), B (bi), C (si)… How do you spell your name? — A-W-A.</li><li>colours: red, green, yellow, blue, black, white. The Senegalese flag is green, yellow and red.</li></ul>
