insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '6E' and p.series_id is null) and c.slug = 'daily-routine-and-time') and slug = 'my-day'), $html$<ul><li>I get up at six o’clock. I go to school at half past seven. She has lunch at one o’clock.</li><li>Present simple: add -s with he / she / it: he plays, she goes, it watches.</li><li>Negative: I don’t / he doesn’t ; question: Do you…? / Does she…?</li><li>Days: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday.</li></ul>
