insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '6E' and p.series_id is null) and c.slug = 'food-and-the-market') and slug = 'at-the-market'), $html$<ul><li>rice, fish, bread, milk, mangoes, onions, tomatoes ;</li><li>countable nouns: a mango, two mangoes — How many mangoes? ;</li><li>uncountable nouns: rice, milk, water — How much rice? ;</li><li>some in affirmative sentences, any in questions and negatives: I have some rice. Have you got any milk?</li></ul>
