insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '6E' and p.series_id is null) and c.slug = 'weather-and-seasons') and slug = 'what-s-the-weather-like'), $html$<ul><li>It’s hot. It’s sunny. It’s windy. It’s raining. It’s cloudy.</li><li>In Senegal there are two seasons: the rainy season (July to October) and the dry season.</li><li>Look! It is raining now: present continuous (be + verb-ing) for what is happening now.</li></ul>
