insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '6E' and p.series_id is null) and c.slug = 'last-weekend') and slug = 'talking-about-the-past'), $html$<ul><li>to be: I was, you were, he was, we were, they were ;</li><li>regular verbs: add -ed: play → played, visit → visited, watch → watched ;</li><li>time words: yesterday, last week, last Sunday.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 1, 'introduction-a-l-etude-de-l-histoire', 'Introduction à l’étude de l’histoire', 'Définition, sources, méthodes, chronologie et intérêt de l’histoire.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
