insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'introduction-a-l-etude-de-l-histoire') and slug = 'qu-est-ce-que-l-histoire'), $html$<p>L’<strong>histoire</strong> est l’étude du passé des hommes à partir de <strong>sources</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 2, 'la-prehistoire', 'La préhistoire', 'Les grandes divisions de la préhistoire, la préhistoire africaine, préhistoire et protohistoire au Sénégal.', 2, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-prehistoire'), 1, 'les-grandes-divisions-de-la-prehistoire', 'Les grandes divisions de la préhistoire', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-prehistoire') and slug = 'les-grandes-divisions-de-la-prehistoire'), $html$<table><thead><tr><th scope="col">Période</th><th scope="col">Caractères</th></tr></thead><tbody><tr><td>paléolithique (pierre taillée)</td><td>chasse, pêche, cueillette ; nomadisme ; découverte du feu</td></tr><tr><td>néolithique (pierre polie)</td><td>agriculture, élevage, poterie ; sédentarisation dans des villages</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-prehistoire'), 2, 'l-afrique-berceau-de-l-humanite', 'L’Afrique, berceau de l’humanité', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-prehistoire') and slug = 'l-afrique-berceau-de-l-humanite'), $html$<ul><li>Les plus anciens restes humains ont été découverts en Afrique de l’Est (Éthiopie, Kenya, Tanzanie) : l’Afrique est le berceau de l’humanité.</li><li>Au néolithique, le Sahara était humide et peuplé : les peintures rupestres du Tassili montrent des chasseurs et des troupeaux.</li><li>Le dessèchement du Sahara a poussé les populations vers le sud et la vallée du Nil.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-prehistoire'), 3, 'prehistoire-et-protohistoire-au-senegal', 'Préhistoire et protohistoire au Sénégal', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-prehistoire') and slug = 'prehistoire-et-protohistoire-au-senegal'), $html$<ul><li>Des outils de pierre ont été trouvés dans la presqu’île du Cap-Vert et dans la vallée de la Falémé.</li><li>Les amas coquilliers du delta du Saloum témoignent d’anciennes populations de pêcheurs.</li><li>Les cercles mégalithiques (Sine Ngayène, Wanar) et les tumulus sont des monuments funéraires de la protohistoire.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 3, 'l-egypte-pharaonique', 'L’Égypte pharaonique', 'Le pays, les hommes, les grandes périodes et la civilisation égyptienne.', 3, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'l-egypte-pharaonique'), 1, 'le-pays-et-l-histoire-de-l-egypte', 'Le pays et l’histoire de l’Égypte', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'l-egypte-pharaonique') and slug = 'le-pays-et-l-histoire-de-l-egypte'), $html$<ul><li>L’Égypte est « un don du Nil » : la crue annuelle dépose le limon fertile.</li><li>Vers 3 000 av. J.-C., la Haute et la Basse-Égypte sont unifiées ; le roi est le <strong>pharaon</strong>.</li><li>Grandes périodes : Ancien Empire (pyramides de Gizeh), Moyen Empire, Nouvel Empire.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'l-egypte-pharaonique'), 2, 'la-civilisation-egyptienne', 'La civilisation égyptienne', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'l-egypte-pharaonique') and slug = 'la-civilisation-egyptienne'), $html$<ul><li>écriture : les <strong>hiéroglyphes</strong>, sur papyrus et sur les monuments ;</li><li>religion : de nombreux dieux (Rê, Osiris, Isis) ; croyance en la vie après la mort, momification ;</li><li>sciences : calendrier, mathématiques, médecine, architecture (pyramides, temples).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 4, 'la-nubie-l-ethiopie-et-les-relations-de-l-afrique-ancienne', 'La Nubie, l’Éthiopie et les relations de l’Afrique ancienne', 'La Nubie (Kerma, Napata, Méroé), l’Éthiopie (Axoum) et les échanges avec l’Afrique intérieure.', 4, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-nubie-l-ethiopie-et-les-relations-de-l-afrique-ancienne'), 1, 'la-nubie-et-l-ethiopie-antiques', 'La Nubie et l’Éthiopie antiques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-nubie-l-ethiopie-et-les-relations-de-l-afrique-ancienne') and slug = 'la-nubie-et-l-ethiopie-antiques'), $html$<ul><li>La <strong>Nubie</strong>, au sud de l’Égypte, a connu les royaumes de Kerma, de Napata puis de Méroé, célèbre pour son fer et ses pyramides.</li><li>Des pharaons noirs venus de Napata ont régné sur l’Égypte (XXV<sup>e</sup> dynastie).</li><li>En <strong>Éthiopie</strong>, le royaume d’Axoum était une puissance commerçante ; il adopta le christianisme au IV<sup>e</sup> siècle.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-nubie-l-ethiopie-et-les-relations-de-l-afrique-ancienne'), 2, 'relations-entre-l-afrique-du-nord-est-et-l-afrique-interieure', 'Relations entre l’Afrique du Nord-Est et l’Afrique intérieure', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-nubie-l-ethiopie-et-les-relations-de-l-afrique-ancienne') and slug = 'relations-entre-l-afrique-du-nord-est-et-l-afrique-interieure'), $html$<ul><li>migrations de populations après le dessèchement du Sahara ;</li><li>diffusion de la métallurgie du fer et de l’agriculture ;</li><li>échanges de produits : or, ivoire, sel, bétail ; influences culturelles.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 5, 'carthage', 'Carthage', 'La civilisation carthaginoise.', 5, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'carthage'), 1, 'la-civilisation-carthaginoise', 'La civilisation carthaginoise', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'carthage') and slug = 'la-civilisation-carthaginoise'), $html$<ul><li>Carthage, en Afrique du Nord (Tunisie actuelle), a été fondée par des Phéniciens au IX<sup>e</sup> siècle av. J.-C.</li><li>Grande puissance maritime et commerçante de la Méditerranée.</li><li>Rivale de Rome, elle est détruite en 146 av. J.-C. après les guerres puniques ; le général Hannibal avait traversé les Alpes avec des éléphants.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 6, 'les-civilisations-antiques-de-l-asie', 'Les civilisations antiques de l’Asie', 'La Mésopotamie et la Palestine : cadre, histoire et civilisation.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'les-civilisations-antiques-de-l-asie'), 1, 'la-mesopotamie', 'La Mésopotamie', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'les-civilisations-antiques-de-l-asie') and slug = 'la-mesopotamie'), $html$<ul><li>Entre le Tigre et l’Euphrate (Irak actuel) : premières villes et premiers États.</li><li>Invention de l’écriture <strong>cunéiforme</strong> sur des tablettes d’argile.</li><li>Le code d’Hammourabi, roi de Babylone, est l’un des premiers recueils de lois.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'les-civilisations-antiques-de-l-asie'), 2, 'la-palestine-foyer-du-monotheisme', 'La Palestine, foyer du monothéisme', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'les-civilisations-antiques-de-l-asie') and slug = 'la-palestine-foyer-du-monotheisme'), $html$<ul><li>Les Hébreux, établis en Palestine, croient en un Dieu unique : c’est le <strong>monothéisme</strong>.</li><li>Leur histoire est racontée dans la Bible ; Jérusalem en est la ville sainte.</li><li>La Palestine est le berceau du judaïsme et du christianisme ; l’islam reconnaît aussi ses prophètes.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 7, 'la-grece-antique', 'La Grèce antique', 'Le pays, les hommes, les grandes périodes et la civilisation grecque.', 7, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-grece-antique'), 1, 'les-cites-grecques', 'Les cités grecques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-grece-antique') and slug = 'les-cites-grecques'), $html$<ul><li>La Grèce est un pays montagneux, ouvert sur la mer : les Grecs vivaient dans des <strong>cités</strong> indépendantes (Athènes, Sparte).</li><li>Athènes invente la <strong>démocratie</strong> au V<sup>e</sup> siècle av. J.-C. (mais les femmes, les étrangers et les esclaves n’étaient pas citoyens).</li><li>Alexandre le Grand conquiert un immense empire ; il fonde Alexandrie en Égypte.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-grece-antique'), 2, 'la-civilisation-grecque', 'La civilisation grecque', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-grece-antique') and slug = 'la-civilisation-grecque'), $html$<ul><li>philosophie (Socrate, Platon, Aristote), sciences (Pythagore, Archimède), histoire (Hérodote) ;</li><li>théâtre, sculpture, temples (Parthénon) ; Jeux olympiques ;</li><li>les savants grecs ont étudié en Égypte : Alexandrie devint un grand centre de savoir.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 8, 'rome-de-la-cite-a-l-empire', 'Rome, de la cité à l’empire', 'Rome, la civilisation romaine et son évolution.', 8, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'rome-de-la-cite-a-l-empire'), 1, 'de-la-cite-romaine-a-l-empire', 'De la cité romaine à l’Empire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'rome-de-la-cite-a-l-empire') and slug = 'de-la-cite-romaine-a-l-empire'), $html$<table><thead><tr><th scope="col">Période</th><th scope="col">Faits</th></tr></thead><tbody><tr><td>royauté (753-509 av. J.-C.)</td><td>fondation légendaire de Rome par Romulus</td></tr><tr><td>République</td><td>Rome conquiert l’Italie, puis la Méditerranée (Carthage)</td></tr><tr><td>Empire (à partir de 27 av. J.-C.)</td><td>Auguste premier empereur ; la « paix romaine »</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'rome-de-la-cite-a-l-empire'), 2, 'la-civilisation-romaine', 'La civilisation romaine', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'rome-de-la-cite-a-l-empire') and slug = 'la-civilisation-romaine'), $html$<ul><li>droit romain, routes, aqueducs, villes avec forum, thermes et amphithéâtres ;</li><li>langue latine, à l’origine du français ;</li><li>l’Afrique du Nord romaine fournissait du blé ; des Africains sont devenus empereurs (Septime Sévère).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 9, 'le-christianisme-et-les-grandes-invasions', 'Le christianisme et les grandes invasions', 'La naissance et l’expansion du christianisme ; les grandes invasions en Europe et en Afrique.', 9, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-christianisme-et-les-grandes-invasions'), 1, 'le-christianisme-dans-le-monde-romain', 'Le christianisme dans le monde romain', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-christianisme-et-les-grandes-invasions') and slug = 'le-christianisme-dans-le-monde-romain'), $html$<ul><li>Jésus naît en Palestine sous l’Empire romain ; ses disciples diffusent son message.</li><li>Les chrétiens sont d’abord persécutés, puis l’empereur Constantin autorise le christianisme (313).</li><li>Il devient la religion officielle de l’Empire à la fin du IV<sup>e</sup> siècle ; saint Augustin, né en Afrique du Nord, en est un grand penseur.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-christianisme-et-les-grandes-invasions'), 2, 'les-grandes-invasions', 'Les grandes invasions', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-christianisme-et-les-grandes-invasions') and slug = 'les-grandes-invasions'), $html$<ul><li>Aux IV<sup>e</sup> et V<sup>e</sup> siècles, des peuples germaniques (Goths, Vandales, Francs) envahissent l’Empire romain d’Occident.</li><li>Les Vandales s’installent en Afrique du Nord et prennent Carthage (439).</li><li>L’Empire romain d’Occident disparaît en 476 ; celui d’Orient (Byzance) continue.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 10, 'introduction-a-la-geographie-s-orienter-et-lire-une-carte', 'Introduction à la géographie : s’orienter et lire une carte', 'Notions d’orientation et de représentation : carte, échelle, légende, latitude, longitude.', 10, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'introduction-a-la-geographie-s-orienter-et-lire-une-carte'), 1, 'la-carte-et-l-echelle', 'La carte et l’échelle', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'introduction-a-la-geographie-s-orienter-et-lire-une-carte') and slug = 'la-carte-et-l-echelle'), $html$<ul><li>La <strong>géographie</strong> étudie les relations entre les hommes et leur milieu.</li><li>Une <strong>carte</strong> représente un espace vu d’en haut, réduit ; elle a un titre, une <strong>légende</strong>, une <strong>échelle</strong> et une orientation (le nord en haut).</li><li>Échelle 1/100 000 : 1 cm sur la carte = 1 km en réalité.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 11, 'le-bassin-arachidier', 'Le Bassin arachidier', 'Étude régionale : la culture sous pluie, de la monoculture à la diversification.', 11, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-bassin-arachidier'), 1, 'situation-milieu-et-population', 'Situation, milieu et population', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-bassin-arachidier') and slug = 'situation-milieu-et-population'), $html$<ul><li>Au centre-ouest du Sénégal (régions de Kaolack, Kaffrine, Fatick, Diourbel, Thiès, Louga).</li><li>Plaines sableuses, climat soudano-sahélien, pluies de juillet à octobre.</li><li>Région très peuplée : Wolof et Sérères surtout ; nombreux villages et villes-marchés (Kaolack, Touba, Diourbel).</li><li>Principales plantes : arachide (culture de rente) et mil (culture vivrière).</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Pour étudier une région, on la situe d’abord sur la carte : où est-elle ? quelles sont ses limites ?</p></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-bassin-arachidier'), 2, 'activites-problemes-et-perspectives', 'Activités, problèmes et perspectives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-bassin-arachidier') and slug = 'activites-problemes-et-perspectives'), $html$<ul><li>Agriculture sous pluie : arachide, mil, niébé, maïs, pastèque ; usage du semoir et de la houe.</li><li>Transformation : huileries (Kaolack, Ziguinchor, Diourbel), artisanat (huile, pâte d’arachide).</li><li>Problèmes : appauvrissement des sols (monoculture), sécheresses, baisse des prix, exode rural.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>La diversification des cultures et la restauration des sols sont des enjeux majeurs pour le Bassin arachidier.</p></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 12, 'dakar-et-le-littoral-central', 'Dakar et le littoral central', 'Étude régionale : les activités urbaines et suburbaines.', 12, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'dakar-et-le-littoral-central'), 1, 'situation-milieu-et-population', 'Situation, milieu et population', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'dakar-et-le-littoral-central') and slug = 'situation-milieu-et-population'), $html$<ul><li>La presqu’île du Cap-Vert, à l’extrême ouest de l’Afrique ; littoral de Dakar à Mbour.</li><li>Climat doux grâce à l’alizé maritime ; Niayes (dépressions humides).</li><li>Forte concentration de population : plus d’un Sénégalais sur cinq vit dans la région de Dakar.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Pour étudier une région, on la situe d’abord sur la carte : où est-elle ? quelles sont ses limites ?</p></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'dakar-et-le-littoral-central'), 2, 'activites-problemes-et-perspectives', 'Activités, problèmes et perspectives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'dakar-et-le-littoral-central') and slug = 'activites-problemes-et-perspectives'), $html$<ul><li>Industrie, port, commerce, services, administration ; maraîchage dans les Niayes ; pêche (Kayar, Mbour, Joal) ; tourisme (Petite-Côte).</li><li>Grands projets : pôle urbain de Diamniadio, TER, autoroute, aéroport Blaise Diagne.</li><li>Problèmes : encombrements, inondations, logement, pollution, chômage des jeunes.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Dakar concentre l’essentiel des activités du pays : il faut mieux répartir le développement entre les régions.</p></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 13, 'le-ferlo', 'Le Ferlo', 'Étude régionale : le problème de l’eau et l’activité pastorale.', 13, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-ferlo'), 1, 'situation-milieu-et-population', 'Situation, milieu et population', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-ferlo') and slug = 'situation-milieu-et-population'), $html$<ul><li>Au nord du pays, entre la vallée du fleuve Sénégal et le Bassin arachidier.</li><li>Climat sahélien, pluies faibles ; vallée fossile du Ferlo ; steppe.</li><li>Population peu nombreuse, surtout peule, souvent mobile.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Pour étudier une région, on la situe d’abord sur la carte : où est-elle ? quelles sont ses limites ?</p></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-ferlo'), 2, 'activites-problemes-et-perspectives', 'Activités, problèmes et perspectives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-ferlo') and slug = 'activites-problemes-et-perspectives'), $html$<ul><li>Élevage extensif de bovins, ovins et caprins ; transhumance vers les points d’eau et les pâturages.</li><li>Forages et mares temporaires ; marchés hebdomadaires de bétail (louma).</li><li>Problèmes : manque d’eau, surpâturage, avancée du désert ; la Grande Muraille verte y plante des arbres.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Dans le Ferlo, l’eau commande la vie des hommes et des troupeaux.</p></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 14, 'la-vallee-du-fleuve-senegal', 'La vallée du fleuve Sénégal', 'Étude régionale : la vallée du fleuve et son aménagement.', 14, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-vallee-du-fleuve-senegal'), 1, 'situation-milieu-et-population', 'Situation, milieu et population', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-vallee-du-fleuve-senegal') and slug = 'situation-milieu-et-population'), $html$<ul><li>Au nord, le long du fleuve Sénégal, de Bakel à Saint-Louis.</li><li>Le <strong>walo</strong> (terres inondables) et le <strong>diéri</strong> (terres sèches) ; climat sahélien.</li><li>Populations toucouleur (haalpulaar), wolof, soninké ; forte émigration.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Pour étudier une région, on la situe d’abord sur la carte : où est-elle ? quelles sont ses limites ?</p></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-vallee-du-fleuve-senegal'), 2, 'activites-problemes-et-perspectives', 'Activités, problèmes et perspectives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-vallee-du-fleuve-senegal') and slug = 'activites-problemes-et-perspectives'), $html$<ul><li>Activités traditionnelles : cultures de décrue, élevage, pêche.</li><li>Aménagements modernes : barrages de Diama et de Manantali (OMVS), riziculture irriguée, tomate, canne à sucre (Richard-Toll).</li><li>Problèmes : salinisation, maladies hydriques, coût des aménagements.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Les barrages ont transformé l’agriculture de la vallée en permettant l’irrigation.</p></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 15, 'la-casamance', 'La Casamance', 'Étude régionale : l’étude d’un écosystème humide.', 15, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-casamance'), 1, 'situation-milieu-et-population', 'Situation, milieu et population', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-casamance') and slug = 'situation-milieu-et-population'), $html$<ul><li>Au sud du pays, séparée du reste du Sénégal par la Gambie.</li><li>Climat subguinéen, pluies abondantes ; forêts, rizières et mangroves le long du fleuve Casamance.</li><li>Populations diola, mandingue, peule, balante… ; villes : Ziguinchor, Kolda, Sédhiou.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Pour étudier une région, on la situe d’abord sur la carte : où est-elle ? quelles sont ses limites ?</p></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-casamance'), 2, 'activites-problemes-et-perspectives', 'Activités, problèmes et perspectives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'la-casamance') and slug = 'activites-problemes-et-perspectives'), $html$<ul><li>Riziculture, cueillette (fruits, huile de palme, vin de palme), pêche, arboriculture (mangues, anacarde), tourisme (Cap Skirring).</li><li>Problèmes : enclavement, déforestation, salinisation des rizières.</li><li>Atouts : très grandes potentialités agricoles et touristiques.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>La Casamance est le « grenier » potentiel du Sénégal ; le pont de Farafégny sur la Gambie facilite son désenclavement.</p></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null), 16, 'le-haut-senegal-sud-est', 'Le Haut-Sénégal (Sud-Est)', 'Étude régionale : une région de contact.', 16, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-haut-senegal-sud-est'), 1, 'situation-milieu-et-population', 'Situation, milieu et population', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-haut-senegal-sud-est') and slug = 'situation-milieu-et-population'), $html$<ul><li>Au sud-est (régions de Tambacounda et de Kédougou), en contact avec le Mali et la Guinée.</li><li>Relief le plus élevé du pays (contreforts du Fouta-Djalon) ; climat soudanien ; savanes et forêts claires.</li><li>Populations bassari, bédik, malinké, peule, diakhanké ; faible densité.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Pour étudier une région, on la situe d’abord sur la carte : où est-elle ? quelles sont ses limites ?</p></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-haut-senegal-sud-est'), 2, 'activites-problemes-et-perspectives', 'Activités, problèmes et perspectives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '6E' and p.series_id is null) and c.slug = 'le-haut-senegal-sud-est') and slug = 'activites-problemes-et-perspectives'), $html$<ul><li>Agriculture (coton, maïs), élevage, chasse et tourisme (parc national du Niokolo-Koba).</li><li>Mines : or (Sabodala), marbre, fer de la Falémé.</li><li>Problèmes : enclavement, orpaillage qui pollue les rivières, manque d’infrastructures.</li></ul><div class="callout"><p class="callout-title">À retenir</p><p>Le Sud-Est possède d’importantes richesses minières et naturelles à exploiter durablement.</p></div>$html$);
