insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '6E' and p.series_id is null) and c.slug = 'la-classification-des-etres-vivants') and slug = 'classer-les-etres-vivants'), $html$<p>Classer, c’est regrouper les êtres vivants qui ont des <strong>caractères communs</strong> (ce qu’ils possèdent).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '6E' and p.series_id is null), 2, 'la-repartition-des-etres-vivants', 'La répartition des êtres vivants', 'Les êtres vivants et les conditions du milieu : eau, lumière, température, sol.', 2, 'published', null, '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '6E' and p.series_id is null) and c.slug = 'la-repartition-des-etres-vivants'), 1, 'les-etres-vivants-et-leur-milieu', 'Les êtres vivants et leur milieu', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '6E' and p.series_id is null) and c.slug = 'la-repartition-des-etres-vivants') and slug = 'les-etres-vivants-et-leur-milieu'), $html$<ul><li>Chaque espèce vit là où les conditions lui conviennent : c’est son <strong>milieu de vie</strong>.</li><li>Facteurs du milieu : eau (humidité), lumière, température, nature du sol.</li><li>La mangrove pousse dans l’eau salée des estuaires ; les cactus et les épineux résistent à la sécheresse ; le palétuvier a des racines aériennes.</li><li>Certains animaux changent de milieu selon les saisons : migrations des oiseaux (parc du Djoudj).</li></ul>
