insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '6E' and p.series_id is null) and c.slug = 'la-production-d-aliments-par-les-vegetaux-chlorophylliens') and slug = 'les-besoins-nutritifs-de-la-plante-verte'), $html$<ul><li>La plante puise par ses racines l’<strong>eau</strong> et les <strong>sels minéraux</strong> du sol : c’est la sève brute.</li><li>Les feuilles absorbent le <strong>dioxyde de carbone</strong> de l’air.</li><li>Elles ont besoin de <strong>lumière</strong> et de <strong>chlorophylle</strong> (pigment vert).</li></ul>
