insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '6E' and p.series_id is null) and c.slug = 'l-amelioration-de-la-production-d-aliments') and slug = 'produire-plus-et-mieux'), $html$<table><thead><tr><th scope="col">Production végétale</th><th scope="col">Production animale</th></tr></thead><tbody><tr><td>semences sélectionnées (variétés de mil, d’arachide résistantes à la sécheresse)</td><td>sélection de races plus productives (vaches laitières, poulets de chair)</td></tr><tr><td>engrais (fumier, compost, engrais chimiques)</td><td>alimentation équilibrée (son, tourteau d’arachide)</td></tr><tr><td>irrigation (vallée du fleuve, Niayes)</td><td>vaccination et soins vétérinaires</td></tr><tr><td>lutte contre les ravageurs (criquets)</td><td>embouche, aviculture, aquaculture</td></tr></tbody></table>
