insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'addition-et-soustraction-des-nombres-relatifs') and slug = 'additionner-et-soustraire-des-relatifs'), $html$<ul><li>deux nombres de même signe : on additionne leurs distances à zéro et on garde le signe : (−3) + (−5) = −8 ;</li><li>deux nombres de signes contraires : on soustrait les distances à zéro et on prend le signe du plus éloigné de zéro : (+7) + (−10) = −3 ;</li><li>soustraire un nombre, c’est ajouter son opposé : 4 − (−6) = 4 + 6 = 10.</li></ul>
