insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'puissances') and slug = 'definition-et-proprietes-des-puissances'), $html$<p class="formula">a<sup>n</sup> = a × a × … × a (n facteurs) ; a<sup>1</sup> = a ; a<sup>0</sup> = 1 (a ≠ 0)</p>
