insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'multiples-et-diviseurs'), 1, 'multiples-diviseurs-et-nombres-premiers', 'Multiples, diviseurs et nombres premiers', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'multiples-et-diviseurs') and slug = 'multiples-diviseurs-et-nombres-premiers'), $html$<ul><li>a est un <strong>multiple</strong> de b s’il existe un entier k tel que a = k × b ; on dit aussi que b est un <strong>diviseur</strong> de a ;</li><li>critères : par 2, 5, 10 (dernier chiffre), par 3 et 9 (somme des chiffres), par 4 (deux derniers chiffres) ;</li><li>un nombre <strong>premier</strong> a exactement deux diviseurs : 1 et lui-même (2, 3, 5, 7, 11, 13…).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null), 5, 'les-fractions', 'Les fractions', 'Simplification, comparaison et opérations sur les fractions.', 5, 'published', 'Activités numériques', '[{"title":"Guide pédagogique de mathématiques, classe de cinquième (MEN, DEMSG, 2010), APAMS","url":"https://apams.gouv.sn/sites/default/files/Guide%20Pedagogique_MATHS_5EME.pdf","kind":"official"},{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-fractions'), 1, 'simplifier-et-comparer-des-fractions', 'Simplifier et comparer des fractions', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-fractions') and slug = 'simplifier-et-comparer-des-fractions'), $html$<ul><li>on simplifie en divisant numérateur et dénominateur par un même nombre : <span class="frac"><span>18</span><span>24</span></span> = <span class="frac"><span>3</span><span>4</span></span> ;</li><li>pour comparer, on réduit au même dénominateur : <span class="frac"><span>2</span><span>3</span></span> = <span class="frac"><span>8</span><span>12</span></span> et <span class="frac"><span>3</span><span>4</span></span> = <span class="frac"><span>9</span><span>12</span></span>, donc <span class="frac"><span>2</span><span>3</span></span> &lt; <span class="frac"><span>3</span><span>4</span></span>.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-fractions'), 2, 'operations-sur-les-fractions', 'Opérations sur les fractions', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-fractions') and slug = 'operations-sur-les-fractions'), $html$<table><thead><tr><th scope="col">Opération</th><th scope="col">Règle</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>addition</td><td>même dénominateur, puis on additionne les numérateurs</td><td><span class="frac"><span>1</span><span>4</span></span> + <span class="frac"><span>1</span><span>6</span></span> = <span class="frac"><span>3</span><span>12</span></span> + <span class="frac"><span>2</span><span>12</span></span> = <span class="frac"><span>5</span><span>12</span></span></td></tr><tr><td>multiplication</td><td>numérateurs entre eux, dénominateurs entre eux</td><td><span class="frac"><span>2</span><span>3</span></span> × <span class="frac"><span>9</span><span>4</span></span> = <span class="frac"><span>18</span><span>12</span></span> = <span class="frac"><span>3</span><span>2</span></span></td></tr><tr><td>division</td><td>multiplier par l’inverse</td><td><span class="frac"><span>3</span><span>5</span></span> ÷ <span class="frac"><span>9</span><span>10</span></span> = <span class="frac"><span>3</span><span>5</span></span> × <span class="frac"><span>10</span><span>9</span></span> = <span class="frac"><span>2</span><span>3</span></span></td></tr></tbody></table>
