insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'proportionnalite-et-pourcentages') and slug = 'quatrieme-proportionnelle-et-pourcentages'), $html$<div class="callout"><p class="callout-title">Quatrième proportionnelle</p><ol><li>Dans un tableau de proportionnalité, a/b = c/d.</li><li>On calcule la quatrième proportionnelle par le produit en croix : d = b × c ÷ a.</li></ol></div>
