insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'reperage-dans-le-plan') and slug = 'coordonnees-relatives'), $html$<ul><li>dans un repère, un point a une abscisse et une ordonnée qui peuvent être négatives : A(−2 ; 3) ;</li><li>les axes partagent le plan en quatre quadrants ;</li><li>le symétrique de M(x ; y) par rapport à l’origine est M’(−x ; −y).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null), 9, 'les-angles', 'Les angles', 'Angles opposés par le sommet, angles formés par deux parallèles et une sécante.', 9, 'published', 'Activités géométriques', '[{"title":"Guide pédagogique de mathématiques, classe de cinquième (MEN, DEMSG, 2010), APAMS","url":"https://apams.gouv.sn/sites/default/files/Guide%20Pedagogique_MATHS_5EME.pdf","kind":"official"},{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
