insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-angles') and slug = 'angles-et-droites-paralleles'), $html$<ul><li>deux angles <strong>opposés par le sommet</strong> ont la même mesure ;</li><li>deux droites parallèles coupées par une sécante forment des angles <strong>alternes-internes</strong> égaux et des angles <strong>correspondants</strong> égaux ;</li><li>réciproquement, si deux angles alternes-internes sont égaux, les droites sont parallèles.</li></ul>
