insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-triangles') and slug = 'construire-un-triangle'), $html$<div class="callout"><p class="callout-title">À retenir</p><p>Inégalité triangulaire : dans un triangle, chaque côté est plus petit que la somme des deux autres. On ne peut pas construire un triangle de côtés 3 cm, 4 cm et 9 cm.</p></div>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-triangles'), 2, 'mediatrices-et-hauteurs', 'Médiatrices et hauteurs', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '5E' and p.series_id is null) and c.slug = 'les-triangles') and slug = 'mediatrices-et-hauteurs'), $html$<ul><li>les trois <strong>médiatrices</strong> d’un triangle se coupent en un point, centre du <strong>cercle circonscrit</strong> (il passe par les trois sommets) ;</li><li>une <strong>hauteur</strong> est la droite passant par un sommet et perpendiculaire au côté opposé ; les trois hauteurs sont concourantes.</li></ul>
