insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '5E' and p.series_id is null) and c.slug = 'le-recit-d-aventure') and slug = 'lire-un-recit-d-aventure'), $html$<ul><li>Le héros affronte des obstacles et des dangers : ce sont les <strong>péripéties</strong>.</li><li>Le <strong>suspense</strong> tient le lecteur en haleine : on veut savoir la suite.</li><li>Le narrateur peut être un personnage (« je ») ou extérieur à l’histoire (« il »).</li></ul>
