insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '5E' and p.series_id is null) and c.slug = 'initiation-a-la-poesie') and slug = 'lire-un-poeme'), $html$<ul><li>Un poème est écrit en <strong>vers</strong>, regroupés en <strong>strophes</strong> ;</li><li>les <strong>rimes</strong> sont les sons répétés en fin de vers ;</li><li>les <strong>images</strong> (comparaisons, métaphores) font voir et ressentir.</li></ul>
