insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '5E' and p.series_id is null) and c.slug = 'plans-for-the-future') and slug = 'what-are-you-going-to-do'), $html$<ul><li>going to for plans: I am going to visit my uncle next week.</li><li>will for predictions and decisions: It will rain tomorrow. I will help you.</li><li>time words: tomorrow, next week, next year, soon.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 1, 'le-monde-a-la-fin-du-vie-siecle', 'Le monde à la fin du VIe siècle', 'L’Europe, l’Asie et l’Afrique vers 600.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
