insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-monde-a-la-fin-du-vie-siecle') and slug = 'le-monde-vers-l-an-600'), $html$<ul><li>En Europe, l’Empire romain d’Occident a disparu ; des royaumes germaniques se partagent son territoire ; l’Empire byzantin (Constantinople) domine l’Orient.</li><li>En Arabie, des tribus nomades et des villes commerçantes (La Mecque) ; la plupart sont polythéistes.</li><li>En Afrique, l’empire du Ghana se développe ; Axoum domine la mer Rouge.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 2, 'la-civilisation-musulmane', 'La civilisation musulmane', 'La naissance de l’islam, l’expansion musulmane et la civilisation musulmane.', 2, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-civilisation-musulmane'), 1, 'la-naissance-de-l-islam', 'La naissance de l’islam', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-civilisation-musulmane') and slug = 'la-naissance-de-l-islam'), $html$<ul><li>Muhammad, né vers 570 à La Mecque, reçoit la révélation vers 610.</li><li>En 622, il émigre à Médine : c’est l’hégire, début du calendrier musulman.</li><li>Le Coran est le livre saint de l’islam ; les cinq piliers sont la profession de foi, la prière, l’aumône, le jeûne du Ramadan et le pèlerinage.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-civilisation-musulmane'), 2, 'l-expansion-et-l-organisation-du-monde-musulman', 'L’expansion et l’organisation du monde musulman', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-civilisation-musulmane') and slug = 'l-expansion-et-l-organisation-du-monde-musulman'), $html$<ul><li>Après la mort du Prophète (632), les califes conquièrent la Syrie, l’Égypte, la Perse, l’Afrique du Nord et l’Espagne.</li><li>Capitales successives : Médine, Damas (Omeyyades), Bagdad (Abbassides).</li><li>L’islam gagne l’Afrique de l’Ouest par le commerce transsaharien.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-civilisation-musulmane'), 3, 'la-civilisation-musulmane', 'La civilisation musulmane', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-civilisation-musulmane') and slug = 'la-civilisation-musulmane'), $html$<ul><li>villes brillantes : Bagdad, Le Caire, Cordoue ;</li><li>sciences : algèbre, chiffres arabes, médecine (Avicenne), astronomie ;</li><li>arts : mosquées, calligraphie, arabesques.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 3, 'les-empires-du-ghana-et-du-mali', 'Les empires du Ghana et du Mali', 'Formation, expansion et civilisation du Ghana et du Mali ; le mouvement almoravide.', 3, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'les-empires-du-ghana-et-du-mali'), 1, 'l-empire-du-ghana-et-le-mouvement-almoravide', 'L’empire du Ghana et le mouvement almoravide', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'les-empires-du-ghana-et-du-mali') and slug = 'l-empire-du-ghana-et-le-mouvement-almoravide'), $html$<ul><li>Empire soninké, riche grâce à l’or et au commerce avec les marchands d’Afrique du Nord (relation avec Aoudaghost) ; capitale Koumbi Saleh.</li><li>Les <strong>Almoravides</strong>, mouvement religieux berbère né au XI<sup>e</sup> siècle, conquièrent le Maroc et l’Espagne et affaiblissent le Ghana (prise de Koumbi en 1076, selon la tradition).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'les-empires-du-ghana-et-du-mali'), 2, 'l-empire-du-mali', 'L’empire du Mali', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'les-empires-du-ghana-et-du-mali') and slug = 'l-empire-du-mali'), $html$<ul><li>Soundjata Keïta fonde l’empire après sa victoire de Kirina (vers 1235) ; la charte du Kouroukan Fouga organise la société.</li><li>Kankou Moussa fait un célèbre pèlerinage à La Mecque (1324) ; Tombouctou devient un centre de savoir.</li><li>L’empire s’étend de l’Atlantique au Niger.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 4, 'l-empire-songhai-et-les-royaumes-du-golfe-de-guinee', 'L’empire Songhaï et les royaumes du golfe de Guinée', 'L’empire Songhaï ; les cités yoruba et le royaume du Bénin.', 4, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-empire-songhai-et-les-royaumes-du-golfe-de-guinee'), 1, 'l-empire-songhai', 'L’empire Songhaï', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-empire-songhai-et-les-royaumes-du-golfe-de-guinee') and slug = 'l-empire-songhai'), $html$<ul><li>capitale Gao, sur le Niger ;</li><li>Sonni Ali Ber agrandit l’empire ; Askia Mohammed l’organise et développe l’islam et les études ;</li><li>défaite face au Maroc à Tondibi (1591).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-empire-songhai-et-les-royaumes-du-golfe-de-guinee'), 2, 'les-royaumes-du-golfe-de-guinee', 'Les royaumes du golfe de Guinée', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-empire-songhai-et-les-royaumes-du-golfe-de-guinee') and slug = 'les-royaumes-du-golfe-de-guinee'), $html$<ul><li>les cités yoruba (Ifé, Oyo) : villes fortifiées, art du bronze et de la terre cuite ;</li><li>le royaume du Bénin : célèbres plaques de bronze du palais de l’oba.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 5, 'la-senegambie-du-xie-au-xvie-siecle', 'La Sénégambie du XIe au XVIe siècle', 'Cadre et peuplement ; le Tékrour et le Fouta ; l’empire du Djolof ; l’empire du Gaabu ; unité et diversité.', 5, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-senegambie-du-xie-au-xvie-siecle'), 1, 'le-tekrour-et-l-empire-du-djolof', 'Le Tékrour et l’empire du Djolof', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-senegambie-du-xie-au-xvie-siecle') and slug = 'le-tekrour-et-l-empire-du-djolof'), $html$<ul><li>La Sénégambie s’étend entre le fleuve Sénégal et le fleuve Gambie ; elle est peuplée de Wolof, Sérères, Peuls, Toucouleurs, Mandingues, Diolas…</li><li>Le <strong>Tékrour</strong>, dans la vallée du fleuve, adopte l’islam au XI<sup>e</sup> siècle.</li><li>L’empire du <strong>Djolof</strong>, fondé par Ndiadiane Ndiaye, regroupe le Walo, le Cayor, le Baol, le Sine et le Saloum ; il se disloque au XVI<sup>e</sup> siècle (bataille de Danki).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-senegambie-du-xie-au-xvie-siecle'), 2, 'l-empire-du-gaabu-et-l-unite-des-civilisations', 'L’empire du Gaabu et l’unité des civilisations', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-senegambie-du-xie-au-xvie-siecle') and slug = 'l-empire-du-gaabu-et-l-unite-des-civilisations'), $html$<ul><li>Le <strong>Gaabu</strong>, royaume mandingue du sud, dirigé par un mansa, s’étend vers la Guinée-Bissau ; sa noblesse guerrière est celle des nyantio.</li><li>Unité : économie agricole, organisation sociale hiérarchisée, rôle des griots, influence de l’islam.</li><li>Diversité : langues, religions traditionnelles, organisation politique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 6, 'l-europe-du-xe-au-xvie-siecle', 'L’Europe du Xe au XVIe siècle', 'Le système féodal ; l’humanisme et la Renaissance.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-europe-du-xe-au-xvie-siecle'), 1, 'le-systeme-feodal', 'Le système féodal', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-europe-du-xe-au-xvie-siecle') and slug = 'le-systeme-feodal'), $html$<ul><li>Le seigneur donne une terre (fief) à un vassal qui lui doit fidélité et aide militaire.</li><li>Les paysans (serfs) travaillent la terre du seigneur et paient des redevances.</li><li>L’Église joue un grand rôle dans la vie des gens.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-europe-du-xe-au-xvie-siecle'), 2, 'l-humanisme-et-la-renaissance', 'L’humanisme et la Renaissance', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-europe-du-xe-au-xvie-siecle') and slug = 'l-humanisme-et-la-renaissance'), $html$<ul><li>Aux XV<sup>e</sup> et XVI<sup>e</sup> siècles, les humanistes redécouvrent les textes antiques et placent l’homme au centre de leur réflexion.</li><li>L’imprimerie (Gutenberg, vers 1450) diffuse les livres.</li><li>Les artistes de la Renaissance (Léonard de Vinci, Michel-Ange) renouvellent l’art.</li></ul>
