insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-amerique-precolombienne-et-les-grands-voyages'), 1, 'les-civilisations-precolombiennes', 'Les civilisations précolombiennes', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-amerique-precolombienne-et-les-grands-voyages') and slug = 'les-civilisations-precolombiennes'), $html$<table><thead><tr><th scope="col">Civilisation</th><th scope="col">Région</th><th scope="col">Caractères</th></tr></thead><tbody><tr><td>Mayas</td><td>Mexique, Guatemala</td><td>écriture, calendrier, pyramides</td></tr><tr><td>Aztèques</td><td>Mexique (Tenochtitlan)</td><td>empire guerrier, temples</td></tr><tr><td>Incas</td><td>Andes (Cuzco)</td><td>empire organisé, routes, Machu Picchu</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-amerique-precolombienne-et-les-grands-voyages'), 2, 'les-grands-voyages-de-decouvertes', 'Les grands voyages de découvertes', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'l-amerique-precolombienne-et-les-grands-voyages') and slug = 'les-grands-voyages-de-decouvertes'), $html$<ul><li>Les Portugais longent les côtes africaines (Gorée, cap Vert vers 1444) et atteignent l’Inde (Vasco de Gama, 1498).</li><li>Christophe Colomb atteint l’Amérique en 1492 ; Magellan fait le premier tour du monde (1519-1522).</li><li>Ces voyages préparent la colonisation et la traite négrière.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 8, 'le-senegal-situation-geologie-et-relief', 'Le Sénégal : situation, géologie et relief', 'Situation et représentation du territoire, structure géologique et relief.', 8, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-situation-geologie-et-relief'), 1, 'situation-et-relief-du-senegal', 'Situation et relief du Sénégal', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-situation-geologie-et-relief') and slug = 'situation-et-relief-du-senegal'), $html$<ul><li>Le Sénégal (196 722 km²) est à l’extrême ouest de l’Afrique, entre 12° et 16°30 de latitude Nord.</li><li>Il est formé surtout d’un grand bassin sédimentaire (roches déposées par la mer) ; le socle ancien n’apparaît qu’au sud-est.</li><li>Le relief est bas et plat : plaines, plateaux bas, dunes du littoral ; les points les plus hauts (environ 600 m) sont au sud-est.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null), 9, 'le-senegal-climat-eaux-sols-vegetation-et-ecosystemes', 'Le Sénégal : climat, eaux, sols, végétation et écosystèmes', 'Climat, hydrographie, sols, végétation et écosystèmes du Sénégal.', 9, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-climat-eaux-sols-vegetation-et-ecosystemes'), 1, 'le-climat-et-l-hydrographie', 'Le climat et l’hydrographie', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-climat-eaux-sols-vegetation-et-ecosystemes') and slug = 'le-climat-et-l-hydrographie'), $html$<ul><li>Climat tropical à deux saisons ; les pluies diminuent du sud (plus de 1 000 mm) au nord (moins de 400 mm).</li><li>On représente le climat d’une ville par un <strong>diagramme climatique</strong> (températures en courbe, pluies en bâtons).</li><li>Fleuves : Sénégal, Gambie, Casamance ; Saloum (estuaire) ; lac de Guiers ; nappes souterraines.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-climat-eaux-sols-vegetation-et-ecosystemes'), 2, 'sols-vegetation-et-ecosystemes', 'Sols, végétation et écosystèmes', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-climat-eaux-sols-vegetation-et-ecosystemes') and slug = 'sols-vegetation-et-ecosystemes'), $html$<table><thead><tr><th scope="col">Zone</th><th scope="col">Végétation</th><th scope="col">Sols</th></tr></thead><tbody><tr><td>nord</td><td>steppe à épineux</td><td>sableux, pauvres</td></tr><tr><td>centre</td><td>savane arbustive et arborée</td><td>sols ferrugineux (« dior », « deck »)</td></tr><tr><td>sud</td><td>forêt claire, rizières</td><td>sols plus riches</td></tr><tr><td>littoral</td><td>mangrove, filaos</td><td>sols salés ou sableux</td></tr></tbody></table>
