insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-population-du-senegal'), 1, 'peuplement-et-accroissement', 'Peuplement et accroissement', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-population-du-senegal') and slug = 'peuplement-et-accroissement'), $html$<ul><li>Peuples : Wolof (les plus nombreux), Pulaar, Sérères, Diolas, Mandingues, Soninkés… ; le français est la langue officielle ; wolof, pulaar, sérère, diola, mandingue, soninké… sont des langues nationales ;</li><li>religions : islam majoritaire, christianisme, religions traditionnelles ;</li><li>la population augmente vite (environ 18 millions en 2023) : forte natalité, recul de la mortalité.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-population-du-senegal'), 2, 'structures-repartition-mobilite-et-villes', 'Structures, répartition, mobilité et villes', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'la-population-du-senegal') and slug = 'structures-repartition-mobilite-et-villes'), $html$<ul><li>La <strong>pyramide des âges</strong> du Sénégal a une base large : la population est très jeune.</li><li>Répartition inégale : forte densité à l’ouest (Dakar, Thiès, Diourbel), faible à l’est.</li><li>Mobilité : exode rural, migrations saisonnières, émigration à l’étranger.</li><li>Villes principales : Dakar, Touba, Thiès, Kaolack, Saint-Louis, Ziguinchor, Mbour.</li></ul>
