insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'agriculture-elevage-et-peche-au-senegal') and slug = 'le-secteur-primaire'), $html$<table><thead><tr><th scope="col">Activité</th><th scope="col">Caractères</th></tr></thead><tbody><tr><td>agriculture</td><td>surtout sous pluie ; arachide, mil, maïs, niébé ; riz irrigué dans la vallée du fleuve ; horticulture dans les Niayes</td></tr><tr><td>élevage</td><td>extensif, transhumant (Ferlo) ; bovins, ovins, caprins ; moutons de Tabaski</td></tr><tr><td>pêche</td><td>artisanale (pirogues) et industrielle ; première source de devises d’exportation</td></tr></tbody></table>
