insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'industrie-tourisme-transports-et-echanges') and slug = 'industrie-tourisme-et-echanges'), $html$<ul><li>Artisanat (tissage, bijouterie, cordonnerie) et industries (huileries, conserveries de poisson, ciment, phosphates et engrais) concentrées autour de Dakar ;</li><li>tourisme : Petite-Côte (Saly), Cap Skirring, Saint-Louis, delta du Saloum ;</li><li>transports : routes, autoroutes, port de Dakar, aéroport Blaise Diagne, TER ;</li><li>échanges extérieurs : exportations de poisson, or, phosphates, arachide ; importations de riz, pétrole, machines.</li></ul>
