insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-problemes-et-perspectives'), 1, 'les-grands-defis-du-senegal', 'Les grands défis du Sénégal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '5E' and p.series_id is null) and c.slug = 'le-senegal-problemes-et-perspectives') and slug = 'les-grands-defis-du-senegal'), $html$<ul><li>La <strong>jeunesse</strong> de la population : fardeau (écoles, emplois à créer) ou potentialité (force de travail, créativité) ?</li><li>Les <strong>relations villes-campagnes</strong> : la ville attire, la campagne la nourrit.</li><li>Les <strong>disparités régionales</strong> : Dakar concentre les richesses ; la décentralisation et la régionalisation cherchent à mieux répartir le développement.</li><li>Les <strong>problèmes d’environnement</strong> : déforestation, érosion côtière, pollution.</li></ul>
