insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'l-alimentation-chez-les-animaux') and slug = 'regimes-alimentaires-et-dentition'), $html$<table><thead><tr><th scope="col">Régime</th><th scope="col">Exemple</th><th scope="col">Dentition</th></tr></thead><tbody><tr><td>herbivore</td><td>mouton, vache</td><td>incisives coupantes, molaires larges pour broyer, pas de canines (ruminants)</td></tr><tr><td>carnivore</td><td>chien, lion</td><td>canines pointues pour déchirer, molaires tranchantes</td></tr><tr><td>omnivore</td><td>homme, porc</td><td>dents variées</td></tr></tbody></table>
