insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-besoins-de-l-organisme-et-la-mauvaise-alimentation') and slug = 'les-besoins-de-l-organisme'), $html$<table><thead><tr><th scope="col">Groupe d’aliments</th><th scope="col">Rôle</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>glucides et lipides</td><td>énergie</td><td>mil, riz, sucre, huile</td></tr><tr><td>protides (protéines)</td><td>construction, croissance</td><td>poisson, viande, œufs, niébé, lait</td></tr><tr><td>vitamines et sels minéraux</td><td>protection, bon fonctionnement</td><td>fruits, légumes, feuilles</td></tr><tr><td>eau</td><td>indispensable à la vie</td><td>boissons, aliments</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-besoins-de-l-organisme-et-la-mauvaise-alimentation'), 2, 'les-maladies-dues-a-une-mauvaise-alimentation', 'Les maladies dues à une mauvaise alimentation', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-besoins-de-l-organisme-et-la-mauvaise-alimentation') and slug = 'les-maladies-dues-a-une-mauvaise-alimentation'), $html$<ul><li>carences : kwashiorkor (manque de protéines), marasme (manque de tout), anémie (fer), goitre (iode), scorbut (vitamine C) ;</li><li>excès : obésité, diabète, hypertension (trop de sucre, de gras, de sel) ;</li><li>intoxications alimentaires : aliments mal conservés.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null), 3, 'le-cadre-de-vie', 'Le cadre de vie', 'Le milieu de vie de l’homme, sa dégradation et sa protection.', 3, 'published', null, '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'le-cadre-de-vie'), 1, 'ameliorer-son-cadre-de-vie', 'Améliorer son cadre de vie', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'le-cadre-de-vie') and slug = 'ameliorer-son-cadre-de-vie'), $html$<ul><li>Le cadre de vie comprend le logement, le quartier, l’école, l’air, l’eau et les espaces verts.</li><li>Dégradations : ordures, eaux usées, bruit, fumées, insalubrité, inondations.</li><li>Conséquences : maladies (paludisme, choléra, maladies respiratoires).</li><li>Solutions : assainissement, gestion des déchets, reboisement, éducation à l’environnement.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null), 4, 'les-sols', 'Les sols', 'Formation, composition, types de sols, érosion et conservation.', 4, 'published', null, '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-sols'), 1, 'formation-et-composition-du-sol', 'Formation et composition du sol', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-sols') and slug = 'formation-et-composition-du-sol'), $html$<ul><li>Le sol se forme lentement par l’altération de la roche (chaleur, eau, racines) et l’apport de matière organique (humus).</li><li>Il contient des éléments minéraux (sable, argile, limon), de l’humus, de l’eau, de l’air et des êtres vivants.</li><li>Au Sénégal : sols « dior » (sableux, filtrants) et « deck » (plus argileux, plus riches).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-sols'), 2, 'l-erosion-et-la-conservation-des-sols', 'L’érosion et la conservation des sols', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-sols') and slug = 'l-erosion-et-la-conservation-des-sols'), $html$<ul><li>L’érosion éolienne (vent) et hydrique (ruissellement) emporte la terre fertile.</li><li>Causes aggravantes : déforestation, feux de brousse, surpâturage.</li><li>Conservation : haies brise-vent, diguettes, reboisement, jachère, fumure organique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null), 5, 'les-roches-sedimentaires', 'Les roches sédimentaires', 'Formation par sédimentation, quelques roches, fossiles, roches du Sénégal.', 5, 'published', null, '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-roches-sedimentaires'), 1, 'formation-des-roches-sedimentaires', 'Formation des roches sédimentaires', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '5E' and p.series_id is null) and c.slug = 'les-roches-sedimentaires') and slug = 'formation-des-roches-sedimentaires'), $html$<ul><li>Des débris (sables, argiles, coquilles) se déposent en couches au fond de l’eau : c’est la <strong>sédimentation</strong>.</li><li>Avec le temps, les couches se tassent et durcissent : elles deviennent des roches (grès, calcaire, argile).</li><li>Elles contiennent souvent des <strong>fossiles</strong>, restes d’êtres vivants anciens.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null), 1, 'les-nombres-rationnels', 'Les nombres rationnels', 'L’ensemble Q, écritures d’un rationnel, opérations, puissances, valeur absolue, comparaison.', 1, 'published', 'Activités numériques', '[{"title":"Programme de mathématiques du premier cycle, classe de quatrième (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_1er_cycle_4_me.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-nombres-rationnels'), 1, 'ecritures-et-operations-dans-q', 'Écritures et opérations dans Q', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-nombres-rationnels') and slug = 'ecritures-et-operations-dans-q'), $html$<p>Un <strong>nombre rationnel</strong> s’écrit <span class="frac"><span>a</span><span>b</span></span> avec a entier relatif et b entier relatif non nul. L’ensemble des rationnels se note <strong>Q</strong> : N ⊂ Z ⊂ D ⊂ Q.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-nombres-rationnels'), 2, 'puissances-valeur-absolue-et-comparaison', 'Puissances, valeur absolue et comparaison', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-nombres-rationnels') and slug = 'puissances-valeur-absolue-et-comparaison'), $html$<ul><li>a<sup>−n</sup> = <span class="frac"><span>1</span><span>a<sup>n</sup></span></span> (a ≠ 0) : 2<sup>−3</sup> = <span class="frac"><span>1</span><span>8</span></span> ;</li><li>la valeur absolue |a| est la distance de a à zéro : |−5| = 5 ; si |a| = |b| alors a = b ou a = −b ;</li><li><span class="frac"><span>a</span><span>b</span></span> = <span class="frac"><span>c</span><span>d</span></span> équivaut à a × d = b × c (produits en croix) ;</li><li>a &gt; b équivaut à a − b &gt; 0 ;</li><li>multiplier les deux membres d’une inégalité par un nombre négatif change son sens.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null), 2, 'le-calcul-algebrique', 'Le calcul algébrique', 'Développer, réduire et factoriser une expression littérale ; égalités remarquables.', 2, 'published', 'Activités numériques', '[{"title":"Programme de mathématiques du premier cycle, classe de quatrième (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_1er_cycle_4_me.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'le-calcul-algebrique'), 1, 'developper-et-reduire', 'Développer et réduire', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'le-calcul-algebrique') and slug = 'developper-et-reduire'), $html$<ul><li>k(a + b) = ka + kb ; (a + b)(c + d) = ac + ad + bc + bd ;</li><li>(a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup> ;</li><li>(a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup> ;</li><li>(a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup>.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'le-calcul-algebrique'), 2, 'factoriser', 'Factoriser', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'le-calcul-algebrique') and slug = 'factoriser'), $html$<div class="callout"><p class="callout-title">Méthode pour factoriser</p><ol><li>Chercher un facteur commun : (x + 1)(2x − 3) + (x + 1)(x + 5) = (x + 1)(3x + 2).</li><li>Sinon, reconnaître une égalité remarquable : x<sup>2</sup> − 9 = (x − 3)(x + 3) ; 4x<sup>2</sup> + 12x + 9 = (2x + 3)<sup>2</sup>.</li><li>Vérifier en redéveloppant.</li></ol></div>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null), 3, 'les-equations-a-une-inconnue', 'Les équations à une inconnue', 'Équations ax + b = 0, équations produit, équations a/x = b ; mise en équation.', 3, 'published', 'Activités numériques', '[{"title":"Programme de mathématiques du premier cycle, classe de quatrième (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_1er_cycle_4_me.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
