insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-equations-a-une-inconnue') and slug = 'resoudre-une-equation'), $html$<ul><li>ax + b = 0 avec a ≠ 0 : x = <span class="frac"><span>−b</span><span>a</span></span> ;</li><li>équation produit : (ax + b)(cx + d) = 0 si et seulement si ax + b = 0 ou cx + d = 0 ;</li><li><span class="frac"><span>a</span><span>x</span></span> = b (x ≠ 0, b ≠ 0) : x = <span class="frac"><span>a</span><span>b</span></span>.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-equations-a-une-inconnue'), 2, 'mettre-un-probleme-en-equation', 'Mettre un problème en équation', false, 'published', 12, now());
