insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'inequations-et-systemes-d-inequations-a-une-inconnue') and slug = 'inequations-et-intervalles'), $html$<ul><li>on résout comme une équation, mais en <strong>changeant le sens</strong> de l’inégalité quand on multiplie ou divise par un nombre négatif ;</li><li>3x − 6 ≤ 0 donne x ≤ 2 : les solutions forment l’intervalle ]−∞ ; 2] ;</li><li>−2x + 4 &gt; 0 donne −2x &gt; −4, donc x &lt; 2 : intervalle ]−∞ ; 2[.</li></ul>
