insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'inequations-et-systemes-d-inequations-a-une-inconnue') and slug = 'systemes-de-deux-inequations'), $html$<p>On résout chaque inéquation, puis on garde les nombres qui vérifient <strong>les deux</strong> : on représente les solutions sur la droite graduée.</p>
