insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'les-applications-lineaires') and slug = 'application-lineaire-et-proportionnalite'), $html$<ul><li>une application linéaire de coefficient a associe à x le nombre f(x) = ax ; on note f : x ↦ ax ;</li><li>f(x) est l’<strong>image</strong> de x ; x est un <strong>antécédent</strong> de f(x) ;</li><li>linéarité : f(x + y) = f(x) + f(y) et f(kx) = k f(x) ;</li><li>sa représentation graphique est une <strong>droite qui passe par l’origine</strong> du repère.</li></ul>
