insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'la-distance'), 2, 'mediatrice-bissectrice-droite-et-cercle', 'Médiatrice, bissectrice, droite et cercle', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'la-distance') and slug = 'mediatrice-bissectrice-droite-et-cercle'), $html$<ul><li>un point M est sur la médiatrice de [AB] si et seulement si MA = MB ; s’il est du côté de A, MA &lt; MB ;</li><li>la distance d’un point A à une droite (D) est AH, où H est le pied de la perpendiculaire à (D) passant par A ;</li><li>un point de la bissectrice d’un angle est à égale distance des deux côtés, et réciproquement ;</li><li>droite et cercle de rayon r, d = distance du centre à la droite : d &lt; r sécants ; d = r tangents ; d &gt; r disjoints.</li></ul>
