insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'la-droite-des-milieux') and slug = 'les-theoremes-de-la-droite-des-milieux'), $html$<ul><li>la droite qui passe par les milieux de deux côtés d’un triangle est parallèle au troisième côté ;</li><li>le segment qui joint ces milieux mesure la moitié du troisième côté ;</li><li>la droite qui passe par le milieu d’un côté parallèlement à un deuxième côté coupe le troisième en son milieu ;</li><li>des parallèles qui découpent des segments égaux sur une sécante en découpent aussi sur toute autre sécante.</li></ul>
