insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'droites-remarquables-dans-un-triangle') and slug = 'bissectrices-et-medianes'), $html$<table><thead><tr><th scope="col">Droites</th><th scope="col">Point de concours</th><th scope="col">Propriété</th></tr></thead><tbody><tr><td>médiatrices</td><td>centre du cercle circonscrit</td><td>à égale distance des sommets</td></tr><tr><td>bissectrices</td><td>centre du cercle inscrit</td><td>à égale distance des côtés</td></tr><tr><td>médianes</td><td>centre de gravité G</td><td>AG = <span class="frac"><span>2</span><span>3</span></span> de la médiane issue de A</td></tr><tr><td>hauteurs</td><td>orthocentre</td><td>—</td></tr></tbody></table>
