insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'translations-et-vecteurs') and slug = 'les-vecteurs'), $html$<ul><li>le vecteur AB⃗ a une direction (celle de (AB)), un sens (de A vers B) et une longueur AB ;</li><li>deux vecteurs sont égaux s’ils ont même direction, même sens et même longueur ;</li><li>ABCD est un parallélogramme si et seulement si AB⃗ = DC⃗ ;</li><li>I est le milieu de [AB] si et seulement si AI⃗ = IB⃗.</li></ul>
