insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'rotations-et-polygones-reguliers') and slug = 'la-rotation'), $html$<p>La rotation de centre O et d’angle α (dans un sens donné) transforme M en M’ tel que <strong>OM’ = OM</strong> et l’angle MOM’ = α.</p>
