insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'rotations-et-polygones-reguliers') and slug = 'les-polygones-reguliers'), $html$<ul><li>un polygone régulier a tous ses côtés égaux et tous ses angles égaux ;</li><li>il est inscrit dans un cercle ; la rotation de centre O et d’angle 360° ÷ n le laisse invariant ;</li><li>triangle équilatéral (120°), carré (90°), hexagone régulier (60°, côté égal au rayon).</li></ul>
