insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'projection-orthogonale-et-reperage') and slug = 'la-projection-orthogonale'), $html$<p>Le <strong>projeté orthogonal</strong> de M sur (D) est le point où la perpendiculaire à (D) passant par M coupe (D).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'projection-orthogonale-et-reperage'), 2, 'milieu-et-distance-dans-un-repere-orthonormal', 'Milieu et distance dans un repère orthonormal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'projection-orthogonale-et-reperage') and slug = 'milieu-et-distance-dans-un-repere-orthonormal'), $html$<p class="formula">I ( <span class="frac"><span>x<sub>A</sub> + x<sub>B</sub></span><span>2</span></span> ; <span class="frac"><span>y<sub>A</sub> + y<sub>B</sub></span><span>2</span></span> ) ; AB<sup>2</sup> = (x<sub>B</sub> − x<sub>A</sub>)<sup>2</sup> + (y<sub>B</sub> − y<sub>A</sub>)<sup>2</sup></p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null), 14, 'geometrie-dans-l-espace', 'Géométrie dans l’espace', 'Droites coplanaires, droite perpendiculaire à un plan, plans parallèles, section d’une sphère.', 14, 'published', 'Activités géométriques', '[{"title":"Programme de mathématiques du premier cycle, classe de quatrième (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_1er_cycle_4_me.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
