insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '4E' and p.series_id is null) and c.slug = 'geometrie-dans-l-espace') and slug = 'droites-et-plans-de-l-espace-la-sphere'), $html$<ul><li>deux droites de l’espace peuvent être coplanaires (dans un même plan) ou non coplanaires ;</li><li>une droite est perpendiculaire à un plan si elle est perpendiculaire à deux droites sécantes de ce plan ;</li><li>deux plans perpendiculaires à une même droite sont parallèles ;</li><li>la section d’une sphère par un plan est un cercle ; si le plan passe par le centre, c’est un <strong>grand cercle</strong>.</li></ul>
