insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '4E' and p.series_id is null) and c.slug = 'la-nouvelle') and slug = 'lire-une-nouvelle'), $html$<ul><li>la nouvelle est un récit <strong>court</strong>, centré sur un événement, avec peu de personnages ;</li><li>elle se termine souvent par une <strong>chute</strong> : une fin inattendue qui éclaire tout le récit ;</li><li>elle peut être réaliste, fantastique ou policière.</li></ul>
