insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '4E' and p.series_id is null) and c.slug = 'la-poesie-de-la-negritude') and slug = 'la-negritude'), $html$<ul><li>mouvement littéraire né à Paris dans les années 1930 autour de Léopold Sédar Senghor, Aimé Césaire et Léon-Gontran Damas ;</li><li>il affirme la dignité et les valeurs des cultures noires face au colonialisme ;</li><li>thèmes : l’Afrique, les ancêtres, la femme noire, la souffrance de l’esclavage et de la colonisation.</li></ul>
