insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '4E' and p.series_id is null) and c.slug = 'the-environment') and slug = 'if-we-protect-the-environment'), $html$<ul><li>vocabulary: pollution, plastic bags, rubbish, to recycle, to plant trees, drought, flood ;</li><li>first conditional: If + present simple, will + verb ;</li><li>If we plant trees, the desert will not advance. If you throw plastic bags, animals will die.</li></ul>
