insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '4E' and p.series_id is null) and c.slug = 'festivals-and-celebrations') and slug = 'celebrations-in-senegal'), $html$<ul><li>Tabaski, Korité, Christmas, Independence Day (on the fourth of April), the Magal of Touba ;</li><li>ordinal numbers: first, second, third, fourth… twenty-first ;</li><li>prepositions: in April, in 1960, on the 4th of April, on Monday, at 8 o’clock.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 1, 'l-afrique-au-xvie-siecle', 'L’Afrique au XVIe siècle', 'L’arrivée des Européens, le déclin du commerce transsaharien et la réorientation du commerce.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-au-xvie-siecle'), 1, 'de-la-caravane-a-la-caravelle', 'De la caravane à la caravelle', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-au-xvie-siecle') and slug = 'de-la-caravane-a-la-caravelle'), $html$<ul><li>Au XV<sup>e</sup> siècle, les Portugais longent les côtes africaines : ils atteignent le Cap-Vert (1444), puis contournent le cap de Bonne-Espérance (Bartolomeu Dias, 1488) ;</li><li>ils installent des comptoirs sur la côte et échangent tissus, armes et alcool contre or, ivoire, gomme et, de plus en plus, captifs ;</li><li>le commerce transsaharien décline, surtout après la chute de l’empire Songhaï (Tondibi, 1591) ;</li><li>le commerce se tourne vers l’Atlantique : les royaumes côtiers s’enrichissent, ceux de l’intérieur s’affaiblissent.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 2, 'l-asie-et-le-nouveau-monde-au-xvie-siecle', 'L’Asie et le Nouveau Monde au XVIe siècle', 'L’arrivée des Européens en Asie et en Amérique, leur implantation et leur organisation.', 2, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-asie-et-le-nouveau-monde-au-xvie-siecle'), 1, 'les-europeens-en-asie-et-en-amerique', 'Les Européens en Asie et en Amérique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-asie-et-le-nouveau-monde-au-xvie-siecle') and slug = 'les-europeens-en-asie-et-en-amerique'), $html$<ul><li>Asie : les Portugais s’installent à Goa (1510), Malacca (1511) et Macao ; ils contrôlent le commerce des épices ;</li><li>Amérique : les Espagnols conquièrent l’empire aztèque (Cortès, 1519-1521) et l’empire inca (Pizarro, 1532-1533) ; les Portugais occupent le Brésil (1500) ;</li><li>les Amérindiens sont soumis au travail forcé ; guerres, épidémies et mauvais traitements les déciment ;</li><li>pour remplacer cette main-d’œuvre, les colons font venir des captifs d’Afrique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 3, 'la-traite-negriere-naissance-mecanisme-et-evolution', 'La traite négrière : naissance, mécanisme et évolution', 'Les origines de la traite atlantique, le commerce triangulaire, son évolution du XVIe au XIXe siècle.', 3, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-traite-negriere-naissance-mecanisme-et-evolution'), 1, 'le-commerce-triangulaire', 'Le commerce triangulaire', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-traite-negriere-naissance-mecanisme-et-evolution') and slug = 'le-commerce-triangulaire'), $html$<table><thead><tr><th scope="col">Étape</th><th scope="col">Trajet</th><th scope="col">Marchandises</th></tr></thead><tbody><tr><td>1</td><td>Europe → Afrique</td><td>tissus, armes, alcool, pacotille</td></tr><tr><td>2</td><td>Afrique → Amérique</td><td>captifs africains</td></tr><tr><td>3</td><td>Amérique → Europe</td><td>sucre, café, coton, tabac</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 4, 'les-consequences-de-la-traite-negriere', 'Les conséquences de la traite négrière', 'Les conséquences en Afrique, en Europe, en Amérique et en Asie.', 4, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-consequences-de-la-traite-negriere'), 1, 'un-bilan-tres-lourd-pour-l-afrique', 'Un bilan très lourd pour l’Afrique', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-consequences-de-la-traite-negriere') and slug = 'un-bilan-tres-lourd-pour-l-afrique'), $html$<table><thead><tr><th scope="col">Région</th><th scope="col">Conséquences</th></tr></thead><tbody><tr><td>Afrique</td><td>perte de millions de jeunes, guerres et razzias, insécurité, recul de l’agriculture et de l’artisanat</td></tr><tr><td>Europe</td><td>enrichissement des ports et des armateurs (Nantes, Bordeaux, Liverpool), capitaux pour l’industrie</td></tr><tr><td>Amérique</td><td>développement des plantations, peuplement d’origine africaine, cultures afro-américaines</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 5, 'la-traite-au-senegal-et-le-mouvement-abolitionniste', 'La traite au Sénégal et le mouvement abolitionniste', 'Les comptoirs de la Sénégambie, Gorée ; l’abolition de la traite et de l’esclavage.', 5, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-traite-au-senegal-et-le-mouvement-abolitionniste'), 1, 'la-traite-au-senegal', 'La traite au Sénégal', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-traite-au-senegal-et-le-mouvement-abolitionniste') and slug = 'la-traite-au-senegal'), $html$<ul><li>les Européens s’installent à Gorée, à Saint-Louis (fondé en 1659), à Rufisque, Portudal et Joal ;</li><li>des compagnies de commerce (Compagnie du Sénégal) échangent captifs, gomme et or contre armes et marchandises ;</li><li>dans le Kayor, le Baol ou le Waalo, les guerres et les razzias de captifs se multiplient.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-traite-au-senegal-et-le-mouvement-abolitionniste'), 2, 'le-mouvement-abolitionniste', 'Le mouvement abolitionniste', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-traite-au-senegal-et-le-mouvement-abolitionniste') and slug = 'le-mouvement-abolitionniste'), $html$<ul><li>au XVIII<sup>e</sup> siècle, des philosophes, des religieux et d’anciens esclaves dénoncent la traite ;</li><li>révoltes d’esclaves : Saint-Domingue devient indépendant sous le nom d’Haïti (1804) ;</li><li>la Grande-Bretagne interdit la traite en 1807 ; la France abolit l’esclavage en 1794, le rétablit en 1802, puis l’abolit définitivement en 1848 (Victor Schœlcher) ;</li><li>aux États-Unis, l’esclavage est aboli en 1865.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 6, 'la-senegambie-dislocation-du-jolof-et-nouveaux-royaumes', 'La Sénégambie : dislocation du Jolof et nouveaux royaumes', 'La bataille de Danki, l’émancipation du Kayor et des autres royaumes.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-senegambie-dislocation-du-jolof-et-nouveaux-royaumes'), 1, 'la-fin-de-l-empire-du-jolof', 'La fin de l’empire du Jolof', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-senegambie-dislocation-du-jolof-et-nouveaux-royaumes') and slug = 'la-fin-de-l-empire-du-jolof'), $html$<ul><li>au XVI<sup>e</sup> siècle, l’empire du Jolof domine le Waalo, le Kayor, le Baol, le Sine et le Saloum ;</li><li>l’arrivée des Portugais sur la côte enrichit les provinces côtières, qui supportent mal l’autorité du Bourba Jolof ;</li><li>à la bataille de Danki (vers 1549), Amary Ngoné Sobel Fall bat le Bourba : le Kayor devient indépendant ;</li><li>les autres royaumes s’émancipent à leur tour.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 7, 'le-fouta-et-les-heritiers-du-gaabu', 'Le Fouta et les héritiers du Gaabu', 'Le Fouta du XVIIe au XIXe siècle ; le Fouladou, les entités mandingues et diolas.', 7, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'le-fouta-et-les-heritiers-du-gaabu'), 1, 'le-fouta-toro', 'Le Fouta Toro', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'le-fouta-et-les-heritiers-du-gaabu') and slug = 'le-fouta-toro'), $html$<ul><li>au XVI<sup>e</sup> siècle, Koli Tenguella fonde la dynastie des Denianké ;</li><li>en 1776, une révolution musulmane dirigée par Thierno Souleymane Baal renverse les Denianké et instaure l’<strong>almamyat</strong> ;</li><li>l’almamy Abdoul Kader Kane est le premier souverain du nouveau régime.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'le-fouta-et-les-heritiers-du-gaabu'), 2, 'apres-le-gaabu', 'Après le Gaabu', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'le-fouta-et-les-heritiers-du-gaabu') and slug = 'apres-le-gaabu'), $html$<ul><li>le Gaabu, royaume mandingue, décline au XIX<sup>e</sup> siècle ; sa capitale Kansala tombe en 1867 devant les Peuls du Fouta-Djallon ;</li><li>Alfa Molo fonde alors le royaume peul du Fouladou ;</li><li>en Casamance, les sociétés diolas, sans État centralisé, s’organisent autour des villages, de la riziculture et des bois sacrés ; des rois-prêtres (comme à Oussouye) ont un rôle religieux.</li></ul>
