insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-empires-peuls-du-sokoto-et-du-macina'), 1, 'sokoto-et-macina', 'Sokoto et Macina', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-empires-peuls-du-sokoto-et-du-macina') and slug = 'sokoto-et-macina'), $html$<ul><li>Ousmane dan Fodio lance en 1804 un jihad contre les rois haoussas ; il fonde le califat de Sokoto (dans l’actuel Nigeria) ;</li><li>Sékou Amadou (Cheikhou Amadou) fonde la Diina du Macina (1818) avec pour capitale Hamdallahi ;</li><li>ces États appliquent la loi islamique et développent l’enseignement coranique.</li></ul>
