insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-empire-toucouleur-d-el-hadji-omar-tall'), 1, 'el-hadji-omar-et-son-empire', 'El Hadji Omar et son empire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-empire-toucouleur-d-el-hadji-omar-tall') and slug = 'el-hadji-omar-et-son-empire'), $html$<ul><li>né vers 1796 à Halwar (Fouta Toro), El Hadji Omar Tall accomplit le pèlerinage et devient un chef de la confrérie tidiane ;</li><li>il lance un jihad en 1852 ; il se heurte aux Français de Faidherbe au siège de Médine (1857) ;</li><li>il conquiert Ségou (1861) et le Macina (1862) ;</li><li>il meurt en 1864 dans les falaises de Bandiagara ; son fils Ahmadou lui succède.</li></ul>
