insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'tchaka-et-les-zoulous-madagascar'), 1, 'tchaka-et-le-mouvement-zoulou', 'Tchaka et le mouvement zoulou', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'tchaka-et-les-zoulous-madagascar') and slug = 'tchaka-et-le-mouvement-zoulou'), $html$<ul><li>vers 1816, Tchaka devient roi des Zoulous ;</li><li>il réforme l’armée : régiments disciplinés, lance courte, tactique en « cornes de buffle » ;</li><li>ses conquêtes provoquent de grands déplacements de populations (le Mfecane) ;</li><li>il est assassiné en 1828.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'tchaka-et-les-zoulous-madagascar'), 2, 'madagascar', 'Madagascar', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'tchaka-et-les-zoulous-madagascar') and slug = 'madagascar'), $html$<ul><li>plusieurs royaumes se forment : Sakalava à l’ouest, Betsimisaraka à l’est, Merina sur les hauts plateaux ;</li><li>Andrianampoinimerina unifie le royaume merina à la fin du XVIII<sup>e</sup> siècle ;</li><li>son fils Radama I<sup>er</sup> étend le royaume à une grande partie de l’île.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 11, 'la-premiere-revolution-industrielle', 'La première révolution industrielle', 'Les transformations techniques, économiques et sociales en Europe.', 11, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-premiere-revolution-industrielle'), 1, 'une-revolution-des-techniques-et-des-societes', 'Une révolution des techniques et des sociétés', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-premiere-revolution-industrielle') and slug = 'une-revolution-des-techniques-et-des-societes'), $html$<ul><li>elle commence en Grande-Bretagne à la fin du XVIII<sup>e</sup> siècle ;</li><li>techniques : machine à vapeur (James Watt), charbon, fer, métiers à tisser mécaniques, chemin de fer (1825-1830) ;</li><li>économie : usines, production en grande quantité, banques, capitalisme ;</li><li>société : exode rural, croissance des villes, naissance de la classe ouvrière (le prolétariat) et de la bourgeoisie industrielle.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null), 12, 'les-lumieres-et-la-revolution-francaise', 'Les Lumières et la Révolution française', 'Le mouvement des idées au XVIIIe siècle ; la Révolution de 1789 et ses conséquences.', 12, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-lumieres-et-la-revolution-francaise'), 1, 'les-lumieres', 'Les Lumières', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-lumieres-et-la-revolution-francaise') and slug = 'les-lumieres'), $html$<ul><li>au XVIII<sup>e</sup> siècle, des philosophes défendent la raison, la liberté et l’égalité ;</li><li>Montesquieu : séparation des pouvoirs (<em>De l’esprit des lois</em>, 1748) ; Rousseau : souveraineté du peuple (<em>Du contrat social</em>, 1762) ; Voltaire : tolérance ;</li><li>Diderot et d’Alembert diffusent les savoirs dans l’<em>Encyclopédie</em>.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-lumieres-et-la-revolution-francaise'), 2, 'la-revolution-francaise', 'La Révolution française', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'les-lumieres-et-la-revolution-francaise') and slug = 'la-revolution-francaise'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Événement</th></tr></thead><tbody><tr><td>14 juillet 1789</td><td>prise de la Bastille</td></tr><tr><td>4 août 1789</td><td>abolition des privilèges</td></tr><tr><td>26 août 1789</td><td>Déclaration des droits de l’homme et du citoyen</td></tr><tr><td>1792</td><td>proclamation de la République</td></tr></tbody></table>
