insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-naissance-des-etats-unis-et-l-empire-ottoman'), 1, 'la-naissance-des-etats-unis', 'La naissance des États-Unis', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-naissance-des-etats-unis-et-l-empire-ottoman') and slug = 'la-naissance-des-etats-unis'), $html$<ul><li>les treize colonies anglaises d’Amérique du Nord refusent les taxes imposées par Londres ;</li><li>le 4 juillet 1776, elles proclament leur indépendance ; George Washington dirige la guerre, avec l’aide de la France ;</li><li>l’Angleterre reconnaît l’indépendance en 1783 ; la Constitution de 1787 crée une république fédérale ;</li><li>George Washington devient le premier président (1789).</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-naissance-des-etats-unis-et-l-empire-ottoman'), 2, 'l-empire-ottoman', 'L’Empire ottoman', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'la-naissance-des-etats-unis-et-l-empire-ottoman') and slug = 'l-empire-ottoman'), $html$<ul><li>les Ottomans prennent Constantinople en 1453, qui devient Istanbul ;</li><li>l’empire atteint son apogée au XVI<sup>e</sup> siècle (Soliman le Magnifique) ;</li><li>il recule ensuite : échec devant Vienne (1683), indépendance de la Grèce (1830) ;</li><li>au XIX<sup>e</sup> siècle, on l’appelle « l’homme malade de l’Europe ».</li></ul>$html$);
