insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'methodes-dissertation-et-commentaire-de-document') and slug = 'rediger-une-dissertation-historique'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Analyser le sujet : mots clés, dates, lieux.</li><li>Introduction : présenter le sujet, poser le problème, annoncer le plan.</li><li>Développement : deux ou trois parties, chacune avec des idées, des exemples et des dates.</li><li>Conclusion : répondre au problème et ouvrir sur une autre question.</li></ol></div>$html$);
