insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'methodes-dissertation-et-commentaire-de-document') and slug = 'commenter-un-document'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Présenter le document : nature, auteur, date, source.</li><li>Dégager l’idée principale.</li><li>Expliquer en s’appuyant sur ses connaissances.</li><li>Montrer l’intérêt et les limites du document.</li></ol></div>
