insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-de-l-ouest-developpement-et-integration') and slug = 'situation-et-problemes-de-developpement'), $html$<ul><li>l’Afrique de l’Ouest s’étend du Sahara au golfe de Guinée et de l’Atlantique au lac Tchad ;</li><li>atouts : population jeune, ressources agricoles, minières (or, phosphates, pétrole, gaz) et halieutiques ;</li><li>contraintes : sécheresses, pauvreté, faible industrialisation, dette, insécurité dans le Sahel.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-de-l-ouest-developpement-et-integration'), 2, 'l-integration-regionale', 'L’intégration régionale', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-de-l-ouest-developpement-et-integration') and slug = 'l-integration-regionale'), $html$<ul><li>la CEDEAO (1975) vise la libre circulation des personnes et des biens ; en 2025, le Mali, le Burkina Faso et le Niger l’ont quittée pour former l’Alliance des États du Sahel ;</li><li>l’UEMOA regroupe huit États qui utilisent le franc CFA ;</li><li>obstacles : routes insuffisantes, tracasseries aux frontières, monnaies différentes, crises politiques.</li></ul>
