insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-milieux-population-et-developpement') and slug = 'la-diversite-physique-et-humaine'), $html$<ul><li>continent de plus de 30 millions de km² et de 54 États ;</li><li>relief : plateaux, hautes terres de l’Est (Kilimandjaro, environ 5 895 m) ; grands fleuves : Nil, Congo, Niger ;</li><li>climats et paysages organisés de part et d’autre de l’équateur : forêt dense, savane, steppe, désert (Sahara) ;</li><li>plus de 1,4 milliard d’habitants, la population la plus jeune du monde ; forte croissance urbaine.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-milieux-population-et-developpement'), 2, 'pauvrete-dependance-et-cooperation', 'Pauvreté, dépendance et coopération', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-afrique-milieux-population-et-developpement') and slug = 'pauvrete-dependance-et-cooperation'), $html$<ul><li>pauvreté : faibles revenus, accès difficile à l’eau, à la santé, à l’école ;</li><li>dépendance : exportation de matières premières brutes, importation de produits fabriqués et de nourriture, dette ;</li><li>coopération : bilatérale (entre deux États) ou multilatérale (ONU, Banque mondiale, Union européenne) ; l’Union africaine (2002) et la Zone de libre-échange continentale africaine encouragent les échanges entre Africains.</li></ul>
