insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-europe') and slug = 'un-continent-integre'), $html$<ul><li>petit continent (environ 10 millions de km²) très découpé ; grande plaine au nord, montagnes jeunes au sud (Alpes) ;</li><li>climats : océanique à l’ouest, continental à l’est, méditerranéen au sud ;</li><li>population nombreuse, urbaine et vieillissante ; forte immigration ;</li><li>l’Union européenne compte 27 États ; plus de vingt d’entre eux utilisent l’euro.</li></ul>
