insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-amerique') and slug = 'un-continent-de-contrastes'), $html$<ul><li>à l’ouest, de hautes montagnes (Rocheuses, Andes) ; au centre, de grandes plaines et de grands fleuves (Mississippi, Amazone) ;</li><li>peuples : Amérindiens, descendants d’Européens et d’Africains déportés par la traite, métis ;</li><li>fortes disparités : les États-Unis et le Canada sont riches ; Haïti est très pauvre ;</li><li>intégration : accord États-Unis–Mexique–Canada, Mercosur en Amérique du Sud.</li></ul>$html$);
