insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-asie') and slug = 'le-continent-le-plus-peuple'), $html$<ul><li>plus grand continent ; l’Himalaya porte le plus haut sommet du monde (Everest, environ 8 849 m) ;</li><li>contrastes : froid de la Sibérie, déserts d’Arabie et de Gobi, climat de mousson au sud et au sud-est ;</li><li>environ 60 % de l’humanité ; l’Inde et la Chine dépassent chacune 1,4 milliard d’habitants ;</li><li>disparités : Japon, Corée du Sud, Chine et pays du Golfe puissants ; Afghanistan ou Bangladesh pauvres ; l’ASEAN unit l’Asie du Sud-Est.</li></ul>$html$);
