insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-oceanie'), 1, 'un-continent-d-iles', 'Un continent d’îles', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '4E' and p.series_id is null) and c.slug = 'l-oceanie') and slug = 'un-continent-d-iles'), $html$<ul><li>l’Australie, la Nouvelle-Zélande et des milliers d’îles du Pacifique (Mélanésie, Micronésie, Polynésie) ;</li><li>peu peuplée (environ 45 millions d’habitants) ;</li><li>l’Australie et la Nouvelle-Zélande sont riches (mines, élevage, services) ; beaucoup de petites îles dépendent de l’aide et sont menacées par la montée des eaux ;</li><li>le Forum des îles du Pacifique favorise la coopération.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 1, 'la-digestion-et-l-absorption-intestinale', 'La digestion et l’absorption intestinale', 'Le tube digestif, la transformation des aliments en nutriments, le passage dans le sang.', 1, 'published', 'Le corps humain et la santé', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-digestion-et-l-absorption-intestinale'), 1, 'la-digestion', 'La digestion', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-digestion-et-l-absorption-intestinale') and slug = 'la-digestion'), $html$<ul><li>le tube digestif : bouche, œsophage, estomac, intestin grêle, gros intestin ; les glandes digestives : glandes salivaires, foie, pancréas ;</li><li>la digestion est mécanique (mastication, brassage) et chimique (les <strong>enzymes</strong> des sucs digestifs) ;</li><li>l’amylase de la salive transforme l’amidon en maltose (test à l’eau iodée qui ne bleuit plus) ;</li><li>à la fin, les aliments sont devenus des <strong>nutriments</strong> : glucose, acides aminés, acides gras et glycérol.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-digestion-et-l-absorption-intestinale'), 2, 'l-absorption-intestinale', 'L’absorption intestinale', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-digestion-et-l-absorption-intestinale') and slug = 'l-absorption-intestinale'), $html$<ul><li>les nutriments traversent la paroi de l’intestin grêle et passent dans le sang et la lymphe : c’est l’<strong>absorption</strong> ;</li><li>la paroi porte des millions de replis, les <strong>villosités</strong>, qui donnent une très grande surface d’échange ;</li><li>ce qui n’est pas absorbé passe dans le gros intestin et forme les selles.</li></ul>
