insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'le-sang-composition-et-maladies') and slug = 'la-composition-du-sang'), $html$<table><thead><tr><th scope="col">Élément</th><th scope="col">Rôle</th></tr></thead><tbody><tr><td>plasma (liquide jaunâtre, plus de la moitié du sang)</td><td>transporte nutriments, déchets, hormones</td></tr><tr><td>globules rouges (hématies)</td><td>transportent le dioxygène grâce à l’hémoglobine</td></tr><tr><td>globules blancs (leucocytes)</td><td>défendent l’organisme contre les microbes</td></tr><tr><td>plaquettes</td><td>arrêtent les saignements (coagulation)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 3, 'la-circulation-sanguine', 'La circulation sanguine', 'Le cœur, les vaisseaux, la double circulation ; pression artérielle et maladies cardio-vasculaires.', 3, 'published', 'Le corps humain et la santé', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-circulation-sanguine'), 1, 'le-c-ur-et-la-double-circulation', 'Le cœur et la double circulation', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-circulation-sanguine') and slug = 'le-c-ur-et-la-double-circulation'), $html$<ul><li>le cœur est un muscle creux à quatre cavités : deux oreillettes et deux ventricules ;</li><li>artères (du cœur vers les organes), veines (des organes vers le cœur), capillaires (échanges avec les cellules) ;</li><li>petite circulation : cœur droit → poumons → cœur gauche (le sang s’y charge en dioxygène) ;</li><li>grande circulation : cœur gauche → organes → cœur droit.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-circulation-sanguine'), 2, 'pression-arterielle-et-maladies-cardio-vasculaires', 'Pression artérielle et maladies cardio-vasculaires', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-circulation-sanguine') and slug = 'pression-arterielle-et-maladies-cardio-vasculaires'), $html$<ul><li>la pression (tension) artérielle se mesure avec un tensiomètre ; chez l’adulte, une valeur proche de 12/8 est normale ;</li><li>l’<strong>hypertension</strong> fatigue le cœur et les vaisseaux : elle peut provoquer un AVC ou un infarctus ;</li><li>facteurs de risque : trop de sel, de gras et de sucre, tabac, alcool, manque d’activité, surpoids.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 4, 'la-contamination-par-les-micro-organismes', 'La contamination par les micro-organismes', 'Microbes, voies de contamination, prévention et lutte.', 4, 'published', 'Le corps humain et la santé', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-contamination-par-les-micro-organismes'), 1, 'microbes-et-contamination', 'Microbes et contamination', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-contamination-par-les-micro-organismes') and slug = 'microbes-et-contamination'), $html$<ul><li>micro-organismes : bactéries, virus, champignons microscopiques, protozoaires ; certains sont utiles, d’autres pathogènes ;</li><li>voies de contamination : air (toux), eau et aliments souillés (choléra), piqûres (le moustique anophèle transmet le paludisme), sang, contact ;</li><li>prévention : hygiène des mains, eau potable, moustiquaire imprégnée, vaccination ;</li><li>les antiseptiques désinfectent une plaie ; les antibiotiques agissent sur les bactéries, pas sur les virus.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 5, 'la-puberte-et-les-organes-reproducteurs', 'La puberté et les organes reproducteurs', 'Les transformations de la puberté, les appareils reproducteurs, le cycle menstruel.', 5, 'published', 'Reproduction et hérédité', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-puberte-et-les-organes-reproducteurs'), 1, 'la-puberte', 'La puberté', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-puberte-et-les-organes-reproducteurs') and slug = 'la-puberte'), $html$<ul><li>vers 10 à 14 ans chez les filles, 12 à 16 ans chez les garçons : poussée de croissance, poils, mue de la voix chez le garçon, seins et règles chez la fille ;</li><li>ces changements sont commandés par des <strong>hormones</strong> : testostérone (testicules), œstrogènes (ovaires) ;</li><li>les changements de l’humeur sont normaux : on peut en parler à un parent ou à l’infirmier.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-puberte-et-les-organes-reproducteurs'), 2, 'les-appareils-reproducteurs', 'Les appareils reproducteurs', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-puberte-et-les-organes-reproducteurs') and slug = 'les-appareils-reproducteurs'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Homme</th><th scope="col">Femme</th></tr></thead><tbody><tr><td>glandes génitales</td><td>testicules</td><td>ovaires</td></tr><tr><td>cellules reproductrices</td><td>spermatozoïdes (production continue)</td><td>ovules (un par cycle environ)</td></tr><tr><td>autres organes</td><td>spermiducte, prostate, pénis</td><td>trompes, utérus, vagin</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 6, 'de-la-fecondation-a-l-accouchement', 'De la fécondation à l’accouchement', 'Fécondation, nidation, développement de l’embryon et du fœtus, accouchement.', 6, 'published', 'Reproduction et hérédité', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'de-la-fecondation-a-l-accouchement'), 1, 'la-grossesse', 'La grossesse', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'de-la-fecondation-a-l-accouchement') and slug = 'la-grossesse'), $html$<ul><li>la <strong>fécondation</strong> est l’union d’un spermatozoïde et d’un ovule dans une trompe : elle donne une cellule-œuf ;</li><li>la cellule-œuf se divise et s’implante dans la paroi de l’utérus : c’est la <strong>nidation</strong> ;</li><li>jusqu’à deux mois on parle d’embryon, ensuite de fœtus ;</li><li>le <strong>placenta</strong> et le cordon ombilical assurent les échanges entre la mère et le fœtus ;</li><li>la grossesse dure environ neuf mois ; l’accouchement se termine par l’expulsion du placenta.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 7, 'eviter-une-grossesse-precoce-et-les-ist', 'Éviter une grossesse précoce et les IST', 'Les risques d’une grossesse précoce, les moyens de l’éviter, les infections sexuellement transmissibles.', 7, 'published', 'Reproduction et hérédité', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'eviter-une-grossesse-precoce-et-les-ist'), 1, 'se-proteger', 'Se protéger', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'eviter-une-grossesse-precoce-et-les-ist') and slug = 'se-proteger'), $html$<ul><li>une grossesse à l’adolescence présente des risques pour la santé de la jeune fille et du bébé, et compromet souvent la scolarité ;</li><li>l’abstinence est le moyen le plus sûr ; il existe aussi des méthodes de contraception, à discuter avec un agent de santé ;</li><li>les IST (infections sexuellement transmissibles), dont le VIH, se transmettent lors de rapports non protégés ; le préservatif protège à la fois des IST et de la grossesse.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 8, 'la-transmission-des-caracteres-hereditaires', 'La transmission des caractères héréditaires', 'Caractères héréditaires et acquis, chromosomes, détermination du sexe.', 8, 'published', 'Reproduction et hérédité', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-transmission-des-caracteres-hereditaires'), 1, 'chromosomes-et-heredite', 'Chromosomes et hérédité', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'la-transmission-des-caracteres-hereditaires') and slug = 'chromosomes-et-heredite'), $html$<ul><li>un caractère <strong>héréditaire</strong> se transmet des parents aux enfants (groupe sanguin, couleur des yeux) ; un caractère <strong>acquis</strong> non (cicatrice, langue parlée) ;</li><li>l’information héréditaire est portée par les <strong>chromosomes</strong>, dans le noyau des cellules ; ils sont formés d’ADN ;</li><li>l’être humain a 46 chromosomes (23 paires) ; les cellules reproductrices n’en ont que 23 ;</li><li>chaque enfant reçoit la moitié de ses chromosomes de son père et l’autre moitié de sa mère.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 9, 'les-seismes-et-la-structure-du-globe', 'Les séismes et la structure du globe', 'Le séisme, ses ondes et ses effets ; les enveloppes de la Terre.', 9, 'published', 'Géologie', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'les-seismes-et-la-structure-du-globe'), 1, 'les-seismes', 'Les séismes', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'les-seismes-et-la-structure-du-globe') and slug = 'les-seismes'), $html$<ul><li>un séisme est une secousse du sol due à une rupture brutale des roches en profondeur, au <strong>foyer</strong> ;</li><li>l’<strong>épicentre</strong> est le point de la surface situé au-dessus du foyer ;</li><li>les ondes sismiques sont enregistrées par un sismographe ; la magnitude (échelle de Richter) mesure l’énergie libérée, l’intensité mesure les dégâts.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'les-seismes-et-la-structure-du-globe'), 2, 'la-structure-du-globe', 'La structure du globe', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'les-seismes-et-la-structure-du-globe') and slug = 'la-structure-du-globe'), $html$<table><thead><tr><th scope="col">Enveloppe</th><th scope="col">Profondeur</th><th scope="col">Caractères</th></tr></thead><tbody><tr><td>croûte</td><td>de 5 à 70 km environ</td><td>roches solides, mince</td></tr><tr><td>manteau</td><td>jusqu’à 2 900 km</td><td>roches chaudes</td></tr><tr><td>noyau</td><td>de 2 900 km au centre (environ 6 370 km)</td><td>fer et nickel ; partie externe liquide</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null), 10, 'le-volcanisme', 'Le volcanisme', 'L’appareil volcanique, les types d’éruptions, les volcans du Sénégal.', 10, 'published', 'Géologie', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'le-volcanisme'), 1, 'volcans-et-eruptions', 'Volcans et éruptions', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '4E' and p.series_id is null) and c.slug = 'le-volcanisme') and slug = 'volcans-et-eruptions'), $html$<ul><li>le magma, roche fondue venue de la profondeur, s’accumule dans une chambre magmatique puis monte par la cheminée jusqu’au cratère ;</li><li>éruption <strong>effusive</strong> : lave fluide qui coule en coulées (volcans d’Hawaï) ;</li><li>éruption <strong>explosive</strong> : lave visqueuse, projections et nuées ardentes, très dangereuses (montagne Pelée, 1902).</li></ul>
