insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'grandeurs-physiques-et-mesures') and slug = 'mesurer-une-grandeur-physique'), $html$<p>Les sciences physiques étudient les phénomènes de la nature (lumière, électricité, mouvement) et la matière. Une <strong>grandeur physique</strong> se mesure : on donne une valeur et une unité.</p>
