insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'introduction-a-l-electricite'), 1, 'le-circuit-electrique', 'Le circuit électrique', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'introduction-a-l-electricite') and slug = 'le-circuit-electrique'), $html$<ul><li>un circuit comprend un <strong>générateur</strong> (pile, batterie), des <strong>récepteurs</strong> (lampe, moteur), un interrupteur et des fils de connexion ;</li><li>le courant ne circule que si le circuit est fermé ;</li><li>les métaux sont <strong>conducteurs</strong> ; le plastique, le verre, le bois sec sont <strong>isolants</strong> ;</li><li>en série, les dipôles forment une seule boucle : si une lampe grille, tout s’éteint ; en dérivation, chaque branche fonctionne seule.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null), 5, 'sources-et-propagation-de-la-lumiere', 'Sources et propagation de la lumière', 'Sources primaires et objets diffusants, récepteurs, propagation rectiligne, ombres et éclipses.', 5, 'published', 'Physique', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'sources-et-propagation-de-la-lumiere'), 1, 'sources-et-recepteurs-de-lumiere', 'Sources et récepteurs de lumière', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'sources-et-propagation-de-la-lumiere') and slug = 'sources-et-recepteurs-de-lumiere'), $html$<ul><li>une <strong>source primaire</strong> produit sa lumière : Soleil, lampe, flamme ;</li><li>un <strong>objet diffusant</strong> renvoie la lumière qu’il reçoit : la Lune, un mur ;</li><li>un récepteur détecte la lumière : l’œil, une cellule photoélectrique, un panneau solaire.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'sources-et-propagation-de-la-lumiere'), 2, 'la-propagation-rectiligne-de-la-lumiere', 'La propagation rectiligne de la lumière', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'sources-et-propagation-de-la-lumiere') and slug = 'la-propagation-rectiligne-de-la-lumiere'), $html$<ul><li>dans un milieu transparent et homogène, la lumière se propage en <strong>ligne droite</strong> ; on la représente par un rayon (flèche) ;</li><li>vitesse dans le vide : environ 300 000 km/s ;</li><li>un objet opaque éclairé a une ombre propre ; il projette une ombre portée ;</li><li>éclipse de Lune : la Lune passe dans l’ombre de la Terre ; éclipse de Soleil : la Lune cache le Soleil.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null), 6, 'reflexion-et-refraction-de-la-lumiere', 'Réflexion et réfraction de la lumière', 'Lois de la réflexion, miroir plan ; changement de direction de la lumière entre deux milieux.', 6, 'published', 'Physique', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'reflexion-et-refraction-de-la-lumiere'), 1, 'reflexion-et-refraction', 'Réflexion et réfraction', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'reflexion-et-refraction-de-la-lumiere') and slug = 'reflexion-et-refraction'), $html$<ul><li><strong>réflexion</strong> : la lumière rebondit sur une surface ; l’angle de réflexion est égal à l’angle d’incidence (i = r) ;</li><li>l’image donnée par un miroir plan est symétrique de l’objet par rapport au miroir ;</li><li><strong>réfraction</strong> : la lumière change de direction en passant d’un milieu transparent à un autre (air → eau) ;</li><li>c’est pourquoi un bâton plongé dans l’eau paraît brisé.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null), 7, 'melanges-et-corps-purs', 'Mélanges et corps purs', 'Mélanges homogènes et hétérogènes, techniques de séparation, critères de pureté.', 7, 'published', 'Chimie', '[{"title":"Relevé DIANGAL du programme du moyen (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
