insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'melanges-et-corps-purs') and slug = 'separer-les-constituants-d-un-melange'), $html$<ul><li>mélange <strong>hétérogène</strong> : on distingue plusieurs constituants (eau boueuse) ; <strong>homogène</strong> : on n’en voit qu’un (eau salée) ;</li><li>décantation puis filtration : séparent un solide d’un liquide ;</li><li>évaporation : récupère le sel de l’eau de mer (marais salants du Saloum, lac Rose) ;</li><li>distillation : sépare les liquides ou récupère l’eau pure.</li></ul>
