insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'la-structure-de-la-matiere') and slug = 'atomes-et-molecules'), $html$<ul><li>la matière est formée de particules très petites : les <strong>atomes</strong> ;</li><li>un atome comprend un noyau et des électrons ; il est électriquement neutre ;</li><li>chaque élément a un symbole : H (hydrogène), O (oxygène), C (carbone), N (azote), Fe (fer), Cu (cuivre), Na (sodium), Cl (chlore) ;</li><li>une <strong>molécule</strong> est un groupe d’atomes liés.</li></ul>
