insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'la-reaction-chimique') and slug = 'reaction-chimique-et-equation-bilan'), $html$<ul><li>au cours d’une réaction chimique, des corps (les <strong>réactifs</strong>) disparaissent et de nouveaux corps (les <strong>produits</strong>) apparaissent ;</li><li>la masse totale se conserve (loi de Lavoisier) : les atomes se réarrangent, ils ne disparaissent pas ;</li><li>l’équation-bilan est équilibrée : autant d’atomes de chaque sorte à gauche et à droite.</li></ul>
