insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '4E' and p.series_id is null) and c.slug = 'la-mole-et-les-grandeurs-molaires') and slug = 'quantite-de-matiere-et-masse-molaire'), $html$<ul><li>une <strong>mole</strong> contient 6,02 × 10<sup>23</sup> particules (nombre d’Avogadro) ;</li><li>la masse molaire M est la masse d’une mole, en g/mol : M(H) = 1 ; M(C) = 12 ; M(O) = 16 ;</li><li>M(H<sub>2</sub>O) = 2 × 1 + 16 = 18 g/mol ; M(CO<sub>2</sub>) = 12 + 2 × 16 = 44 g/mol ;</li><li>pour un gaz, le volume molaire vaut environ 22,4 L/mol dans les conditions normales (0 °C).</li></ul>
