insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '3E' and p.series_id is null) and c.slug = 'le-resume-de-texte') and slug = 'les-regles-du-resume'), $html$<ul><li>Réduire le texte au quart de sa longueur environ (le nombre de mots est fixé par la consigne).</li><li>Respecter l’ordre des idées et le système d’énonciation de l’auteur.</li><li>Reformuler avec ses propres mots, sans recopier de phrases.</li><li>Ne rien ajouter : pas d’opinion personnelle ni de « l’auteur dit que… ».</li></ul>
