insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '3E' and p.series_id is null) and c.slug = 'le-resume-de-texte') and slug = 'la-methode-du-resume'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire le texte plusieurs fois et dégager le thème et la thèse.</li><li>Repérer les paragraphes et les connecteurs : ils montrent le plan.</li><li>Noter l’idée essentielle de chaque partie, en supprimant les exemples.</li><li>Rédiger un texte suivi, avec des connecteurs, puis compter les mots.</li></ol></div>
