insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '3E' and p.series_id is null) and c.slug = 'daily-life-and-routines') and slug = 'talking-about-your-day'), $html$<ul><li>I wake up at six o’clock.</li><li>I have breakfast and I go to school.</li><li>In the afternoon, I do my homework and help at home.</li><li>In the evening, I have dinner with my family and go to bed at ten.</li></ul>
