insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '3E' and p.series_id is null) and c.slug = 'the-simple-past') and slug = 'regular-and-irregular-verbs'), $html$<p>We use the <strong>simple past</strong> for finished actions at a definite time in the past: yesterday, last week, in 2020.</p>
