insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'les-revolutions-chinoises') and slug = 'la-revolution-de-1911'), $html$<p>En 1911, la dynastie mandchoue est renversée ; la <strong>République</strong> est proclamée en 1912. <strong>Sun Yat-sen</strong> fonde le Guomindang (parti nationaliste).</p>
