insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-decolonisation-en-afrique') and slug = 'les-causes-de-la-decolonisation'), $html$<ul><li>L’affaiblissement de la France et du Royaume-Uni après 1945.</li><li>La participation des Africains à la guerre et l’éveil du nationalisme (partis, syndicats, étudiants).</li><li>Le soutien de l’ONU, des États-Unis, de l’URSS et des pays du Tiers-monde (Bandung).</li></ul>$html$);
