insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-decolonisation-en-afrique') and slug = 'les-formes-de-la-decolonisation'), $html$<ul><li><strong>Pacifique</strong>, par la négociation : la plupart des colonies françaises d’Afrique noire, le Ghana.</li><li><strong>Violente</strong>, par la lutte armée : Algérie, Kenya, colonies portugaises.</li></ul>
