insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-decolonisation-en-afrique'), 4, 'la-decolonisation-en-afrique-centrale', 'La décolonisation en Afrique centrale', true, 'published', 10, now());
