insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-decolonisation-en-afrique'), 5, 'les-independances-en-afrique-de-l-ouest', 'Les indépendances en Afrique de l’Ouest', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-decolonisation-en-afrique') and slug = 'les-independances-en-afrique-de-l-ouest'), $html$<ul><li>1957 : la Gold Coast devient le <strong>Ghana</strong> de Kwame Nkrumah, premier pays d’Afrique de l’Ouest à obtenir l’indépendance.</li><li>1958 : la <strong>Guinée</strong> de Sékou Touré vote « non » au référendum et devient indépendante.</li><li>1960 : indépendance des autres colonies de l’AOF, dont le Sénégal ; le Nigeria en octobre 1960.</li></ul>$html$);
