insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'EC' and l.code = '3E' and p.series_id is null) and c.slug = 'la-constitution-du-senegal') and slug = 'qu-est-ce-qu-une-constitution'), $html$<p>La <strong>Constitution</strong> est la loi fondamentale de l’État : elle organise les pouvoirs et garantit les droits et libertés. Toutes les autres lois doivent la respecter.</p>
