insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-calcul-dans-ir'), 1, 'puissances-et-radicaux', 'Puissances et radicaux', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-calcul-dans-ir') and slug = 'puissances-et-radicaux'), $html$<ul><li>a<sup>m</sup> × a<sup>n</sup> = a<sup>m+n</sup> ; <span class="frac"><span>a<sup>m</sup></span><span>a<sup>n</sup></span></span> = a<sup>m−n</sup> ; (ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup> ;</li><li>pour a ≥ 0 et b ≥ 0 : √(ab) = √a × √b ; √(a<sup>2</sup>) = |a| pour tout réel a ;</li><li>on rend un dénominateur rationnel : <span class="frac"><span>1</span><span>√2</span></span> = <span class="frac"><span>√2</span><span>2</span></span>.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-calcul-dans-ir'), 2, 'valeur-absolue-et-distance', 'Valeur absolue et distance', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-calcul-dans-ir') and slug = 'valeur-absolue-et-distance'), $html$<ul><li>|x| = x si x ≥ 0 et |x| = −x si x &lt; 0 ;</li><li>|x − a| est la distance entre x et a sur la droite graduée ;</li><li>|x − a| ≤ r équivaut à a − r ≤ x ≤ a + r.</li></ul>
