insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'intervalles-et-calcul-approche') and slug = 'intervalles-et-encadrements'), $html$<ul><li>l’intervalle [a ; b] a pour centre <span class="frac"><span>a + b</span><span>2</span></span> et pour rayon <span class="frac"><span>b − a</span><span>2</span></span> ;</li><li>on additionne des encadrements membre à membre : si 1,41 &lt; √2 &lt; 1,42 et 1,73 &lt; √3 &lt; 1,74, alors 3,14 &lt; √2 + √3 &lt; 3,16 ;</li><li>la <strong>partie entière</strong> E(x) est le plus grand entier inférieur ou égal à x : E(2,7) = 2 ; E(−2,3) = −3.</li></ul>
