insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'generalites-sur-les-fonctions') and slug = 'fonction-et-ensemble-de-definition'), $html$<ul><li>une fonction f associe à chaque x de son ensemble de définition D<sub>f</sub> un unique nombre f(x) ;</li><li>f(x) = <span class="frac"><span>1</span><span>x − 2</span></span> : D<sub>f</sub> = IR privé de 2 (le dénominateur ne doit pas s’annuler) ;</li><li>f(x) = √(x − 1) : D<sub>f</sub> = [1 ; +∞[ (on ne prend la racine que d’un nombre positif).</li></ul>$html$);
