insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'generalites-sur-les-fonctions') and slug = 'variations-et-parite'), $html$<ul><li>taux de variation entre a et b : <span class="frac"><span>f(b) − f(a)</span><span>b − a</span></span> ; positif sur un intervalle : f y est croissante ;</li><li>f est <strong>paire</strong> si f(−x) = f(x) : sa courbe est symétrique par rapport à l’axe des ordonnées ;</li><li>f est <strong>impaire</strong> si f(−x) = −f(x) : sa courbe est symétrique par rapport à l’origine ;</li><li>la composée g ∘ f est définie par (g ∘ f)(x) = g[f(x)].</li></ul>
