insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'equations-et-inequations-du-second-degre') and slug = 'signe-du-trinome-et-inequations'), $html$<ul><li>le trinôme a le signe de a <strong>à l’extérieur</strong> des racines et le signe contraire entre les racines ;</li><li>s’il n’a pas de racine, il a toujours le signe de a ;</li><li>pour résoudre une inéquation, on étudie le signe dans un tableau.</li></ul>
