insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'systemes-d-equations-et-d-inequations-a-deux-inconnues') and slug = 'systemes-de-deux-equations'), $html$<ul><li>par <strong>substitution</strong> : on exprime une inconnue en fonction de l’autre ;</li><li>par <strong>combinaison</strong> (addition) : on élimine une inconnue ;</li><li>par le <strong>déterminant</strong> : pour ax + by = c et a’x + b’y = c’, D = ab’ − a’b ; si D ≠ 0, la solution est unique ;</li><li>graphiquement : la solution est le point d’intersection des deux droites.</li></ul>
