insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'systemes-d-equations-et-d-inequations-a-deux-inconnues') and slug = 'inequations-a-deux-inconnues'), $html$<p>Une droite d’équation ax + by + c = 0 partage le plan en deux <strong>demi-plans</strong> : dans l’un ax + by + c &gt; 0, dans l’autre ax + by + c &lt; 0. On teste un point (souvent l’origine) pour savoir lequel convient.</p>
