insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'polynomes-et-fractions-rationnelles') and slug = 'factoriser-un-polynome'), $html$<ul><li>si a est un <strong>zéro</strong> de P (P(a) = 0), alors P(x) = (x − a) Q(x), avec Q de degré un de moins ;</li><li>on trouve Q par identification des coefficients, par la méthode de Horner ou par division euclidienne ;</li><li>on étudie ensuite le signe de P dans un tableau de signes.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'polynomes-et-fractions-rationnelles'), 2, 'fractions-rationnelles', 'Fractions rationnelles', true, 'published', 12, now());
