insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'reperage-cartesien'), 1, 'colinearite-et-equations-de-droites', 'Colinéarité et équations de droites', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'reperage-cartesien') and slug = 'colinearite-et-equations-de-droites'), $html$<ul><li>u⃗(x ; y) et v⃗(x’ ; y’) sont colinéaires si et seulement si le déterminant xy’ − x’y = 0 ;</li><li>une droite a une équation de la forme ax + by + c = 0 ; le vecteur (−b ; a) la dirige ;</li><li>si elle n’est pas parallèle à l’axe des ordonnées : y = mx + p (m est le coefficient directeur) ;</li><li>équations paramétriques : x = x<sub>A</sub> + kα, y = y<sub>A</sub> + kβ, où (α ; β) dirige la droite.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 11, 'angles-orientes-et-trigonometrie', 'Angles orientés et trigonométrie', 'Radian, cercle trigonométrique, mesure principale, cosinus et sinus.', 11, 'published', 'Activités géométriques', '[{"title":"Programme de mathématiques du second cycle, seconde S (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_2de_S.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'angles-orientes-et-trigonometrie'), 1, 'le-cercle-trigonometrique', 'Le cercle trigonométrique', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'le-cercle-trigonometrique'), $html$<ul><li>π radians = 180° ; un angle orienté a une infinité de mesures, égales à 2π près ;</li><li>sa mesure principale est celle qui appartient à ]−π ; π] ;</li><li>cos<sup>2</sup>x + sin<sup>2</sup>x = 1 ;</li><li>cos(−x) = cos x ; sin(−x) = −sin x ; cos(π − x) = −cos x ; sin(π − x) = sin x ; cos(π/2 − x) = sin x.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 12, 'produit-scalaire', 'Produit scalaire', 'Définitions, orthogonalité, relations métriques, distance d’un point à une droite, cercle.', 12, 'published', 'Activités géométriques', '[{"title":"Programme de mathématiques du second cycle, seconde S (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_2de_S.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'produit-scalaire'), 1, 'definitions-et-proprietes', 'Définitions et propriétés', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'produit-scalaire') and slug = 'definitions-et-proprietes'), $html$<ul><li>u⃗ · v⃗ = ‖u⃗‖ × ‖v⃗‖ × cos(u⃗, v⃗) ;</li><li>dans un repère orthonormal : u⃗ · v⃗ = xx’ + yy’ ;</li><li>deux vecteurs non nuls sont orthogonaux si et seulement si leur produit scalaire est nul.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'produit-scalaire'), 2, 'relations-metriques-et-applications', 'Relations métriques et applications', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'produit-scalaire') and slug = 'relations-metriques-et-applications'), $html$<ul><li>Al-Kashi : BC<sup>2</sup> = AB<sup>2</sup> + AC<sup>2</sup> − 2 AB × AC × cos Â ;</li><li>distance de A(α ; β) à la droite ax + by + c = 0 : <span class="frac"><span>|aα + bβ + c|</span><span>√(a<sup>2</sup> + b<sup>2</sup>)</span></span> ;</li><li>cercle de centre (a ; b) et de rayon r : (x − a)<sup>2</sup> + (y − b)<sup>2</sup> = r<sup>2</sup>.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 13, 'les-transformations-du-plan', 'Les transformations du plan', 'Translation, symétries, homothétie, rotation et composées.', 13, 'published', 'Activités géométriques', '[{"title":"Programme de mathématiques du second cycle, seconde S (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_2de_S.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-transformations-du-plan'), 1, 'homothetie-et-rotation', 'Homothétie et rotation', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-transformations-du-plan') and slug = 'homothetie-et-rotation'), $html$<ul><li>l’homothétie de centre O et de rapport k transforme M en M’ tel que OM’⃗ = kOM⃗ ;</li><li>elle multiplie les longueurs par |k| et les aires par k² ; elle conserve les angles et le parallélisme ;</li><li>la rotation de centre O et d’angle θ conserve les distances et les angles orientés.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-transformations-du-plan'), 2, 'composer-des-transformations', 'Composer des transformations', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-transformations-du-plan') and slug = 'composer-des-transformations'), $html$<table><thead><tr><th scope="col">Composée</th><th scope="col">Résultat</th></tr></thead><tbody><tr><td>deux homothéties de même centre, rapports k et k’</td><td>homothétie de rapport kk’</td></tr><tr><td>deux symétries centrales de centres O et O’</td><td>translation de vecteur 2OO’⃗</td></tr><tr><td>deux symétries orthogonales d’axes parallèles</td><td>translation</td></tr></tbody></table>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 14, 'geometrie-dans-l-espace', 'Géométrie dans l’espace', 'Perspective cavalière, positions relatives, parallélisme et orthogonalité.', 14, 'published', 'Activités géométriques', '[{"title":"Programme de mathématiques du second cycle, seconde S (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math_2de_S.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'geometrie-dans-l-espace'), 1, 'droites-et-plans-de-l-espace', 'Droites et plans de l’espace', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'geometrie-dans-l-espace') and slug = 'droites-et-plans-de-l-espace'), $html$<ul><li>perspective cavalière : les droites parallèles restent parallèles, les arêtes cachées sont en pointillés ;</li><li>deux droites de l’espace sont sécantes, parallèles ou non coplanaires ;</li><li>une droite parallèle à une droite d’un plan est parallèle à ce plan ;</li><li>si deux plans sécants contiennent deux droites parallèles, leur intersection est parallèle à ces droites (théorème du toit) ;</li><li>une droite orthogonale à deux droites sécantes d’un plan est orthogonale à ce plan.</li></ul>$html$);
