insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'atomes-elements-et-classification-periodique'), 1, 'l-atome', 'L’atome', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'atomes-elements-et-classification-periodique') and slug = 'l-atome'), $html$<ul><li>l’atome est formé d’un noyau (Z protons et N neutrons, A = Z + N nucléons) et de Z électrons ;</li><li>on note un noyau <sup>A</sup><sub>Z</sub>X : <sup>12</sup><sub>6</sub>C contient 6 protons et 6 neutrons ;</li><li>des <strong>isotopes</strong> ont le même Z mais des A différents (¹²C et ¹⁴C) ;</li><li>les électrons se répartissent en couches K (2 au plus), L (8), M (8 pour les 18 premiers éléments).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'atomes-elements-et-classification-periodique'), 2, 'la-classification-periodique', 'La classification périodique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'atomes-elements-et-classification-periodique') and slug = 'la-classification-periodique'), $html$<ul><li>les éléments sont rangés par Z croissant ; une ligne (période) correspond à une couche en cours de remplissage ;</li><li>les éléments d’une même colonne (famille) ont le même nombre d’électrons sur la couche externe et des propriétés voisines ;</li><li>familles : alcalins (colonne 1), halogènes (colonne 17), gaz nobles (colonne 18, très stables).</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 3, 'les-liaisons-chimiques', 'Les liaisons chimiques', 'Règles du duet et de l’octet, liaison covalente, liaison ionique.', 3, 'published', 'Chimie', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-liaisons-chimiques'), 1, 'liaison-covalente-et-liaison-ionique', 'Liaison covalente et liaison ionique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-liaisons-chimiques') and slug = 'liaison-covalente-et-liaison-ionique'), $html$<ul><li>les atomes cherchent à avoir la structure électronique du gaz noble le plus proche (règles du duet et de l’octet) ;</li><li><strong>liaison covalente</strong> : mise en commun d’un doublet d’électrons (H–H, H–O–H) ;</li><li><strong>liaison ionique</strong> : un atome cède des électrons à un autre ; les ions formés s’attirent (Na⁺ et Cl⁻ dans le sel).</li></ul>
