insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'electrisation-et-courant-electrique') and slug = 'l-electrisation'), $html$<ul><li>un corps frotté peut s’électriser : il gagne ou perd des électrons ;</li><li>deux corps de charges de même signe se repoussent ; de signes contraires, ils s’attirent ;</li><li>la charge élémentaire vaut e = 1,6 × 10⁻¹⁹ C ;</li><li>le courant électrique est un déplacement d’ensemble de porteurs de charges (électrons dans les métaux, ions dans les solutions).</li></ul>$html$);
