insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-circuit-electrique-intensite-et-tension') and slug = 'intensite-et-tension'), $html$<ul><li>le courant sort par la borne + du générateur ; dans les métaux, il est dû au déplacement des électrons (en sens inverse) ;</li><li>l’<strong>intensité</strong> I (ampère, A) se mesure avec un ampèremètre branché <strong>en série</strong> ;</li><li>la <strong>tension</strong> U (volt, V) se mesure avec un voltmètre branché <strong>en dérivation</strong> ;</li><li>en série, l’intensité est la même partout et les tensions s’additionnent ; en dérivation, les intensités s’additionnent (loi des nœuds) et la tension est la même.</li></ul>$html$);
