insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'dipoles-passifs-et-dipoles-actifs') and slug = 'dipoles-actifs'), $html$<ul><li>un générateur (pile) a une f.é.m. E et une résistance interne r : U = E − rI ;</li><li>un électrolyseur ou un moteur (récepteur actif) : U = E’ + r’I ;</li><li>le point de fonctionnement d’un circuit est l’intersection des caractéristiques du générateur et du récepteur.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 15, 'l-amplificateur-operationnel', 'L’amplificateur opérationnel', 'Présentation, régime linéaire, montages suiveur, inverseur et non inverseur.', 15, 'published', 'Physique', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
