insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-amplificateur-operationnel') and slug = 'montages-de-base'), $html$<ul><li>l’amplificateur opérationnel idéal a des courants d’entrée nuls ; en régime linéaire, la tension entre ses entrées est nulle ;</li><li>suiveur : U<sub>s</sub> = U<sub>e</sub> ;</li><li>inverseur : U<sub>s</sub> = −(R₂/R₁) U<sub>e</sub> ;</li><li>non inverseur : U<sub>s</sub> = (1 + R₂/R₁) U<sub>e</sub>.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 1, 'l-ecosysteme-structure-et-fonctionnement', 'L’écosystème : structure et fonctionnement', 'Biotope et biocénose, facteurs du milieu, chaînes alimentaires, flux d’énergie et cycle de la matière.', 1, 'published', null, '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-ecosysteme-structure-et-fonctionnement'), 1, 'structure-d-un-ecosysteme', 'Structure d’un écosystème', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-ecosysteme-structure-et-fonctionnement') and slug = 'structure-d-un-ecosysteme'), $html$<ul><li>un écosystème = un <strong>biotope</strong> (milieu physique : sol, eau, climat) + une <strong>biocénose</strong> (ensemble des êtres vivants) ;</li><li>facteurs abiotiques : lumière, température, eau, sol ; facteurs biotiques : relations entre êtres vivants (prédation, compétition, symbiose, parasitisme) ;</li><li>exemples au Sénégal : mangrove du Saloum, savane du Niokolo-Koba, Niayes.</li></ul>$html$);
