insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-evolution-des-ecosystemes-et-l-action-de-l-homme') and slug = 'ecosystemes-menaces-ecosystemes-proteges'), $html$<ul><li>un écosystème évolue naturellement (colonisation d’un sol nu, puis végétation de plus en plus dense) ;</li><li>l’homme le dégrade : déboisement, feux de brousse, surpâturage, surpêche, pollution ;</li><li>conséquences : érosion, désertification, perte de biodiversité ;</li><li>réponses : parcs et réserves, reboisement (Grande Muraille verte), repos biologique en mer, gestion communautaire.</li></ul>
