insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-eau') and slug = 'le-cycle-et-les-ressources'), $html$<ul><li>cycle : évaporation, condensation (nuages), précipitations, ruissellement, infiltration vers les nappes ;</li><li>au Sénégal : eaux de surface (fleuves Sénégal et Gambie, lac de Guiers) et eaux souterraines (nappes) ;</li><li>le lac de Guiers alimente en partie Dakar en eau potable.</li></ul>$html$);
