insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-sols') and slug = 'le-sol-un-milieu-vivant'), $html$<ul><li>le sol se forme par altération de la roche mère et décomposition de la matière organique (humification) ;</li><li>il comprend des horizons superposés ; il contient argile, limon, sable, humus, eau, air et êtres vivants ;</li><li>le complexe argilo-humique retient l’eau et les ions minéraux utiles aux plantes ;</li><li>dégradation : érosion, salinisation (tannes), appauvrissement ; conservation : jachère, fumure organique, haies, diguettes.</li></ul>
