insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-resume-de-texte') and slug = 'resumer-un-texte-argumentatif'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire le texte plusieurs fois et dégager la thèse.</li><li>Repérer les articulations logiques (mais, donc, en effet) et les idées de chaque paragraphe.</li><li>Reformuler avec ses mots, au même point de vue que l’auteur, sans citer ni commenter.</li><li>Respecter le nombre de mots demandé (avec une marge de 10 % environ) et l’indiquer.</li></ol></div>
