insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-commentaire-de-texte') and slug = 'lire-methodiquement-un-texte'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Situer le texte (auteur, œuvre, époque, genre).</li><li>Dégager le thème et l’idée générale.</li><li>Relever les procédés (champs lexicaux, figures de style, temps, rythme).</li><li>Organiser l’interprétation en deux ou trois axes de lecture.</li></ol></div>$html$);
