insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-roman') and slug = 'analyser-un-roman'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Question à se poser</th></tr></thead><tbody><tr><td>narrateur</td><td>qui raconte ? (personnage ou narrateur extérieur)</td></tr><tr><td>point de vue</td><td>interne, externe ou omniscient ?</td></tr><tr><td>personnages</td><td>portrait, rôle, évolution</td></tr><tr><td>temps</td><td>ordre des événements, retours en arrière, ellipses</td></tr></tbody></table>
