insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'la-poesie') and slug = 'lire-un-poeme'), $html$<ul><li>vers : alexandrin (12 syllabes), décasyllabe (10), octosyllabe (8) ; vers libres ;</li><li>rimes plates (AABB), croisées (ABAB), embrassées (ABBA) ;</li><li>formes : sonnet (deux quatrains et deux tercets), poème en prose, poème de la Négritude rythmé par la répétition.</li></ul>
