insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'le-theatre') and slug = 'lire-et-voir-le-theatre'), $html$<ul><li>double énonciation : les personnages se parlent, mais l’auteur s’adresse au public ;</li><li>comédie (fin heureuse, satire des mœurs) et tragédie (personnages nobles, fatalité) ;</li><li>exposition, nœud, dénouement.</li></ul>$html$);
