insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'litterature-du-moyen-age-et-de-la-renaissance'), 1, 'du-moyen-age-a-la-renaissance', 'Du Moyen Âge à la Renaissance', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'litterature-du-moyen-age-et-de-la-renaissance') and slug = 'du-moyen-age-a-la-renaissance'), $html$<ul><li>Moyen Âge : chansons de geste (<em>La Chanson de Roland</em>), romans de chevalerie, fabliaux ;</li><li>XVI<sup>e</sup> siècle : l’humanisme (Rabelais, Montaigne) met l’homme et le savoir au centre ;</li><li>la Pléiade (Ronsard, Du Bellay) enrichit la langue et la poésie française.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 1, 'l-histoire-et-les-sources-de-l-histoire-africaine', 'L’histoire et les sources de l’histoire africaine', 'Définition et importance de l’histoire ; tradition orale, archéologie, linguistique.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-histoire-et-les-sources-de-l-histoire-africaine'), 1, 'ecrire-l-histoire-de-l-afrique', 'Écrire l’histoire de l’Afrique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-histoire-et-les-sources-de-l-histoire-africaine') and slug = 'ecrire-l-histoire-de-l-afrique'), $html$<ul><li>l’histoire étudie le passé des sociétés humaines à partir de sources critiquées ;</li><li>sources écrites (chroniques arabes, Tarikh es-Soudan, récits européens), mais aussi <strong>tradition orale</strong> conservée par les griots ;</li><li>l’<strong>archéologie</strong> (fouilles, datation au carbone 14) et la <strong>linguistique</strong> (parentés entre les langues) complètent les textes.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 2, 'la-prehistoire-africaine-et-senegalaise', 'La préhistoire africaine et sénégalaise', 'L’Afrique berceau de l’humanité, paléolithique, révolution néolithique, préhistoire et protohistoire du Sénégal.', 2, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'la-prehistoire-africaine-et-senegalaise'), 1, 'l-afrique-berceau-de-l-humanite', 'L’Afrique, berceau de l’humanité', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'la-prehistoire-africaine-et-senegalaise') and slug = 'l-afrique-berceau-de-l-humanite'), $html$<ul><li>les plus anciens fossiles d’hominidés ont été découverts en Afrique (Toumaï au Tchad, Lucy en Éthiopie) ;</li><li>au <strong>paléolithique</strong>, les hommes taillent la pierre, chassent, cueillent et maîtrisent le feu ;</li><li>la <strong>révolution néolithique</strong> apporte l’agriculture, l’élevage, la poterie et la sédentarisation (Sahara vert).</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'la-prehistoire-africaine-et-senegalaise'), 2, 'prehistoire-et-protohistoire-du-senegal', 'Préhistoire et protohistoire du Sénégal', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'la-prehistoire-africaine-et-senegalaise') and slug = 'prehistoire-et-protohistoire-du-senegal'), $html$<ul><li>outils paléolithiques et néolithiques trouvés dans la presqu’île du Cap-Vert et dans la vallée de la Falémé ;</li><li>les amas coquilliers du Saloum et de Casamance témoignent d’une longue occupation du littoral ;</li><li>les cercles mégalithiques de Sénégambie (Sine Ngayène, Wanar) sont inscrits au patrimoine mondial de l’UNESCO.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 3, 'les-civilisations-de-l-afrique-ancienne', 'Les civilisations de l’Afrique ancienne', 'L’Égypte pharaonique, Axoum, les relations entre la Méditerranée et le monde noir.', 3, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-civilisations-de-l-afrique-ancienne'), 1, 'l-egypte-pharaonique-et-axoum', 'L’Égypte pharaonique et Axoum', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-civilisations-de-l-afrique-ancienne') and slug = 'l-egypte-pharaonique-et-axoum'), $html$<ul><li>l’Égypte, née le long du Nil vers 3000 av. J.-C., est gouvernée par le pharaon, roi-dieu ;</li><li>écriture hiéroglyphique, pyramides, astronomie, médecine, calendrier ;</li><li>Cheikh Anta Diop a souligné la parenté de la civilisation égyptienne avec le reste de l’Afrique noire ;</li><li>Axoum (Éthiopie) domine le commerce de la mer Rouge et adopte le christianisme au IV<sup>e</sup> siècle.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 4, 'l-afrique-occidentale-du-viie-au-xviie-siecle', 'L’Afrique occidentale du VIIe au XVIIe siècle', 'Ghana, Mali, Songhaï ; l’islamisation ; les empires du Jolof et du Gaabu.', 4, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-afrique-occidentale-du-viie-au-xviie-siecle'), 1, 'les-civilisations-du-soudan-medieval', 'Les civilisations du Soudan médiéval', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-afrique-occidentale-du-viie-au-xviie-siecle') and slug = 'les-civilisations-du-soudan-medieval'), $html$<table><thead><tr><th scope="col">Empire</th><th scope="col">Période</th><th scope="col">Repères</th></tr></thead><tbody><tr><td>Ghana</td><td>jusqu’au XI<sup>e</sup> siècle</td><td>Koumbi Saleh, or, commerce transsaharien</td></tr><tr><td>Mali</td><td>XIII<sup>e</sup>-XV<sup>e</sup> siècle</td><td>Soundjata Keïta, Kankou Moussa, Tombouctou</td></tr><tr><td>Songhaï</td><td>XV<sup>e</sup>-XVI<sup>e</sup> siècle</td><td>Gao, Sonni Ali Ber, Askia Mohammed, Tondibi (1591)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-afrique-occidentale-du-viie-au-xviie-siecle'), 2, 'les-empires-du-jolof-et-du-gaabu', 'Les empires du Jolof et du Gaabu', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-afrique-occidentale-du-viie-au-xviie-siecle') and slug = 'les-empires-du-jolof-et-du-gaabu'), $html$<ul><li>le Jolof, fondé selon la tradition par Ndiadiane Ndiaye, domine au XV<sup>e</sup> siècle les royaumes wolofs et sérères ;</li><li>il se disloque après la bataille de Danki (vers 1549) ;</li><li>le Gaabu, issu de l’empire du Mali, domine la Haute-Casamance et la Guinée-Bissau actuelle jusqu’en 1867 (Kansala).</li></ul>$html$);
