insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-traites-negrieres'), 1, 'traite-arabe-et-traite-atlantique', 'Traite arabe et traite atlantique', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-traites-negrieres') and slug = 'traite-arabe-et-traite-atlantique'), $html$<ul><li>la traite arabe, plus ancienne (dès le VII<sup>e</sup> siècle), passe par le Sahara, la mer Rouge et l’océan Indien ;</li><li>la traite atlantique (XVI<sup>e</sup>-XIX<sup>e</sup> siècle) alimente les plantations d’Amérique par le commerce triangulaire ;</li><li>conséquences en Afrique : saignée démographique, guerres, insécurité, recul des activités productives.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')), 6, 'l-afrique-du-xviiie-siecle-a-la-veille-de-l-imperialisme', 'L’Afrique du XVIIIe siècle à la veille de l’impérialisme', 'La révolution torodo, l’empire d’El Hadji Omar, l’empire zoulou de Tchaka.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
