insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-afrique-du-xviiie-siecle-a-la-veille-de-l-imperialisme') and slug = 'revolutions-et-empires'), $html$<ul><li>révolution torodo (1776) au Fouta Toro : les Denianké sont renversés, l’almamyat est instauré ;</li><li>El Hadji Omar Tall lance son jihad en 1852 et fonde l’empire toucouleur (Ségou, Macina) ;</li><li>Tchaka réforme l’armée zouloue et bâtit un puissant royaume en Afrique australe (1816-1828).</li></ul>$html$);
