insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-europe-et-l-amerique-de-1776-a-1870'), 1, 'l-age-des-revolutions', 'L’âge des révolutions', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'l-europe-et-l-amerique-de-1776-a-1870') and slug = 'l-age-des-revolutions'), $html$<table><thead><tr><th scope="col">Révolution</th><th scope="col">Dates clés</th><th scope="col">Idées et résultats</th></tr></thead><tbody><tr><td>américaine</td><td>1776, 1783, 1787</td><td>indépendance, république fédérale, Constitution</td></tr><tr><td>française</td><td>1789, 1792</td><td>fin de la monarchie absolue, Déclaration des droits de l’homme</td></tr><tr><td>haïtienne</td><td>1791-1804</td><td>révolte des esclaves (Toussaint Louverture), première république noire</td></tr></tbody></table>$html$);
