insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'continents-oceans-et-mers') and slug = 'terres-et-mers'), $html$<ul><li>les océans couvrent environ 71 % de la surface de la Terre ;</li><li>cinq océans : Pacifique (le plus grand), Atlantique, Indien, Arctique, Austral ;</li><li>les eaux marines sont salées et animées de courants : le courant froid des Canaries longe la côte sénégalaise ;</li><li>les remontées d’eaux froides (upwelling) rendent ces côtes très poissonneuses.</li></ul>$html$);
