insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'S')) and c.slug = 'les-climats-de-la-terre') and slug = 'facteurs-et-elements-du-climat'), $html$<ul><li>éléments : température, précipitations, pression, vents, humidité ;</li><li>facteurs : latitude, altitude, distance à la mer, courants marins, circulation atmosphérique ;</li><li>au Sénégal, l’harmattan (sec, venu du Sahara) souffle en saison sèche ; la mousson (humide) apporte les pluies d’été.</li></ul>
