insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'la-terre-dans-le-systeme-solaire') and slug = 'les-mouvements-de-la-terre'), $html$<ul><li>la Terre tourne sur elle-même en 24 h environ (rotation) : alternance du jour et de la nuit ;</li><li>elle tourne autour du Soleil en 365 jours et 6 heures environ (révolution) ;</li><li>l’inclinaison de son axe explique les saisons et l’inégale durée des jours ;</li><li>un lieu est repéré par sa latitude (par rapport à l’équateur) et sa longitude (par rapport au méridien de Greenwich).</li></ul>
