insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'les-reliefs-de-la-terre') and slug = 'formation-et-modele-des-reliefs'), $html$<ul><li>la lithosphère est découpée en plaques qui se déplacent : elles forment les chaînes de montagnes et provoquent séismes et volcans ;</li><li>roches magmatiques, sédimentaires et métamorphiques ;</li><li>grandes structures : socles anciens, bassins sédimentaires, chaînes récentes ;</li><li>l’érosion (eau, vent, glace) façonne les reliefs : plaines, plateaux, montagnes.</li></ul>
