insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'calcul-algebrique-dans-ir') and slug = 'identites-remarquables-et-factorisation'), $html$<ul><li>(a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup> ; (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup> ; (a + b)(a − b) = a<sup>2</sup> − b<sup>2</sup> ;</li><li>(a + b)<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup> ;</li><li>a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>).</li></ul>
