insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'fonctions-affines-et-droites-du-plan') and slug = 'fonctions-affines'), $html$<ul><li>f(x) = ax + b ; sa courbe est une droite de coefficient directeur a et d’ordonnée à l’origine b ;</li><li>le taux d’accroissement <span class="frac"><span>f(x₂) − f(x₁)</span><span>x₂ − x₁</span></span> est constant et égal à a ;</li><li>deux droites sont parallèles si elles ont le même coefficient directeur ; dans un repère orthonormal, elles sont perpendiculaires si le produit des coefficients vaut −1.</li></ul>
