insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'lectures-graphiques') and slug = 'lire-un-graphique'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire le titre, les axes et leurs unités.</li><li>Repérer les maximums, les minimums, les hausses et les baisses.</li><li>Interpoler : entre deux points connus, on estime une valeur en supposant une évolution régulière (en ligne droite).</li></ol></div>
