insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'statistique-position-et-dispersion') and slug = 'resumer-une-serie-statistique'), $html$<ul><li>position : mode, médiane (valeur du milieu de la série ordonnée), moyenne ;</li><li>quartiles : Q1 et Q3 encadrent la moitié centrale des valeurs ;</li><li>dispersion : étendue (plus grande − plus petite valeur), écart interquartile Q3 − Q1, écart-type.</li></ul>
