insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'systemes-d-equations-et-d-inequations-a-deux-inconnues') and slug = 'systemes-de-deux-equations'), $html$<ul><li>par <strong>substitution</strong> : on exprime une inconnue en fonction de l’autre ;</li><li>par <strong>combinaison</strong> (addition) : on élimine une inconnue ;</li><li>par le <strong>déterminant</strong> : pour ax + by = c et a’x + b’y = c’, D = ab’ − a’b ; si D ≠ 0, la solution est unique ;</li><li>graphiquement : la solution est le point d’intersection des deux droites.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'systemes-d-equations-et-d-inequations-a-deux-inconnues'), 2, 'inequations-a-deux-inconnues', 'Inéquations à deux inconnues', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'systemes-d-equations-et-d-inequations-a-deux-inconnues') and slug = 'inequations-a-deux-inconnues'), $html$<p>Une droite d’équation ax + by + c = 0 partage le plan en deux <strong>demi-plans</strong> : dans l’un ax + by + c &gt; 0, dans l’autre ax + by + c &lt; 0. On teste un point (souvent l’origine) pour savoir lequel convient.</p>
