insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'melanges-et-corps-purs') and slug = 'melanges-corps-purs-corps-simples'), $html$<ul><li>un corps pur a des constantes physiques fixes (températures de fusion et d’ébullition, masse volumique) ;</li><li>séparation : décantation, filtration, distillation, extraction par solvant, chromatographie ;</li><li>un corps pur <strong>simple</strong> n’est formé que d’un seul élément (dioxygène O₂, fer Fe) ; un corps <strong>composé</strong> en contient plusieurs (eau H₂O).</li></ul>
