insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'structure-et-quantite-de-matiere') and slug = 'de-l-atome-a-la-mole'), $html$<ul><li>la matière est faite d’atomes, de molécules et d’ions ;</li><li>un atome : un noyau (protons et neutrons) et des électrons ; il est neutre ;</li><li>la quantité de matière se compte en moles : n = m ÷ M.</li></ul>
