insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'transformations-de-la-matiere') and slug = 'physique-ou-chimique'), $html$<ul><li>transformation physique : la matière change d’état ou de forme mais reste la même (la glace fond) ;</li><li>transformation chimique : de nouvelles substances apparaissent (le bois brûle, le fer rouille) ;</li><li>au cours d’une réaction chimique, les éléments et la masse se conservent.</li></ul>
