insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'solutions-aqueuses-acides-et-basiques-ph') and slug = 'solutions-et-concentration'), $html$<ul><li>une solution aqueuse est obtenue en dissolvant un <strong>soluté</strong> dans l’eau (le solvant) ;</li><li>concentration massique : C<sub>m</sub> = m ÷ V (g/L) ; concentration molaire : C = n ÷ V (mol/L) ;</li><li>une solution d’acide chlorhydrique contient des ions H₃O⁺ ; une solution d’hydroxyde de sodium (soude) des ions OH⁻.</li></ul>
