insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-electricite-dans-notre-environnement') and slug = 'produire-et-utiliser-l-electricite'), $html$<ul><li>centrales thermiques (fioul, gaz), solaires, éoliennes (Taïba Ndiaye), hydroélectriques (barrage de Manantali) ;</li><li>le courant du secteur est alternatif : environ 230 V (on dit souvent « 220 V ») et 50 Hz ;</li><li>dangers : électrocution, incendie ; le disjoncteur et la prise de terre protègent ;</li><li>économiser l’énergie : éteindre les lampes, préférer les lampes à basse consommation.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')), 6, 'le-circuit-electrique-intensite-et-tension', 'Le circuit électrique : intensité et tension', 'Courant électrique, sens conventionnel, intensité et tension, lois des circuits.', 6, 'published', 'Physique', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'le-circuit-electrique-intensite-et-tension'), 1, 'intensite-et-tension', 'Intensité et tension', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'le-circuit-electrique-intensite-et-tension') and slug = 'intensite-et-tension'), $html$<ul><li>le courant sort par la borne + du générateur ; dans les métaux, il est dû au déplacement des électrons (en sens inverse) ;</li><li>l’<strong>intensité</strong> I (ampère, A) se mesure avec un ampèremètre branché <strong>en série</strong> ;</li><li>la <strong>tension</strong> U (volt, V) se mesure avec un voltmètre branché <strong>en dérivation</strong> ;</li><li>en série, l’intensité est la même partout et les tensions s’additionnent ; en dérivation, les intensités s’additionnent (loi des nœuds) et la tension est la même.</li></ul>$html$);
