insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'mouvement-et-vitesse') and slug = 'decrire-un-mouvement'), $html$<ul><li>un mouvement se décrit par rapport à un <strong>référentiel</strong> (le sol, le car) : un passager est immobile par rapport au car, en mouvement par rapport à la route ;</li><li>la trajectoire est l’ensemble des positions successives : rectiligne, circulaire, curviligne ;</li><li>mouvement uniforme : la vitesse reste constante.</li></ul>
