insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'forces-poids-et-masse') and slug = 'les-forces'), $html$<ul><li>une force peut mettre un objet en mouvement, modifier son mouvement ou le déformer ;</li><li>elle a un point d’application, une direction, un sens et une intensité (en newtons, N) mesurée au dynamomètre ;</li><li>on la représente par un vecteur ; forces de contact (réaction, tension d’un fil) ou à distance (poids, force magnétique).</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'forces-poids-et-masse'), 2, 'poids-et-masse', 'Poids et masse', true, 'published', 12, now());
