insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-ecosysteme-structure-et-fonctionnement'), 1, 'structure-d-un-ecosysteme', 'Structure d’un écosystème', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-ecosysteme-structure-et-fonctionnement') and slug = 'structure-d-un-ecosysteme'), $html$<ul><li>un écosystème = un <strong>biotope</strong> (milieu physique : sol, eau, climat) + une <strong>biocénose</strong> (ensemble des êtres vivants) ;</li><li>facteurs abiotiques : lumière, température, eau, sol ; facteurs biotiques : relations entre êtres vivants (prédation, compétition, symbiose, parasitisme) ;</li><li>exemples au Sénégal : mangrove du Saloum, savane du Niokolo-Koba, Niayes.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-ecosysteme-structure-et-fonctionnement'), 2, 'chaines-alimentaires-et-flux-d-energie', 'Chaînes alimentaires et flux d’énergie', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-ecosysteme-structure-et-fonctionnement') and slug = 'chaines-alimentaires-et-flux-d-energie'), $html$<table><thead><tr><th scope="col">Niveau</th><th scope="col">Rôle</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>producteurs</td><td>fabriquent la matière organique par photosynthèse</td><td>herbe, plancton végétal</td></tr><tr><td>consommateurs primaires</td><td>herbivores</td><td>gazelle, criquet</td></tr><tr><td>consommateurs secondaires</td><td>carnivores</td><td>lion, oiseau insectivore</td></tr><tr><td>décomposeurs</td><td>recyclent la matière organique en matière minérale</td><td>bactéries, champignons</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')), 2, 'l-evolution-des-ecosystemes-et-l-action-de-l-homme', 'L’évolution des écosystèmes et l’action de l’homme', 'Successions écologiques, dégradation, désertification, protection et gestion durable.', 2, 'published', null, '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-evolution-des-ecosystemes-et-l-action-de-l-homme'), 1, 'ecosystemes-menaces-ecosystemes-proteges', 'Écosystèmes menacés, écosystèmes protégés', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-evolution-des-ecosystemes-et-l-action-de-l-homme') and slug = 'ecosystemes-menaces-ecosystemes-proteges'), $html$<ul><li>un écosystème évolue naturellement (colonisation d’un sol nu, puis végétation de plus en plus dense) ;</li><li>l’homme le dégrade : déboisement, feux de brousse, surpâturage, surpêche, pollution ;</li><li>conséquences : érosion, désertification, perte de biodiversité ;</li><li>réponses : parcs et réserves, reboisement (Grande Muraille verte), repos biologique en mer, gestion communautaire.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')), 3, 'l-eau', 'L’eau', 'Le cycle de l’eau, les ressources en eau du Sénégal, la pollution et le traitement de l’eau.', 3, 'published', null, '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-eau'), 1, 'le-cycle-et-les-ressources', 'Le cycle et les ressources', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-eau') and slug = 'le-cycle-et-les-ressources'), $html$<ul><li>cycle : évaporation, condensation (nuages), précipitations, ruissellement, infiltration vers les nappes ;</li><li>au Sénégal : eaux de surface (fleuves Sénégal et Gambie, lac de Guiers) et eaux souterraines (nappes) ;</li><li>le lac de Guiers alimente en partie Dakar en eau potable.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-eau'), 2, 'pollution-et-potabilisation', 'Pollution et potabilisation', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'l-eau') and slug = 'pollution-et-potabilisation'), $html$<ul><li>pollutions : eaux usées, engrais et pesticides, déchets plastiques, salinisation des nappes près de la côte ;</li><li>maladies liées à l’eau : choléra, diarrhées, bilharziose ;</li><li>potabilisation : décantation, filtration, désinfection (chlore) ;</li><li>à la maison : conserver l’eau dans un récipient propre et fermé.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')), 4, 'les-sols', 'Les sols', 'Formation, constituants, propriétés et fertilité ; dégradation et conservation.', 4, 'published', null, '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'les-sols'), 1, 'le-sol-un-milieu-vivant', 'Le sol, un milieu vivant', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '2NDE' and p.series_id = (select id from public.series where code = 'L')) and c.slug = 'les-sols') and slug = 'le-sol-un-milieu-vivant'), $html$<ul><li>le sol se forme par altération de la roche mère et décomposition de la matière organique (humification) ;</li><li>il comprend des horizons superposés ; il contient argile, limon, sable, humus, eau, air et êtres vivants ;</li><li>le complexe argilo-humique retient l’eau et les ions minéraux utiles aux plantes ;</li><li>dégradation : érosion, salinisation (tannes), appauvrissement ; conservation : jachère, fumure organique, haies, diguettes.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 1, 'generalites-sur-les-fonctions-et-applications', 'Généralités sur les fonctions et applications', 'Applications injectives, surjectives, bijectives ; parité, périodicité ; courbes associées.', 1, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'generalites-sur-les-fonctions-et-applications'), 1, 'applications-et-fonctions', 'Applications et fonctions', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'generalites-sur-les-fonctions-et-applications') and slug = 'applications-et-fonctions'), $html$<ul><li>une application f de E dans F est <strong>injective</strong> si deux éléments distincts ont des images distinctes, <strong>surjective</strong> si tout élément de F a au moins un antécédent, <strong>bijective</strong> si elle est les deux ;</li><li>une bijection admet une application réciproque f⁻¹ ;</li><li>f est périodique de période T si f(x + T) = f(x) : cos et sin sont 2π-périodiques ;</li><li>la courbe de x ↦ f(x − a) + b se déduit de celle de f par la translation de vecteur (a ; b).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 2, 'limites-et-continuite', 'Limites et continuité', 'Limites finies et infinies, opérations, formes indéterminées, asymptotes, continuité.', 2, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite'), 1, 'calculer-des-limites', 'Calculer des limites', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite') and slug = 'calculer-des-limites'), $html$<ul><li>à l’infini, un polynôme a la limite de son terme de plus haut degré ; une fraction rationnelle, celle du quotient des termes de plus haut degré ;</li><li>formes indéterminées : ∞ − ∞, 0 × ∞, ∞/∞, 0/0 : on factorise ou on simplifie ;</li><li>si lim f(x) = ±∞ quand x tend vers a, la droite x = a est asymptote verticale ; si lim f(x) = b à l’infini, y = b est asymptote horizontale.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite'), 2, 'la-continuite', 'La continuité', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite') and slug = 'la-continuite'), $html$<ul><li>f est continue en a si lim f(x) = f(a) quand x tend vers a ;</li><li>les fonctions polynômes et rationnelles sont continues sur leur ensemble de définition ;</li><li>l’image d’un intervalle par une fonction continue est un intervalle (théorème des valeurs intermédiaires).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 3, 'derivation-et-applications', 'Dérivation et applications', 'Nombre dérivé, tangente, dérivées usuelles, sens de variation, extremums.', 3, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-applications'), 1, 'nombre-derive-et-tangente', 'Nombre dérivé et tangente', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-applications') and slug = 'nombre-derive-et-tangente'), $html$<p class="formula">f’(a) = lim <span class="frac"><span>f(a + h) − f(a)</span><span>h</span></span> quand h → 0 ; tangente : y = f’(a)(x − a) + f(a)</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-applications'), 2, 'derivee-et-variations', 'Dérivée et variations', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-applications') and slug = 'derivee-et-variations'), $html$<ul><li>f’ ≥ 0 sur un intervalle : f y est croissante ; f’ ≤ 0 : décroissante ;</li><li>si f’ s’annule en changeant de signe en a, f(a) est un extremum local.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 4, 'etude-de-fonctions', 'Étude de fonctions', 'Plan d’étude d’une fonction polynôme ou rationnelle, asymptotes, éléments de symétrie.', 4, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'etude-de-fonctions'), 1, 'etudier-une-fonction', 'Étudier une fonction', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'etude-de-fonctions') and slug = 'etudier-une-fonction'), $html$<div class="callout"><p class="callout-title">Plan d’étude</p><ol><li>Ensemble de définition, parité ou périodicité éventuelles.</li><li>Limites aux bornes et asymptotes (verticales, horizontales, obliques y = ax + b si f(x) − (ax + b) tend vers 0).</li><li>Dérivée, signe de la dérivée, tableau de variations.</li><li>Points particuliers (intersections avec les axes, tangentes), puis courbe.</li></ol></div>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 5, 'suites-numeriques', 'Suites numériques', 'Génération d’une suite, sens de variation, suites arithmétiques et géométriques.', 5, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques'), 1, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Arithmétique (raison r)</th><th scope="col">Géométrique (raison q)</th></tr></thead><tbody><tr><td>relation</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>somme de termes consécutifs</td><td>nombre de termes × (premier + dernier) ÷ 2</td><td>premier × <span class="frac"><span>1 − q<sup>nombre de termes</sup></span><span>1 − q</span></span> (q ≠ 1)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 6, 'polynomes-equations-et-systemes', 'Polynômes, équations et systèmes', 'Méthode de Horner, somme et produit des racines, équations à paramètre, pivot de Gauss.', 6, 'published', 'Algèbre', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'polynomes-equations-et-systemes'), 1, 'polynomes-et-equations', 'Polynômes et équations', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'polynomes-equations-et-systemes') and slug = 'polynomes-et-equations'), $html$<ul><li>si a est racine de P, la méthode de Horner donne le quotient Q tel que P(x) = (x − a)Q(x) ;</li><li>si ax<sup>2</sup> + bx + c = 0 a deux racines x₁ et x₂ : x₁ + x₂ = −b/a et x₁x₂ = c/a ;</li><li>un système de trois équations à trois inconnues se résout par la méthode du pivot de Gauss (on se ramène à un système triangulaire).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 7, 'denombrement', 'Dénombrement', 'Arbres et tableaux, p-listes, arrangements, combinaisons, triangle de Pascal, binôme de Newton.', 7, 'published', 'Algèbre', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'denombrement'), 1, 'compter-sans-se-tromper', 'Compter sans se tromper', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'denombrement') and slug = 'compter-sans-se-tromper'), $html$<table><thead><tr><th scope="col">Situation</th><th scope="col">Nombre</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>p-listes (ordre, répétitions possibles)</td><td>n<sup>p</sup></td><td>codes de 4 chiffres : 10⁴ = 10 000</td></tr><tr><td>arrangements (ordre, sans répétition)</td><td>A<sup>p</sup><sub>n</sub> = <span class="frac"><span>n!</span><span>(n − p)!</span></span></td><td>podium de 3 parmi 8 : 8 × 7 × 6 = 336</td></tr><tr><td>combinaisons (sans ordre)</td><td>C<sup>p</sup><sub>n</sub> = <span class="frac"><span>n!</span><span>p!(n − p)!</span></span></td><td>comité de 2 parmi 5 : 10</td></tr><tr><td>permutations</td><td>n!</td><td>ranger 4 livres : 24</td></tr></tbody></table>
