insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'couples-oxydant-reducteur-ion-metallique-metal') and slug = 'oxydants-reducteurs-et-classification'), $html$<ul><li>un <strong>oxydant</strong> capte des électrons ; un <strong>réducteur</strong> en cède ;</li><li>couple Cu²⁺/Cu : Cu²⁺ + 2 e⁻ ⇄ Cu ;</li><li>une lame de zinc dans une solution de sulfate de cuivre se recouvre de cuivre : Zn + Cu²⁺ → Zn²⁺ + Cu ;</li><li>on classe les couples par leur potentiel standard E° (référence : couple H⁺/H₂, E° = 0 V).</li></ul>
