insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-electrolyses') and slug = 'bilan-quantitatif-d-une-electrolyse'), $html$<ul><li>à l’anode (reliée au +) se produit une oxydation ; à la cathode (reliée au −), une réduction ;</li><li>quantité d’électricité : Q = I × t (coulombs) ;</li><li>quantité d’électrons : n(e⁻) = Q ÷ F, avec F = 96 500 C/mol (faraday).</li></ul>
