insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-echanges-cellulaires') and slug = 'diffusion-et-osmose'), $html$<ul><li>diffusion : les substances dissoutes passent du milieu le plus concentré vers le moins concentré ;</li><li>osmose : l’eau traverse la membrane vers le milieu le plus concentré (hypertonique) ;</li><li>dans un milieu hypotonique, la cellule végétale se gonfle (turgescence) ; dans un milieu hypertonique, elle se vide (plasmolyse) ;</li><li>le transport actif fait passer des substances contre le gradient de concentration, en consommant de l’énergie (ATP).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 4, 'chromosomes-et-mitose', 'Chromosomes et mitose', 'Structure des chromosomes, caryotype, étapes de la mitose.', 4, 'published', 'Biologie cellulaire', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'chromosomes-et-mitose'), 1, 'la-division-cellulaire', 'La division cellulaire', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'chromosomes-et-mitose') and slug = 'la-division-cellulaire'), $html$<ul><li>un chromosome est formé d’ADN associé à des protéines ; avant la division, il est dupliqué (deux chromatides) ;</li><li>le caryotype humain compte 46 chromosomes (2n = 46) ;</li><li>la mitose : prophase, métaphase (chromosomes alignés sur la plaque équatoriale), anaphase (séparation des chromatides), télophase ;</li><li>elle donne deux cellules filles identiques à la cellule mère.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 5, 'la-synthese-des-proteines', 'La synthèse des protéines', 'ADN, gène, transcription, traduction, code génétique.', 5, 'published', 'Biologie cellulaire', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
