insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-ration-alimentaire') and slug = 'une-ration-adaptee'), $html$<ul><li>valeur énergétique : 1 g de glucides ou de protides fournit environ 17 kJ, 1 g de lipides environ 38 kJ ;</li><li>la ration varie avec l’âge, le sexe, l’activité, la grossesse ou l’allaitement ;</li><li>équilibre conseillé : environ 55 % de l’énergie par les glucides, 30 % par les lipides, 15 % par les protides ;</li><li>malnutrition par carence (kwashiorkor, marasme) ou par excès (obésité, diabète).</li></ul>$html$);
