insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-roches-magmatiques-granite-et-basalte') and slug = 'granite-et-basalte'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Granite</th><th scope="col">Basalte</th></tr></thead><tbody><tr><td>refroidissement</td><td>lent, en profondeur</td><td>rapide, en surface</td></tr><tr><td>structure</td><td>grenue (tous les minéraux en cristaux)</td><td>microlitique (verre et petits cristaux)</td></tr><tr><td>minéraux</td><td>quartz, feldspaths, micas</td><td>feldspaths, pyroxènes, olivine</td></tr><tr><td>au Sénégal</td><td>Sénégal oriental</td><td>presqu’île du Cap-Vert</td></tr></tbody></table>$html$);
