insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-dissertation-litteraire') and slug = 'construire-une-dissertation'), $html$<ul><li>analyser les mots clés du sujet et reformuler la question posée ;</li><li>plan dialectique (thèse, antithèse, synthèse) ou thématique ;</li><li>chaque argument est illustré par un exemple tiré des œuvres lues.</li></ul>
