insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-revolution-industrielle-et-ses-consequences'), 1, 'genese-et-consequences', 'Genèse et conséquences', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-revolution-industrielle-et-ses-consequences') and slug = 'genese-et-consequences'), $html$<ul><li>née en Grande-Bretagne à la fin du XVIII<sup>e</sup> siècle (charbon, machine à vapeur, textile), elle gagne l’Europe et les États-Unis ;</li><li>deuxième révolution industrielle à la fin du XIX<sup>e</sup> siècle : électricité, pétrole, chimie, automobile ;</li><li>le capitalisme se développe (banques, sociétés anonymes, concentrations) ;</li><li>la société se transforme : bourgeoisie industrielle, classe ouvrière, exode rural, urbanisation.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-revolution-industrielle-et-ses-consequences'), 2, 'syndicalisme-et-socialisme', 'Syndicalisme et socialisme', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-revolution-industrielle-et-ses-consequences') and slug = 'syndicalisme-et-socialisme'), $html$<ul><li>les ouvriers s’organisent en syndicats pour obtenir de meilleurs salaires et conditions de travail ;</li><li>le socialisme critique le capitalisme ; Karl Marx et Friedrich Engels publient le <em>Manifeste du parti communiste</em> (1848) ;</li><li>l’Église catholique propose sa doctrine sociale (encyclique <em>Rerum novarum</em>, 1891).</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 2, 'l-imperialisme-europeen-en-afrique', 'L’impérialisme européen en Afrique', 'Causes, doctrines et méthodes ; positions en 1870 et en 1914 ; la conférence de Berlin.', 2, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-imperialisme-europeen-en-afrique'), 1, 'le-partage-de-l-afrique', 'Le partage de l’Afrique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-imperialisme-europeen-en-afrique') and slug = 'le-partage-de-l-afrique'), $html$<ul><li>causes : besoins de matières premières et de débouchés, rivalités entre puissances, prestige, prétendue « mission civilisatrice » ;</li><li>méthodes : explorations, missions, traités de protectorat, conquête militaire ;</li><li>la conférence de Berlin (1884-1885) fixe les règles de l’occupation des côtes africaines ;</li><li>en 1914, seuls l’Éthiopie et le Liberia restent indépendants.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S1')), 3, 'les-resistances-africaines-a-l-imperialisme', 'Les résistances africaines à l’impérialisme', 'Résistances armées, culturelles et passives.', 3, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
