insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'barycentre-et-lignes-de-niveau') and slug = 'barycentre-de-plusieurs-points'), $html$<ul><li>G barycentre de (A, a), (B, b), (C, c) avec a + b + c ≠ 0 : aGA⃗ + bGB⃗ + cGC⃗ = 0⃗ ;</li><li>associativité : on peut remplacer des points par leur barycentre partiel affecté de la somme de leurs coefficients ;</li><li>coordonnées : x<sub>G</sub> = <span class="frac"><span>ax<sub>A</sub> + bx<sub>B</sub> + cx<sub>C</sub></span><span>a + b + c</span></span>.</li></ul>
