insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'generalisation-de-l-oxydoreduction') and slug = 'nombres-d-oxydation-et-voie-seche'), $html$<ul><li>le nombre d’oxydation (n.o.) d’un élément augmente lors d’une oxydation et diminue lors d’une réduction ;</li><li>on équilibre une équation redox en égalisant les électrons échangés ;</li><li>voie sèche : réaction sans solution, par exemple la réduction de l’oxyde de fer par l’aluminium (aluminothermie) ou par le carbone dans les hauts-fourneaux.</li></ul>
