insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'les-roches-metamorphiques-et-la-tectonique') and slug = 'metamorphisme-et-deformations'), $html$<ul><li>sous l’effet de la température et de la pression, une roche se transforme sans fondre : c’est le métamorphisme (argile → schiste → micaschiste → gneiss) ;</li><li>les roches se déforment : plis (déformation souple) et failles (cassures) ;</li><li>ces déformations résultent des mouvements des plaques et accompagnent la formation des chaînes de montagnes.</li></ul>$html$);
