insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'le-commentaire-compose') and slug = 'rediger-un-commentaire-compose'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Introduction : situer le texte, présenter son thème, annoncer les axes.</li><li>Développement : deux ou trois axes ; chaque idée s’appuie sur des citations et des procédés analysés.</li><li>Conclusion : bilan de la lecture et ouverture.</li></ol></div>
