insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'la-population-mondiale') and slug = 'croissance-et-repartition'), $html$<ul><li>plus de 8 milliards d’habitants ; la croissance ralentit, mais reste forte en Afrique ;</li><li>taux d’accroissement naturel = taux de natalité − taux de mortalité ;</li><li>la population est concentrée en Asie de l’Est et du Sud, en Europe, en Afrique de l’Ouest ; les déserts et les régions froides sont presque vides ;</li><li>migrations internes (exode rural) et internationales ; politiques natalistes ou de limitation des naissances.</li></ul>
