insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'la-litterature-negro-africaine') and slug = 'de-la-negritude-au-roman-africain'), $html$<ul><li>la Négritude (Senghor, Césaire, Damas) affirme les valeurs des civilisations noires ;</li><li>le roman colonial dénonce l’injustice : <em>Une vie de boy</em> (Ferdinand Oyono, 1956) ;</li><li><em>L’Aventure ambiguë</em> (Cheikh Hamidou Kane, 1961) pose la question de la rencontre des cultures ;</li><li><em>Une si longue lettre</em> (Mariama Bâ, 1979) donne la parole aux femmes.</li></ul>$html$);
