insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'polynomes-et-signe') and slug = 'factoriser-et-etudier-le-signe'), $html$<ul><li>si P(a) = 0, P(x) = (x − a)Q(x) ; on trouve Q par division euclidienne ou identification ;</li><li>on étudie le signe de chaque facteur et on dresse un tableau de signes ;</li><li>on en déduit les solutions d’une inéquation P(x) ≥ 0.</li></ul>
