insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'statistique-ajustement-par-la-methode-de-mayer') and slug = 'la-droite-de-mayer'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Représenter le nuage de points.</li><li>Partager la série (rangée selon x) en deux groupes de même effectif.</li><li>Calculer le point moyen de chaque groupe.</li><li>Tracer la droite qui passe par ces deux points : elle sert à faire des prévisions.</li></ol></div>$html$);
