insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'le-xviiie-siecle-les-lumieres') and slug = 'les-philosophes-des-lumieres'), $html$<ul><li>Montesquieu (<em>Lettres persanes</em>, <em>De l’esprit des lois</em>) ;</li><li>Voltaire (<em>Candide</em>) dénonce l’intolérance et l’esclavage ;</li><li>Rousseau (<em>Du contrat social</em>) et Diderot (<em>Encyclopédie</em>).</li></ul>
