insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'le-xixe-siecle-romantisme-realisme-symbolisme') and slug = 'trois-mouvements'), $html$<table><thead><tr><th scope="col">Mouvement</th><th scope="col">Caractères</th><th scope="col">Auteurs</th></tr></thead><tbody><tr><td>romantisme</td><td>expression du moi, sentiments, nature, engagement</td><td>Hugo, Lamartine</td></tr><tr><td>réalisme et naturalisme</td><td>peindre la société telle qu’elle est</td><td>Balzac, Flaubert, Zola</td></tr><tr><td>symbolisme</td><td>suggérer par les images et la musique des mots</td><td>Baudelaire, Verlaine, Rimbaud</td></tr></tbody></table>$html$);
