insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective'), 1, 'vers-une-nouvelle-guerre', 'Vers une nouvelle guerre', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective') and slug = 'vers-une-nouvelle-guerre'), $html$<ul><li>le krach de Wall Street (octobre 1929) provoque une crise mondiale : faillites, chômage, effondrement des prix agricoles (y compris de l’arachide) ;</li><li>fascisme en Italie (Mussolini, 1922), nazisme en Allemagne (Hitler, 1933) ;</li><li>la Société des Nations ne peut empêcher les agressions : invasion de l’Éthiopie par l’Italie (1935), remilitarisation de la Rhénanie, annexions allemandes.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')), 8, 'la-seconde-guerre-mondiale-et-l-afrique', 'La Seconde Guerre mondiale et l’Afrique', 'Les principales étapes du conflit ; la participation de l’Afrique.', 8, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-seconde-guerre-mondiale-et-l-afrique'), 1, '1939-1945', '1939-1945', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-seconde-guerre-mondiale-et-l-afrique') and slug = '1939-1945'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Événement</th></tr></thead><tbody><tr><td>septembre 1939</td><td>invasion de la Pologne, début de la guerre</td></tr><tr><td>juin 1940</td><td>défaite de la France ; appel du général de Gaulle</td></tr><tr><td>1941</td><td>l’URSS et les États-Unis entrent en guerre</td></tr><tr><td>1942-1943</td><td>tournants : El-Alamein, Stalingrad</td></tr><tr><td>mai et août 1945</td><td>capitulation de l’Allemagne, puis du Japon après les bombes atomiques</td></tr></tbody></table>
