insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'le-senegal-de-1914-a-1945') and slug = 'le-senegal-colonial'), $html$<ul><li>en 1914, Blaise Diagne est le premier député africain élu à l’Assemblée nationale française ; il organise le recrutement de tirailleurs en 1918 ;</li><li>entre les deux guerres : économie de traite de l’arachide, chemin de fer Dakar-Niger, crise des années 1930 ;</li><li>vie politique animée dans les Quatre Communes (Dakar, Gorée, Rufisque, Saint-Louis) ;</li><li>pendant la Seconde Guerre mondiale, l’AOF est d’abord fidèle au régime de Vichy (bataille de Dakar, septembre 1940), puis rejoint les Alliés fin 1942.</li></ul>$html$);
