insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'systemes-et-optimisation') and slug = 'optimiser-sous-contraintes'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Choisir les inconnues (x, y) et traduire les contraintes par des inéquations.</li><li>Représenter la région des solutions (polygone des contraintes).</li><li>Le maximum ou le minimum de la quantité à optimiser est atteint en un sommet du polygone.</li></ol></div>
