insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'couples-oxydant-reducteur-et-piles-electrochimiques') and slug = 'la-pile-daniell'), $html$<ul><li>un oxydant capte des électrons, un réducteur en cède ; ils forment un couple (Cu²⁺/Cu, Zn²⁺/Zn) ;</li><li>pile Daniell : une lame de zinc dans une solution de Zn²⁺, une lame de cuivre dans une solution de Cu²⁺, reliées par un pont salin ;</li><li>le zinc est oxydé (pôle −), les ions cuivre sont réduits (pôle +) ; f.é.m. d’environ 1,1 V.</li></ul>
