insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-cellule-techniques-d-etude-et-organisation') and slug = 'observer-et-decrire-la-cellule'), $html$<ul><li>le microscope optique grossit jusqu’à 1 000 fois environ ; le microscope électronique révèle l’ultrastructure ;</li><li>toute cellule a une membrane plasmique, un cytoplasme et (chez les eucaryotes) un noyau ;</li><li>organites : mitochondries (respiration), réticulum et ribosomes (synthèse des protéines), appareil de Golgi ;</li><li>la cellule végétale a en plus une paroi, une grande vacuole et des chloroplastes (photosynthèse) ;</li><li>mouvements cellulaires : cyclose, déplacement amiboïde, battement des cils et des flagelles.</li></ul>
