insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'bacteries-et-virus') and slug = 'procaryotes-et-virus'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Bactérie</th><th scope="col">Virus</th></tr></thead><tbody><tr><td>nature</td><td>cellule sans noyau (procaryote)</td><td>pas une cellule : matériel génétique dans une capside</td></tr><tr><td>taille</td><td>environ 1 μm</td><td>de 20 à 300 nm</td></tr><tr><td>multiplication</td><td>seule, par division</td><td>seulement dans une cellule hôte</td></tr><tr><td>traitement</td><td>antibiotiques</td><td>les antibiotiques sont inefficaces ; vaccins, antiviraux</td></tr></tbody></table>$html$);
