insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-echanges-cellulaires') and slug = 'diffusion-et-osmose'), $html$<ul><li>diffusion : les substances dissoutes passent du milieu le plus concentré vers le moins concentré ;</li><li>osmose : l’eau traverse la membrane vers le milieu le plus concentré (hypertonique) ;</li><li>dans un milieu hypotonique, la cellule végétale se gonfle (turgescence) ; dans un milieu hypertonique, elle se vide (plasmolyse) ;</li><li>le transport actif fait passer des substances contre le gradient de concentration, en consommant de l’énergie (ATP).</li></ul>
