insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'chromosomes-et-mitose') and slug = 'la-division-cellulaire'), $html$<ul><li>un chromosome est formé d’ADN associé à des protéines ; avant la division, il est dupliqué (deux chromatides) ;</li><li>le caryotype humain compte 46 chromosomes (2n = 46) ;</li><li>la mitose : prophase, métaphase (chromosomes alignés sur la plaque équatoriale), anaphase (séparation des chromatides), télophase ;</li><li>elle donne deux cellules filles identiques à la cellule mère.</li></ul>
