insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-synthese-des-proteines') and slug = 'de-l-adn-a-la-proteine'), $html$<ul><li>un <strong>gène</strong> est une portion d’ADN qui porte l’information pour fabriquer une protéine ;</li><li>transcription (dans le noyau) : l’ADN est copié en ARN messager ;</li><li>traduction (dans le cytoplasme, sur les ribosomes) : chaque codon de trois nucléotides correspond à un acide aminé ;</li><li>le code génétique est universel : il est le même chez presque tous les êtres vivants.</li></ul>
