insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-aliments-et-la-digestion') and slug = 'des-aliments-aux-nutriments'), $html$<table><thead><tr><th scope="col">Aliment simple</th><th scope="col">Enzyme</th><th scope="col">Nutriment</th></tr></thead><tbody><tr><td>amidon</td><td>amylases (salive, pancréas)</td><td>glucose</td></tr><tr><td>protéines</td><td>pepsine (estomac), trypsine (pancréas)</td><td>acides aminés</td></tr><tr><td>lipides</td><td>lipase (pancréas), aidée de la bile</td><td>acides gras et glycérol</td></tr></tbody></table>
