insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-absorption-intestinale-et-le-devenir-des-nutriments') and slug = 'absorption-et-distribution'), $html$<ul><li>les nutriments traversent la paroi de l’intestin grêle au niveau des villosités ;</li><li>le glucose et les acides aminés passent dans le sang et gagnent le foie ; les lipides passent surtout dans la lymphe ;</li><li>les cellules utilisent les nutriments pour produire de l’énergie et fabriquer leur propre matière.</li></ul>$html$);
