insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'introduction-a-la-geologie-et-structure-du-globe') and slug = 'la-structure-interne-du-globe'), $html$<ul><li>la géologie étudie la Terre, ses roches, son histoire et ses ressources ;</li><li>la vitesse des ondes sismiques change à certaines profondeurs : ces discontinuités séparent la croûte, le manteau et le noyau ;</li><li>Moho : limite croûte-manteau ; discontinuité de Gutenberg (2 900 km) : limite manteau-noyau ;</li><li>la lithosphère rigide (croûte et sommet du manteau) repose sur l’asthénosphère, plus ductile.</li></ul>$html$);
