insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-phrase-nominale-et-la-phrase-verbale') and slug = 'deux-types-de-phrases'), $html$<table><thead><tr><th scope="col">Phrase</th><th scope="col">Éléments</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>nominale (al-jumla al-ismiyya)</td><td>sujet (al-mubtada’) + prédicat (al-khabar), tous deux au nominatif</td><td>الكتابُ جديدٌ (al-kitābu jadīdun) : le livre est neuf</td></tr><tr><td>verbale (al-jumla al-fi‘liyya)</td><td>verbe (al-fi‘l) + sujet (al-fā‘il) + complément d’objet (al-maf‘ūl bihi)</td><td>كتبَ التلميذُ الدرسَ (kataba at-tilmīdhu ad-darsa) : l’élève a écrit la leçon</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 2, 'les-cas-et-la-declinaison', 'Les cas et la déclinaison', 'Nominatif, accusatif et génitif ; les prépositions.', 2, 'published', 'Langue', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-cas-et-la-declinaison'), 1, 'l-i-rab', 'L’i‘rāb', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-cas-et-la-declinaison') and slug = 'l-i-rab'), $html$<ul><li>le nom se décline : <strong>nominatif</strong> (raf‘, voyelle u : ـُ), <strong>accusatif</strong> (naṣb, voyelle a : ـَ), <strong>génitif</strong> (jarr, voyelle i : ـِ) ;</li><li>le sujet et le prédicat sont au nominatif ; le complément d’objet est à l’accusatif ;</li><li>après une préposition (fī « dans », min « de », ilā « vers », ‘alā « sur »), le nom est au génitif.</li></ul>
