insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-conjugaison-l-accompli-et-l-inacheve'), 1, 'conjuguer-un-verbe-trilitere', 'Conjuguer un verbe trilitère', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-conjugaison-l-accompli-et-l-inacheve') and slug = 'conjuguer-un-verbe-trilitere'), $html$<ul><li>la plupart des mots arabes viennent d’une <strong>racine</strong> de trois consonnes : k-t-b exprime l’idée d’écrire ;</li><li>l’<strong>accompli</strong> (al-māḍī) exprime une action terminée : كتبَ (kataba) « il a écrit » ;</li><li>l’<strong>inachevé</strong> (al-muḍāri‘) exprime une action en cours ou future : يكتبُ (yaktubu) « il écrit » ;</li><li>l’<strong>impératif</strong> (al-amr) : اكتبْ (uktub) « écris ! ».</li></ul>
