insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-schemes-et-la-derivation') and slug = 'une-racine-une-famille-de-mots'), $html$<table><thead><tr><th scope="col">Schème</th><th scope="col">Sens</th><th scope="col">Racine k-t-b</th></tr></thead><tbody><tr><td>fā‘il</td><td>celui qui fait</td><td>كاتب (kātib) : écrivain</td></tr><tr><td>maf‘ūl</td><td>ce qui subit l’action</td><td>مكتوب (maktūb) : écrit, lettre</td></tr><tr><td>maf‘al</td><td>lieu de l’action</td><td>مكتب (maktab) : bureau</td></tr><tr><td>maf‘ala</td><td>lieu (souvent)</td><td>مكتبة (maktaba) : bibliothèque</td></tr></tbody></table>
