insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie-arabe-preislamique') and slug = 'les-poetes-de-la-jahiliyya'), $html$<ul><li>avant l’islam, la poésie est l’art majeur des Arabes : le poète défend l’honneur de sa tribu ;</li><li>les <strong>Mu‘allaqāt</strong> (« poèmes suspendus ») rassemblent les plus célèbres poèmes de cette époque ; Imru’ al-Qays en est le plus connu ;</li><li>la <strong>qaṣīda</strong> classique s’ouvre sur l’évocation du campement abandonné (nasīb), décrit le voyage (raḥīl), puis traite son sujet principal (éloge, fierté, satire).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 6, 'la-litterature-aux-epoques-islamique-et-omeyyade', 'La littérature aux époques islamique et omeyyade', 'Le Coran, modèle de la langue ; la poésie au service de l’islam ; poésie omeyyade.', 6, 'published', 'Littérature', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-litterature-aux-epoques-islamique-et-omeyyade'), 1, 'de-l-islam-aux-omeyyades', 'De l’islam aux Omeyyades', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-litterature-aux-epoques-islamique-et-omeyyade') and slug = 'de-l-islam-aux-omeyyades'), $html$<ul><li>le Coran devient la référence de la langue arabe et de son éloquence ;</li><li>Ḥassān ibn Thābit est appelé « le poète du Prophète » ;</li><li>sous les Omeyyades (Damas, 661-750), la poésie de joute oppose Jarīr et al-Farazdaq ; le ghazal ‘udhrī chante un amour chaste et impossible (Jamīl Buthayna).</li></ul>$html$);
