insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-fondements-de-la-civilisation-arabo-islamique') and slug = 'naissance-et-expansion'), $html$<ul><li>le Coran et la Sunna (paroles et actes du Prophète) sont les sources de l’islam ;</li><li>l’hégire (622) ouvre le calendrier musulman ;</li><li>les quatre premiers califes (Abū Bakr, ‘Umar, ‘Uthmān, ‘Alī) étendent l’islam hors d’Arabie ;</li><li>sous les Omeyyades puis les Abbassides, l’arabe devient langue de l’administration, de la science et de la culture.</li></ul>$html$);
