insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-arabe-au-senegal'), 1, 'une-tradition-savante', 'Une tradition savante', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-arabe-au-senegal') and slug = 'une-tradition-savante'), $html$<ul><li>l’arabe est enseigné depuis des siècles dans les daaras et les écoles coraniques ;</li><li>de grands érudits sénégalais ont écrit en arabe : Cheikh Moussa Kamara (histoire du Fouta), El Hadji Malick Sy (poésie religieuse), Cheikh Ahmadou Bamba (khassaïdes) ;</li><li>l’<strong>ajami</strong> consiste à écrire les langues nationales en caractères arabes : le wolofal pour le wolof (poèmes de Serigne Moussa Ka).</li></ul>
