insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-xixe-siecle-romantisme-realisme-symbolisme') and slug = 'trois-mouvements'), $html$<table><thead><tr><th scope="col">Mouvement</th><th scope="col">Caractères</th><th scope="col">Auteurs</th></tr></thead><tbody><tr><td>romantisme</td><td>expression du moi, sentiments, nature, engagement</td><td>Hugo, Lamartine</td></tr><tr><td>réalisme et naturalisme</td><td>peindre la société telle qu’elle est</td><td>Balzac, Flaubert, Zola</td></tr><tr><td>symbolisme</td><td>suggérer par les images et la musique des mots</td><td>Baudelaire, Verlaine, Rimbaud</td></tr></tbody></table>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 7, 'la-litterature-negro-africaine', 'La littérature négro-africaine', 'La Négritude, le roman de la période coloniale et des indépendances.', 7, 'published', 'Histoire littéraire', '[{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-litterature-negro-africaine'), 1, 'de-la-negritude-au-roman-africain', 'De la Négritude au roman africain', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-litterature-negro-africaine') and slug = 'de-la-negritude-au-roman-africain'), $html$<ul><li>la Négritude (Senghor, Césaire, Damas) affirme les valeurs des civilisations noires ;</li><li>le roman colonial dénonce l’injustice : <em>Une vie de boy</em> (Ferdinand Oyono, 1956) ;</li><li><em>L’Aventure ambiguë</em> (Cheikh Hamidou Kane, 1961) pose la question de la rencontre des cultures ;</li><li><em>Une si longue lettre</em> (Mariama Bâ, 1979) donne la parole aux femmes.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 1, 'la-revolution-industrielle-et-ses-consequences', 'La révolution industrielle et ses conséquences', 'Genèse et manifestations ; conséquences économiques, sociales et politiques ; syndicalisme et socialisme.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-revolution-industrielle-et-ses-consequences'), 1, 'genese-et-consequences', 'Genèse et conséquences', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-revolution-industrielle-et-ses-consequences') and slug = 'genese-et-consequences'), $html$<ul><li>née en Grande-Bretagne à la fin du XVIII<sup>e</sup> siècle (charbon, machine à vapeur, textile), elle gagne l’Europe et les États-Unis ;</li><li>deuxième révolution industrielle à la fin du XIX<sup>e</sup> siècle : électricité, pétrole, chimie, automobile ;</li><li>le capitalisme se développe (banques, sociétés anonymes, concentrations) ;</li><li>la société se transforme : bourgeoisie industrielle, classe ouvrière, exode rural, urbanisation.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-revolution-industrielle-et-ses-consequences'), 2, 'syndicalisme-et-socialisme', 'Syndicalisme et socialisme', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-revolution-industrielle-et-ses-consequences') and slug = 'syndicalisme-et-socialisme'), $html$<ul><li>les ouvriers s’organisent en syndicats pour obtenir de meilleurs salaires et conditions de travail ;</li><li>le socialisme critique le capitalisme ; Karl Marx et Friedrich Engels publient le <em>Manifeste du parti communiste</em> (1848) ;</li><li>l’Église catholique propose sa doctrine sociale (encyclique <em>Rerum novarum</em>, 1891).</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 2, 'l-imperialisme-europeen-en-afrique', 'L’impérialisme européen en Afrique', 'Causes, doctrines et méthodes ; positions en 1870 et en 1914 ; la conférence de Berlin.', 2, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-imperialisme-europeen-en-afrique'), 1, 'le-partage-de-l-afrique', 'Le partage de l’Afrique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-imperialisme-europeen-en-afrique') and slug = 'le-partage-de-l-afrique'), $html$<ul><li>causes : besoins de matières premières et de débouchés, rivalités entre puissances, prestige, prétendue « mission civilisatrice » ;</li><li>méthodes : explorations, missions, traités de protectorat, conquête militaire ;</li><li>la conférence de Berlin (1884-1885) fixe les règles de l’occupation des côtes africaines ;</li><li>en 1914, seuls l’Éthiopie et le Liberia restent indépendants.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 3, 'les-resistances-africaines-a-l-imperialisme', 'Les résistances africaines à l’impérialisme', 'Résistances armées, culturelles et passives.', 3, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-resistances-africaines-a-l-imperialisme'), 1, 'resister-a-la-conquete', 'Résister à la conquête', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-resistances-africaines-a-l-imperialisme') and slug = 'resister-a-la-conquete'), $html$<table><thead><tr><th scope="col">Forme</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>armée</td><td>Lat Dior au Kayor (mort à Dékhélé en 1886), Samory Touré, Alboury Ndiaye, Mamadou Lamine Dramé, Fodé Kaba</td></tr><tr><td>culturelle et religieuse</td><td>Cheikh Ahmadou Bamba (exil au Gabon, 1895-1902), Aline Sitoé Diatta en Casamance</td></tr><tr><td>passive</td><td>refus de l’impôt et des cultures imposées, fuite, migrations</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 4, 'l-imperialisme-en-asie-en-amerique-et-dans-les-caraibes', 'L’impérialisme en Asie, en Amérique et dans les Caraïbes', 'Les impérialismes européens, américain, japonais et russe ; le cas de la Chine.', 4, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-imperialisme-en-asie-en-amerique-et-dans-les-caraibes'), 1, 'un-monde-domine', 'Un monde dominé', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-imperialisme-en-asie-en-amerique-et-dans-les-caraibes') and slug = 'un-monde-domine'), $html$<ul><li>Asie : l’Inde britannique, l’Indochine française ; la Chine est ouverte de force (guerres de l’opium) et partagée en zones d’influence ;</li><li>le Japon se modernise (ère Meiji, 1868) et devient à son tour impérialiste (Corée, Mandchourie) ; la Russie s’étend en Sibérie et en Asie centrale ;</li><li>Amérique : les États-Unis dominent les Caraïbes et l’Amérique centrale (doctrine Monroe, canal de Panama).</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 5, 'la-premiere-guerre-mondiale-et-l-afrique', 'La Première Guerre mondiale et l’Afrique', 'Causes, déroulement et conséquences de la guerre de 1914-1918 ; l’Afrique dans le conflit.', 5, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-premiere-guerre-mondiale-et-l-afrique'), 1, 'la-grande-guerre', 'La Grande Guerre', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-premiere-guerre-mondiale-et-l-afrique') and slug = 'la-grande-guerre'), $html$<ul><li>causes : rivalités impériales et économiques, nationalismes, système d’alliances ; l’attentat de Sarajevo (1914) déclenche le conflit ;</li><li>guerre de mouvement puis de tranchées (Verdun, 1916) ; l’entrée des États-Unis (1917) ;</li><li>l’armistice est signé le 11 novembre 1918 ; le traité de Versailles (1919) sanctionne l’Allemagne ;</li><li>l’Afrique fournit soldats (tirailleurs), travailleurs et ressources ; les colonies allemandes sont partagées.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 6, 'la-revolution-russe-et-la-chine-de-1911-a-1945', 'La révolution russe et la Chine de 1911 à 1945', 'Les révolutions de 1917 et l’URSS ; la Chine de la république à la guerre contre le Japon.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-revolution-russe-et-la-chine-de-1911-a-1945'), 1, 'revolutions-en-russie-et-en-chine', 'Révolutions en Russie et en Chine', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-revolution-russe-et-la-chine-de-1911-a-1945') and slug = 'revolutions-en-russie-et-en-chine'), $html$<ul><li>en 1917, le tsar abdique ; en octobre, les bolcheviks de Lénine prennent le pouvoir ; l’URSS naît en 1922 ; Staline impose ensuite une dictature ;</li><li>en Chine, la république est proclamée en 1911-1912 (Sun Yat-sen) ; le Guomindang de Tchang Kaï-chek affronte les communistes de Mao Zedong (Longue Marche, 1934-1935) ;</li><li>à partir de 1937, la Chine combat l’invasion japonaise.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')), 7, 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective', 'La crise des années 1930, les fascismes et la faillite de la sécurité collective', 'La crise de 1929, la montée des régimes totalitaires, l’échec de la SDN.', 7, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective'), 1, 'vers-une-nouvelle-guerre', 'Vers une nouvelle guerre', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective') and slug = 'vers-une-nouvelle-guerre'), $html$<ul><li>le krach de Wall Street (octobre 1929) provoque une crise mondiale : faillites, chômage, effondrement des prix agricoles (y compris de l’arachide) ;</li><li>fascisme en Italie (Mussolini, 1922), nazisme en Allemagne (Hitler, 1933) ;</li><li>la Société des Nations ne peut empêcher les agressions : invasion de l’Éthiopie par l’Italie (1935), remilitarisation de la Rhénanie, annexions allemandes.</li></ul>$html$);
