insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-seconde-guerre-mondiale-et-l-afrique') and slug = '1939-1945'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Événement</th></tr></thead><tbody><tr><td>septembre 1939</td><td>invasion de la Pologne, début de la guerre</td></tr><tr><td>juin 1940</td><td>défaite de la France ; appel du général de Gaulle</td></tr><tr><td>1941</td><td>l’URSS et les États-Unis entrent en guerre</td></tr><tr><td>1942-1943</td><td>tournants : El-Alamein, Stalingrad</td></tr><tr><td>mai et août 1945</td><td>capitulation de l’Allemagne, puis du Japon après les bombes atomiques</td></tr></tbody></table>
