insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-ville-et-les-activites-urbaines') and slug = 'l-urbanisation-du-monde'), $html$<ul><li>plus de la moitié de l’humanité vit en ville ; l’urbanisation est très rapide dans les pays du Sud ;</li><li>fonctions : politique, économique, culturelle, religieuse (Touba), portuaire (Dakar) ;</li><li>l’industrie se transforme (délocalisations, nouvelles technologies) ; les services dominent les économies développées ;</li><li>problèmes des villes du Sud : quartiers spontanés, embouteillages, chômage, inondations, déchets.</li></ul>$html$);
