insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'transports-echanges-et-integration-economique') and slug = 'un-monde-d-echanges'), $html$<ul><li>transports maritimes (90 % des marchandises), aériens, routiers, ferroviaires ; télécommunications et internet ;</li><li>l’Organisation mondiale du commerce (OMC) encadre le commerce international ;</li><li>échange inégal : les pays du Sud exportent des matières premières aux prix instables et importent des produits manufacturés plus chers ;</li><li>intégration : UE, ACEUM (ex-ALENA), CEDEAO, UEMOA.</li></ul>$html$);
