insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'derivation-et-etude-de-fonctions') and slug = 'deriver-pour-etudier'), $html$<ul><li>(x<sup>n</sup>)’ = nx<sup>n−1</sup> ; (ku)’ = ku’ ; (u + v)’ = u’ + v’ ;</li><li>le signe de f’ donne le sens de variation de f ;</li><li>la tangente au point d’abscisse a a pour équation y = f’(a)(x − a) + f(a).</li></ul>
