insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'suites-arithmetiques-et-geometriques') and slug = 'deux-types-de-suites'), $html$<ul><li>arithmétique : on ajoute toujours la même raison r : u<sub>n</sub> = u<sub>0</sub> + nr ;</li><li>géométrique : on multiplie toujours par la même raison q : u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup> ;</li><li>application : un capital placé à intérêts composés de 5 % par an est multiplié par 1,05 chaque année.</li></ul>
