insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'generalites-sur-les-fonctions-et-applications'), 1, 'applications-et-fonctions', 'Applications et fonctions', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'generalites-sur-les-fonctions-et-applications') and slug = 'applications-et-fonctions'), $html$<ul><li>une application f de E dans F est <strong>injective</strong> si deux éléments distincts ont des images distinctes, <strong>surjective</strong> si tout élément de F a au moins un antécédent, <strong>bijective</strong> si elle est les deux ;</li><li>une bijection admet une application réciproque f⁻¹ ;</li><li>f est périodique de période T si f(x + T) = f(x) : cos et sin sont 2π-périodiques ;</li><li>la courbe de x ↦ f(x − a) + b se déduit de celle de f par la translation de vecteur (a ; b).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')), 2, 'limites-et-continuite', 'Limites et continuité', 'Limites finies et infinies, opérations, formes indéterminées, asymptotes, continuité.', 2, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S1 et S3 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS1etS3.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'limites-et-continuite'), 1, 'calculer-des-limites', 'Calculer des limites', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'limites-et-continuite') and slug = 'calculer-des-limites'), $html$<ul><li>à l’infini, un polynôme a la limite de son terme de plus haut degré ; une fraction rationnelle, celle du quotient des termes de plus haut degré ;</li><li>formes indéterminées : ∞ − ∞, 0 × ∞, ∞/∞, 0/0 : on factorise ou on simplifie ;</li><li>si lim f(x) = ±∞ quand x tend vers a, la droite x = a est asymptote verticale ; si lim f(x) = b à l’infini, y = b est asymptote horizontale.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'limites-et-continuite'), 2, 'la-continuite', 'La continuité', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'limites-et-continuite') and slug = 'la-continuite'), $html$<ul><li>f est continue en a si lim f(x) = f(a) quand x tend vers a ;</li><li>les fonctions polynômes et rationnelles sont continues sur leur ensemble de définition ;</li><li>l’image d’un intervalle par une fonction continue est un intervalle (théorème des valeurs intermédiaires).</li></ul>
