insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'polynomes-equations-et-systemes') and slug = 'polynomes-et-equations'), $html$<ul><li>si a est racine de P, la méthode de Horner donne le quotient Q tel que P(x) = (x − a)Q(x) ;</li><li>si ax<sup>2</sup> + bx + c = 0 a deux racines x₁ et x₂ : x₁ + x₂ = −b/a et x₁x₂ = c/a ;</li><li>un système de trois équations à trois inconnues se résout par la méthode du pivot de Gauss (on se ramène à un système triangulaire).</li></ul>
