insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-dessin-technique-projections-et-vues'), 1, 'representer-une-piece', 'Représenter une pièce', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-dessin-technique-projections-et-vues') and slug = 'representer-une-piece'), $html$<ul><li>on représente une pièce par plusieurs <strong>vues</strong> obtenues par projection orthogonale ;</li><li>disposition européenne : la vue de dessus se place sous la vue de face, la vue de gauche à droite de la vue de face ;</li><li>traits : continu fort (arêtes vues), interrompu court (arêtes cachées), mixte fin (axes et plans de symétrie) ;</li><li>l’échelle compare le dessin à la pièce réelle : 1:1 (grandeur nature), 1:2 (réduction), 2:1 (agrandissement).</li></ul>$html$);
