insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'coupes-et-sections'), 1, 'voir-l-interieur-d-une-piece', 'Voir l’intérieur d’une pièce', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'coupes-et-sections') and slug = 'voir-l-interieur-d-une-piece'), $html$<ul><li>une <strong>coupe</strong> montre l’intérieur d’une pièce, comme si on l’avait sciée selon un plan ;</li><li>les parties coupées sont hachurées (traits fins inclinés à 45°) ;</li><li>la demi-coupe montre à la fois l’extérieur et l’intérieur d’une pièce symétrique ;</li><li>une <strong>section</strong> ne représente que la partie située dans le plan de coupe.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')), 3, 'cotation-et-tolerances', 'Cotation et tolérances', 'Cotes, tolérances dimensionnelles, ajustements, état de surface.', 3, 'published', 'Dessin technique', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'cotation-et-tolerances'), 1, 'coter-une-piece', 'Coter une pièce', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'cotation-et-tolerances') and slug = 'coter-une-piece'), $html$<ul><li>une cote indique une dimension en millimètres ; chaque dimension n’est cotée qu’une fois ;</li><li>une pièce ne peut pas être fabriquée exactement à la cote : on fixe une <strong>tolérance</strong> (ex. 20 ± 0,1) ;</li><li>un ajustement associe un alésage et un arbre (ex. ⌀ 20 H7/g6) : avec jeu, incertain ou serré ;</li><li>l’état de surface (rugosité Ra) précise la finition attendue.</li></ul>
