insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'les-assemblages'), 1, 'assembler-des-pieces', 'Assembler des pièces', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'les-assemblages') and slug = 'assembler-des-pieces'), $html$<ul><li>démontables : vis, boulons (vis + écrou), goujons, goupilles, clavettes, anneaux élastiques ;</li><li>permanents : soudure, rivetage, collage, frettage ;</li><li>désignation d’un filetage : M10 × 1,5 (diamètre nominal 10 mm, pas 1,5 mm) ;</li><li>freinage des écrous : rondelle, contre-écrou, écrou autofreiné.</li></ul>$html$);
