insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'la-statique-du-solide'), 1, 'l-equilibre-d-un-solide', 'L’équilibre d’un solide', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'la-statique-du-solide') and slug = 'l-equilibre-d-un-solide'), $html$<ul><li>une action mécanique se modélise par une force (point d’application, direction, sens, intensité en N) ;</li><li>moment d’une force par rapport à un point : M = F × d (N·m) ;</li><li>principe fondamental de la statique : à l’équilibre, la somme des forces est nulle et la somme des moments est nulle ;</li><li>frottement (loi de Coulomb) : à la limite du glissement, T = f × N.</li></ul>
