insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'generalites-sur-les-fonctions-et-applications') and slug = 'applications-et-fonctions'), $html$<ul><li>une application f de E dans F est <strong>injective</strong> si deux éléments distincts ont des images distinctes, <strong>surjective</strong> si tout élément de F a au moins un antécédent, <strong>bijective</strong> si elle est les deux ;</li><li>une bijection admet une application réciproque f⁻¹ ;</li><li>f est périodique de période T si f(x + T) = f(x) : cos et sin sont 2π-périodiques ;</li><li>la courbe de x ↦ f(x − a) + b se déduit de celle de f par la translation de vecteur (a ; b).</li></ul>
