insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'limites-et-continuite') and slug = 'calculer-des-limites'), $html$<ul><li>à l’infini, un polynôme a la limite de son terme de plus haut degré ; une fraction rationnelle, celle du quotient des termes de plus haut degré ;</li><li>formes indéterminées : ∞ − ∞, 0 × ∞, ∞/∞, 0/0 : on factorise ou on simplifie ;</li><li>si lim f(x) = ±∞ quand x tend vers a, la droite x = a est asymptote verticale ; si lim f(x) = b à l’infini, y = b est asymptote horizontale.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'limites-et-continuite'), 2, 'la-continuite', 'La continuité', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'limites-et-continuite') and slug = 'la-continuite'), $html$<ul><li>f est continue en a si lim f(x) = f(a) quand x tend vers a ;</li><li>les fonctions polynômes et rationnelles sont continues sur leur ensemble de définition ;</li><li>l’image d’un intervalle par une fonction continue est un intervalle (théorème des valeurs intermédiaires).</li></ul>
