insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'derivation-et-applications') and slug = 'nombre-derive-et-tangente'), $html$<p class="formula">f’(a) = lim <span class="frac"><span>f(a + h) − f(a)</span><span>h</span></span> quand h → 0 ; tangente : y = f’(a)(x − a) + f(a)</p>
