insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Arithmétique (raison r)</th><th scope="col">Géométrique (raison q)</th></tr></thead><tbody><tr><td>relation</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>somme de termes consécutifs</td><td>nombre de termes × (premier + dernier) ÷ 2</td><td>premier × <span class="frac"><span>1 − q<sup>nombre de termes</sup></span><span>1 − q</span></span> (q ≠ 1)</td></tr></tbody></table>
