insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'denombrement') and slug = 'compter-sans-se-tromper'), $html$<table><thead><tr><th scope="col">Situation</th><th scope="col">Nombre</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>p-listes (ordre, répétitions possibles)</td><td>n<sup>p</sup></td><td>codes de 4 chiffres : 10⁴ = 10 000</td></tr><tr><td>arrangements (ordre, sans répétition)</td><td>A<sup>p</sup><sub>n</sub> = <span class="frac"><span>n!</span><span>(n − p)!</span></span></td><td>podium de 3 parmi 8 : 8 × 7 × 6 = 336</td></tr><tr><td>combinaisons (sans ordre)</td><td>C<sup>p</sup><sub>n</sub> = <span class="frac"><span>n!</span><span>p!(n − p)!</span></span></td><td>comité de 2 parmi 5 : 10</td></tr><tr><td>permutations</td><td>n!</td><td>ranger 4 livres : 24</td></tr></tbody></table>
