insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'formules-trigonometriques'), $html$<ul><li>cos(a + b) = cos a cos b − sin a sin b ; sin(a + b) = sin a cos b + cos a sin b ;</li><li>cos 2a = cos<sup>2</sup>a − sin<sup>2</sup>a = 2cos<sup>2</sup>a − 1 = 1 − 2sin<sup>2</sup>a ; sin 2a = 2 sin a cos a ;</li><li>un angle inscrit mesure la moitié de l’angle au centre qui intercepte le même arc.</li></ul>$html$);
