insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'equations-trigonometriques'), $html$<ul><li>cos x = cos a ⟺ x = a + 2kπ ou x = −a + 2kπ (k entier) ;</li><li>sin x = sin a ⟺ x = a + 2kπ ou x = π − a + 2kπ ;</li><li>on représente les solutions sur le cercle trigonométrique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')), 11, 'transformations-du-plan', 'Transformations du plan', 'Isométries, translations, rotations, homothéties et leurs composées.', 11, 'published', 'Géométrie', '[{"title":"Programme de mathématiques, première S2 et S4 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS2etS4_0.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'transformations-du-plan'), 1, 'isometries-et-composees', 'Isométries et composées', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'transformations-du-plan') and slug = 'isometries-et-composees'), $html$<ul><li>une isométrie conserve les distances : translations, rotations, symétries ;</li><li>la composée de deux rotations de même centre et d’angles θ et θ’ est la rotation d’angle θ + θ’ ;</li><li>la composée de deux symétries orthogonales d’axes sécants en O est une rotation de centre O d’angle double de l’angle des axes ;</li><li>une homothétie de rapport k conserve les angles et multiplie les distances par |k|.</li></ul>$html$);
