insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'geometrie-dans-l-espace') and slug = 'vecteurs-et-produit-scalaire-dans-l-espace'), $html$<ul><li>trois vecteurs sont coplanaires si l’un est combinaison linéaire des deux autres ;</li><li>dans un repère orthonormé : u⃗ · v⃗ = xx’ + yy’ + zz’ ;</li><li>un plan de vecteur normal n⃗(a ; b ; c) a une équation ax + by + cz + d = 0 ;</li><li>la sphère de centre Ω(a ; b ; c) et de rayon r : (x − a)<sup>2</sup> + (y − b)<sup>2</sup> + (z − c)<sup>2</sup> = r<sup>2</sup>.</li></ul>$html$);
