insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'generalites-sur-la-chimie-organique') and slug = 'les-composes-du-carbone'), $html$<ul><li>la chimie organique est la chimie des composés du carbone (sauf CO, CO₂ et carbonates) ;</li><li>l’atome de carbone est <strong>tétravalent</strong> : il forme quatre liaisons ;</li><li>formule brute (C₂H₆O), développée (toutes les liaisons), semi-développée (CH₃–CH₂–OH) ;</li><li>des <strong>isomères</strong> ont la même formule brute mais des formules développées différentes (éthanol et méthoxyméthane).</li></ul>
