insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')), 8, 'la-ration-alimentaire', 'La ration alimentaire', 'Besoins énergétiques, ration équilibrée et ses variations, malnutrition.', 8, 'published', 'Nutrition', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
