insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-roches-sedimentaires-et-residuelles'), 1, 'du-sediment-a-la-roche', 'Du sédiment à la roche', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-roches-sedimentaires-et-residuelles') and slug = 'du-sediment-a-la-roche'), $html$<ul><li>les roches sédimentaires se forment par altération, transport, dépôt puis diagenèse (tassement, cimentation) ;</li><li>détritiques (grès), chimiques ou biochimiques (calcaire, phosphate) ;</li><li>les roches <strong>résiduelles</strong> restent sur place après altération : latérite et cuirasses ferrugineuses des plateaux, bauxite.</li></ul>$html$);
