insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-roches-metamorphiques-et-la-tectonique'), 1, 'metamorphisme-et-deformations', 'Métamorphisme et déformations', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-roches-metamorphiques-et-la-tectonique') and slug = 'metamorphisme-et-deformations'), $html$<ul><li>sous l’effet de la température et de la pression, une roche se transforme sans fondre : c’est le métamorphisme (argile → schiste → micaschiste → gneiss) ;</li><li>les roches se déforment : plis (déformation souple) et failles (cassures) ;</li><li>ces déformations résultent des mouvements des plaques et accompagnent la formation des chaînes de montagnes.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')), 13, 'les-ensembles-geologiques-et-les-ressources-du-senegal', 'Les ensembles géologiques et les ressources du Sénégal', 'Bassin sédimentaire et socle, paléogéographie, ressources minières et énergétiques.', 13, 'published', 'Géologie', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-ensembles-geologiques-et-les-ressources-du-senegal'), 1, 'la-geologie-du-senegal', 'La géologie du Sénégal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-ensembles-geologiques-et-les-ressources-du-senegal') and slug = 'la-geologie-du-senegal'), $html$<ul><li>l’essentiel du pays appartient au <strong>bassin sédimentaire</strong> sénégalo-mauritanien ; le <strong>socle</strong> ancien affleure au sud-est (Kédougou) ;</li><li>la paléogéographie reconstitue les anciens rivages : la mer a recouvert une grande partie du pays au cours des temps géologiques ;</li><li>ressources : phosphates (Taïba, Matam), calcaire (cimenteries de Bargny et de Pout), zircon des sables des Niayes, or (Sabodala), fer de la Falémé, pétrole et gaz en mer (Sangomar, Grand Tortue Ahmeyim).</li></ul>
