insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'ecosystemes-naturels-et-agrosystemes'), 1, 'du-milieu-naturel-au-champ', 'Du milieu naturel au champ', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'ecosystemes-naturels-et-agrosystemes') and slug = 'du-milieu-naturel-au-champ'), $html$<ul><li>un écosystème associe un milieu (sol, climat, eau) et des êtres vivants en interaction ;</li><li>un <strong>agrosystème</strong> est un écosystème aménagé par l’homme pour produire : peu d’espèces, récoltes exportées, apports d’eau et d’engrais ;</li><li>les rotations, l’association de cultures et les haies maintiennent la biodiversité et la fertilité.</li></ul>$html$);
