insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-eau-et-l-irrigation') and slug = 'apporter-l-eau-aux-cultures'), $html$<ul><li>au Sénégal, les pluies diminuent du sud (plus de 1 000 mm par an en Casamance) au nord (moins de 400 mm) ;</li><li>la saison des pluies (hivernage) dure de trois à cinq mois ;</li><li>irrigation gravitaire (vallée du fleuve Sénégal, riz), par aspersion, ou goutte-à-goutte (maraîchage, économe en eau) ;</li><li>une mauvaise irrigation peut saliniser les sols.</li></ul>$html$);
