insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-inegalites-de-developpement-dans-le-monde'), 1, 'mesurer-le-developpement', 'Mesurer le développement', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'les-inegalites-de-developpement-dans-le-monde') and slug = 'mesurer-le-developpement'), $html$<ul><li>le PIB par habitant mesure la richesse produite ; l’IDH combine revenu, santé (espérance de vie) et éducation ;</li><li>pays développés, pays émergents (Chine, Inde, Brésil), pays moins avancés ;</li><li>les inégalités existent aussi à l’intérieur des pays (villes et campagnes).</li></ul>$html$);
