insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'essay-writing') and slug = 'writing-an-essay'), $html$<ul><li>introduction: present the topic and your opinion ;</li><li>body: one paragraph per argument, with a topic sentence and an example ;</li><li>conclusion: sum up and give a final thought ;</li><li>linking words: firstly, in addition, on the other hand, however, to conclude.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 1, 'generalites-sur-les-fonctions-et-applications', 'Généralités sur les fonctions et applications', 'Applications injectives, surjectives, bijectives ; parité, périodicité ; courbes associées.', 1, 'published', 'Analyse', '[{"title":"Programme de mathématiques, première S2 et S4 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS2etS4_0.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'generalites-sur-les-fonctions-et-applications'), 1, 'applications-et-fonctions', 'Applications et fonctions', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'generalites-sur-les-fonctions-et-applications') and slug = 'applications-et-fonctions'), $html$<ul><li>une application f de E dans F est <strong>injective</strong> si deux éléments distincts ont des images distinctes, <strong>surjective</strong> si tout élément de F a au moins un antécédent, <strong>bijective</strong> si elle est les deux ;</li><li>une bijection admet une application réciproque f⁻¹ ;</li><li>f est périodique de période T si f(x + T) = f(x) : cos et sin sont 2π-périodiques ;</li><li>la courbe de x ↦ f(x − a) + b se déduit de celle de f par la translation de vecteur (a ; b).</li></ul>
