insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-et-continuite') and slug = 'la-continuite'), $html$<ul><li>f est continue en a si lim f(x) = f(a) quand x tend vers a ;</li><li>les fonctions polynômes et rationnelles sont continues sur leur ensemble de définition ;</li><li>l’image d’un intervalle par une fonction continue est un intervalle (théorème des valeurs intermédiaires).</li></ul>
