insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'derivation-et-applications') and slug = 'derivee-et-variations'), $html$<ul><li>f’ ≥ 0 sur un intervalle : f y est croissante ; f’ ≤ 0 : décroissante ;</li><li>si f’ s’annule en changeant de signe en a, f(a) est un extremum local.</li></ul>
