insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'etude-de-fonctions') and slug = 'etudier-une-fonction'), $html$<div class="callout"><p class="callout-title">Plan d’étude</p><ol><li>Ensemble de définition, parité ou périodicité éventuelles.</li><li>Limites aux bornes et asymptotes (verticales, horizontales, obliques y = ax + b si f(x) − (ax + b) tend vers 0).</li><li>Dérivée, signe de la dérivée, tableau de variations.</li><li>Points particuliers (intersections avec les axes, tangentes), puis courbe.</li></ol></div>
