insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'barycentre-et-lignes-de-niveau'), 1, 'barycentre-de-plusieurs-points', 'Barycentre de plusieurs points', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'barycentre-et-lignes-de-niveau') and slug = 'barycentre-de-plusieurs-points'), $html$<ul><li>G barycentre de (A, a), (B, b), (C, c) avec a + b + c ≠ 0 : aGA⃗ + bGB⃗ + cGC⃗ = 0⃗ ;</li><li>associativité : on peut remplacer des points par leur barycentre partiel affecté de la somme de leurs coefficients ;</li><li>coordonnées : x<sub>G</sub> = <span class="frac"><span>ax<sub>A</sub> + bx<sub>B</sub> + cx<sub>C</sub></span><span>a + b + c</span></span>.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 10, 'angles-orientes-et-trigonometrie', 'Angles orientés et trigonométrie', 'Angles inscrits, formules d’addition et de duplication, équations trigonométriques.', 10, 'published', 'Géométrie', '[{"title":"Programme de mathématiques, première S2 et S4 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS2etS4_0.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'angles-orientes-et-trigonometrie'), 1, 'formules-trigonometriques', 'Formules trigonométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'formules-trigonometriques'), $html$<ul><li>cos(a + b) = cos a cos b − sin a sin b ; sin(a + b) = sin a cos b + cos a sin b ;</li><li>cos 2a = cos<sup>2</sup>a − sin<sup>2</sup>a = 2cos<sup>2</sup>a − 1 = 1 − 2sin<sup>2</sup>a ; sin 2a = 2 sin a cos a ;</li><li>un angle inscrit mesure la moitié de l’angle au centre qui intercepte le même arc.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'angles-orientes-et-trigonometrie'), 2, 'equations-trigonometriques', 'Équations trigonométriques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'equations-trigonometriques'), $html$<ul><li>cos x = cos a ⟺ x = a + 2kπ ou x = −a + 2kπ (k entier) ;</li><li>sin x = sin a ⟺ x = a + 2kπ ou x = π − a + 2kπ ;</li><li>on représente les solutions sur le cercle trigonométrique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 11, 'transformations-du-plan', 'Transformations du plan', 'Isométries, translations, rotations, homothéties et leurs composées.', 11, 'published', 'Géométrie', '[{"title":"Programme de mathématiques, première S2 et S4 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS2etS4_0.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'transformations-du-plan'), 1, 'isometries-et-composees', 'Isométries et composées', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'transformations-du-plan') and slug = 'isometries-et-composees'), $html$<ul><li>une isométrie conserve les distances : translations, rotations, symétries ;</li><li>la composée de deux rotations de même centre et d’angles θ et θ’ est la rotation d’angle θ + θ’ ;</li><li>la composée de deux symétries orthogonales d’axes sécants en O est une rotation de centre O d’angle double de l’angle des axes ;</li><li>une homothétie de rapport k conserve les angles et multiplie les distances par |k|.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 12, 'geometrie-dans-l-espace', 'Géométrie dans l’espace', 'Vecteurs de l’espace, coplanarité, produit scalaire, plans et sphères.', 12, 'published', 'Géométrie', '[{"title":"Programme de mathématiques, première S2 et S4 (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/math1erS2etS4_0.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'geometrie-dans-l-espace'), 1, 'vecteurs-et-produit-scalaire-dans-l-espace', 'Vecteurs et produit scalaire dans l’espace', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'geometrie-dans-l-espace') and slug = 'vecteurs-et-produit-scalaire-dans-l-espace'), $html$<ul><li>trois vecteurs sont coplanaires si l’un est combinaison linéaire des deux autres ;</li><li>dans un repère orthonormé : u⃗ · v⃗ = xx’ + yy’ + zz’ ;</li><li>un plan de vecteur normal n⃗(a ; b ; c) a une équation ax + by + cz + d = 0 ;</li><li>la sphère de centre Ω(a ; b ; c) et de rayon r : (x − a)<sup>2</sup> + (y − b)<sup>2</sup> + (z − c)<sup>2</sup> = r<sup>2</sup>.</li></ul>$html$);
