insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-alcenes-et-les-alcynes') and slug = 'hydrocarbures-insatures'), $html$<table><thead><tr><th scope="col">Famille</th><th scope="col">Formule générale</th><th scope="col">Exemple</th></tr></thead><tbody><tr><td>alcènes (double liaison C=C)</td><td>C<sub>n</sub>H<sub>2n</sub></td><td>éthylène (éthène) CH₂=CH₂</td></tr><tr><td>alcynes (triple liaison C≡C)</td><td>C<sub>n</sub>H<sub>2n−2</sub></td><td>acétylène (éthyne) HC≡CH</td></tr></tbody></table>
