insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-benzene-et-les-composes-aromatiques') and slug = 'le-benzene'), $html$<ul><li>formule brute C₆H₆ : cycle de six carbones, électrons délocalisés (formule de Kekulé) ;</li><li>il donne surtout des réactions de <strong>substitution</strong> (nitration, halogénation) ; l’addition est difficile ;</li><li>il est toxique : on le manipule avec précaution.</li></ul>$html$);
