insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-aliments-et-la-digestion') and slug = 'des-aliments-aux-nutriments'), $html$<table><thead><tr><th scope="col">Aliment simple</th><th scope="col">Enzyme</th><th scope="col">Nutriment</th></tr></thead><tbody><tr><td>amidon</td><td>amylases (salive, pancréas)</td><td>glucose</td></tr><tr><td>protéines</td><td>pepsine (estomac), trypsine (pancréas)</td><td>acides aminés</td></tr><tr><td>lipides</td><td>lipase (pancréas), aidée de la bile</td><td>acides gras et glycérol</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 8, 'la-ration-alimentaire', 'La ration alimentaire', 'Besoins énergétiques, ration équilibrée et ses variations, malnutrition.', 8, 'published', 'Nutrition', '[{"title":"Relevé DIANGAL du programme du lycée (titres de chapitres de Sunudaara), à confirmer","kind":"external"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-ration-alimentaire'), 1, 'une-ration-adaptee', 'Une ration adaptée', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-ration-alimentaire') and slug = 'une-ration-adaptee'), $html$<ul><li>valeur énergétique : 1 g de glucides ou de protides fournit environ 17 kJ, 1 g de lipides environ 38 kJ ;</li><li>la ration varie avec l’âge, le sexe, l’activité, la grossesse ou l’allaitement ;</li><li>équilibre conseillé : environ 55 % de l’énergie par les glucides, 30 % par les lipides, 15 % par les protides ;</li><li>malnutrition par carence (kwashiorkor, marasme) ou par excès (obésité, diabète).</li></ul>$html$);
