insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-ensembles-geologiques-et-les-ressources-du-senegal'), 1, 'la-geologie-du-senegal', 'La géologie du Sénégal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-ensembles-geologiques-et-les-ressources-du-senegal') and slug = 'la-geologie-du-senegal'), $html$<ul><li>l’essentiel du pays appartient au <strong>bassin sédimentaire</strong> sénégalo-mauritanien ; le <strong>socle</strong> ancien affleure au sud-est (Kédougou) ;</li><li>la paléogéographie reconstitue les anciens rivages : la mer a recouvert une grande partie du pays au cours des temps géologiques ;</li><li>ressources : phosphates (Taïba, Matam), calcaire (cimenteries de Bargny et de Pout), zircon des sables des Niayes, or (Sabodala), fer de la Falémé, pétrole et gaz en mer (Sangomar, Grand Tortue Ahmeyim).</li></ul>
