insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-croissance-microbienne') and slug = 'comment-les-microbes-se-multiplient'), $html$<ul><li>facteurs : température, eau disponible (activité de l’eau), pH, oxygène, nutriments ;</li><li>la plupart des pathogènes se multiplient vite entre 20 et 45 °C environ ; le froid ralentit leur croissance, la cuisson les détruit ;</li><li>courbe de croissance : latence, croissance exponentielle, phase stationnaire, déclin.</li></ul>
