insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'proteines-et-enzymes') and slug = 'proteines-et-enzymes'), $html$<ul><li>les protéines sont des chaînes d’acides aminés reliés par des liaisons peptidiques ;</li><li>la chaleur ou l’acidité les <strong>dénaturent</strong> : le blanc d’œuf coagule, le lait caille ;</li><li>les enzymes sont des protéines qui accélèrent les réactions ; elles agissent mieux à une température et un pH donnés ;</li><li>le brunissement d’une pomme ou d’une mangue coupée est enzymatique ; le jus de citron le ralentit.</li></ul>$html$);
