insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-litterature-negro-africaine') and slug = 'de-la-negritude-au-roman-africain'), $html$<ul><li>la Négritude (Senghor, Césaire, Damas) affirme les valeurs des civilisations noires ;</li><li>le roman colonial dénonce l’injustice : <em>Une vie de boy</em> (Ferdinand Oyono, 1956) ;</li><li><em>L’Aventure ambiguë</em> (Cheikh Hamidou Kane, 1961) pose la question de la rencontre des cultures ;</li><li><em>Une si longue lettre</em> (Mariama Bâ, 1979) donne la parole aux femmes.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 1, 'la-revolution-industrielle-et-ses-consequences', 'La révolution industrielle et ses conséquences', 'Genèse et manifestations ; conséquences économiques, sociales et politiques ; syndicalisme et socialisme.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-revolution-industrielle-et-ses-consequences'), 1, 'genese-et-consequences', 'Genèse et conséquences', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-revolution-industrielle-et-ses-consequences') and slug = 'genese-et-consequences'), $html$<ul><li>née en Grande-Bretagne à la fin du XVIII<sup>e</sup> siècle (charbon, machine à vapeur, textile), elle gagne l’Europe et les États-Unis ;</li><li>deuxième révolution industrielle à la fin du XIX<sup>e</sup> siècle : électricité, pétrole, chimie, automobile ;</li><li>le capitalisme se développe (banques, sociétés anonymes, concentrations) ;</li><li>la société se transforme : bourgeoisie industrielle, classe ouvrière, exode rural, urbanisation.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-revolution-industrielle-et-ses-consequences'), 2, 'syndicalisme-et-socialisme', 'Syndicalisme et socialisme', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-revolution-industrielle-et-ses-consequences') and slug = 'syndicalisme-et-socialisme'), $html$<ul><li>les ouvriers s’organisent en syndicats pour obtenir de meilleurs salaires et conditions de travail ;</li><li>le socialisme critique le capitalisme ; Karl Marx et Friedrich Engels publient le <em>Manifeste du parti communiste</em> (1848) ;</li><li>l’Église catholique propose sa doctrine sociale (encyclique <em>Rerum novarum</em>, 1891).</li></ul>$html$);
