insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-imperialisme-europeen-en-afrique'), 1, 'le-partage-de-l-afrique', 'Le partage de l’Afrique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-imperialisme-europeen-en-afrique') and slug = 'le-partage-de-l-afrique'), $html$<ul><li>causes : besoins de matières premières et de débouchés, rivalités entre puissances, prestige, prétendue « mission civilisatrice » ;</li><li>méthodes : explorations, missions, traités de protectorat, conquête militaire ;</li><li>la conférence de Berlin (1884-1885) fixe les règles de l’occupation des côtes africaines ;</li><li>en 1914, seuls l’Éthiopie et le Liberia restent indépendants.</li></ul>
