insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-resistances-africaines-a-l-imperialisme') and slug = 'resister-a-la-conquete'), $html$<table><thead><tr><th scope="col">Forme</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>armée</td><td>Lat Dior au Kayor (mort à Dékhélé en 1886), Samory Touré, Alboury Ndiaye, Mamadou Lamine Dramé, Fodé Kaba</td></tr><tr><td>culturelle et religieuse</td><td>Cheikh Ahmadou Bamba (exil au Gabon, 1895-1902), Aline Sitoé Diatta en Casamance</td></tr><tr><td>passive</td><td>refus de l’impôt et des cultures imposées, fuite, migrations</td></tr></tbody></table>
