insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-imperialisme-en-asie-en-amerique-et-dans-les-caraibes') and slug = 'un-monde-domine'), $html$<ul><li>Asie : l’Inde britannique, l’Indochine française ; la Chine est ouverte de force (guerres de l’opium) et partagée en zones d’influence ;</li><li>le Japon se modernise (ère Meiji, 1868) et devient à son tour impérialiste (Corée, Mandchourie) ; la Russie s’étend en Sibérie et en Asie centrale ;</li><li>Amérique : les États-Unis dominent les Caraïbes et l’Amérique centrale (doctrine Monroe, canal de Panama).</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 5, 'la-premiere-guerre-mondiale-et-l-afrique', 'La Première Guerre mondiale et l’Afrique', 'Causes, déroulement et conséquences de la guerre de 1914-1918 ; l’Afrique dans le conflit.', 5, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-premiere-guerre-mondiale-et-l-afrique'), 1, 'la-grande-guerre', 'La Grande Guerre', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-premiere-guerre-mondiale-et-l-afrique') and slug = 'la-grande-guerre'), $html$<ul><li>causes : rivalités impériales et économiques, nationalismes, système d’alliances ; l’attentat de Sarajevo (1914) déclenche le conflit ;</li><li>guerre de mouvement puis de tranchées (Verdun, 1916) ; l’entrée des États-Unis (1917) ;</li><li>l’armistice est signé le 11 novembre 1918 ; le traité de Versailles (1919) sanctionne l’Allemagne ;</li><li>l’Afrique fournit soldats (tirailleurs), travailleurs et ressources ; les colonies allemandes sont partagées.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 6, 'la-revolution-russe-et-la-chine-de-1911-a-1945', 'La révolution russe et la Chine de 1911 à 1945', 'Les révolutions de 1917 et l’URSS ; la Chine de la république à la guerre contre le Japon.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-revolution-russe-et-la-chine-de-1911-a-1945'), 1, 'revolutions-en-russie-et-en-chine', 'Révolutions en Russie et en Chine', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-revolution-russe-et-la-chine-de-1911-a-1945') and slug = 'revolutions-en-russie-et-en-chine'), $html$<ul><li>en 1917, le tsar abdique ; en octobre, les bolcheviks de Lénine prennent le pouvoir ; l’URSS naît en 1922 ; Staline impose ensuite une dictature ;</li><li>en Chine, la république est proclamée en 1911-1912 (Sun Yat-sen) ; le Guomindang de Tchang Kaï-chek affronte les communistes de Mao Zedong (Longue Marche, 1934-1935) ;</li><li>à partir de 1937, la Chine combat l’invasion japonaise.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 7, 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective', 'La crise des années 1930, les fascismes et la faillite de la sécurité collective', 'La crise de 1929, la montée des régimes totalitaires, l’échec de la SDN.', 7, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective'), 1, 'vers-une-nouvelle-guerre', 'Vers une nouvelle guerre', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-crise-des-annees-1930-les-fascismes-et-la-faillite-de-la-securite-collective') and slug = 'vers-une-nouvelle-guerre'), $html$<ul><li>le krach de Wall Street (octobre 1929) provoque une crise mondiale : faillites, chômage, effondrement des prix agricoles (y compris de l’arachide) ;</li><li>fascisme en Italie (Mussolini, 1922), nazisme en Allemagne (Hitler, 1933) ;</li><li>la Société des Nations ne peut empêcher les agressions : invasion de l’Éthiopie par l’Italie (1935), remilitarisation de la Rhénanie, annexions allemandes.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 8, 'la-seconde-guerre-mondiale-et-l-afrique', 'La Seconde Guerre mondiale et l’Afrique', 'Les principales étapes du conflit ; la participation de l’Afrique.', 8, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-seconde-guerre-mondiale-et-l-afrique'), 1, '1939-1945', '1939-1945', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-seconde-guerre-mondiale-et-l-afrique') and slug = '1939-1945'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Événement</th></tr></thead><tbody><tr><td>septembre 1939</td><td>invasion de la Pologne, début de la guerre</td></tr><tr><td>juin 1940</td><td>défaite de la France ; appel du général de Gaulle</td></tr><tr><td>1941</td><td>l’URSS et les États-Unis entrent en guerre</td></tr><tr><td>1942-1943</td><td>tournants : El-Alamein, Stalingrad</td></tr><tr><td>mai et août 1945</td><td>capitulation de l’Allemagne, puis du Japon après les bombes atomiques</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 9, 'le-senegal-de-1914-a-1945', 'Le Sénégal de 1914 à 1945', 'Le Sénégal dans les deux guerres mondiales et dans l’entre-deux-guerres.', 9, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-senegal-de-1914-a-1945'), 1, 'le-senegal-colonial', 'Le Sénégal colonial', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-senegal-de-1914-a-1945') and slug = 'le-senegal-colonial'), $html$<ul><li>en 1914, Blaise Diagne est le premier député africain élu à l’Assemblée nationale française ; il organise le recrutement de tirailleurs en 1918 ;</li><li>entre les deux guerres : économie de traite de l’arachide, chemin de fer Dakar-Niger, crise des années 1930 ;</li><li>vie politique animée dans les Quatre Communes (Dakar, Gorée, Rufisque, Saint-Louis) ;</li><li>pendant la Seconde Guerre mondiale, l’AOF est d’abord fidèle au régime de Vichy (bataille de Dakar, septembre 1940), puis rejoint les Alliés fin 1942.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 10, 'les-inegalites-de-developpement-dans-le-monde', 'Les inégalités de développement dans le monde', 'Mesurer le développement ; pays développés, émergents et moins avancés.', 10, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-inegalites-de-developpement-dans-le-monde'), 1, 'mesurer-le-developpement', 'Mesurer le développement', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-inegalites-de-developpement-dans-le-monde') and slug = 'mesurer-le-developpement'), $html$<ul><li>le PIB par habitant mesure la richesse produite ; l’IDH combine revenu, santé (espérance de vie) et éducation ;</li><li>pays développés, pays émergents (Chine, Inde, Brésil), pays moins avancés ;</li><li>les inégalités existent aussi à l’intérieur des pays (villes et campagnes).</li></ul>$html$);
