insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-population-mondiale'), 1, 'croissance-et-repartition', 'Croissance et répartition', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-population-mondiale') and slug = 'croissance-et-repartition'), $html$<ul><li>plus de 8 milliards d’habitants ; la croissance ralentit, mais reste forte en Afrique ;</li><li>taux d’accroissement naturel = taux de natalité − taux de mortalité ;</li><li>la population est concentrée en Asie de l’Est et du Sud, en Europe, en Afrique de l’Ouest ; les déserts et les régions froides sont presque vides ;</li><li>migrations internes (exode rural) et internationales ; politiques natalistes ou de limitation des naissances.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')), 12, 'les-formes-de-mise-en-valeur-agricole-et-la-peche', 'Les formes de mise en valeur agricole et la pêche', 'Agricultures tropicales traditionnelles et commerciales, agriculture européenne, pays neufs, pêche.', 12, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
