insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-formes-de-mise-en-valeur-agricole-et-la-peche') and slug = 'des-agricultures-contrastees'), $html$<table><thead><tr><th scope="col">Type</th><th scope="col">Caractères</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>vivrière traditionnelle</td><td>outils simples, autoconsommation, jachère</td><td>mil, sorgho, riz pluvial</td></tr><tr><td>commerciale tropicale</td><td>cultures d’exportation, plantations</td><td>arachide, cacao, coton</td></tr><tr><td>intensive européenne</td><td>mécanisation, engrais, forts rendements, subventions</td><td>céréales, élevage laitier</td></tr><tr><td>pays neufs</td><td>immenses exploitations très mécanisées</td><td>États-Unis, Canada, Australie</td></tr></tbody></table>
