insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'l-activite-economique-et-ses-agents') and slug = 'besoins-biens-et-agents'), $html$<ul><li>l’activité économique cherche à satisfaire des <strong>besoins</strong> illimités avec des ressources rares ;</li><li>les biens économiques sont rares et ont un prix ; les biens libres (l’air) sont gratuits ;</li><li>agents économiques : ménages (consomment), entreprises (produisent), administrations publiques, institutions financières, reste du monde ;</li><li>le <strong>circuit économique</strong> représente les flux réels (biens, travail) et monétaires (salaires, dépenses) entre ces agents.</li></ul>$html$);
