insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-marche-et-la-formation-des-prix') and slug = 'l-equilibre-du-marche'), $html$<ul><li>la demande diminue quand le prix augmente ; l’offre augmente quand le prix augmente ;</li><li>le <strong>prix d’équilibre</strong> est celui pour lequel la quantité offerte égale la quantité demandée ;</li><li>structures de marché : concurrence, monopole (un seul vendeur), oligopole (quelques vendeurs) ;</li><li>l’État peut intervenir : prix homologués, subventions, taxes.</li></ul>
