insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'la-monnaie-et-le-financement-de-l-economie') and slug = 'la-monnaie'), $html$<ul><li>fonctions : intermédiaire des échanges, unité de compte, réserve de valeur ;</li><li>formes : monnaie fiduciaire (billets, pièces), scripturale (comptes bancaires), électronique (paiement par téléphone) ;</li><li>au Sénégal, la monnaie est le franc CFA, émis par la BCEAO, dont le siège est à Dakar ;</li><li>les banques financent l’économie par le crédit ; les entreprises se financent aussi par autofinancement ou en émettant des actions.</li></ul>$html$);
