insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'revenu-consommation-et-epargne') and slug = 'utiliser-son-revenu'), $html$<ul><li>revenus primaires : salaires, profits, intérêts, loyers ; revenus de transfert : allocations, pensions, envois des émigrés ;</li><li>revenu disponible = revenus − impôts et cotisations ;</li><li>il est partagé entre consommation et épargne ;</li><li>loi d’Engel : quand le revenu augmente, la part consacrée à l’alimentation diminue.</li></ul>
