insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'l-investissement') and slug = 'investir'), $html$<ul><li>investir, c’est acquérir des biens de production durables : matériel, bâtiments, mais aussi formation et recherche (investissement immatériel) ;</li><li>investissement de remplacement, de capacité (produire plus) ou de productivité (produire mieux) ;</li><li>il dépend de la demande attendue, du taux d’intérêt et de la rentabilité espérée ;</li><li>financement : autofinancement, emprunt, augmentation de capital, subventions.</li></ul>$html$);
