insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'la-comptabilite-nationale') and slug = 'mesurer-la-richesse-produite'), $html$<ul><li>le <strong>PIB</strong> est la somme des valeurs ajoutées produites sur le territoire en un an ;</li><li>PIB par habitant = PIB ÷ population ;</li><li>le PIB nominal est mesuré aux prix courants ; le PIB réel élimine la hausse des prix ;</li><li>taux de croissance = (PIB de l’année − PIB de l’année précédente) ÷ PIB de l’année précédente × 100.</li></ul>
