insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'GEST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'l-entreprise-et-son-environnement') and slug = 'qu-est-ce-qu-une-entreprise'), $html$<ul><li>une entreprise combine des moyens humains, matériels et financiers pour produire des biens ou des services et les vendre ;</li><li>classification : par taille (TPE, PME, grandes entreprises), par secteur, par forme juridique ;</li><li>formes du droit OHADA : entreprise individuelle, SARL, SA, GIE ;</li><li>fonctions : approvisionnement, production, commercialisation, gestion du personnel, finance.</li></ul>$html$);
