insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'GEST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'les-comptes-et-la-partie-double') and slug = 'debit-et-credit'), $html$<ul><li>un compte a deux colonnes : le <strong>débit</strong> (à gauche) et le <strong>crédit</strong> (à droite) ;</li><li>un compte d’actif augmente au débit ; un compte de passif augmente au crédit ;</li><li>les charges s’enregistrent au débit, les produits au crédit ;</li><li><strong>partie double</strong> : chaque opération touche au moins deux comptes, pour le même montant au débit et au crédit.</li></ul>
