insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'statistique-a-deux-variables') and slug = 'ajustement-d-un-nuage-de-points'), $html$<ul><li>on représente les couples (x<sub>i</sub> ; y<sub>i</sub>) par un nuage de points ; G(x̄ ; ȳ) est le point moyen ;</li><li>méthode de Mayer : on partage le nuage en deux groupes et on trace la droite qui passe par les deux points moyens ;</li><li>méthode des moindres carrés : la droite de régression de y en x passe par G et a pour coefficient cov(x, y) ÷ V(x).</li></ul>
