insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'probabilites-premieres-notions'), 1, 'calculer-une-probabilite', 'Calculer une probabilité', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'probabilites-premieres-notions') and slug = 'calculer-une-probabilite'), $html$<ul><li>une expérience aléatoire a plusieurs issues possibles ; leur ensemble est l’<strong>univers</strong> Ω ;</li><li>en cas d’équiprobabilité : P(A) = <span class="frac"><span>nombre d’issues favorables</span><span>nombre d’issues possibles</span></span> ;</li><li>P(Ā) = 1 − P(A) ; P(A ∪ B) = P(A) + P(B) − P(A ∩ B) ;</li><li>deux événements incompatibles n’ont aucune issue commune : P(A ∪ B) = P(A) + P(B).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')), 4, 'suites-numeriques', 'Suites numériques', 'Génération d’une suite, sens de variation, suites arithmétiques et géométriques.', 4, 'published', 'Analyse', '[{"title":"Programme de mathématiques de la série G, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesG.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'suites-numeriques'), 1, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Arithmétique (raison r)</th><th scope="col">Géométrique (raison q)</th></tr></thead><tbody><tr><td>relation</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>somme de termes consécutifs</td><td>nombre de termes × (premier + dernier) ÷ 2</td><td>premier × <span class="frac"><span>1 − q<sup>nombre de termes</sup></span><span>1 − q</span></span> (q ≠ 1)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')), 5, 'limites-et-continuite', 'Limites et continuité', 'Limites finies et infinies, opérations, formes indéterminées, asymptotes, continuité.', 5, 'published', 'Analyse', '[{"title":"Programme de mathématiques de la série G, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesG.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'limites-et-continuite'), 1, 'calculer-des-limites', 'Calculer des limites', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'limites-et-continuite') and slug = 'calculer-des-limites'), $html$<ul><li>à l’infini, un polynôme a la limite de son terme de plus haut degré ; une fraction rationnelle, celle du quotient des termes de plus haut degré ;</li><li>formes indéterminées : ∞ − ∞, 0 × ∞, ∞/∞, 0/0 : on factorise ou on simplifie ;</li><li>si lim f(x) = ±∞ quand x tend vers a, la droite x = a est asymptote verticale ; si lim f(x) = b à l’infini, y = b est asymptote horizontale.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'limites-et-continuite'), 2, 'la-continuite', 'La continuité', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'limites-et-continuite') and slug = 'la-continuite'), $html$<ul><li>f est continue en a si lim f(x) = f(a) quand x tend vers a ;</li><li>les fonctions polynômes et rationnelles sont continues sur leur ensemble de définition ;</li><li>l’image d’un intervalle par une fonction continue est un intervalle (théorème des valeurs intermédiaires).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')), 6, 'derivation-et-applications', 'Dérivation et applications', 'Nombre dérivé, tangente, dérivées usuelles, sens de variation, extremums.', 6, 'published', 'Analyse', '[{"title":"Programme de mathématiques de la série G, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesG.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'derivation-et-applications'), 1, 'nombre-derive-et-tangente', 'Nombre dérivé et tangente', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'derivation-et-applications') and slug = 'nombre-derive-et-tangente'), $html$<p class="formula">f’(a) = lim <span class="frac"><span>f(a + h) − f(a)</span><span>h</span></span> quand h → 0 ; tangente : y = f’(a)(x − a) + f(a)</p>
