insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'coupes-et-sections'), 1, 'voir-l-interieur-d-une-piece', 'Voir l’intérieur d’une pièce', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'coupes-et-sections') and slug = 'voir-l-interieur-d-une-piece'), $html$<ul><li>une <strong>coupe</strong> montre l’intérieur d’une pièce, comme si on l’avait sciée selon un plan ;</li><li>les parties coupées sont hachurées (traits fins inclinés à 45°) ;</li><li>la demi-coupe montre à la fois l’extérieur et l’intérieur d’une pièce symétrique ;</li><li>une <strong>section</strong> ne représente que la partie située dans le plan de coupe.</li></ul>$html$);
