insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'cotation-et-tolerances'), 1, 'coter-une-piece', 'Coter une pièce', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'cotation-et-tolerances') and slug = 'coter-une-piece'), $html$<ul><li>une cote indique une dimension en millimètres ; chaque dimension n’est cotée qu’une fois ;</li><li>une pièce ne peut pas être fabriquée exactement à la cote : on fixe une <strong>tolérance</strong> (ex. 20 ± 0,1) ;</li><li>un ajustement associe un alésage et un arbre (ex. ⌀ 20 H7/g6) : avec jeu, incertain ou serré ;</li><li>l’état de surface (rugosité Ra) précise la finition attendue.</li></ul>
