insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'les-liaisons-mecaniques'), 1, 'liaisons-et-degres-de-liberte', 'Liaisons et degrés de liberté', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'les-liaisons-mecaniques') and slug = 'liaisons-et-degres-de-liberte'), $html$<table><thead><tr><th scope="col">Liaison</th><th scope="col">Mouvements possibles</th></tr></thead><tbody><tr><td>encastrement</td><td>aucun</td></tr><tr><td>pivot</td><td>1 rotation</td></tr><tr><td>glissière</td><td>1 translation</td></tr><tr><td>pivot glissant</td><td>1 rotation + 1 translation de même axe</td></tr><tr><td>hélicoïdale</td><td>rotation et translation liées (vis-écrou)</td></tr><tr><td>rotule</td><td>3 rotations</td></tr><tr><td>appui plan</td><td>2 translations + 1 rotation</td></tr></tbody></table>
