insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'le-guidage-en-rotation') and slug = 'guider-un-arbre'), $html$<ul><li>palier lisse : coussinet en bronze ou en matière plastique, simple et peu coûteux ;</li><li>roulements à billes ou à rouleaux : moins de frottement, vitesses plus élevées ;</li><li>un montage de roulements arrête l’arbre en translation par des épaulements, des anneaux élastiques ou des écrous ;</li><li>la lubrification (graisse, huile) réduit l’usure et l’échauffement.</li></ul>$html$);
