insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'TECH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'securite-et-organisation-de-l-atelier') and slug = 'travailler-en-securite'), $html$<ul><li>équipements de protection individuelle : lunettes, chaussures de sécurité, protections auditives, tenue ajustée ;</li><li>sur machine : carter fermé, arrêt d’urgence accessible, ne jamais retirer les copeaux à la main ;</li><li>méthode 5S : trier, ranger, nettoyer, standardiser, maintenir.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 1, 'barycentre-et-lignes-de-niveau', 'Barycentre et lignes de niveau', 'Barycentre de n points, barycentres partiels, lignes de niveau.', 1, 'published', 'Géométrie', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'barycentre-et-lignes-de-niveau'), 1, 'barycentre-de-plusieurs-points', 'Barycentre de plusieurs points', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'barycentre-et-lignes-de-niveau') and slug = 'barycentre-de-plusieurs-points'), $html$<ul><li>G barycentre de (A, a), (B, b), (C, c) avec a + b + c ≠ 0 : aGA⃗ + bGB⃗ + cGC⃗ = 0⃗ ;</li><li>associativité : on peut remplacer des points par leur barycentre partiel affecté de la somme de leurs coefficients ;</li><li>coordonnées : x<sub>G</sub> = <span class="frac"><span>ax<sub>A</sub> + bx<sub>B</sub> + cx<sub>C</sub></span><span>a + b + c</span></span>.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 2, 'transformations-du-plan', 'Transformations du plan', 'Isométries, translations, rotations, homothéties et leurs composées.', 2, 'published', 'Géométrie', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'transformations-du-plan'), 1, 'isometries-et-composees', 'Isométries et composées', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'transformations-du-plan') and slug = 'isometries-et-composees'), $html$<ul><li>une isométrie conserve les distances : translations, rotations, symétries ;</li><li>la composée de deux rotations de même centre et d’angles θ et θ’ est la rotation d’angle θ + θ’ ;</li><li>la composée de deux symétries orthogonales d’axes sécants en O est une rotation de centre O d’angle double de l’angle des axes ;</li><li>une homothétie de rapport k conserve les angles et multiplie les distances par |k|.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 3, 'geometrie-dans-l-espace', 'Géométrie dans l’espace', 'Vecteurs de l’espace, coplanarité, produit scalaire, plans et sphères.', 3, 'published', 'Géométrie', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'geometrie-dans-l-espace'), 1, 'vecteurs-et-produit-scalaire-dans-l-espace', 'Vecteurs et produit scalaire dans l’espace', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'geometrie-dans-l-espace') and slug = 'vecteurs-et-produit-scalaire-dans-l-espace'), $html$<ul><li>trois vecteurs sont coplanaires si l’un est combinaison linéaire des deux autres ;</li><li>dans un repère orthonormé : u⃗ · v⃗ = xx’ + yy’ + zz’ ;</li><li>un plan de vecteur normal n⃗(a ; b ; c) a une équation ax + by + cz + d = 0 ;</li><li>la sphère de centre Ω(a ; b ; c) et de rayon r : (x − a)<sup>2</sup> + (y − b)<sup>2</sup> + (z − c)<sup>2</sup> = r<sup>2</sup>.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 4, 'angles-orientes-et-trigonometrie', 'Angles orientés et trigonométrie', 'Angles inscrits, formules d’addition et de duplication, équations trigonométriques.', 4, 'published', 'Géométrie', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'angles-orientes-et-trigonometrie'), 1, 'formules-trigonometriques', 'Formules trigonométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'formules-trigonometriques'), $html$<ul><li>cos(a + b) = cos a cos b − sin a sin b ; sin(a + b) = sin a cos b + cos a sin b ;</li><li>cos 2a = cos<sup>2</sup>a − sin<sup>2</sup>a = 2cos<sup>2</sup>a − 1 = 1 − 2sin<sup>2</sup>a ; sin 2a = 2 sin a cos a ;</li><li>un angle inscrit mesure la moitié de l’angle au centre qui intercepte le même arc.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'angles-orientes-et-trigonometrie'), 2, 'equations-trigonometriques', 'Équations trigonométriques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'angles-orientes-et-trigonometrie') and slug = 'equations-trigonometriques'), $html$<ul><li>cos x = cos a ⟺ x = a + 2kπ ou x = −a + 2kπ (k entier) ;</li><li>sin x = sin a ⟺ x = a + 2kπ ou x = π − a + 2kπ ;</li><li>on représente les solutions sur le cercle trigonométrique.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 5, 'generalites-sur-les-fonctions-et-applications', 'Généralités sur les fonctions et applications', 'Applications injectives, surjectives, bijectives ; parité, périodicité ; courbes associées.', 5, 'published', 'Analyse', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'generalites-sur-les-fonctions-et-applications'), 1, 'applications-et-fonctions', 'Applications et fonctions', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'generalites-sur-les-fonctions-et-applications') and slug = 'applications-et-fonctions'), $html$<ul><li>une application f de E dans F est <strong>injective</strong> si deux éléments distincts ont des images distinctes, <strong>surjective</strong> si tout élément de F a au moins un antécédent, <strong>bijective</strong> si elle est les deux ;</li><li>une bijection admet une application réciproque f⁻¹ ;</li><li>f est périodique de période T si f(x + T) = f(x) : cos et sin sont 2π-périodiques ;</li><li>la courbe de x ↦ f(x − a) + b se déduit de celle de f par la translation de vecteur (a ; b).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 6, 'polynomes-equations-et-systemes', 'Polynômes, équations et systèmes', 'Méthode de Horner, somme et produit des racines, équations à paramètre, pivot de Gauss.', 6, 'published', 'Algèbre', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'polynomes-equations-et-systemes'), 1, 'polynomes-et-equations', 'Polynômes et équations', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'polynomes-equations-et-systemes') and slug = 'polynomes-et-equations'), $html$<ul><li>si a est racine de P, la méthode de Horner donne le quotient Q tel que P(x) = (x − a)Q(x) ;</li><li>si ax<sup>2</sup> + bx + c = 0 a deux racines x₁ et x₂ : x₁ + x₂ = −b/a et x₁x₂ = c/a ;</li><li>un système de trois équations à trois inconnues se résout par la méthode du pivot de Gauss (on se ramène à un système triangulaire).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 7, 'suites-numeriques', 'Suites numériques', 'Génération d’une suite, sens de variation, suites arithmétiques et géométriques.', 7, 'published', 'Analyse', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'suites-numeriques'), 1, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Arithmétique (raison r)</th><th scope="col">Géométrique (raison q)</th></tr></thead><tbody><tr><td>relation</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>somme de termes consécutifs</td><td>nombre de termes × (premier + dernier) ÷ 2</td><td>premier × <span class="frac"><span>1 − q<sup>nombre de termes</sup></span><span>1 − q</span></span> (q ≠ 1)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 8, 'limites-et-continuite', 'Limites et continuité', 'Limites finies et infinies, opérations, formes indéterminées, asymptotes, continuité.', 8, 'published', 'Analyse', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'limites-et-continuite'), 1, 'calculer-des-limites', 'Calculer des limites', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'limites-et-continuite') and slug = 'calculer-des-limites'), $html$<ul><li>à l’infini, un polynôme a la limite de son terme de plus haut degré ; une fraction rationnelle, celle du quotient des termes de plus haut degré ;</li><li>formes indéterminées : ∞ − ∞, 0 × ∞, ∞/∞, 0/0 : on factorise ou on simplifie ;</li><li>si lim f(x) = ±∞ quand x tend vers a, la droite x = a est asymptote verticale ; si lim f(x) = b à l’infini, y = b est asymptote horizontale.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'limites-et-continuite'), 2, 'la-continuite', 'La continuité', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'limites-et-continuite') and slug = 'la-continuite'), $html$<ul><li>f est continue en a si lim f(x) = f(a) quand x tend vers a ;</li><li>les fonctions polynômes et rationnelles sont continues sur leur ensemble de définition ;</li><li>l’image d’un intervalle par une fonction continue est un intervalle (théorème des valeurs intermédiaires).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T1')), 9, 'derivation-et-applications', 'Dérivation et applications', 'Nombre dérivé, tangente, dérivées usuelles, sens de variation, extremums.', 9, 'published', 'Analyse', '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
