insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ELEC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'magnetisme-et-induction') and slug = 'de-l-electroaimant-a-la-dynamo'), $html$<ul><li>un courant crée un champ magnétique (électroaimant, bobine) ;</li><li>force de Laplace : un conducteur parcouru par un courant dans un champ subit une force F = B × I × L (principe du moteur) ;</li><li>induction : un flux magnétique variable crée une tension induite (principe de l’alternateur et du transformateur) ;</li><li>loi de Lenz : le courant induit s’oppose à la cause qui lui a donné naissance.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ELEC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T2')), 6, 'composants-electroniques-de-base', 'Composants électroniques de base', 'Diode, redressement, filtrage, diode Zener, LED.', 6, 'published', 'Électronique', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ELEC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'composants-electroniques-de-base'), 1, 'redresser-et-filtrer', 'Redresser et filtrer', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ELEC' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'composants-electroniques-de-base') and slug = 'redresser-et-filtrer'), $html$<ul><li>la diode ne laisse passer le courant que dans un sens ;</li><li>redressement simple alternance (une diode) ou double alternance (pont de quatre diodes) ;</li><li>un condensateur de filtrage lisse la tension redressée ;</li><li>une diode Zener stabilise la tension ; une LED émet de la lumière quand elle conduit.</li></ul>
