insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '1RE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'nombres-complexes') and slug = 'forme-algebrique'), $html$<ul><li>un nombre complexe s’écrit z = a + ib, avec a et b réels et i<sup>2</sup> = −1 ;</li><li>a est la partie réelle, b la partie imaginaire ; le conjugué de z est z̄ = a − ib ;</li><li>on calcule comme avec des réels en remplaçant i² par −1 ; pour diviser, on multiplie par le conjugué du dénominateur.</li></ul>
