insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'arithmetique') and slug = 'pgcd-ppcm-et-algorithme-d-euclide'), $html$<p>Le <strong>PGCD</strong> de a et b est leur plus grand diviseur commun ; le <strong>PPCM</strong> leur plus petit multiple commun strictement positif. Si PGCD(a, b) = 1, a et b sont <strong>premiers entre eux</strong>.</p>
