insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques'), 2, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Suite arithmétique de raison r</th><th scope="col">Suite géométrique de raison q</th></tr></thead><tbody><tr><td>Définition</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>Terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr = u<sub>p</sub> + (n − p)r</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>Somme de termes consécutifs</td><td>(nombre de termes) × <span class="frac"><span>premier + dernier</span><span>2</span></span></td><td>premier × <span class="frac"><span>1 − q<sup>N</sup></span><span>1 − q</span></span> (N termes, q ≠ 1)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques'), 3, 'sens-de-variation-et-suites-bornees', 'Sens de variation et suites bornées', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques') and slug = 'sens-de-variation-et-suites-bornees'), $html$<p>Une suite (u<sub>n</sub>) est <strong>croissante</strong> si u<sub>n+1</sub> ≥ u<sub>n</sub> pour tout n, <strong>décroissante</strong> si u<sub>n+1</sub> ≤ u<sub>n</sub>, <strong>monotone</strong> si elle est l’un ou l’autre.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques'), 4, 'limites-de-suites-et-theoremes-de-convergence', 'Limites de suites et théorèmes de convergence', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques') and slug = 'limites-de-suites-et-theoremes-de-convergence'), $html$<p>Une suite <strong>converge</strong> vers ℓ si ses termes deviennent aussi proches de ℓ qu’on veut à partir d’un certain rang ; sinon elle <strong>diverge</strong> (limite infinie ou pas de limite). Les opérations sur les limites sont les mêmes que pour les fonctions.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques'), 5, 'suites-definies-par-u-n-1-f-u-n', 'Suites définies par u(n+1) = f(u(n))', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'suites-numeriques') and slug = 'suites-definies-par-u-n-1-f-u-n'), $html$<p>On représente une telle suite en traçant la courbe de f et la droite y = x : on place u<sub>0</sub> sur l’axe des abscisses, on « monte » à la courbe pour lire u<sub>1</sub> = f(u<sub>0</sub>), on le reporte sur l’axe grâce à la droite y = x, et ainsi de suite. Le dessin permet de conjecturer le sens de variation et la limite.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 5, 'limites-et-continuite', 'Limites et continuité', 'Opérations sur les limites, asymptotes, théorème des valeurs intermédiaires, fonction réciproque.', 5, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite'), 1, 'limites-operations-et-formes-indeterminees', 'Limites : opérations et formes indéterminées', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite') and slug = 'limites-operations-et-formes-indeterminees'), $html$<p>Les limites des fonctions de référence (x ↦ x<sup>n</sup>, <span class="frac"><span>1</span><span>x</span></span>, √x…) permettent de calculer les limites des sommes, produits et quotients.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite'), 2, 'asymptotes-et-branches-infinies', 'Asymptotes et branches infinies', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite') and slug = 'asymptotes-et-branches-infinies'), $html$<p>Les limites aux bornes de l’ensemble de définition décrivent l’allure de la courbe 𝒞 de f « à l’infini ».</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite'), 3, 'continuite-et-theoreme-des-valeurs-intermediaires', 'Continuité et théorème des valeurs intermédiaires', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite') and slug = 'continuite-et-theoreme-des-valeurs-intermediaires'), $html$<p>f est <strong>continue en a</strong> si lim<sub>x→a</sub> f(x) = f(a) : la courbe se trace « sans lever le crayon ». Les polynômes, les fonctions rationnelles, √x, sin, cos, ln et exp sont continues sur leur ensemble de définition, ainsi que leurs sommes, produits, quotients et composées.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite'), 4, 'fonction-reciproque', 'Fonction réciproque', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'limites-et-continuite') and slug = 'fonction-reciproque'), $html$<p>Si f est <strong>continue et strictement monotone</strong> sur un intervalle I, elle réalise une <strong>bijection</strong> de I sur l’intervalle J = f(I) : tout y de J a un unique antécédent x dans I. On définit ainsi la fonction réciproque f<sup>−1</sup> : y = f(x) ⇔ x = f<sup>−1</sup>(y).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 6, 'derivation-et-etude-de-fonctions', 'Dérivation et étude de fonctions', 'Dérivée d’une composée, accroissements finis, dérivées successives, plan d’étude.', 6, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
