insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions') and slug = 'derivee-d-une-fonction-composee'), $html$<p>Si f est dérivable en x et g dérivable en f(x), alors g ∘ f est dérivable en x et :</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions'), 2, 'accroissements-finis', 'Accroissements finis', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions') and slug = 'accroissements-finis'), $html$<p><strong>Théorème des accroissements finis</strong> (admis) : si f est continue sur [a ; b] et dérivable sur ]a ; b[, il existe au moins un réel c de ]a ; b[ tel que</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions'), 3, 'derivees-successives-et-points-d-inflexion', 'Dérivées successives et points d’inflexion', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions') and slug = 'derivees-successives-et-points-d-inflexion'), $html$<p>Si f’ est elle-même dérivable, sa dérivée est la <strong>dérivée seconde</strong> f’’ (notée aussi <span class="frac"><span>d²f</span><span>dx²</span></span> en physique), et ainsi de suite : f<sup>(n)</sup> est la dérivée n-ième.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions'), 4, 'etude-complete-d-une-fonction', 'Étude complète d’une fonction', true, 'published', 20, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'derivation-et-etude-de-fonctions') and slug = 'etude-complete-d-une-fonction'), $html$<div class="callout"><p class="callout-title">Plan d’étude</p><ol><li>Ensemble de définition D<sub>f</sub> ; parité ou périodicité pour réduire l’étude.</li><li>Limites aux bornes de D<sub>f</sub> et asymptotes.</li><li>Dérivée, signe de la dérivée, tableau de variations.</li><li>Éléments de symétrie, points particuliers (intersections avec les axes), tangentes utiles.</li><li>Tracé : asymptotes d’abord, puis points du tableau, puis la courbe.</li></ol></div>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 7, 'fonction-logarithme-neperien', 'Fonction logarithme népérien', 'Définition, propriétés algébriques, étude de ln et de ln u, équations et logarithme décimal.', 7, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'fonction-logarithme-neperien'), 1, 'le-logarithme-neperien-definition-et-proprietes', 'Le logarithme népérien : définition et propriétés', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'fonction-logarithme-neperien') and slug = 'le-logarithme-neperien-definition-et-proprietes'), $html$<p>La <strong>fonction logarithme népérien</strong>, notée ln, est l’unique primitive de x ↦ <span class="frac"><span>1</span><span>x</span></span> sur ]0 ; +∞[ qui s’annule en 1.</p>
