insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'coniques') and slug = 'l-ellipse'), $html$<p class="formula">Équation réduite : <span class="frac"><span>x²</span><span>a²</span></span> + <span class="frac"><span>y²</span><span>b²</span></span> = 1, avec a &gt; b &gt; 0</p>
