insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'interferences-lumineuses') and slug = 'l-experience-des-fentes-de-young'), $html$<p>Deux fentes fines F₁ et F₂, distantes de a, sont éclairées par la même source monochromatique : ce sont deux sources <strong>cohérentes</strong>. Sur un écran à la distance D, on observe des franges alternativement brillantes et sombres, régulièrement espacées.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'interferences-lumineuses'), 2, 'interpretation-et-applications', 'Interprétation et applications', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'interferences-lumineuses') and slug = 'interpretation-et-applications'), $html$<p>Les interférences ne s’expliquent que si la lumière est une <strong>onde</strong> : deux vibrations en phase s’ajoutent, deux vibrations en opposition de phase s’annulent. La diffraction par une fente fine en est un autre signe.</p>
