insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'effet-photoelectrique') and slug = 'mise-en-evidence-de-l-effet-photoelectrique'), $html$<p>Une plaque de zinc chargée négativement se décharge quand on l’éclaire en ultraviolet, mais pas en lumière visible, même intense (expérience de Hertz) : la lumière arrache des électrons au métal.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'effet-photoelectrique'), 2, 'le-photon-et-la-relation-d-einstein', 'Le photon et la relation d’Einstein', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'effet-photoelectrique') and slug = 'le-photon-et-la-relation-d-einstein'), $html$<p>Einstein (1905) : la lumière est formée de <strong>photons</strong>, chacun transportant l’énergie</p>
