insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'niveaux-d-energie-de-l-atome') and slug = 'quantification-de-l-energie-et-spectres'), $html$<p>L’énergie d’un atome ne peut prendre que certaines valeurs : elle est <strong>quantifiée</strong>. Le niveau le plus bas est l’état fondamental ; les autres sont des états excités.</p>
