insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-amines') and slug = 'structure-et-nomenclature-des-amines'), $html$<p>Une <strong>amine</strong> dérive de l’ammoniac NH₃ par remplacement d’un ou plusieurs atomes d’hydrogène par des groupes carbonés.</p>
