insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reaction-acide-faible-base-forte-effet-tampon') and slug = 'dosage-d-un-acide-faible-par-une-base-forte'), $html$<p class="formula">CH₃COOH + OH⁻ → CH₃COO⁻ + H₂O (réaction totale)</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reaction-acide-faible-base-forte-effet-tampon'), 2, 'solutions-tampons', 'Solutions tampons', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reaction-acide-faible-base-forte-effet-tampon') and slug = 'solutions-tampons'), $html$<p>Une <strong>solution tampon</strong> a un pH qui varie peu par addition modérée d’acide ou de base, ou par dilution. On l’obtient en mélangeant un acide faible et sa base conjuguée en quantités voisines : son pH est proche du pK<sub>a</sub>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 24, 'acides-amines', 'Acides α-aminés', 'Structure, chiralité, représentation de Fischer, amphion, liaison peptidique.', 24, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'acides-amines'), 1, 'structure-et-chiralite-des-acides-amines', 'Structure et chiralité des acides α-aminés', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'acides-amines') and slug = 'structure-et-chiralite-des-acides-amines'), $html$<p>Un <strong>acide α-aminé</strong> a pour formule R−CH(NH₂)−COOH : le groupe amine et le groupe carboxyle sont portés par le même carbone. Ce sont les briques des protéines (glycine R = H, alanine R = CH₃…).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'acides-amines'), 2, 'amphion-et-liaison-peptidique', 'Amphion et liaison peptidique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'acides-amines') and slug = 'amphion-et-liaison-peptidique'), $html$<p>En solution aqueuse, un acide α-aminé existe surtout sous forme d’<strong>amphion</strong> (ou zwitterion) : R−CH(NH₃⁺)−COO⁻. Il est à la fois acide (NH₃⁺) et basique (COO⁻) : c’est un <strong>ampholyte</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 1, 'organisation-du-systeme-nerveux-cerebro-spinal', 'Organisation du système nerveux cérébro-spinal', 'Encéphale et moelle épinière : protection, organisation externe et interne, rôles.', 1, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal'), 1, 'organisation-de-l-encephale', 'Organisation de l’encéphale', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal') and slug = 'organisation-de-l-encephale'), $html$<p>Le système nerveux central (encéphale et moelle épinière) est protégé par des os (boîte crânienne, colonne vertébrale), par trois <strong>méninges</strong> (dure-mère, arachnoïde, pie-mère) et par le <strong>liquide céphalorachidien</strong>, qui amortit les chocs.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal'), 2, 'organisation-de-la-moelle-epiniere', 'Organisation de la moelle épinière', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal') and slug = 'organisation-de-la-moelle-epiniere'), $html$<p>La moelle épinière est un cordon nerveux logé dans le canal vertébral. Sur une coupe transversale, on voit la <strong>substance grise</strong> en forme de papillon (ou de H) au centre, entourée de <strong>substance blanche</strong>, avec le canal de l’épendyme au milieu.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 2, 'le-tissu-nerveux-et-ses-proprietes', 'Le tissu nerveux et ses propriétés', 'Neurone et nerf, excitabilité, potentiels de repos et d’action, conduction, synapse.', 2, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes'), 1, 'structure-du-tissu-nerveux', 'Structure du tissu nerveux', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes') and slug = 'structure-du-tissu-nerveux'), $html$<p>L’unité du tissu nerveux est le <strong>neurone</strong>, cellule formée d’un corps cellulaire (avec le noyau), de prolongements courts et ramifiés, les <strong>dendrites</strong>, et d’un prolongement long, l’<strong>axone</strong>, terminé par des arborisations.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes'), 2, 'proprietes-du-tissu-nerveux', 'Propriétés du tissu nerveux', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes') and slug = 'proprietes-du-tissu-nerveux'), $html$<p>Le tissu nerveux a deux propriétés : l’<strong>excitabilité</strong> (capacité à réagir à un stimulus en produisant un message nerveux, l’influx) et la <strong>conductibilité</strong> (capacité à propager ce message).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes'), 3, 'phenomenes-electriques-lies-a-l-influx-nerveux', 'Phénomènes électriques liés à l’influx nerveux', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes') and slug = 'phenomenes-electriques-lies-a-l-influx-nerveux'), $html$<p>Avec une microélectrode implantée dans l’axone et une autre à la surface, un oscilloscope révèle une différence de potentiel.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes'), 4, 'conduction-de-l-influx-nerveux', 'Conduction de l’influx nerveux', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes') and slug = 'conduction-de-l-influx-nerveux'), $html$<p>Le potentiel d’action créé en un point dépolarise la zone voisine, qui produit à son tour un potentiel d’action : l’influx se propage sans s’affaiblir, dans un seul sens (la zone qui vient d’être active est réfractaire).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes'), 5, 'la-transmission-synaptique', 'La transmission synaptique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-tissu-nerveux-et-ses-proprietes') and slug = 'la-transmission-synaptique'), $html$<p>Une <strong>synapse</strong> est la zone de contact entre deux neurones, ou entre un neurone et une cellule effectrice (la plaque motrice, avec un muscle). Elle comprend un élément présynaptique, une fente synaptique et un élément postsynaptique.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 3, 'activite-du-muscle-strie-squelettique', 'Activité du muscle strié squelettique', 'Structure du muscle, unité motrice, contraction, énergie et chaleur.', 3, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-du-muscle-strie-squelettique'), 1, 'structure-du-muscle-strie-squelettique', 'Structure du muscle strié squelettique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-du-muscle-strie-squelettique') and slug = 'structure-du-muscle-strie-squelettique'), $html$<p>Un muscle squelettique est formé de faisceaux de <strong>fibres musculaires</strong> : ce sont de très longues cellules à plusieurs noyaux.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-du-muscle-strie-squelettique'), 2, 'fonctionnement-du-muscle-squelettique', 'Fonctionnement du muscle squelettique', false, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-du-muscle-strie-squelettique') and slug = 'fonctionnement-du-muscle-squelettique'), $html$<h2>Phénomènes mécaniques</h2>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 4, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', 'Automatisme cardiaque, cycle cardiaque, régulation nerveuse et hormonale de la pression artérielle.', 4, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 1, 'l-automatisme-cardiaque', 'L’automatisme cardiaque', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'l-automatisme-cardiaque'), $html$<p>Un cœur isolé et irrigué continue à battre : il est <strong>automatique</strong>. Cette activité naît dans le <strong>tissu nodal</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 2, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), $html$<p>La <strong>pression artérielle</strong> est la pression du sang dans les artères. Elle varie entre une valeur maximale (systolique, environ 12 cmHg) et minimale (diastolique, environ 8 cmHg). Elle dépend du débit cardiaque et de la résistance des vaisseaux.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 5, 'regulation-de-la-glycemie', 'Régulation de la glycémie', 'Insuline et glucagon, rôle du foie, diabète.', 5, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'regulation-de-la-glycemie'), 1, 'regulation-de-la-glycemie', 'Régulation de la glycémie', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'regulation-de-la-glycemie') and slug = 'regulation-de-la-glycemie'), $html$<p>La <strong>glycémie</strong> est le taux de glucose dans le sang : environ 1 g/L à jeun (0,8 à 1,2 g/L). Le glucose est la principale source d’énergie des cellules.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 6, 'immunologie', 'Immunologie', 'Soi et non-soi, réponses immunitaires, VIH-sida.', 6, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'immunologie'), 1, 'le-systeme-immunitaire', 'Le système immunitaire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'immunologie') and slug = 'le-systeme-immunitaire'), $html$<p>Le système immunitaire distingue le <strong>soi</strong> (ce qui appartient à l’organisme, marqué par les molécules du CMH à la surface des cellules) du <strong>non-soi</strong> (microbes, cellules étrangères, cellules anormales). Une molécule reconnue comme étrangère est un <strong>antigène</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'immunologie'), 2, 'la-reponse-immunitaire', 'La réponse immunitaire', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'immunologie') and slug = 'la-reponse-immunitaire'), $html$<h2>Réponse non spécifique (immédiate)</h2>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'immunologie'), 3, 'le-vih-et-le-sida', 'Le VIH et le sida', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'immunologie') and slug = 'le-vih-et-le-sida'), $html$<p>Le <strong>VIH</strong> (virus de l’immunodéficience humaine) est un rétrovirus qui infecte surtout les <strong>lymphocytes T4</strong>, chefs d’orchestre de la réponse immunitaire.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 7, 'reproduction-chez-les-mammiferes', 'Reproduction chez les mammifères', 'Gamétogenèse, fécondation et régulation hormonale des appareils reproducteurs.', 7, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
