insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'appareils-reproducteurs-et-gametogenese'), $html$<p>Les <strong>gonades</strong> (testicules, ovaires) produisent les gamètes et des hormones sexuelles.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reproduction-chez-les-mammiferes'), 2, 'fecondation-et-problemes-lies-a-la-fecondation', 'Fécondation et problèmes liés à la fécondation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'fecondation-et-problemes-lies-a-la-fecondation'), $html$<p>La <strong>fécondation</strong> a lieu dans le tiers supérieur de la trompe : un seul spermatozoïde traverse la zone pellucide grâce aux enzymes de son acrosome, puis son noyau fusionne avec celui de l’ovocyte. La cellule-œuf (2n = 46) est formée.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reproduction-chez-les-mammiferes'), 3, 'regulation-hormonale-des-appareils-reproducteurs', 'Régulation hormonale des appareils reproducteurs', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'regulation-hormonale-des-appareils-reproducteurs'), $html$<p>L’<strong>hypothalamus</strong> sécrète la GnRH, qui stimule l’<strong>hypophyse</strong>. Celle-ci libère deux hormones, FSH et LH, qui agissent sur les gonades.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 8, 'genetique', 'Génétique', 'Lois de Mendel, monohybridisme, dihybridisme, gènes liés et crossing-over.', 8, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'genetique'), 1, 'lois-statistiques-de-la-transmission-des-caracteres', 'Lois statistiques de la transmission des caractères', true, 'published', 20, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'genetique') and slug = 'lois-statistiques-de-la-transmission-des-caracteres'), $html$<p>Un <strong>gène</strong> occupe un locus sur un chromosome ; ses différentes versions sont les <strong>allèles</strong>. Un individu diploïde possède deux allèles de chaque gène : homozygote s’ils sont identiques, hétérozygote sinon. Un allèle <strong>dominant</strong> s’exprime chez l’hétérozygote, un allèle <strong>récessif</strong> non.</p>
