insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'heredite-humaine') and slug = 'l-heredite-chez-l-espece-humaine'), $html$<p>On étudie la transmission des caractères humains à l’aide d’<strong>arbres généalogiques</strong> (carrés pour les hommes, ronds pour les femmes, symboles pleins pour les atteints).</p>
