insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'nature-et-culture') and slug = 'l-inne-l-acquis-et-le-fait-culturel'), $html$<p>La <strong>nature</strong> désigne ce qui est donné à la naissance (l’inné) ; la <strong>culture</strong>, ce que l’homme acquiert et transmet par l’éducation : langage, techniques, croyances, règles.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'nature-et-culture'), 2, 'le-travail', 'Le travail', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'nature-et-culture') and slug = 'le-travail'), $html$<p>Le <strong>travail</strong> est l’activité par laquelle l’homme transforme la nature pour satisfaire ses besoins.</p>
