insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-differents-types-de-sciences') and slug = 'le-probleme-de-la-verite'), $html$<table><thead><tr><th scope="col">Conception de la vérité</th><th scope="col">Critère</th></tr></thead><tbody><tr><td>vérité-correspondance</td><td>une idée est vraie si elle est conforme à la réalité</td></tr><tr><td>vérité-cohérence</td><td>un énoncé est vrai s’il ne contredit pas le système dont il fait partie (mathématiques)</td></tr><tr><td>vérité-évidence (Descartes)</td><td>est vrai ce que je conçois clairement et distinctement</td></tr><tr><td>pragmatisme</td><td>est vrai ce qui réussit, ce qui est utile</td></tr></tbody></table>
