insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-representation-artistique') and slug = 'art-realite-et-creation-artistique'), $html$<table><thead><tr><th scope="col">Thèse</th><th scope="col">Idée</th></tr></thead><tbody><tr><td>l’art imite la nature (Platon)</td><td>l’œuvre est une copie de copie, éloignée de la vérité</td></tr><tr><td>l’art révèle la réalité</td><td>il montre ce que nous ne voyons pas (Bergson : l’artiste écarte le voile de l’habitude)</td></tr><tr><td>l’art crée une autre réalité</td><td>l’art abstrait ne représente rien d’existant</td></tr></tbody></table>
