insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'decolonisation-et-affirmation-du-tiers-monde'), 1, 'les-causes-generales-de-la-decolonisation', 'Les causes générales de la décolonisation', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'decolonisation-et-affirmation-du-tiers-monde') and slug = 'les-causes-generales-de-la-decolonisation'), $html$<table><thead><tr><th scope="col">Causes</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>internes aux colonies</td><td>mouvements nationalistes, élites formées à l’école occidentale, syndicats, partis politiques</td></tr><tr><td>liées à la guerre</td><td>défaites des métropoles (France en 1940), participation des colonisés à la guerre, promesses (conférence de Brazzaville, 1944)</td></tr><tr><td>internationales</td><td>Charte de l’Atlantique (1941) et Charte de l’ONU (droit des peuples à disposer d’eux-mêmes) ; États-Unis et URSS hostiles au colonialisme</td></tr><tr><td>idéologiques</td><td>panafricanisme, négritude, marxisme</td></tr></tbody></table>
