insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique'), 1, 'l-algerie-une-decolonisation-par-la-guerre', 'L’Algérie : une décolonisation par la guerre', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique') and slug = 'l-algerie-une-decolonisation-par-la-guerre'), $html$<ul><li>l’Algérie compte environ un million de colons européens ; les « Algériens musulmans » n’ont pas l’égalité des droits ;</li><li>8 mai 1945 : la répression des manifestations de Sétif et Guelma fait des milliers de morts ;</li><li>1<sup>er</sup> novembre 1954 : le FLN déclenche l’insurrection (« Toussaint rouge ») ;</li><li>guerre très violente (torture, attentats), crise politique en France et retour du général de Gaulle (1958) ;</li><li>accords d’Évian (18 mars 1962), puis indépendance le 5 juillet 1962.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique'), 2, 'la-gold-coast-premiere-colonie-d-afrique-noire-independante', 'La Gold Coast, première colonie d’Afrique noire indépendante', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique') and slug = 'la-gold-coast-premiere-colonie-d-afrique-noire-independante'), $html$<ul><li>colonie britannique riche en cacao et en or, avec une élite instruite ;</li><li>Kwame Nkrumah fonde le Convention People’s Party (1949) et lance l’« action positive » (grèves, boycotts) ;</li><li>le Royaume-Uni accorde l’autonomie, puis l’indépendance le 6 mars 1957 : la Gold Coast devient le <strong>Ghana</strong>.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique'), 3, 'le-senegal-de-l-union-francaise-a-l-independance', 'Le Sénégal : de l’Union française à l’indépendance', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique') and slug = 'le-senegal-de-l-union-francaise-a-l-independance'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Étape</th></tr></thead><tbody><tr><td>1944</td><td>conférence de Brazzaville : promesse de réformes, mais pas d’indépendance ; massacre de tirailleurs à Thiaroye (1<sup>er</sup> décembre)</td></tr><tr><td>1946</td><td>loi Lamine Guèye : citoyenneté française pour les habitants des colonies ; abolition du travail forcé (loi Houphouët-Boigny)</td></tr><tr><td>1948</td><td>Senghor fonde le Bloc démocratique sénégalais (BDS)</td></tr><tr><td>1956</td><td>loi-cadre Defferre : suffrage universel, conseils de gouvernement</td></tr><tr><td>1958</td><td>référendum du 28 septembre : le Sénégal vote « oui » à la Communauté française</td></tr><tr><td>1959</td><td>Fédération du Mali avec le Soudan français</td></tr><tr><td>1960</td><td>indépendance de la Fédération (20 juin), éclatement (20 août) ; Senghor président de la République (septembre)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique'), 4, 'guinee-bissau-et-angola-les-luttes-armees', 'Guinée-Bissau et Angola : les luttes armées', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-decolonisation-en-afrique') and slug = 'guinee-bissau-et-angola-les-luttes-armees'), $html$<p>Le Portugal refuse toute décolonisation : les mouvements de libération prennent les armes.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 5, 'les-civilisations-negro-africaines', 'Les civilisations négro-africaines', 'Concept de civilisation, cadre, organisation des sociétés, religions traditionnelles, évolution.', 5, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines'), 1, 'le-concept-de-civilisation', 'Le concept de civilisation', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines') and slug = 'le-concept-de-civilisation'), $html$<p>Une <strong>civilisation</strong> est l’ensemble des caractères communs (techniques, institutions, croyances, arts, valeurs) d’une société ou d’un groupe de sociétés, sur une longue durée.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines'), 2, 'cadre-geographique-et-organisation-des-societes-negro-africaines', 'Cadre géographique et organisation des sociétés négro-africaines', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines') and slug = 'cadre-geographique-et-organisation-des-societes-negro-africaines'), $html$<p>Les civilisations négro-africaines se sont développées au sud du Sahara, dans des milieux variés (savanes, forêts, sahel), avec une histoire ancienne (Nubie, empires du Ghana, du Mali, du Songhaï, royaumes du golfe de Guinée).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines'), 3, 'les-religions-traditionnelles-africaines', 'Les religions traditionnelles africaines', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines') and slug = 'les-religions-traditionnelles-africaines'), $html$<ul><li>croyance en un Dieu suprême créateur, souvent lointain (Roog chez les Sereer) ;</li><li>culte des ancêtres, intermédiaires entre les vivants et le monde invisible ;</li><li>génies et esprits liés à la nature (eau, arbres, terre) ;</li><li>rites d’initiation, sacrifices, cérémonies de guérison (ndëpp chez les Lébous).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines'), 4, 'l-evolution-du-monde-negro-africain', 'L’évolution du monde négro-africain', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'les-civilisations-negro-africaines') and slug = 'l-evolution-du-monde-negro-africain'), $html$<table><thead><tr><th scope="col">Influence</th><th scope="col">Exemples au Sénégal</th></tr></thead><tbody><tr><td>islam</td><td>islamisation ancienne (Tekrour, XI<sup>e</sup> siècle) ; confréries : Qadiriyya, Tidjaniyya (El Hadji Malick Sy), Mouridiyya (Cheikh Ahmadou Bamba, Touba), Layène (Seydina Limamou Laye)</td></tr><tr><td>christianisme</td><td>missions catholiques et protestantes, écoles ; pèlerinage marial de Popenguine</td></tr><tr><td>colonisation et décolonisation</td><td>école française, villes, économie de traite ; après 1960, construction de l’État-nation</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 6, 'la-civilisation-musulmane', 'La civilisation musulmane', 'Naissance de l’islam, Coran et piliers, expansion, culture, unité et diversité du monde musulman.', 6, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane'), 1, 'la-naissance-de-l-islam', 'La naissance de l’islam', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane') and slug = 'la-naissance-de-l-islam'), $html$<ul><li>l’Arabie préislamique : tribus nomades et sédentaires, commerce caravanier, La Mecque et sa Kaaba, majoritairement polythéiste ;</li><li>Muhammad (Mahomet), né vers 570 à La Mecque, reçoit la révélation vers 610 ;</li><li>persécuté, il émigre à Médine en 622 : c’est l’<strong>hégire</strong>, point de départ du calendrier musulman ;</li><li>il revient à La Mecque en 630 ; à sa mort (632), l’Arabie est unifiée autour de l’islam.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane'), 2, 'le-coran-et-les-fondements-de-l-islam', 'Le Coran et les fondements de l’islam', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane') and slug = 'le-coran-et-les-fondements-de-l-islam'), $html$<p>Le <strong>Coran</strong> (114 sourates) est, pour les musulmans, la parole de Dieu révélée au Prophète. La <strong>Sunna</strong> (tradition du Prophète, rapportée par les hadiths) le complète.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane'), 3, 'la-constitution-du-monde-musulman', 'La constitution du monde musulman', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane') and slug = 'la-constitution-du-monde-musulman'), $html$<table><thead><tr><th scope="col">Période</th><th scope="col">Faits essentiels</th></tr></thead><tbody><tr><td>632-661</td><td>califes « bien guidés » (Abou Bakr, Omar, Othman, Ali) : conquête de la Syrie, de l’Égypte, de la Perse</td></tr><tr><td>661-750</td><td>Omeyyades (capitale Damas) : expansion de l’Espagne à l’Indus</td></tr><tr><td>750-1258</td><td>Abbassides (capitale Bagdad) : apogée culturel ; puis morcellement du monde musulman</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane'), 4, 'la-culture-musulmane', 'La culture musulmane', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane') and slug = 'la-culture-musulmane'), $html$<table><thead><tr><th scope="col">Domaine</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>sciences</td><td>al-Khwarizmi (algèbre), chiffres dits « arabes » venus de l’Inde, astronomie, médecine d’Avicenne (Ibn Sina)</td></tr><tr><td>philosophie et histoire</td><td>Averroès (Ibn Rushd), commentateur d’Aristote ; Ibn Khaldoun, penseur de l’histoire</td></tr><tr><td>arts</td><td>architecture des mosquées (Kairouan, Cordoue), calligraphie, arabesques</td></tr><tr><td>en Afrique de l’Ouest</td><td>Tombouctou et ses manuscrits, Djenné</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane'), 5, 'unite-et-diversite-du-monde-musulman', 'Unité et diversité du monde musulman', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'la-civilisation-musulmane') and slug = 'unite-et-diversite-du-monde-musulman'), $html$<table><thead><tr><th scope="col">Tendances historiques</th><th scope="col"></th></tr></thead><tbody><tr><td>sunnites</td><td>majoritaires ; suivent la Sunna et les califes successifs</td></tr><tr><td>chiites</td><td>partisans d’Ali et de ses descendants (Iran, Irak)</td></tr><tr><td>kharijites</td><td>« ceux qui sont sortis », minoritaires (ibadites d’Oman)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 7, 'le-systeme-monde-des-espaces-interdependants', 'Le système-monde : des espaces interdépendants', 'Mondialisation, grands pôles et espaces-blocs, interdépendance et inégalités.', 7, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-systeme-monde-des-espaces-interdependants'), 1, 'le-systeme-monde', 'Le système-monde', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'le-systeme-monde-des-espaces-interdependants') and slug = 'le-systeme-monde'), $html$<p>La <strong>mondialisation</strong> est la mise en relation des différentes parties du monde par les échanges de marchandises, de capitaux, d’informations et de personnes. Elle forme un <strong>système-monde</strong> où tout est lié.</p>
