insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain'), 1, 'atouts-et-handicaps-de-la-nature', 'Atouts et handicaps de la nature', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain') and slug = 'atouts-et-handicaps-de-la-nature'), $html$<table><thead><tr><th scope="col">Atouts</th><th scope="col">Handicaps</th></tr></thead><tbody><tr><td>immensité (plus de 21 millions de km² pour les États-Unis, le Canada et le Mexique)</td><td>froid du Grand Nord canadien, déserts de l’Ouest</td></tr><tr><td>grandes plaines fertiles du centre</td><td>catastrophes naturelles : ouragans, tornades, séismes (Californie)</td></tr><tr><td>ressources minières et énergétiques abondantes (pétrole, gaz, charbon, fer)</td><td>sécheresses et incendies</td></tr><tr><td>fleuves navigables (Mississippi, Saint-Laurent), Grands Lacs, deux façades maritimes</td><td></td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain'), 2, 'populations-villes-et-societes', 'Populations, villes et sociétés', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain') and slug = 'populations-villes-et-societes'), $html$<ul><li>une population formée par l’immigration : peuples autochtones, Européens, Africains déportés par la traite, Latino-Américains, Asiatiques ;</li><li>États-Unis : environ 335 millions d’habitants ; Canada : environ 40 millions ; Mexique : environ 130 millions ;</li><li>une population très urbanisée : mégalopoles (Boston-Washington, Grands Lacs), métropoles du Sud et de l’Ouest (Sun Belt) ;</li><li>des problèmes sociaux : inégalités, ghettos, discriminations raciales, immigration clandestine à la frontière mexicaine.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain'), 3, 'la-construction-de-l-espace-economique-nord-americain', 'La construction de l’espace économique nord-américain', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain') and slug = 'la-construction-de-l-espace-economique-nord-americain'), $html$<p>L’ALENA (1994), remplacé par l’ACEUM (2020), a créé une zone de libre-échange entre les États-Unis, le Canada et le Mexique.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain'), 4, 'le-modele-economique-americain', 'Le modèle économique américain', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-nord-americain') and slug = 'le-modele-economique-americain'), $html$<table><thead><tr><th scope="col">Caractéristiques</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>libéralisme et esprit d’entreprise</td><td>rôle des grandes firmes, du marché et de l’innovation</td></tr><tr><td>première puissance économique mondiale</td><td>environ un quart de la richesse mondiale</td></tr><tr><td>agriculture productiviste</td><td>grandes exploitations mécanisées, agrobusiness, premier exportateur agricole</td></tr><tr><td>industrie et services de pointe</td><td>aéronautique, informatique (Silicon Valley), finance (Wall Street)</td></tr><tr><td>puissance mondiale</td><td>dollar, armée, culture (cinéma, Internet)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 9, 'l-espace-europeen', 'L’espace européen', 'Milieux et populations, construction européenne, la France ou l’Allemagne.', 9, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-europeen'), 1, 'milieux-naturels-et-populations', 'Milieux naturels et populations', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-europeen') and slug = 'milieux-naturels-et-populations'), $html$<ul><li>milieux tempérés majoritaires, avec des nuances océaniques, continentales, méditerranéennes, montagnardes ;</li><li>un relief varié (plaines du Nord, Alpes) et des littoraux très découpés ;</li><li>une population nombreuse (environ 450 millions dans l’UE), vieillissante, avec une faible fécondité ;</li><li>l’Europe est devenue une terre d’immigration, notamment africaine : la question migratoire est un enjeu politique majeur.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-europeen'), 2, 'la-construction-europeenne-realites-et-perspectives', 'La construction européenne : réalités et perspectives', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-europeen') and slug = 'la-construction-europeenne-realites-et-perspectives'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Étape</th></tr></thead><tbody><tr><td>1951</td><td>CECA (charbon et acier) entre six pays</td></tr><tr><td>1957</td><td>traité de Rome : Communauté économique européenne (marché commun)</td></tr><tr><td>1992</td><td>traité de Maastricht : Union européenne</td></tr><tr><td>1999-2002</td><td>l’euro, monnaie unique</td></tr><tr><td>2004-2013</td><td>élargissements à l’Est</td></tr><tr><td>2020</td><td>sortie du Royaume-Uni (Brexit) : l’UE compte 27 membres</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-europeen'), 3, 'la-france-et-l-allemagne-deux-puissances-de-l-union-europeenne', 'La France et l’Allemagne : deux puissances de l’Union européenne', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-espace-europeen') and slug = 'la-france-et-l-allemagne-deux-puissances-de-l-union-europeenne'), $html$<table><thead><tr><th scope="col"></th><th scope="col">France</th><th scope="col">Allemagne</th></tr></thead><tbody><tr><td>population</td><td>environ 68 millions</td><td>environ 84 millions, la plus peuplée de l’UE</td></tr><tr><td>points forts</td><td>agriculture (premier producteur de l’UE), aéronautique, nucléaire, tourisme, luxe</td><td>industrie (automobile, machines, chimie), premier exportateur de l’UE</td></tr><tr><td>faiblesses</td><td>chômage, dette publique</td><td>vieillissement, dépendance énergétique</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 10, 'l-asie-pacifique', 'L’Asie-Pacifique', 'Facteurs d’émergence, le modèle japonais, la Chine : démographie et développement.', 10, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique'), 1, 'les-facteurs-d-emergence-de-l-asie-pacifique-et-leurs-limites', 'Les facteurs d’émergence de l’Asie-Pacifique et leurs limites', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique') and slug = 'les-facteurs-d-emergence-de-l-asie-pacifique-et-leurs-limites'), $html$<ul><li>une main-d’œuvre nombreuse, disciplinée et longtemps bon marché ;</li><li>des États interventionnistes et une stratégie d’industrialisation tournée vers l’exportation ;</li><li>un « effet de vol d’oies sauvages » : le Japon, puis les « dragons » (Corée du Sud, Taïwan, Hong Kong, Singapour), puis les « tigres » et la Chine ;</li><li>l’épargne élevée, l’éducation, les investissements étrangers.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique'), 2, 'le-modele-economique-japonais', 'Le modèle économique japonais', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique') and slug = 'le-modele-economique-japonais'), $html$<ul><li>un archipel montagneux, pauvre en ressources et exposé aux séismes et tsunamis ;</li><li>après 1945, le « miracle japonais » : forte croissance grâce à l’État (MITI), aux grands groupes (keiretsu), au travail et à l’innovation ;</li><li>points forts : automobile (Toyota), électronique, robotique ;</li><li>une population concentrée sur le littoral (mégalopole de Tokyo à Osaka).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique'), 3, 'la-chine-les-problemes-demographiques', 'La Chine : les problèmes démographiques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique') and slug = 'la-chine-les-problemes-demographiques'), $html$<ul><li>environ 1,4 milliard d’habitants ; l’Inde l’a dépassée en 2023 ;</li><li>la politique de l’enfant unique (1979-2015) a freiné la croissance mais provoqué un vieillissement rapide et un déséquilibre entre garçons et filles ;</li><li>la Chine autorise deux enfants (2016), puis trois (2021) ;</li><li>fort exode rural vers les villes de l’Est : les « mingong » (travailleurs migrants).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique'), 4, 'la-chine-le-modele-de-developpement', 'La Chine : le modèle de développement', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-asie-pacifique') and slug = 'la-chine-le-modele-de-developpement'), $html$<ul><li>depuis 1978, une « économie socialiste de marché » : ouverture, zones économiques spéciales, investissements étrangers ;</li><li>deuxième économie du monde, « atelier du monde », premier exportateur ;</li><li>investissements en Afrique (au Sénégal : Grand Théâtre, Musée des civilisations noires, autoroute Ila Touba) et « nouvelles routes de la soie » ;</li><li>montée en gamme : téléphonie, voitures électriques, espace.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')), 11, 'l-amerique-latine', 'L’Amérique latine', 'Milieux et populations, le Brésil, puissance émergente.', 11, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-amerique-latine'), 1, 'milieux-naturels-et-populations', 'Milieux naturels et populations', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-amerique-latine') and slug = 'milieux-naturels-et-populations'), $html$<ul><li>des milieux très variés : cordillère des Andes, forêt amazonienne, pampa, déserts (Atacama) ;</li><li>une population métissée (Amérindiens, Européens, descendants d’Africains) et très urbanisée ;</li><li>de grandes métropoles (Mexico, São Paulo, Buenos Aires) entourées de quartiers pauvres (favelas, bidonvilles) ;</li><li>des inégalités sociales parmi les plus fortes du monde.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-amerique-latine'), 2, 'le-bresil-une-puissance-du-tiers-monde', 'Le Brésil, une puissance du tiers-monde', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S1')) and c.slug = 'l-amerique-latine') and slug = 'le-bresil-une-puissance-du-tiers-monde'), $html$<table><thead><tr><th scope="col">Atouts</th><th scope="col">Problèmes</th></tr></thead><tbody><tr><td>territoire immense (8,5 millions de km²), environ 203 millions d’habitants</td><td>inégalités sociales et régionales (Sud-Est riche, Nordeste pauvre)</td></tr><tr><td>agriculture d’exportation : soja, café, sucre, viande</td><td>déforestation de l’Amazonie</td></tr><tr><td>industrie (aéronautique, automobile), pétrole offshore</td><td>violence urbaine, favelas</td></tr><tr><td>membre des BRICS</td><td>instabilité politique et économique</td></tr></tbody></table>
