insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'derivees-et-primitives'), 2, 'derivees-successives-et-points-d-inflexion', 'Dérivées successives et points d’inflexion', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'derivees-et-primitives') and slug = 'derivees-successives-et-points-d-inflexion'), $html$<p>Si f’ est elle-même dérivable, sa dérivée est la <strong>dérivée seconde</strong> f’’ (notée aussi <span class="frac"><span>d²f</span><span>dx²</span></span> en physique), et ainsi de suite : f<sup>(n)</sup> est la dérivée n-ième.</p>
