insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nombres-complexes-et-similitudes') and slug = 'similitudes-planes-directes'), $html$<p>Une <strong>similitude directe</strong> est une transformation du plan dont l’écriture complexe est z’ = az + b, avec a ≠ 0. Elle multiplie les distances par k = |a| et conserve les angles orientés.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 1, 'cinematique-du-point', 'Cinématique du point', 'Vecteurs position, vitesse et accélération ; mouvements rectilignes et circulaires.', 1, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'cinematique-du-point'), 1, 'position-vitesse-et-acceleration', 'Position, vitesse et accélération', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'cinematique-du-point') and slug = 'position-vitesse-et-acceleration'), $html$<p>Dans un repère lié au référentiel d’étude, la position d’un point mobile M est donnée par le <strong>vecteur position</strong> OM⃗(t) = x(t) i⃗ + y(t) j⃗ + z(t) k⃗.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'cinematique-du-point'), 2, 'mouvements-rectilignes', 'Mouvements rectilignes', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'cinematique-du-point') and slug = 'mouvements-rectilignes'), $html$<table><thead><tr><th scope="col">Mouvement</th><th scope="col">Accélération</th><th scope="col">Équations horaires</th></tr></thead><tbody><tr><td>rectiligne uniforme</td><td>a = 0</td><td>x = v t + x₀</td></tr><tr><td>rectiligne uniformément varié</td><td>a constante</td><td>v = a t + v₀ ; x = ½ a t² + v₀ t + x₀</td></tr><tr><td>rectiligne sinusoïdal</td><td>a = −ω² x</td><td>x = X<sub>m</sub> cos(ωt + φ)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'cinematique-du-point'), 3, 'mouvements-circulaires', 'Mouvements circulaires', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'cinematique-du-point') and slug = 'mouvements-circulaires'), $html$<p>Sur un cercle de rayon R, on repère M par son abscisse angulaire θ(t). La vitesse angulaire est ω = <span class="frac"><span>dθ</span><span>dt</span></span> (rad/s) et la vitesse v = Rω.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 2, 'bases-de-la-dynamique', 'Bases de la dynamique', 'Référentiels galiléens, lois de Newton, quantité de mouvement et chocs.', 2, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'bases-de-la-dynamique'), 1, 'quantite-de-mouvement-et-referentiels-galileens', 'Quantité de mouvement et référentiels galiléens', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'bases-de-la-dynamique') and slug = 'quantite-de-mouvement-et-referentiels-galileens'), $html$<p>Le <strong>centre d’inertie</strong> G d’un solide est le point dont le mouvement est le plus simple. La <strong>quantité de mouvement</strong> d’un système de masse m est p⃗ = mv<sub>G</sub>⃗ (kg·m/s).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'bases-de-la-dynamique'), 2, 'relation-fondamentale-de-la-dynamique', 'Relation fondamentale de la dynamique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'bases-de-la-dynamique') and slug = 'relation-fondamentale-de-la-dynamique'), $html$<p class="formula">Dans un référentiel galiléen : ΣF<sub>ext</sub>⃗ = <span class="frac"><span>dp⃗</span><span>dt</span></span> = ma<sub>G</sub>⃗</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 3, 'applications-des-bases-de-la-dynamique', 'Applications des bases de la dynamique', 'Chute libre, projectiles, chute dans un fluide, mouvements circulaires, particule dans un champ électrique.', 3, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique'), 1, 'chute-libre-et-plan-incline', 'Chute libre et plan incliné', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'chute-libre-et-plan-incline'), $html$<p>Un corps en <strong>chute libre</strong> n’est soumis qu’à son poids : la relation fondamentale donne a⃗ = g⃗ (g ≈ 9,8 m/s²), quelle que soit sa masse.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique'), 2, 'mouvement-d-un-projectile', 'Mouvement d’un projectile', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'mouvement-d-un-projectile'), $html$<p>Un projectile est lancé de O avec une vitesse v₀ faisant un angle α avec l’horizontale. On néglige l’air : a⃗ = g⃗.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique'), 3, 'chute-verticale-dans-un-fluide', 'Chute verticale dans un fluide', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'chute-verticale-dans-un-fluide'), $html$<p>Dans un fluide, un corps est soumis à son poids P⃗, à la <strong>poussée d’Archimède</strong> (verticale, vers le haut, égale au poids du fluide déplacé : ρ<sub>fluide</sub> V g) et à une force de frottement opposée à la vitesse, souvent modélisée par f = kv.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique'), 4, 'mouvements-circulaires-pendule-conique-virage-fronde', 'Mouvements circulaires : pendule conique, virage, fronde', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'mouvements-circulaires-pendule-conique-virage-fronde'), $html$<p>Pour un mouvement circulaire uniforme de rayon R, la somme des forces est <strong>centripète</strong> et vaut m<span class="frac"><span>v²</span><span>R</span></span>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique'), 5, 'particule-chargee-dans-un-champ-electrique-uniforme', 'Particule chargée dans un champ électrique uniforme', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'particule-chargee-dans-un-champ-electrique-uniforme'), $html$<p>Entre deux plaques parallèles distantes de d et soumises à la tension U, le champ est uniforme : E = <span class="frac"><span>U</span><span>d</span></span> (V/m). Une particule de charge q et de masse m subit F⃗ = qE⃗ ; son poids est négligeable.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 4, 'gravitation-universelle', 'Gravitation universelle', 'Loi de Newton, champ de gravitation, mouvement des satellites et lois de Kepler.', 4, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'gravitation-universelle'), 1, 'loi-de-la-gravitation-et-champ-de-gravitation', 'Loi de la gravitation et champ de gravitation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'gravitation-universelle') and slug = 'loi-de-la-gravitation-et-champ-de-gravitation'), $html$<p class="formula">F = G <span class="frac"><span>m m’</span><span>d²</span></span>, avec G = 6,67 × 10<sup>−11</sup> N·m²/kg²</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'gravitation-universelle'), 2, 'mouvement-des-satellites', 'Mouvement des satellites', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'gravitation-universelle') and slug = 'mouvement-des-satellites'), $html$<p>Dans le référentiel géocentrique, un satellite en orbite circulaire de rayon r = R + h n’est soumis qu’à la gravitation. La relation fondamentale donne un mouvement <strong>circulaire uniforme</strong> :</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 5, 'champs-magnetiques', 'Champs magnétiques', 'Aimants, lignes de champ, champ terrestre, champs créés par un courant (fil, solénoïde).', 5, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'champs-magnetiques'), 1, 'generalites-sur-le-champ-magnetique', 'Généralités sur le champ magnétique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'champs-magnetiques') and slug = 'generalites-sur-le-champ-magnetique'), $html$<p>Un aimant ou un courant crée un <strong>champ magnétique</strong> B⃗ dans l’espace qui l’entoure. On le détecte avec une aiguille aimantée, qui s’oriente selon B⃗ (du pôle sud vers le pôle nord de l’aiguille).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'champs-magnetiques'), 2, 'champs-magnetiques-crees-par-des-courants', 'Champs magnétiques créés par des courants', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'champs-magnetiques') and slug = 'champs-magnetiques-crees-par-des-courants'), $html$<p>Le sens de B⃗ se trouve avec la règle de la main droite (ou du bonhomme d’Ampère : le courant entre par ses pieds et sort par sa tête, il regarde le point considéré ; B⃗ est dirigé vers sa gauche).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 6, 'particule-chargee-dans-un-champ-magnetique-uniforme', 'Particule chargée dans un champ magnétique uniforme', 'Force de Lorentz, mouvement circulaire uniforme, spectrographe de masse et cyclotron.', 6, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
