insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'loi-de-laplace') and slug = 'applications-de-la-loi-de-laplace'), $html$<ul><li><strong>rails de Laplace</strong> : une tige posée sur deux rails alimentés se met à rouler ;</li><li><strong>moteur électrique à courant continu</strong> : des forces de Laplace sur les côtés d’une bobine créent un couple qui la fait tourner ;</li><li><strong>haut-parleur</strong> : une bobine dans le champ d’un aimant fait vibrer la membrane au rythme du courant ;</li><li><strong>roue de Barlow</strong> : une roue conductrice tourne entre les pôles d’un aimant.</li></ul>
