insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'reactions-nucleaires'), 1, 'le-noyau-et-l-energie-de-liaison', 'Le noyau et l’énergie de liaison', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'reactions-nucleaires') and slug = 'le-noyau-et-l-energie-de-liaison'), $html$<p>Un noyau <sup>A</sup><sub>Z</sub>X contient Z protons et N = A − Z neutrons (les nucléons). Des <strong>isotopes</strong> ont le même Z et des A différents.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'reactions-nucleaires'), 2, 'radioactivite-et-decroissance', 'Radioactivité et décroissance', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'reactions-nucleaires') and slug = 'radioactivite-et-decroissance'), $html$<table><thead><tr><th scope="col">Type</th><th scope="col">Particule émise</th><th scope="col">Équation</th></tr></thead><tbody><tr><td>α</td><td>noyau d’hélium</td><td><sup>A</sup><sub>Z</sub>X → <sup>A−4</sup><sub>Z−2</sub>Y + <sup>4</sup><sub>2</sub>He</td></tr><tr><td>β⁻</td><td>électron</td><td>un neutron devient un proton : Z augmente de 1</td></tr><tr><td>β⁺</td><td>positon</td><td>un proton devient un neutron : Z diminue de 1</td></tr><tr><td>γ</td><td>photon</td><td>désexcitation du noyau fils</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'reactions-nucleaires'), 3, 'fission-fusion-et-applications', 'Fission, fusion et applications', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'reactions-nucleaires') and slug = 'fission-fusion-et-applications'), $html$<ul><li><strong>Fission</strong> : un noyau lourd (uranium 235) frappé par un neutron se casse en deux noyaux plus légers et libère 2 ou 3 neutrons : réaction en chaîne, contrôlée dans les centrales nucléaires ;</li><li><strong>Fusion</strong> : deux noyaux légers (isotopes de l’hydrogène) s’unissent ; c’est la source d’énergie du Soleil.</li></ul>
