insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'les-alcools') and slug = 'structure-nomenclature-et-classes-des-alcools'), $html$<p>Un <strong>alcool</strong> possède un groupe hydroxyle −OH lié à un carbone tétragonal. Formule générale des alcools saturés : C<sub>n</sub>H<sub>2n+1</sub>OH. Le nom se forme en remplaçant le « e » final de l’alcane par « ol », avec l’indice du carbone fonctionnel le plus petit possible.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'les-alcools'), 2, 'oxydation-menagee-et-identification', 'Oxydation ménagée et identification', true, 'published', 15, now());
