insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'acides-et-bases-faibles-couples-acide-base'), 1, 'acides-faibles-bases-faibles-et-couples', 'Acides faibles, bases faibles et couples', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'acides-et-bases-faibles-couples-acide-base') and slug = 'acides-faibles-bases-faibles-et-couples'), $html$<p>Un <strong>acide faible</strong> ne réagit que partiellement avec l’eau : son pH est supérieur à −log C. Exemple : CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'acides-et-bases-faibles-couples-acide-base'), 2, 'classification-des-couples-et-domaines-de-predominance', 'Classification des couples et domaines de prédominance', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'acides-et-bases-faibles-couples-acide-base') and slug = 'classification-des-couples-et-domaines-de-predominance'), $html$<ul><li>plus le pK<sub>a</sub> est petit, plus l’acide est fort (et sa base conjuguée faible) ;</li><li>couples de l’eau : H₃O⁺/H₂O (pK<sub>a</sub> = 0) et H₂O/OH⁻ (pK<sub>a</sub> = 14).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 23, 'reaction-acide-faible-base-forte-effet-tampon', 'Réaction acide faible-base forte, effet tampon', 'Dosage d’un acide faible par une base forte (et inversement), demi-équivalence, solutions tampons.', 23, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
