insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'activite-du-muscle-strie-squelettique') and slug = 'structure-du-muscle-strie-squelettique'), $html$<p>Un muscle squelettique est formé de faisceaux de <strong>fibres musculaires</strong> : ce sont de très longues cellules à plusieurs noyaux.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'activite-du-muscle-strie-squelettique'), 2, 'fonctionnement-du-muscle-squelettique', 'Fonctionnement du muscle squelettique', true, 'published', 18, now());
