insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'biotechnologies') and slug = 'les-biotechnologies'), $html$<p>Le <strong>génie génétique</strong> permet de transférer un gène d’un organisme à un autre, car le code génétique est universel.</p>
