insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nature-et-culture'), 1, 'l-inne-l-acquis-et-le-fait-culturel', 'L’inné, l’acquis et le fait culturel', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nature-et-culture') and slug = 'l-inne-l-acquis-et-le-fait-culturel'), $html$<p>La <strong>nature</strong> désigne ce qui est donné à la naissance (l’inné) ; la <strong>culture</strong>, ce que l’homme acquiert et transmet par l’éducation : langage, techniques, croyances, règles.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nature-et-culture'), 2, 'le-travail', 'Le travail', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nature-et-culture') and slug = 'le-travail'), $html$<p>Le <strong>travail</strong> est l’activité par laquelle l’homme transforme la nature pour satisfaire ses besoins.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nature-et-culture'), 3, 'langage-pensee-et-communication', 'Langage, pensée et communication', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'nature-et-culture') and slug = 'langage-pensee-et-communication'), $html$<p>Le <strong>langage</strong> est la faculté de communiquer au moyen de signes. La langue est un système de signes propre à une communauté (wolof, pulaar, français…).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 5, 'individu-et-societe', 'Individu et société', 'Individu, personne et société ; les normes, la conformité et la déviance.', 5, 'published', 'La vie sociale', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'individu-et-societe'), 1, 'individu-personne-et-societe', 'Individu, personne et société', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'individu-et-societe') and slug = 'individu-personne-et-societe'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>individu</td><td>être unique, distinct des autres (« qui ne peut être divisé »)</td></tr><tr><td>personne</td><td>être humain doué de raison et de liberté, sujet de droits et de devoirs, qui a une dignité</td></tr><tr><td>société</td><td>groupe d’individus liés par des règles, des institutions et une culture communes</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'individu-et-societe'), 2, 'les-normes-conformite-et-deviance', 'Les normes : conformité et déviance', true, 'published', 12, now());
