insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'synthese-compte-rendu-et-correspondance'), 1, 'synthese-de-documents-et-compte-rendu', 'Synthèse de documents et compte rendu', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'synthese-compte-rendu-et-correspondance') and slug = 'synthese-de-documents-et-compte-rendu'), $html$<p>La <strong>synthèse</strong> rassemble les informations de plusieurs documents sur un même thème, de façon objective et organisée. Le <strong>compte rendu</strong> (ou rapport) relate un événement (réunion, visite, conférence).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'synthese-compte-rendu-et-correspondance'), 2, 'rediger-une-lettre', 'Rédiger une lettre', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'synthese-compte-rendu-et-correspondance') and slug = 'rediger-une-lettre'), $html$<ul><li>lettre <strong>formelle</strong> (demande, réclamation, candidature) : coordonnées, lieu et date, destinataire, objet, formule d’appel (« Monsieur le Proviseur »), corps du texte, formule de politesse, signature ;</li><li>lettre <strong>personnelle</strong> : ton familier, mais langue correcte.</li></ul>
