insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'science-and-technology') and slug = 'inventions-discoveries-and-icts'), $html$<h2>Reading: Mobile money</h2><p>A few years ago, sending money to a village meant travelling or trusting a driver. Today, thanks to mobile phones, money can be sent in seconds. Mobile money has changed the daily lives of millions of Africans.</p><p>Science and technology bring great benefits, but they also raise ethical questions: who controls our personal data? Should we use genetically modified crops?</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'science-and-technology'), 2, 'describing-a-process', 'Describing a process', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'science-and-technology') and slug = 'describing-a-process'), $html$<p>To describe how something is made or how it works, we use <strong>the passive</strong> and <strong>sequence words</strong>.</p>
