insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'information-and-communication') and slug = 'the-media-and-the-information-explosion'), $html$<h2>Reading: Fake news</h2><p>With social networks, anyone can publish information. News travels faster than ever, but so do rumours and fake news. Before sharing a message, we should check its source and compare it with other reliable media.</p><p>Advertisements are everywhere too. They inform consumers but also try to make them buy things they do not need.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'information-and-communication'), 2, 'reported-speech', 'Reported speech', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'information-and-communication') and slug = 'reported-speech'), $html$<table><thead><tr><th scope="col">Direct speech</th><th scope="col">Reported speech</th></tr></thead><tbody><tr><td>“I am tired,” she said.</td><td>She said (that) she was tired.</td></tr><tr><td>“We will come,” they said.</td><td>They said they would come.</td></tr><tr><td>“I saw him yesterday,” he said.</td><td>He said he had seen him the day before.</td></tr><tr><td>“Where do you live?” he asked.</td><td>He asked me where I lived.</td></tr><tr><td>“Are you ready?” she asked.</td><td>She asked if I was ready.</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')), 6, 'exam-skills-reading-and-writing', 'Exam skills: reading and writing', 'Reading comprehension strategies and essay writing for the baccalauréat.', 6, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'exam-skills-reading-and-writing'), 1, 'reading-comprehension-strategies', 'Reading comprehension strategies', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'reading-comprehension-strategies'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li><strong>Skim</strong> the text: read the title and the first lines of each paragraph to get the general idea.</li><li>Read the questions before reading the text in detail.</li><li><strong>Scan</strong> for specific information: names, dates, numbers, key words.</li><li>For “True or False”, always justify with a short quotation from the text.</li><li>Guess the meaning of new words from the context, the word family or prefixes and suffixes.</li></ol></div>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'exam-skills-reading-and-writing'), 2, 'writing-an-essay', 'Writing an essay', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S2')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'writing-an-essay'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Read the subject carefully and underline the key words.</li><li>Brainstorm ideas and examples, then make a plan.</li><li><strong>Introduction</strong>: present the topic and announce your point of view or your plan.</li><li><strong>Body</strong>: one paragraph per idea, with an example; use linking words.</li><li><strong>Conclusion</strong>: sum up and give your opinion.</li><li>Check your grammar, spelling and the number of words required.</li></ol></div>
