insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques'), 1, 'les-fonctions-de-la-pensee-philosophique', 'Les fonctions de la pensée philosophique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'les-fonctions-de-la-pensee-philosophique'), $html$<ul><li><strong>fonction critique</strong> : examiner les préjugés, les opinions et les pouvoirs ;</li><li><strong>fonction libératrice</strong> : apprendre à penser par soi-même ;</li><li><strong>fonction de synthèse</strong> : relier les savoirs dispersés et s’interroger sur leurs fondements ;</li><li><strong>fonction éthique</strong> : réfléchir à la manière de bien vivre et d’agir.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques'), 2, 'philosophie-et-ideologie', 'Philosophie et idéologie', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'philosophie-et-ideologie'), $html$<p>Une <strong>idéologie</strong> est un système d’idées qui justifie les intérêts d’un groupe ou d’un pouvoir, en se présentant comme une vérité évidente.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques'), 3, 'philosopher-aujourd-hui', 'Philosopher aujourd’hui', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'philosopher-aujourd-hui'), $html$<p>Les sciences ont pris à la philosophie beaucoup de ses anciens objets (la nature, la société, le psychisme). Mais de nouvelles questions apparaissent, que la science seule ne peut trancher :</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')), 4, 'l-idee-d-une-philosophie-africaine', 'L’idée d’une philosophie africaine', 'Repères historiques et débats : ethnophilosophie, négritude, philosophie critique.', 4, 'published', 'La réflexion philosophique', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-idee-d-une-philosophie-africaine'), 1, 'la-philosophie-africaine-reperes-historiques', 'La philosophie africaine : repères historiques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-idee-d-une-philosophie-africaine') and slug = 'la-philosophie-africaine-reperes-historiques'), $html$<table><thead><tr><th scope="col">Repère</th><th scope="col">Apport</th></tr></thead><tbody><tr><td>Placide Tempels, <em>La Philosophie bantoue</em> (1945)</td><td>affirme que les Bantous ont une philosophie, centrée sur la « force vitale »</td></tr><tr><td>Alexis Kagame, <em>La philosophie bantu-rwandaise de l’être</em> (1956)</td><td>dégage une philosophie à partir de la langue kinyarwanda</td></tr><tr><td>Cheikh Anta Diop, <em>Nations nègres et culture</em> (1954)</td><td>rattache l’Égypte ancienne au monde noir et en fait une source de la pensée</td></tr><tr><td>Léopold Sédar Senghor et la négritude</td><td>valorise les valeurs culturelles du monde noir</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-idee-d-une-philosophie-africaine'), 2, 'la-philosophie-africaine-debats-et-controverses', 'La philosophie africaine : débats et controverses', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-idee-d-une-philosophie-africaine') and slug = 'la-philosophie-africaine-debats-et-controverses'), $html$<p>L’approche de Tempels, appelée <strong>ethnophilosophie</strong>, a été vivement critiquée.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')), 5, 'nature-et-culture', 'Nature et culture', 'L’inné et l’acquis, relativité et universalité des cultures, le travail, le langage.', 5, 'published', 'La vie sociale', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'nature-et-culture'), 1, 'l-inne-l-acquis-et-le-fait-culturel', 'L’inné, l’acquis et le fait culturel', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'nature-et-culture') and slug = 'l-inne-l-acquis-et-le-fait-culturel'), $html$<p>La <strong>nature</strong> désigne ce qui est donné à la naissance (l’inné) ; la <strong>culture</strong>, ce que l’homme acquiert et transmet par l’éducation : langage, techniques, croyances, règles.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'nature-et-culture'), 2, 'le-travail', 'Le travail', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'nature-et-culture') and slug = 'le-travail'), $html$<p>Le <strong>travail</strong> est l’activité par laquelle l’homme transforme la nature pour satisfaire ses besoins.</p>
