insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'science-et-technique') and slug = 'science-et-technique'), $html$<p>La <strong>technique</strong> est l’ensemble des procédés par lesquels l’homme transforme la nature pour ses besoins. Elle est plus ancienne que la science (outils de la préhistoire).</p>
