insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'la-poesie') and slug = 'les-outils-de-la-versification'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>vers</td><td>ligne de poème ; l’alexandrin compte 12 syllabes, le décasyllabe 10, l’octosyllabe 8</td></tr><tr><td>e muet</td><td>se prononce devant une consonne, s’élide devant une voyelle ou en fin de vers</td></tr><tr><td>diérèse, synérèse</td><td>prononcer une syllabe en deux (li-on) ou deux en une (lion)</td></tr><tr><td>rimes</td><td>plates (AABB), croisées (ABAB), embrassées (ABBA) ; pauvres, suffisantes ou riches</td></tr><tr><td>strophe</td><td>groupe de vers : quatrain (4), tercet (3)…</td></tr><tr><td>sonnet</td><td>deux quatrains et deux tercets</td></tr></tbody></table>
