insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'la-poesie') and slug = 'poesie-classique-et-romantique'), $html$<table><thead><tr><th scope="col">Œuvre (liste officielle)</th><th scope="col">Ce qu’il faut savoir</th></tr></thead><tbody><tr><td>Boileau, <em>L’Art poétique</em> (1674)</td><td>texte théorique du classicisme : clarté, raison, imitation des Anciens, règles</td></tr><tr><td>La Fontaine, <em>Fables</em></td><td>récits en vers, souvent animaliers, qui instruisent en plaisant ; morale explicite ou implicite</td></tr><tr><td>Victor Hugo, <em>Les Contemplations</em> (1856)</td><td>poésie romantique et lyrique : souvenirs, deuil de sa fille Léopoldine, méditation</td></tr></tbody></table>
