insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-amerique-latine') and slug = 'milieux-naturels-et-populations'), $html$<ul><li>des milieux très variés : cordillère des Andes, forêt amazonienne, pampa, déserts (Atacama) ;</li><li>une population métissée (Amérindiens, Européens, descendants d’Africains) et très urbanisée ;</li><li>de grandes métropoles (Mexico, São Paulo, Buenos Aires) entourées de quartiers pauvres (favelas, bidonvilles) ;</li><li>des inégalités sociales parmi les plus fortes du monde.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-amerique-latine'), 2, 'le-bresil-une-puissance-du-tiers-monde', 'Le Brésil, une puissance du tiers-monde', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'l-amerique-latine') and slug = 'le-bresil-une-puissance-du-tiers-monde'), $html$<table><thead><tr><th scope="col">Atouts</th><th scope="col">Problèmes</th></tr></thead><tbody><tr><td>territoire immense (8,5 millions de km²), environ 203 millions d’habitants</td><td>inégalités sociales et régionales (Sud-Est riche, Nordeste pauvre)</td></tr><tr><td>agriculture d’exportation : soja, café, sucre, viande</td><td>déforestation de l’Amazonie</td></tr><tr><td>industrie (aéronautique, automobile), pétrole offshore</td><td>violence urbaine, favelas</td></tr><tr><td>membre des BRICS</td><td>instabilité politique et économique</td></tr></tbody></table>
