insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'health-welfare-and-environment'), 1, 'health-and-environment', 'Health and environment', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'health-welfare-and-environment') and slug = 'health-and-environment'), $html$<h2>Reading: Plastic everywhere</h2><p>Plastic bags are cheap and practical, but they take hundreds of years to break down. They block drains, kill animals that eat them and pollute our beaches. Burning them releases toxic smoke.</p><p>Good hygiene, clean water and vaccination prevent many diseases such as cholera, malaria and measles. Keeping fit and eating a balanced diet are also important for our health.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'health-welfare-and-environment'), 2, 'giving-advice-and-conditionals', 'Giving advice and conditionals', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'health-welfare-and-environment') and slug = 'giving-advice-and-conditionals'), $html$<table><thead><tr><th scope="col">Advice</th><th scope="col">Example</th></tr></thead><tbody><tr><td>should / ought to</td><td>You should wash your hands before eating.</td></tr><tr><td>had better (+ base verb)</td><td>You had better see a doctor.</td></tr><tr><td>If I were you, I would…</td><td>If I were you, I would sleep under a mosquito net.</td></tr></tbody></table>
