insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'cultural-heritage'), 1, 'customs-ceremonies-and-values', 'Customs, ceremonies and values', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'cultural-heritage') and slug = 'customs-ceremonies-and-values'), $html$<h2>Reading: Teranga</h2><p>Senegal is often called the country of teranga, a Wolof word meaning hospitality. Guests are welcomed, fed and treated with respect. Muslims and Christians live together peacefully and often celebrate each other’s religious festivals.</p><p>Naming ceremonies, weddings and religious pilgrimages bring families together. These customs teach values such as solidarity, tolerance and generosity.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'cultural-heritage'), 2, 'relative-clauses', 'Relative clauses', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'cultural-heritage') and slug = 'relative-clauses'), $html$<table><thead><tr><th scope="col">Pronoun</th><th scope="col">Use</th><th scope="col">Example</th></tr></thead><tbody><tr><td>who</td><td>people</td><td>The griot who sang at the wedding is famous.</td></tr><tr><td>which / that</td><td>things</td><td>Gorée is an island which reminds us of the slave trade.</td></tr><tr><td>whose</td><td>possession</td><td>Senghor, whose poems are studied in schools, was a president.</td></tr><tr><td>where</td><td>places</td><td>Touba is the city where the Grand Magal takes place.</td></tr></tbody></table>
