insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'education'), 1, 'traditional-and-modern-education', 'Traditional and modern education', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'education') and slug = 'traditional-and-modern-education'), $html$<h2>Reading: Learning under the tree</h2><p>In traditional African societies, children learned from their elders through stories, proverbs, initiation and work. Education was the responsibility of the whole community.</p><p>Today, school is compulsory, but many children still leave school early. Some people think that modern education should teach both academic knowledge and the values of the past.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'education'), 2, 'linking-words-for-an-argumentative-essay', 'Linking words for an argumentative essay', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'education') and slug = 'linking-words-for-an-argumentative-essay'), $html$<table><thead><tr><th scope="col">Function</th><th scope="col">Linking words</th></tr></thead><tbody><tr><td>adding</td><td>moreover, furthermore, in addition, besides</td></tr><tr><td>contrasting</td><td>however, although, whereas, on the other hand, despite + noun</td></tr><tr><td>cause</td><td>because, since, as, because of + noun</td></tr><tr><td>consequence</td><td>so, therefore, as a result, consequently</td></tr><tr><td>concluding</td><td>to sum up, in conclusion, all in all</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')), 9, 'exam-skills-reading-and-writing', 'Exam skills: reading and writing', 'Reading comprehension strategies and essay writing for the baccalauréat.', 9, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'exam-skills-reading-and-writing'), 1, 'reading-comprehension-strategies', 'Reading comprehension strategies', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'reading-comprehension-strategies'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li><strong>Skim</strong> the text: read the title and the first lines of each paragraph to get the general idea.</li><li>Read the questions before reading the text in detail.</li><li><strong>Scan</strong> for specific information: names, dates, numbers, key words.</li><li>For “True or False”, always justify with a short quotation from the text.</li><li>Guess the meaning of new words from the context, the word family or prefixes and suffixes.</li></ol></div>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'exam-skills-reading-and-writing'), 2, 'writing-an-essay', 'Writing an essay', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'writing-an-essay'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Read the subject carefully and underline the key words.</li><li>Brainstorm ideas and examples, then make a plan.</li><li><strong>Introduction</strong>: present the topic and announce your point of view or your plan.</li><li><strong>Body</strong>: one paragraph per idea, with an example; use linking words.</li><li><strong>Conclusion</strong>: sum up and give your opinion.</li><li>Check your grammar, spelling and the number of words required.</li></ol></div>
