insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'fonction-exponentielle') and slug = 'etude-de-l-exponentielle-et-derivee-de-e-u'), $html$<p>exp est dérivable sur ℝ et (e<sup>x</sup>)’ = e<sup>x</sup> &gt; 0 : elle est strictement croissante.</p>
