insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'suites-numeriques'), 1, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Suite arithmétique de raison r</th><th scope="col">Suite géométrique de raison q</th></tr></thead><tbody><tr><td>Définition</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>Terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr = u<sub>p</sub> + (n − p)r</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>Somme de termes consécutifs</td><td>(nombre de termes) × <span class="frac"><span>premier + dernier</span><span>2</span></span></td><td>premier × <span class="frac"><span>1 − q<sup>N</sup></span><span>1 − q</span></span> (N termes, q ≠ 1)</td></tr></tbody></table>
