insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'suites-numeriques') and slug = 'sens-de-variation-et-suites-bornees'), $html$<p>Une suite (u<sub>n</sub>) est <strong>croissante</strong> si u<sub>n+1</sub> ≥ u<sub>n</sub> pour tout n, <strong>décroissante</strong> si u<sub>n+1</sub> ≤ u<sub>n</sub>, <strong>monotone</strong> si elle est l’un ou l’autre.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'suites-numeriques'), 4, 'limites-de-suites-et-theoremes-de-convergence', 'Limites de suites et théorèmes de convergence', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'suites-numeriques') and slug = 'limites-de-suites-et-theoremes-de-convergence'), $html$<p>Une suite <strong>converge</strong> vers ℓ si ses termes deviennent aussi proches de ℓ qu’on veut à partir d’un certain rang ; sinon elle <strong>diverge</strong> (limite infinie ou pas de limite). Les opérations sur les limites sont les mêmes que pour les fonctions.</p>
