insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L1')) and c.slug = 'calcul-integral') and slug = 'primitives'), $html$<p>F est une <strong>primitive</strong> de f sur un intervalle I si F’ = f sur I. Toute fonction continue sur I admet des primitives ; si F en est une, les autres sont les F + C (C constante). Une seule prend une valeur donnée en un point.</p>
