insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique'), 1, 'qu-est-ce-que-la-philosophie', 'Qu’est-ce que la philosophie ?', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'qu-est-ce-que-la-philosophie'), $html$<p>Étymologiquement, la philosophie est l’« amour de la sagesse » (en grec <em>philein</em>, aimer, et <em>sophia</em>, sagesse). Le philosophe n’est pas un sage qui possède la vérité : il la cherche.</p>
