insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'philosophie-mythe-religion-et-science'), $html$<p>La philosophie naît en Grèce au VI<sup>e</sup> siècle avant notre ère, quand des penseurs (Thalès, Héraclite, puis Socrate, Platon, Aristote) cherchent à expliquer le monde par des raisons et non plus par des récits sur les dieux. On parle du passage du <em>mythos</em> (récit) au <em>logos</em> (discours rationnel).</p>
