insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques'), 3, 'philosopher-aujourd-hui', 'Philosopher aujourd’hui', false, 'published', 10, now());
