insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'conscience-et-inconscient') and slug = 'la-conscience'), $html$<p>La <strong>conscience psychologique</strong> est la connaissance que le sujet a de lui-même et de ce qu’il vit. La <strong>conscience morale</strong> est la faculté de juger le bien et le mal de ses actes.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'conscience-et-inconscient'), 2, 'l-inconscient-psychique-et-la-personnalite', 'L’inconscient psychique et la personnalité', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'conscience-et-inconscient') and slug = 'l-inconscient-psychique-et-la-personnalite'), $html$<p>Pour Freud, une grande partie de notre vie psychique échappe à la conscience : c’est l’<strong>inconscient</strong>. Des désirs refoulés, souvent liés à l’enfance, s’y trouvent et cherchent à s’exprimer.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 8, 'la-liberte', 'La liberté', 'Liberté, déterminisme et fatalisme ; libre-arbitre et responsabilité.', 8, 'published', 'La vie sociale', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-liberte'), 1, 'liberte-determinisme-et-fatalisme', 'Liberté, déterminisme et fatalisme', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-liberte') and slug = 'liberte-determinisme-et-fatalisme'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>liberté</td><td>pouvoir d’agir selon sa volonté, sans contrainte</td></tr><tr><td>déterminisme</td><td>tout phénomène a des causes qui le produisent nécessairement (sciences)</td></tr><tr><td>fatalisme</td><td>croyance que tout est écrit d’avance, quoi qu’on fasse</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-liberte'), 2, 'libre-arbitre-et-responsabilite', 'Libre-arbitre et responsabilité', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'la-liberte') and slug = 'libre-arbitre-et-responsabilite'), $html$<p>Le <strong>libre-arbitre</strong> est le pouvoir de choisir entre plusieurs possibles. Pour Descartes, la volonté est infinie : c’est en elle que l’homme ressemble le plus à Dieu.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 9, 'l-etat', 'L’État', 'Genèse, formes, fonctions et finalités de l’État ; droits, libertés et mondialisation.', 9, 'published', 'La vie sociale', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-etat'), 1, 'le-fait-politique-et-la-genese-de-l-etat', 'Le fait politique et la genèse de l’État', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-etat') and slug = 'le-fait-politique-et-la-genese-de-l-etat'), $html$<p>Le <strong>politique</strong> concerne l’organisation du pouvoir dans une société. L’<strong>État</strong> est l’institution qui détient l’autorité souveraine sur un territoire et une population.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-etat'), 2, 'formes-fonctions-et-finalites-de-l-etat', 'Formes, fonctions et finalités de l’État', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-etat') and slug = 'formes-fonctions-et-finalites-de-l-etat'), $html$<table><thead><tr><th scope="col">Forme</th><th scope="col">Qui gouverne ?</th></tr></thead><tbody><tr><td>monarchie</td><td>un seul, selon des lois</td></tr><tr><td>aristocratie, oligarchie</td><td>un petit nombre</td></tr><tr><td>démocratie</td><td>le peuple, directement ou par ses représentants</td></tr><tr><td>dictature, tyrannie</td><td>un seul, sans limites ni lois</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-etat'), 3, 'etat-droits-libertes-et-mondialisation', 'État, droits, libertés et mondialisation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-etat') and slug = 'etat-droits-libertes-et-mondialisation'), $html$<p>L’État moderne doit garantir les <strong>droits humains</strong> (Déclaration universelle de 1948) et les libertés fondamentales : d’expression, de culte, d’association, de circulation.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 10, 'l-emergence-de-la-pensee-scientifique', 'L’émergence de la pensée scientifique', 'Formes de connaissance, naissance de la science, obstacles épistémologiques, méthode.', 10, 'published', 'Épistémologie', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-emergence-de-la-pensee-scientifique'), 1, 'les-formes-de-la-connaissance', 'Les formes de la connaissance', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-emergence-de-la-pensee-scientifique') and slug = 'les-formes-de-la-connaissance'), $html$<table><thead><tr><th scope="col">Connaissance</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>sensible</td><td>donnée par les sens ; immédiate mais parfois trompeuse (illusions)</td></tr><tr><td>empirique</td><td>tirée de l’expérience répétée et de l’habitude (savoir-faire du pêcheur, du paysan)</td></tr><tr><td>intuitive</td><td>saisie immédiate d’une vérité par l’esprit</td></tr><tr><td>discursive</td><td>obtenue par un raisonnement, étape par étape (démonstration)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-emergence-de-la-pensee-scientifique'), 2, 'naissance-de-la-science-et-obstacles-epistemologiques', 'Naissance de la science et obstacles épistémologiques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-emergence-de-la-pensee-scientifique') and slug = 'naissance-de-la-science-et-obstacles-epistemologiques'), $html$<p>La science moderne naît au XVII<sup>e</sup> siècle avec Galilée, qui allie mathématiques et expérience : « le livre de la nature est écrit en langage mathématique ». Elle suppose la rupture avec l’opinion et l’autorité.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-emergence-de-la-pensee-scientifique'), 3, 'la-connaissance-scientifique-principes-et-methodes', 'La connaissance scientifique : principes et méthodes', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-emergence-de-la-pensee-scientifique') and slug = 'la-connaissance-scientifique-principes-et-methodes'), $html$<div class="callout"><p class="callout-title">La méthode expérimentale (Claude Bernard)</p><ol><li><strong>Observation</strong> d’un fait polémique, qui pose problème.</li><li><strong>Hypothèse</strong> : explication provisoire.</li><li><strong>Expérimentation</strong> : on produit les conditions pour vérifier l’hypothèse.</li><li><strong>Loi</strong> ou <strong>théorie</strong> : énoncé général, souvent mathématique.</li></ol></div>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 11, 'les-differents-types-de-sciences', 'Les différents types de sciences', 'Sciences formelles, sciences de la nature et de l’homme, problème de la vérité.', 11, 'published', 'Épistémologie', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-differents-types-de-sciences'), 1, 'les-sciences-formelles-logique-et-mathematiques', 'Les sciences formelles : logique et mathématiques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-differents-types-de-sciences') and slug = 'les-sciences-formelles-logique-et-mathematiques'), $html$<p>La logique et les mathématiques ne portent pas sur des faits mais sur des formes de raisonnement. Elles procèdent par <strong>déduction</strong> à partir d’axiomes et de définitions.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-differents-types-de-sciences'), 2, 'sciences-de-la-nature-et-sciences-de-l-homme', 'Sciences de la nature et sciences de l’homme', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-differents-types-de-sciences') and slug = 'sciences-de-la-nature-et-sciences-de-l-homme'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Sciences de la nature</th><th scope="col">Sciences de l’homme</th></tr></thead><tbody><tr><td>exemples</td><td>physique, chimie, biologie</td><td>psychologie, sociologie, histoire, économie, linguistique</td></tr><tr><td>objet</td><td>des phénomènes qui obéissent à des lois</td><td>l’homme, être conscient et libre</td></tr><tr><td>méthode</td><td>expérimentation, mesure, prévision</td><td>observation, enquête, statistique, interprétation</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-differents-types-de-sciences'), 3, 'le-probleme-de-la-verite', 'Le problème de la vérité', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-differents-types-de-sciences') and slug = 'le-probleme-de-la-verite'), $html$<table><thead><tr><th scope="col">Conception de la vérité</th><th scope="col">Critère</th></tr></thead><tbody><tr><td>vérité-correspondance</td><td>une idée est vraie si elle est conforme à la réalité</td></tr><tr><td>vérité-cohérence</td><td>un énoncé est vrai s’il ne contredit pas le système dont il fait partie (mathématiques)</td></tr><tr><td>vérité-évidence (Descartes)</td><td>est vrai ce que je conçois clairement et distinctement</td></tr><tr><td>pragmatisme</td><td>est vrai ce qui réussit, ce qui est utile</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 12, 'science-et-technique', 'Science et technique', 'Rapports entre science et technique, progrès et valeurs.', 12, 'published', 'Épistémologie', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'science-et-technique'), 1, 'science-et-technique', 'Science et technique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'science-et-technique') and slug = 'science-et-technique'), $html$<p>La <strong>technique</strong> est l’ensemble des procédés par lesquels l’homme transforme la nature pour ses besoins. Elle est plus ancienne que la science (outils de la préhistoire).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'science-et-technique'), 2, 'science-technique-et-valeurs', 'Science, technique et valeurs', true, 'published', 12, now());
