insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'le-theatre'), 1, 'le-texte-theatral', 'Le texte théâtral', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'le-theatre') and slug = 'le-texte-theatral'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>dialogue, réplique, tirade</td><td>échanges entre personnages ; une tirade est une longue réplique</td></tr><tr><td>monologue, aparté</td><td>personnage seul en scène ; parole adressée au public que les autres n’entendent pas</td></tr><tr><td>didascalies</td><td>indications de mise en scène (en italique)</td></tr><tr><td>double énonciation</td><td>les personnages se parlent, mais l’auteur s’adresse au public</td></tr><tr><td>exposition, nœud, dénouement</td><td>étapes de l’action</td></tr></tbody></table>
