insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal'), 1, 'problemes-et-perspectives-de-developpement-de-l-afrique', 'Problèmes et perspectives de développement de l’Afrique', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'problemes-et-perspectives-de-developpement-de-l-afrique'), $html$<table><thead><tr><th scope="col">Problèmes</th><th scope="col">Perspectives</th></tr></thead><tbody><tr><td>pauvreté, faible industrialisation, dépendance aux matières premières</td><td>ressources minières et énergétiques considérables</td></tr><tr><td>dette, instabilité politique, conflits</td><td>population jeune (environ 1,4 milliard d’habitants), urbanisation, marché intérieur</td></tr><tr><td>insuffisance des infrastructures et des services (santé, éducation)</td><td>intégration régionale : CEDEAO, Union africaine, ZLECAf</td></tr><tr><td>effets du changement climatique (désertification, sécheresses)</td><td>numérique (paiement mobile), énergies renouvelables</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal'), 2, 'le-senegal-milieux-naturels-et-populations', 'Le Sénégal : milieux naturels et populations', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'le-senegal-milieux-naturels-et-populations'), $html$<ul><li>196 722 km², 14 régions ; un relief plat (sauf le Sud-Est) ; climat tropical, du sahélien au nord au soudano-guinéen en Casamance ;</li><li>une saison des pluies (de juin-juillet à octobre) et une longue saison sèche ;</li><li>fleuves Sénégal, Gambie, Casamance, Saloum ;</li><li>environ 18 millions d’habitants (recensement de 2023), une population très jeune ;</li><li>une population inégalement répartie : forte concentration à Dakar et dans l’Ouest, faibles densités à l’Est ;</li><li>exode rural et émigration (vers l’Europe, les pays voisins).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal'), 3, 'la-question-de-l-eau-au-senegal', 'La question de l’eau au Sénégal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'la-question-de-l-eau-au-senegal'), $html$<ul><li>des pluies faibles et irrégulières au nord, des sécheresses (années 1970-1980) ;</li><li>l’OMVS (Sénégal, Mali, Mauritanie, Guinée) a construit les barrages de Diama (contre la remontée de l’eau salée) et de Manantali (irrigation, électricité) ;</li><li>Dakar est alimentée en partie par le lac de Guiers, à plus de 200 km, et par des forages ; la nappe est menacée par la salinisation ;</li><li>l’agriculture irriguée se développe dans la vallée du fleuve (riz, tomate, oignon).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal'), 4, 'problemes-economiques-et-politiques-de-developpement-du-senegal', 'Problèmes économiques et politiques de développement du Sénégal', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'problemes-economiques-et-politiques-de-developpement-du-senegal'), $html$<table><thead><tr><th scope="col">Secteur</th><th scope="col">Situation</th></tr></thead><tbody><tr><td>agriculture</td><td>arachide, mil, riz, horticulture ; dépendance aux pluies ; importations de riz</td></tr><tr><td>pêche</td><td>première ressource d’exportation, menacée par la surpêche</td></tr><tr><td>mines et énergie</td><td>phosphates, or (Sabodala), zircon ; pétrole (Sangomar, depuis 2024) et gaz</td></tr><tr><td>services</td><td>port de Dakar, télécommunications, tourisme, transferts des émigrés</td></tr></tbody></table>
