insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'economy'), 1, 'poverty-and-development', 'Poverty and development', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'economy') and slug = 'poverty-and-development'), $html$<h2>Reading: From groundnuts to oil</h2><p>For decades, Senegal’s economy depended on groundnuts. Today, fishing, mining, services and tourism are also important, and the country started producing oil in 2024.</p><p>However, natural resources are not enough to fight poverty. Sustainable development means growing the economy while protecting the environment and giving everyone access to education, health and decent jobs.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'economy'), 2, 'describing-graphs-and-making-comparisons', 'Describing graphs and making comparisons', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'economy') and slug = 'describing-graphs-and-making-comparisons'), $html$<table><thead><tr><th scope="col">Trend</th><th scope="col">Verbs</th><th scope="col">Adverbs</th></tr></thead><tbody><tr><td>going up</td><td>rise, increase, grow</td><td>sharply, steadily, slightly</td></tr><tr><td>going down</td><td>fall, decrease, drop</td><td>dramatically, gradually</td></tr><tr><td>no change</td><td>remain stable, level off</td><td></td></tr></tbody></table>
