insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'events-and-changes'), 1, 'colonial-times-and-the-struggle-for-independence', 'Colonial times and the struggle for independence', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'events-and-changes') and slug = 'colonial-times-and-the-struggle-for-independence'), $html$<h2>Reading: The winds of change</h2><p>After the Second World War, many African soldiers who had fought for Europe came back with new ideas. Political parties and trade unions were created, and leaders such as Kwame Nkrumah, Léopold Sédar Senghor and Amílcar Cabral demanded freedom.</p><p>Ghana became independent in 1957. In 1960 alone, seventeen African countries gained their independence. In Portuguese colonies, the struggle was longer and armed.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'events-and-changes'), 2, 'talking-about-the-past-tenses-and-the-passive', 'Talking about the past: tenses and the passive', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'events-and-changes') and slug = 'talking-about-the-past-tenses-and-the-passive'), $html$<table><thead><tr><th scope="col">Tense</th><th scope="col">Use</th><th scope="col">Example</th></tr></thead><tbody><tr><td>past simple</td><td>finished action at a given time</td><td>Senegal became independent in 1960.</td></tr><tr><td>past continuous</td><td>action in progress in the past</td><td>They were fighting when the war ended.</td></tr><tr><td>past perfect</td><td>action before another past action</td><td>When he arrived, the meeting had started.</td></tr><tr><td>used to + verb</td><td>past habit</td><td>People used to travel by camel.</td></tr></tbody></table>
