insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'education') and slug = 'linking-words-for-an-argumentative-essay'), $html$<table><thead><tr><th scope="col">Function</th><th scope="col">Linking words</th></tr></thead><tbody><tr><td>adding</td><td>moreover, furthermore, in addition, besides</td></tr><tr><td>contrasting</td><td>however, although, whereas, on the other hand, despite + noun</td></tr><tr><td>cause</td><td>because, since, as, because of + noun</td></tr><tr><td>consequence</td><td>so, therefore, as a result, consequently</td></tr><tr><td>concluding</td><td>to sum up, in conclusion, all in all</td></tr></tbody></table>
