insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'limites-et-continuite') and slug = 'continuite-d-une-fonction'), $html$<p>f est <strong>continue en x₀</strong> si f(x₀) existe et si la limite de f(x) quand x tend vers x₀ est f(x₀). Elle est continue sur un intervalle si elle l’est en chaque point : sa courbe se trace sans lever le crayon.</p>
