insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'fonction-exponentielle'), 1, 'la-fonction-exponentielle-definition-et-proprietes', 'La fonction exponentielle : définition et propriétés', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'fonction-exponentielle') and slug = 'la-fonction-exponentielle-definition-et-proprietes'), $html$<p>ln est une bijection de ]0 ; +∞[ sur ℝ. Sa réciproque est la <strong>fonction exponentielle</strong>, notée exp, avec exp(x) = e<sup>x</sup>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'fonction-exponentielle'), 2, 'etude-de-l-exponentielle-et-derivee-de-e-u', 'Étude de l’exponentielle et dérivée de e^u', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'fonction-exponentielle') and slug = 'etude-de-l-exponentielle-et-derivee-de-e-u'), $html$<p>exp est dérivable sur ℝ et (e<sup>x</sup>)’ = e<sup>x</sup> &gt; 0 : elle est strictement croissante.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 9, 'suites-numeriques', 'Suites numériques', 'Suites arithmétiques et géométriques, récurrence, variations et convergence.', 9, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'suites-numeriques'), 1, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Suite arithmétique de raison r</th><th scope="col">Suite géométrique de raison q</th></tr></thead><tbody><tr><td>Définition</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>Terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr = u<sub>p</sub> + (n − p)r</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>Somme de termes consécutifs</td><td>(nombre de termes) × <span class="frac"><span>premier + dernier</span><span>2</span></span></td><td>premier × <span class="frac"><span>1 − q<sup>N</sup></span><span>1 − q</span></span> (N termes, q ≠ 1)</td></tr></tbody></table>
