insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'production-transport-et-utilisation-de-l-energie-electrique') and slug = 'produire-l-electricite'), $html$<p>Dans presque toutes les centrales, une <strong>turbine</strong> fait tourner un <strong>alternateur</strong> : un aimant (ou électroaimant) tourne devant des bobines et y crée une tension alternative.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'production-transport-et-utilisation-de-l-energie-electrique'), 2, 'transporter-et-utiliser-l-energie-electrique', 'Transporter et utiliser l’énergie électrique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'production-transport-et-utilisation-de-l-energie-electrique') and slug = 'transporter-et-utiliser-l-energie-electrique'), $html$<p>Un <strong>transformateur</strong> modifie la tension alternative : <span class="frac"><span>U₂</span><span>U₁</span></span> = <span class="frac"><span>N₂</span><span>N₁</span></span> (rapport des nombres de spires). Il ne fonctionne qu’en courant alternatif.</p>
