insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'energie-nucleaire') and slug = 'le-noyau-et-la-radioactivite'), $html$<p>Un noyau <sup>A</sup><sub>Z</sub>X contient Z protons et A − Z neutrons. Certains noyaux instables se désintègrent spontanément : c’est la <strong>radioactivité</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'energie-nucleaire'), 2, 'fission-fusion-et-energie-liberee', 'Fission, fusion et énergie libérée', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'energie-nucleaire') and slug = 'fission-fusion-et-energie-liberee'), $html$<p>Dans une réaction nucléaire, la masse des produits est un peu plus petite que celle des réactifs. La masse perdue Δm est transformée en énergie selon la relation d’Einstein :</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 3, 'signaux-et-ondes-mecaniques', 'Signaux et ondes mécaniques', 'Signal, onde transversale et longitudinale, célérité, période, longueur d’onde, son.', 3, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
