insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'signaux-et-ondes-mecaniques') and slug = 'propagation-d-un-signal'), $html$<p>Un <strong>signal</strong> est une déformation brève qui se propage dans un milieu (corde, ressort, surface de l’eau, air) sans transport de matière.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'signaux-et-ondes-mecaniques'), 2, 'ondes-progressives-periodiques-et-son', 'Ondes progressives périodiques et son', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'signaux-et-ondes-mecaniques') and slug = 'ondes-progressives-periodiques-et-son'), $html$<p>Si la source vibre périodiquement, l’onde est périodique : chaque point du milieu vibre avec la même période T.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 4, 'aspect-ondulatoire-de-la-lumiere', 'Aspect ondulatoire de la lumière', 'Diffraction, interférences, longueur d’onde et couleurs.', 4, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'aspect-ondulatoire-de-la-lumiere'), 1, 'la-lumiere-une-onde', 'La lumière, une onde', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'aspect-ondulatoire-de-la-lumiere') and slug = 'la-lumiere-une-onde'), $html$<p>Une fente très fine éclairée par un laser ne donne pas une simple tache : la lumière s’étale, c’est la <strong>diffraction</strong>. Deux fentes voisines donnent des franges brillantes et sombres : ce sont des <strong>interférences</strong>. Ces deux phénomènes montrent que la lumière est une onde.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 5, 'aspect-corpusculaire-de-la-lumiere', 'Aspect corpusculaire de la lumière', 'Effet photoélectrique, photon, dualité onde-corpuscule.', 5, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'aspect-corpusculaire-de-la-lumiere'), 1, 'le-photon-et-la-dualite-onde-corpuscule', 'Le photon et la dualité onde-corpuscule', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'aspect-corpusculaire-de-la-lumiere') and slug = 'le-photon-et-la-dualite-onde-corpuscule'), $html$<p>La lumière ultraviolette arrache des électrons à une plaque de zinc ; la lumière visible, même intense, n’y arrive pas : c’est l’<strong>effet photoélectrique</strong>. Pour l’expliquer, Einstein a proposé que la lumière soit formée de grains d’énergie, les <strong>photons</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 6, 'matieres-plastiques', 'Matières plastiques', 'Polymères, polyaddition et polycondensation, motif, degré de polymérisation, recyclage.', 6, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'matieres-plastiques'), 1, 'les-polymeres', 'Les polymères', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'matieres-plastiques') and slug = 'les-polymeres'), $html$<p>Un <strong>polymère</strong> est une très grande molécule formée par l’enchaînement d’un même groupe d’atomes, le <strong>motif</strong>, issu de petites molécules : les <strong>monomères</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'matieres-plastiques'), 2, 'proprietes-et-recyclage-des-plastiques', 'Propriétés et recyclage des plastiques', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'matieres-plastiques') and slug = 'proprietes-et-recyclage-des-plastiques'), $html$<ul><li><strong>thermoplastiques</strong> : ils ramollissent à la chaleur et peuvent être remoulés (PE, PVC) ;</li><li><strong>thermodurcissables</strong> : ils durcissent définitivement (bakélite) ;</li><li>les plastiques sont légers, isolants, imperméables et bon marché.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 7, 'les-textiles', 'Les textiles', 'Fibres naturelles, artificielles et synthétiques ; polyamides et polyesters.', 7, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-textiles'), 1, 'fibres-naturelles-artificielles-et-synthetiques', 'Fibres naturelles, artificielles et synthétiques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-textiles') and slug = 'fibres-naturelles-artificielles-et-synthetiques'), $html$<table><thead><tr><th scope="col">Type</th><th scope="col">Origine</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>naturelles végétales</td><td>plantes</td><td>coton (Sénégal oriental), lin, sisal</td></tr><tr><td>naturelles animales</td><td>animaux</td><td>laine, soie</td></tr><tr><td>artificielles</td><td>polymère naturel transformé</td><td>viscose (à partir de la cellulose)</td></tr><tr><td>synthétiques</td><td>pétrole</td><td>nylon, polyester (tergal), acrylique</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 8, 'les-savons', 'Les savons', 'Corps gras, saponification, structure et action d’un savon.', 8, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-savons'), 1, 'fabrication-des-savons', 'Fabrication des savons', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-savons') and slug = 'fabrication-des-savons'), $html$<p>Les huiles et graisses (huile d’arachide, de palme, beurre de karité) sont des <strong>triglycérides</strong> : des esters du glycérol et d’acides gras.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-savons'), 2, 'comment-un-savon-lave', 'Comment un savon lave', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'les-savons') and slug = 'comment-un-savon-lave'), $html$<p>L’ion carboxylate a une tête <strong>hydrophile</strong> (−COO⁻, attirée par l’eau) et une queue <strong>hydrophobe</strong> et lipophile (la chaîne carbonée, attirée par les graisses) : il est <strong>amphiphile</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 9, 'lessives-antiseptiques-et-desinfectants', 'Lessives, antiseptiques et désinfectants', 'Détergents de synthèse, composition des lessives, antiseptiques et désinfectants.', 9, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'lessives-antiseptiques-et-desinfectants'), 1, 'lessives-antiseptiques-et-desinfectants', 'Lessives, antiseptiques et désinfectants', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'lessives-antiseptiques-et-desinfectants') and slug = 'lessives-antiseptiques-et-desinfectants'), $html$<p>Les <strong>détergents de synthèse</strong> ont la même structure amphiphile que les savons, mais restent efficaces en eau dure. Une lessive contient des tensioactifs, des adoucisseurs d’eau, des agents de blanchiment, des enzymes et des parfums.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 10, 'pollution-de-l-air-et-de-l-eau', 'Pollution de l’air et de l’eau', 'Principaux polluants, effet de serre, pluies acides, pollution et traitement de l’eau.', 10, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'pollution-de-l-air-et-de-l-eau'), 1, 'la-pollution-de-l-air', 'La pollution de l’air', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'pollution-de-l-air-et-de-l-eau') and slug = 'la-pollution-de-l-air'), $html$<table><thead><tr><th scope="col">Polluant</th><th scope="col">Origine</th><th scope="col">Effets</th></tr></thead><tbody><tr><td>monoxyde de carbone CO</td><td>combustions incomplètes (moteurs, charbon de bois)</td><td>très toxique, mortel en lieu clos</td></tr><tr><td>dioxyde de soufre SO₂ et oxydes d’azote</td><td>industries, véhicules</td><td>pluies acides, maladies respiratoires</td></tr><tr><td>particules fines</td><td>trafic, poussières, brûlage des ordures</td><td>asthme, maladies cardiaques</td></tr><tr><td>dioxyde de carbone CO₂</td><td>combustion des énergies fossiles</td><td>renforcement de l’effet de serre</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'pollution-de-l-air-et-de-l-eau'), 2, 'la-pollution-de-l-eau', 'La pollution de l’eau', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'pollution-de-l-air-et-de-l-eau') and slug = 'la-pollution-de-l-eau'), $html$<ul><li><strong>matières organiques</strong> (eaux usées, ordures) : elles consomment l’oxygène de l’eau ;</li><li><strong>nitrates et phosphates</strong> (engrais, lessives) : prolifération d’algues, ou eutrophisation ;</li><li><strong>métaux lourds</strong> (plomb, mercure de l’orpaillage) : ils s’accumulent dans les poissons et les organismes ;</li><li><strong>hydrocarbures</strong> : marées noires.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 1, 'organisation-du-systeme-nerveux-cerebro-spinal', 'Organisation du système nerveux cérébro-spinal', 'Encéphale et moelle épinière : protection, organisation externe et interne, rôles.', 1, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal'), 1, 'organisation-de-l-encephale', 'Organisation de l’encéphale', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal') and slug = 'organisation-de-l-encephale'), $html$<p>Le système nerveux central (encéphale et moelle épinière) est protégé par des os (boîte crânienne, colonne vertébrale), par trois <strong>méninges</strong> (dure-mère, arachnoïde, pie-mère) et par le <strong>liquide céphalorachidien</strong>, qui amortit les chocs.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal'), 2, 'organisation-de-la-moelle-epiniere', 'Organisation de la moelle épinière', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'organisation-du-systeme-nerveux-cerebro-spinal') and slug = 'organisation-de-la-moelle-epiniere'), $html$<p>La moelle épinière est un cordon nerveux logé dans le canal vertébral. Sur une coupe transversale, on voit la <strong>substance grise</strong> en forme de papillon (ou de H) au centre, entourée de <strong>substance blanche</strong>, avec le canal de l’épendyme au milieu.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 2, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', 'Automatisme cardiaque, cycle cardiaque, régulation nerveuse et hormonale de la pression artérielle.', 2, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 1, 'l-automatisme-cardiaque', 'L’automatisme cardiaque', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'l-automatisme-cardiaque'), $html$<p>Un cœur isolé et irrigué continue à battre : il est <strong>automatique</strong>. Cette activité naît dans le <strong>tissu nodal</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 2, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', false, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), $html$<p>La <strong>pression artérielle</strong> est la pression du sang dans les artères. Elle varie entre une valeur maximale (systolique, environ 12 cmHg) et minimale (diastolique, environ 8 cmHg). Elle dépend du débit cardiaque et de la résistance des vaisseaux.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 3, 'regulation-de-la-glycemie', 'Régulation de la glycémie', 'Insuline et glucagon, rôle du foie, diabète.', 3, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'regulation-de-la-glycemie'), 1, 'regulation-de-la-glycemie', 'Régulation de la glycémie', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'regulation-de-la-glycemie') and slug = 'regulation-de-la-glycemie'), $html$<p>La <strong>glycémie</strong> est le taux de glucose dans le sang : environ 1 g/L à jeun (0,8 à 1,2 g/L). Le glucose est la principale source d’énergie des cellules.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 4, 'immunologie', 'Immunologie', 'Soi et non-soi, réponses immunitaires, VIH-sida.', 4, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'immunologie'), 1, 'le-systeme-immunitaire', 'Le système immunitaire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'immunologie') and slug = 'le-systeme-immunitaire'), $html$<p>Le système immunitaire distingue le <strong>soi</strong> (ce qui appartient à l’organisme, marqué par les molécules du CMH à la surface des cellules) du <strong>non-soi</strong> (microbes, cellules étrangères, cellules anormales). Une molécule reconnue comme étrangère est un <strong>antigène</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'immunologie'), 2, 'la-reponse-immunitaire', 'La réponse immunitaire', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'immunologie') and slug = 'la-reponse-immunitaire'), $html$<h2>Réponse non spécifique (immédiate)</h2>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'immunologie'), 3, 'le-vih-et-le-sida', 'Le VIH et le sida', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'immunologie') and slug = 'le-vih-et-le-sida'), $html$<p>Le <strong>VIH</strong> (virus de l’immunodéficience humaine) est un rétrovirus qui infecte surtout les <strong>lymphocytes T4</strong>, chefs d’orchestre de la réponse immunitaire.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 5, 'reproduction-chez-les-mammiferes', 'Reproduction chez les mammifères', 'Gamétogenèse, fécondation et régulation hormonale des appareils reproducteurs.', 5, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'reproduction-chez-les-mammiferes'), 1, 'appareils-reproducteurs-et-gametogenese', 'Appareils reproducteurs et gamétogenèse', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'appareils-reproducteurs-et-gametogenese'), $html$<p>Les <strong>gonades</strong> (testicules, ovaires) produisent les gamètes et des hormones sexuelles.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'reproduction-chez-les-mammiferes'), 2, 'fecondation-et-problemes-lies-a-la-fecondation', 'Fécondation et problèmes liés à la fécondation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'fecondation-et-problemes-lies-a-la-fecondation'), $html$<p>La <strong>fécondation</strong> a lieu dans le tiers supérieur de la trompe : un seul spermatozoïde traverse la zone pellucide grâce aux enzymes de son acrosome, puis son noyau fusionne avec celui de l’ovocyte. La cellule-œuf (2n = 46) est formée.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'reproduction-chez-les-mammiferes'), 3, 'regulation-hormonale-des-appareils-reproducteurs', 'Régulation hormonale des appareils reproducteurs', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'regulation-hormonale-des-appareils-reproducteurs'), $html$<p>L’<strong>hypothalamus</strong> sécrète la GnRH, qui stimule l’<strong>hypophyse</strong>. Celle-ci libère deux hormones, FSH et LH, qui agissent sur les gonades.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')), 6, 'heredite-humaine', 'Hérédité humaine', 'Arbres généalogiques, maladies héréditaires, groupes sanguins, anomalies chromosomiques.', 6, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'heredite-humaine'), 1, 'l-heredite-chez-l-espece-humaine', 'L’hérédité chez l’espèce humaine', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'L2')) and c.slug = 'heredite-humaine') and slug = 'l-heredite-chez-l-espece-humaine'), $html$<p>On étudie la transmission des caractères humains à l’aide d’<strong>arbres généalogiques</strong> (carrés pour les hommes, ronds pour les femmes, symboles pleins pour les atteints).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 1, 'la-rhetorique-arabe', 'La rhétorique arabe', 'La balāgha : comparaison, métaphore, métonymie, figures de sonorité et d’opposition.', 1, 'published', 'Langue', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-rhetorique-arabe'), 1, 'les-figures-de-la-balagha', 'Les figures de la balāgha', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-rhetorique-arabe') and slug = 'les-figures-de-la-balagha'), $html$<table><thead><tr><th scope="col">Figure</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>tashbīh</td><td>comparaison, avec un outil (ka, mithl)</td></tr><tr><td>isti‘āra</td><td>métaphore : comparaison sans outil ni comparé</td></tr><tr><td>kināya</td><td>expression indirecte (métonymie, périphrase)</td></tr><tr><td>ṭibāq</td><td>rapprochement de deux contraires (antithèse)</td></tr><tr><td>jinās</td><td>rapprochement de deux mots aux sons proches (paronomase)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 2, 'la-metrique-arabe', 'La métrique arabe', 'Le ‘arūḍ d’al-Khalīl, les mètres, la rime.', 2, 'published', 'Langue', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-metrique-arabe'), 1, 'le-arud', 'Le ‘arūḍ', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-metrique-arabe') and slug = 'le-arud'), $html$<ul><li>al-Khalīl ibn Aḥmad (VIII<sup>e</sup> siècle) a décrit les règles de la métrique arabe : le <strong>‘arūḍ</strong> ;</li><li>il décrit quinze mètres (buḥūr) ; le grammairien al-Akhfash en ajoute un seizième. Les plus courants sont le ṭawīl, le basīṭ, le kāmil et le wāfir ;</li><li>le vers classique a deux hémistiches ; toute la qaṣīda garde la même rime et la même lettre finale (rawī).</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 3, 'la-litterature-abbasside', 'La littérature abbasside', 'Poésie et prose de l’âge classique : al-Mutanabbī, Abū Nuwās, al-Jāḥiẓ, Ibn al-Muqaffa‘.', 3, 'published', 'Littérature', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-litterature-abbasside'), 1, 'l-age-d-or-de-bagdad', 'L’âge d’or de Bagdad', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-litterature-abbasside') and slug = 'l-age-d-or-de-bagdad'), $html$<ul><li>sous les Abbassides (750-1258), Bagdad devient un grand centre culturel ;</li><li>poésie : Abū Nuwās renouvelle les thèmes ; al-Mutanabbī est considéré comme l’un des plus grands poètes arabes ;</li><li>prose : al-Jāḥiẓ (essais, <em>Le Livre des animaux</em>), Ibn al-Muqaffa‘ (<em>Kalīla wa Dimna</em>, fables) ;</li><li>les contes des <em>Mille et Une Nuits</em> se sont formés sur plusieurs siècles.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 4, 'la-nahda-et-la-litterature-arabe-moderne', 'La Nahda et la littérature arabe moderne', 'La renaissance arabe du XIXe siècle et les grands auteurs du XXe siècle.', 4, 'published', 'Littérature', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-nahda-et-la-litterature-arabe-moderne'), 1, 'renaissance-et-modernite', 'Renaissance et modernité', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-nahda-et-la-litterature-arabe-moderne') and slug = 'renaissance-et-modernite'), $html$<ul><li>la <strong>Nahda</strong> (« renaissance ») au XIX<sup>e</sup> siècle renouvelle la langue, la presse et la littérature ;</li><li>Aḥmad Shawqī est surnommé « le prince des poètes » ;</li><li>Ṭāhā Ḥusayn raconte son enfance dans <em>Al-Ayyām</em> (Le Livre des jours) ;</li><li>Naguib Mahfouz reçoit le prix Nobel de littérature en 1988 ; Mahmoud Darwich est le grand poète palestinien.</li></ul>$html$);
