insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'methodes-dissertation-et-commentaire-en-arabe') and slug = 'rediger-en-arabe'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Introduction (al-muqaddima) : présenter le sujet et poser la question.</li><li>Développement (al-‘arḍ) : idées organisées en paragraphes, avec des exemples tirés des textes étudiés.</li><li>Conclusion (al-khātima) : répondre à la question et ouvrir.</li><li>Soigner les liaisons (wa, fa, thumma, lākin) et la correction de l’i‘rāb.</li></ol></div>$html$);
