insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'les-sciences-dans-la-civilisation-arabo-islamique') and slug = 'savants-et-savoirs'), $html$<table><thead><tr><th scope="col">Savant</th><th scope="col">Domaine</th></tr></thead><tbody><tr><td>al-Khwārizmī</td><td>mathématiques : l’algèbre (al-jabr) ; son nom a donné « algorithme »</td></tr><tr><td>Ibn Sīnā (Avicenne)</td><td>médecine, philosophie</td></tr><tr><td>Ibn Rushd (Averroès)</td><td>philosophie, commentaire d’Aristote</td></tr><tr><td>al-Idrīsī</td><td>géographie, cartographie</td></tr><tr><td>Ibn Khaldūn</td><td>histoire et sociologie (<em>la Muqaddima</em>)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 7, 'l-islam-en-afrique-de-l-ouest', 'L’islam en Afrique de l’Ouest', 'Diffusion de l’islam, centres de savoir, confréries.', 7, 'published', 'Civilisation arabo-islamique', '[{"title":"Épreuves et coefficients du Bac par série (samabac.sn, 2019), à confirmer avec l’Office du Bac","url":"https://samabac.sn/baccalaureat-les-epreuves-par-serie-les-coefficients-et-le-nombre-de-point-demande","kind":"external"},{"title":"Chapitres indicatifs : programme officiel non trouvé (à valider)","kind":"diangal"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-islam-en-afrique-de-l-ouest'), 1, 'diffusion-et-confreries', 'Diffusion et confréries', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-islam-en-afrique-de-l-ouest') and slug = 'diffusion-et-confreries'), $html$<ul><li>l’islam gagne l’Afrique de l’Ouest par le commerce transsaharien et les lettrés ; les Almoravides (XI<sup>e</sup> siècle) jouent un rôle important ;</li><li>Tombouctou et sa mosquée de Sankoré sont un grand foyer de savoir (Ahmed Baba, XVI<sup>e</sup> siècle) ;</li><li>au Sénégal, les confréries soufies structurent la vie religieuse : Qadiriyya, Tijaniyya, Mouridiyya, Layène.</li></ul>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 1, 'origines-et-specificite-de-la-reflexion-philosophique', 'Origines et spécificité de la réflexion philosophique', 'Définir la philosophie, la distinguer du sens commun, du mythe, de la religion et de la science.', 1, 'published', 'La réflexion philosophique', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique'), 1, 'qu-est-ce-que-la-philosophie', 'Qu’est-ce que la philosophie ?', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'qu-est-ce-que-la-philosophie'), $html$<p>Étymologiquement, la philosophie est l’« amour de la sagesse » (en grec <em>philein</em>, aimer, et <em>sophia</em>, sagesse). Le philosophe n’est pas un sage qui possède la vérité : il la cherche.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique'), 2, 'philosophie-mythe-religion-et-science', 'Philosophie, mythe, religion et science', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'philosophie-mythe-religion-et-science'), $html$<p>La philosophie naît en Grèce au VI<sup>e</sup> siècle avant notre ère, quand des penseurs (Thalès, Héraclite, puis Socrate, Platon, Aristote) cherchent à expliquer le monde par des raisons et non plus par des récits sur les dieux. On parle du passage du <em>mythos</em> (récit) au <em>logos</em> (discours rationnel).</p>
