insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'les-fonctions-de-la-pensee-philosophique'), $html$<ul><li><strong>fonction critique</strong> : examiner les préjugés, les opinions et les pouvoirs ;</li><li><strong>fonction libératrice</strong> : apprendre à penser par soi-même ;</li><li><strong>fonction de synthèse</strong> : relier les savoirs dispersés et s’interroger sur leurs fondements ;</li><li><strong>fonction éthique</strong> : réfléchir à la manière de bien vivre et d’agir.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques'), 2, 'philosophie-et-ideologie', 'Philosophie et idéologie', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'philosophie-et-ideologie'), $html$<p>Une <strong>idéologie</strong> est un système d’idées qui justifie les intérêts d’un groupe ou d’un pouvoir, en se présentant comme une vérité évidente.</p>
