insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'conscience-et-inconscient') and slug = 'la-conscience'), $html$<p>La <strong>conscience psychologique</strong> est la connaissance que le sujet a de lui-même et de ce qu’il vit. La <strong>conscience morale</strong> est la faculté de juger le bien et le mal de ses actes.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'conscience-et-inconscient'), 2, 'l-inconscient-psychique-et-la-personnalite', 'L’inconscient psychique et la personnalité', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'conscience-et-inconscient') and slug = 'l-inconscient-psychique-et-la-personnalite'), $html$<p>Pour Freud, une grande partie de notre vie psychique échappe à la conscience : c’est l’<strong>inconscient</strong>. Des désirs refoulés, souvent liés à l’enfance, s’y trouvent et cherchent à s’exprimer.</p>
