insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-liberte'), 1, 'liberte-determinisme-et-fatalisme', 'Liberté, déterminisme et fatalisme', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-liberte') and slug = 'liberte-determinisme-et-fatalisme'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>liberté</td><td>pouvoir d’agir selon sa volonté, sans contrainte</td></tr><tr><td>déterminisme</td><td>tout phénomène a des causes qui le produisent nécessairement (sciences)</td></tr><tr><td>fatalisme</td><td>croyance que tout est écrit d’avance, quoi qu’on fasse</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-liberte'), 2, 'libre-arbitre-et-responsabilite', 'Libre-arbitre et responsabilité', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-liberte') and slug = 'libre-arbitre-et-responsabilite'), $html$<p>Le <strong>libre-arbitre</strong> est le pouvoir de choisir entre plusieurs possibles. Pour Descartes, la volonté est infinie : c’est en elle que l’homme ressemble le plus à Dieu.</p>
