insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-amerique-latine'), 1, 'milieux-naturels-et-populations', 'Milieux naturels et populations', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-amerique-latine') and slug = 'milieux-naturels-et-populations'), $html$<ul><li>des milieux très variés : cordillère des Andes, forêt amazonienne, pampa, déserts (Atacama) ;</li><li>une population métissée (Amérindiens, Européens, descendants d’Africains) et très urbanisée ;</li><li>de grandes métropoles (Mexico, São Paulo, Buenos Aires) entourées de quartiers pauvres (favelas, bidonvilles) ;</li><li>des inégalités sociales parmi les plus fortes du monde.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-amerique-latine'), 2, 'le-bresil-une-puissance-du-tiers-monde', 'Le Brésil, une puissance du tiers-monde', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-amerique-latine') and slug = 'le-bresil-une-puissance-du-tiers-monde'), $html$<table><thead><tr><th scope="col">Atouts</th><th scope="col">Problèmes</th></tr></thead><tbody><tr><td>territoire immense (8,5 millions de km²), environ 203 millions d’habitants</td><td>inégalités sociales et régionales (Sud-Est riche, Nordeste pauvre)</td></tr><tr><td>agriculture d’exportation : soja, café, sucre, viande</td><td>déforestation de l’Amazonie</td></tr><tr><td>industrie (aéronautique, automobile), pétrole offshore</td><td>violence urbaine, favelas</td></tr><tr><td>membre des BRICS</td><td>instabilité politique et économique</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 12, 'l-afrique-et-le-senegal', 'L’Afrique et le Sénégal', 'Problèmes et perspectives de l’Afrique ; le Sénégal : milieux, population, eau, économie.', 12, 'published', 'Géographie', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal'), 1, 'problemes-et-perspectives-de-developpement-de-l-afrique', 'Problèmes et perspectives de développement de l’Afrique', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'problemes-et-perspectives-de-developpement-de-l-afrique'), $html$<table><thead><tr><th scope="col">Problèmes</th><th scope="col">Perspectives</th></tr></thead><tbody><tr><td>pauvreté, faible industrialisation, dépendance aux matières premières</td><td>ressources minières et énergétiques considérables</td></tr><tr><td>dette, instabilité politique, conflits</td><td>population jeune (environ 1,4 milliard d’habitants), urbanisation, marché intérieur</td></tr><tr><td>insuffisance des infrastructures et des services (santé, éducation)</td><td>intégration régionale : CEDEAO, Union africaine, ZLECAf</td></tr><tr><td>effets du changement climatique (désertification, sécheresses)</td><td>numérique (paiement mobile), énergies renouvelables</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal'), 2, 'le-senegal-milieux-naturels-et-populations', 'Le Sénégal : milieux naturels et populations', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'le-senegal-milieux-naturels-et-populations'), $html$<ul><li>196 722 km², 14 régions ; un relief plat (sauf le Sud-Est) ; climat tropical, du sahélien au nord au soudano-guinéen en Casamance ;</li><li>une saison des pluies (de juin-juillet à octobre) et une longue saison sèche ;</li><li>fleuves Sénégal, Gambie, Casamance, Saloum ;</li><li>environ 18 millions d’habitants (recensement de 2023), une population très jeune ;</li><li>une population inégalement répartie : forte concentration à Dakar et dans l’Ouest, faibles densités à l’Est ;</li><li>exode rural et émigration (vers l’Europe, les pays voisins).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal'), 3, 'la-question-de-l-eau-au-senegal', 'La question de l’eau au Sénégal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'la-question-de-l-eau-au-senegal'), $html$<ul><li>des pluies faibles et irrégulières au nord, des sécheresses (années 1970-1980) ;</li><li>l’OMVS (Sénégal, Mali, Mauritanie, Guinée) a construit les barrages de Diama (contre la remontée de l’eau salée) et de Manantali (irrigation, électricité) ;</li><li>Dakar est alimentée en partie par le lac de Guiers, à plus de 200 km, et par des forages ; la nappe est menacée par la salinisation ;</li><li>l’agriculture irriguée se développe dans la vallée du fleuve (riz, tomate, oignon).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal'), 4, 'problemes-economiques-et-politiques-de-developpement-du-senegal', 'Problèmes économiques et politiques de développement du Sénégal', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'problemes-economiques-et-politiques-de-developpement-du-senegal'), $html$<table><thead><tr><th scope="col">Secteur</th><th scope="col">Situation</th></tr></thead><tbody><tr><td>agriculture</td><td>arachide, mil, riz, horticulture ; dépendance aux pluies ; importations de riz</td></tr><tr><td>pêche</td><td>première ressource d’exportation, menacée par la surpêche</td></tr><tr><td>mines et énergie</td><td>phosphates, or (Sabodala), zircon ; pétrole (Sangomar, depuis 2024) et gaz</td></tr><tr><td>services</td><td>port de Dakar, télécommunications, tourisme, transferts des émigrés</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 1, 'le-surrealisme', 'Le surréalisme', 'Origines, principes et techniques du surréalisme ; ses liens avec la négritude.', 1, 'published', 'Littérature', '[{"title":"Nouveaux programmes de français, enseignement secondaire général (Commission nationale de français, 2009), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Francais_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-surrealisme'), 1, 'le-mouvement-surrealiste', 'Le mouvement surréaliste', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-surrealisme') and slug = 'le-mouvement-surrealiste'), $html$<p>Né après la Première Guerre mondiale, dans le prolongement du mouvement Dada, le <strong>surréalisme</strong> est fondé par André Breton (<em>Manifeste du surréalisme</em>, 1924). Il veut libérer l’homme de la logique, de la morale bourgeoise et des conventions littéraires.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-surrealisme'), 2, 'surrealisme-et-poesie-de-la-negritude', 'Surréalisme et poésie de la négritude', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-surrealisme') and slug = 'surrealisme-et-poesie-de-la-negritude'), $html$<p>Les poètes de la négritude ont trouvé dans le surréalisme une arme contre la raison occidentale qui justifiait la colonisation, et une liberté d’images proche de l’oralité africaine.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 2, 'la-poesie', 'La poésie', 'Versification, poésie classique et romantique, poésie de la négritude.', 2, 'published', 'Esthétique des genres', '[{"title":"Nouveaux programmes de français, enseignement secondaire général (Commission nationale de français, 2009), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Francais_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie'), 1, 'les-outils-de-la-versification', 'Les outils de la versification', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie') and slug = 'les-outils-de-la-versification'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>vers</td><td>ligne de poème ; l’alexandrin compte 12 syllabes, le décasyllabe 10, l’octosyllabe 8</td></tr><tr><td>e muet</td><td>se prononce devant une consonne, s’élide devant une voyelle ou en fin de vers</td></tr><tr><td>diérèse, synérèse</td><td>prononcer une syllabe en deux (li-on) ou deux en une (lion)</td></tr><tr><td>rimes</td><td>plates (AABB), croisées (ABAB), embrassées (ABBA) ; pauvres, suffisantes ou riches</td></tr><tr><td>strophe</td><td>groupe de vers : quatrain (4), tercet (3)…</td></tr><tr><td>sonnet</td><td>deux quatrains et deux tercets</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie'), 2, 'poesie-classique-et-romantique', 'Poésie classique et romantique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie') and slug = 'poesie-classique-et-romantique'), $html$<table><thead><tr><th scope="col">Œuvre (liste officielle)</th><th scope="col">Ce qu’il faut savoir</th></tr></thead><tbody><tr><td>Boileau, <em>L’Art poétique</em> (1674)</td><td>texte théorique du classicisme : clarté, raison, imitation des Anciens, règles</td></tr><tr><td>La Fontaine, <em>Fables</em></td><td>récits en vers, souvent animaliers, qui instruisent en plaisant ; morale explicite ou implicite</td></tr><tr><td>Victor Hugo, <em>Les Contemplations</em> (1856)</td><td>poésie romantique et lyrique : souvenirs, deuil de sa fille Léopoldine, méditation</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie'), 3, 'la-poesie-de-la-negritude', 'La poésie de la négritude', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-poesie') and slug = 'la-poesie-de-la-negritude'), $html$<p>La <strong>négritude</strong>, mouvement né dans les années 1930 à Paris autour de Senghor, Césaire et Damas, revendique la dignité et les valeurs culturelles du monde noir.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 3, 'le-roman', 'Le roman', 'Narrateur et focalisation, personnages, temps ; romans de la liste officielle.', 3, 'published', 'Esthétique des genres', '[{"title":"Nouveaux programmes de français, enseignement secondaire général (Commission nationale de français, 2009), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Francais_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-roman'), 1, 'les-outils-de-l-analyse-du-roman', 'Les outils de l’analyse du roman', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-roman') and slug = 'les-outils-de-l-analyse-du-roman'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Ce qu’on observe</th></tr></thead><tbody><tr><td>narrateur</td><td>interne (« je » personnage) ou externe (« il »)</td></tr><tr><td>focalisation</td><td>zéro (narrateur omniscient), interne (à travers un personnage), externe (de l’extérieur, comme une caméra)</td></tr><tr><td>personnages</td><td>portrait physique et moral, rôle dans l’action (schéma actanciel)</td></tr><tr><td>temps du récit</td><td>ordre (retour en arrière, anticipation), rythme (scène, sommaire, ellipse, pause)</td></tr><tr><td>discours rapporté</td><td>direct, indirect, indirect libre</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-roman'), 2, 'les-romans-au-programme', 'Les romans au programme', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'le-roman') and slug = 'les-romans-au-programme'), $html$<table><thead><tr><th scope="col">Œuvre</th><th scope="col">Repères</th></tr></thead><tbody><tr><td>Abbé Prévost, <em>Manon Lescaut</em> (1731)</td><td>passion destructrice du chevalier Des Grieux pour Manon ; récit à la première personne</td></tr><tr><td>Albert Camus, <em>L’Étranger</em> (1942)</td><td>Meursault, indifférent au monde, tue un homme ; l’absurde ; style neutre, phrases courtes</td></tr><tr><td>Ahmadou Kourouma, <em>Les Soleils des indépendances</em> (1968)</td><td>Fama, prince malinké déchu après les indépendances ; désillusion politique ; français « malinkisé »</td></tr><tr><td>Amadou Hampâté Bâ, <em>L’Étrange Destin de Wangrin</em> (1973)</td><td>un interprète rusé sous la colonisation en Afrique de l’Ouest ; récit nourri de tradition orale</td></tr></tbody></table>
