insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 6, 'la-dissertation-litteraire', 'La dissertation littéraire', 'Analyser un sujet, problématiser, construire un plan et rédiger.', 6, 'published', 'Exercices du baccalauréat', '[{"title":"Nouveaux programmes de français, enseignement secondaire général (Commission nationale de français, 2009), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Francais_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-dissertation-litteraire'), 1, 'analyser-le-sujet-et-construire-le-plan', 'Analyser le sujet et construire le plan', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-dissertation-litteraire') and slug = 'analyser-le-sujet-et-construire-le-plan'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire le sujet, souligner les mots clés et les définir.</li><li>Identifier la thèse proposée (souvent une citation) et la question posée.</li><li>Formuler la problématique.</li><li>Rechercher idées et exemples précis tirés des œuvres étudiées, puis les classer.</li><li>Choisir un plan : dialectique (oui / mais / dépassement), thématique ou analytique.</li></ol></div>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-dissertation-litteraire'), 2, 'rediger-la-dissertation', 'Rédiger la dissertation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'la-dissertation-litteraire') and slug = 'rediger-la-dissertation'), $html$<ul><li><strong>introduction</strong> : amorce, présentation et citation du sujet, problématique, annonce du plan ;</li><li><strong>développement</strong> : chaque partie a une idée directrice ; chaque paragraphe = un argument + un exemple analysé ;</li><li><strong>transitions</strong> : bilan de la partie et annonce de la suivante ;</li><li><strong>conclusion</strong> : bilan, réponse à la problématique, ouverture.</li></ul>
