insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'trade-professions-and-occupations') and slug = 'obligation-necessity-and-the-letter-of-application'), $html$<table><thead><tr><th scope="col">Function</th><th scope="col">Structure</th><th scope="col">Example</th></tr></thead><tbody><tr><td>obligation</td><td>must / have to</td><td>Workers must wear a helmet.</td></tr><tr><td>absence of obligation</td><td>don’t have to / needn’t</td><td>You don’t have to wear a uniform.</td></tr><tr><td>prohibition</td><td>mustn’t / be not allowed to</td><td>Children mustn’t work in mines.</td></tr><tr><td>past obligation</td><td>had to</td><td>He had to work at the age of ten.</td></tr></tbody></table>
