insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'free-time-and-entertainment') and slug = 'expressing-likes-dislikes-and-preferences'), $html$<table><thead><tr><th scope="col">Structure</th><th scope="col">Example</th></tr></thead><tbody><tr><td>like / love / enjoy / hate + verb-ing</td><td>I enjoy reading novels.</td></tr><tr><td>prefer + noun / verb-ing + to</td><td>She prefers football to basketball.</td></tr><tr><td>would rather + base verb (+ than)</td><td>I would rather stay at home than go out tonight.</td></tr><tr><td>would like + to + verb</td><td>I would like to visit Gorée.</td></tr></tbody></table>
