insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'cultural-heritage'), 1, 'customs-ceremonies-and-values', 'Customs, ceremonies and values', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'cultural-heritage') and slug = 'customs-ceremonies-and-values'), $html$<h2>Reading: Teranga</h2><p>Senegal is often called the country of teranga, a Wolof word meaning hospitality. Guests are welcomed, fed and treated with respect. Muslims and Christians live together peacefully and often celebrate each other’s religious festivals.</p><p>Naming ceremonies, weddings and religious pilgrimages bring families together. These customs teach values such as solidarity, tolerance and generosity.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'cultural-heritage'), 2, 'relative-clauses', 'Relative clauses', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'cultural-heritage') and slug = 'relative-clauses'), $html$<table><thead><tr><th scope="col">Pronoun</th><th scope="col">Use</th><th scope="col">Example</th></tr></thead><tbody><tr><td>who</td><td>people</td><td>The griot who sang at the wedding is famous.</td></tr><tr><td>which / that</td><td>things</td><td>Gorée is an island which reminds us of the slave trade.</td></tr><tr><td>whose</td><td>possession</td><td>Senghor, whose poems are studied in schools, was a president.</td></tr><tr><td>where</td><td>places</td><td>Touba is the city where the Grand Magal takes place.</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 7, 'information-and-communication', 'Information and communication', 'Media, ICTs, advertisements, the right to information ; reported speech.', 7, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'information-and-communication'), 1, 'the-media-and-the-information-explosion', 'The media and the information explosion', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'information-and-communication') and slug = 'the-media-and-the-information-explosion'), $html$<h2>Reading: Fake news</h2><p>With social networks, anyone can publish information. News travels faster than ever, but so do rumours and fake news. Before sharing a message, we should check its source and compare it with other reliable media.</p><p>Advertisements are everywhere too. They inform consumers but also try to make them buy things they do not need.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'information-and-communication'), 2, 'reported-speech', 'Reported speech', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'information-and-communication') and slug = 'reported-speech'), $html$<table><thead><tr><th scope="col">Direct speech</th><th scope="col">Reported speech</th></tr></thead><tbody><tr><td>“I am tired,” she said.</td><td>She said (that) she was tired.</td></tr><tr><td>“We will come,” they said.</td><td>They said they would come.</td></tr><tr><td>“I saw him yesterday,” he said.</td><td>He said he had seen him the day before.</td></tr><tr><td>“Where do you live?” he asked.</td><td>He asked me where I lived.</td></tr><tr><td>“Are you ready?” she asked.</td><td>She asked if I was ready.</td></tr></tbody></table>
