insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'derivabilite') and slug = 'nombre-derive-et-tangente'), $html$<p>Le <strong>nombre dérivé</strong> de f en x₀ est la limite, si elle existe, du taux d’accroissement <span class="frac"><span>f(x) − f(x₀)</span><span>x − x₀</span></span>. C’est le coefficient directeur de la tangente à la courbe au point d’abscisse x₀.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'derivabilite'), 2, 'derivee-et-sens-de-variation', 'Dérivée et sens de variation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'derivabilite') and slug = 'derivee-et-sens-de-variation'), $html$<ul><li>si f’ &gt; 0 sur un intervalle I (sauf en quelques points), f est strictement croissante sur I ;</li><li>si f’ &lt; 0, f est strictement décroissante ;</li><li>si f’ s’annule en changeant de signe en x₀, f a un extremum en x₀.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')), 6, 'etude-de-fonctions', 'Étude de fonctions', 'Symétries, asymptotes, plan d’étude, valeur absolue et résolutions graphiques.', 6, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
