insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'etude-de-fonctions') and slug = 'parite-et-elements-de-symetrie'), $html$<table><thead><tr><th scope="col">Propriété</th><th scope="col">Condition (pour tout x de D<sub>f</sub>, −x ∈ D<sub>f</sub>)</th><th scope="col">Courbe</th></tr></thead><tbody><tr><td>f paire</td><td>f(−x) = f(x)</td><td>symétrique par rapport à l’axe des ordonnées</td></tr><tr><td>f impaire</td><td>f(−x) = −f(x)</td><td>symétrique par rapport à l’origine</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'etude-de-fonctions'), 2, 'asymptotes-et-branches-infinies', 'Asymptotes et branches infinies', true, 'published', 15, now());
