insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'LA')) and c.slug = 'fonction-exponentielle') and slug = 'la-fonction-exponentielle-definition-et-proprietes'), $html$<p>ln est une bijection de ]0 ; +∞[ sur ℝ. Sa réciproque est la <strong>fonction exponentielle</strong>, notée exp, avec exp(x) = e<sup>x</sup>.</p>
