insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'nombres-complexes') and slug = 'forme-algebrique-et-conjugue'), $html$<p>L’ensemble ℂ des <strong>nombres complexes</strong> prolonge ℝ : il contient un nombre i tel que i² = −1. Tout complexe s’écrit de façon unique z = a + ib (a, b réels) : a = Re(z) est la partie réelle, b = Im(z) la partie imaginaire.</p>
