insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'barycentres-et-lignes-de-niveau') and slug = 'barycentre-de-n-points-ponderes'), $html$<p>Soient des points A₁, …, A<sub>n</sub> affectés des coefficients α₁, …, α<sub>n</sub> de somme S = α₁ + … + α<sub>n</sub> ≠ 0. Il existe un unique point G, le <strong>barycentre</strong>, tel que :</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'barycentres-et-lignes-de-niveau'), 2, 'fonctions-vectorielles-et-scalaires-de-leibniz', 'Fonctions vectorielles et scalaires de Leibniz', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'barycentres-et-lignes-de-niveau') and slug = 'fonctions-vectorielles-et-scalaires-de-leibniz'), $html$<p>On étudie f(M) = α₁MA₁² + … + α<sub>n</sub>MA<sub>n</sub>² pour trouver les <strong>lignes de niveau</strong> f(M) = k.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'barycentres-et-lignes-de-niveau'), 3, 'lignes-de-niveau-et-points-cocycliques', 'Lignes de niveau et points cocycliques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'barycentres-et-lignes-de-niveau') and slug = 'lignes-de-niveau-et-points-cocycliques'), $html$<table><thead><tr><th scope="col">Ensemble des points M tels que</th><th scope="col">Nature</th></tr></thead><tbody><tr><td><span class="frac"><span>MA</span><span>MB</span></span> = k, k ≠ 1</td><td>cercle (cercle d’Apollonius), car MA² − k²MB² = 0</td></tr><tr><td><span class="frac"><span>MA</span><span>MB</span></span> = 1</td><td>médiatrice de [AB]</td></tr><tr><td>MA⃗ · MB⃗ = k</td><td>cercle de centre I milieu de [AB], car MA⃗ · MB⃗ = MI² − <span class="frac"><span>AB²</span><span>4</span></span></td></tr><tr><td>(MA⃗, MB⃗) = α [2π]</td><td>arc de cercle d’extrémités A et B (privé de A et B)</td></tr><tr><td>(MA⃗, MB⃗) = α [π]</td><td>cercle passant par A et B (privé de A et B)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')), 12, 'isometries-et-similitudes-planes', 'Isométries et similitudes planes', 'Isométries, similitudes directes et leur écriture complexe, triangles semblables.', 12, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'isometries-et-similitudes-planes'), 1, 'isometries-du-plan', 'Isométries du plan', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'isometries-et-similitudes-planes') and slug = 'isometries-du-plan'), $html$<p>Une <strong>isométrie</strong> conserve les distances : translations, rotations, réflexions (symétries axiales), symétries centrales et leurs composées. Ce sont des applications affines qui conservent le barycentre, l’alignement, les angles géométriques et les aires.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'isometries-et-similitudes-planes'), 2, 'similitudes-planes-directes', 'Similitudes planes directes', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'isometries-et-similitudes-planes') and slug = 'similitudes-planes-directes'), $html$<p>Une <strong>similitude directe</strong> est une transformation du plan dont l’écriture complexe est z’ = az + b, avec a ≠ 0. Elle multiplie les distances par k = |a| et conserve les angles orientés.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'isometries-et-similitudes-planes'), 3, 'triangles-semblables', 'Triangles semblables', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'isometries-et-similitudes-planes') and slug = 'triangles-semblables'), $html$<p>Deux triangles ABC et A’B’C’ sont <strong>directement semblables</strong> s’il existe une similitude directe qui transforme A en A’, B en B’ et C en C’.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')), 13, 'produit-vectoriel-et-produit-mixte', 'Produit vectoriel et produit mixte', 'Orientation de l’espace, produit vectoriel, aires, distances, produit mixte et volumes.', 13, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'produit-vectoriel-et-produit-mixte'), 1, 'orientation-de-l-espace-et-produit-vectoriel', 'Orientation de l’espace et produit vectoriel', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'produit-vectoriel-et-produit-mixte') and slug = 'orientation-de-l-espace-et-produit-vectoriel'), $html$<p>Un repère (O ; i⃗, j⃗, k⃗) est <strong>direct</strong> si un observateur debout sur k⃗ (le « bonhomme d’Ampère ») voit i⃗ tourner vers j⃗ dans le sens inverse des aiguilles d’une montre.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'produit-vectoriel-et-produit-mixte'), 2, 'applications-du-produit-vectoriel', 'Applications du produit vectoriel', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'produit-vectoriel-et-produit-mixte') and slug = 'applications-du-produit-vectoriel'), $html$<ul><li>Aire du parallélogramme ABDC : ‖AB⃗ ∧ AC⃗‖ ; aire du triangle ABC : <span class="frac"><span>1</span><span>2</span></span>‖AB⃗ ∧ AC⃗‖.</li><li>AB⃗ ∧ AC⃗ est un <strong>vecteur normal</strong> au plan (ABC) : il donne une équation du plan.</li><li>A, B, C sont alignés si et seulement si AB⃗ ∧ AC⃗ = 0⃗.</li><li>Distance d’un point M à la droite (AB) : d = <span class="frac"><span>‖AM⃗ ∧ AB⃗‖</span><span>AB</span></span>.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'produit-vectoriel-et-produit-mixte'), 3, 'produit-mixte-et-volumes', 'Produit mixte et volumes', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'produit-vectoriel-et-produit-mixte') and slug = 'produit-mixte-et-volumes'), $html$<p>Le <strong>produit mixte</strong> de trois vecteurs est le réel [u⃗, v⃗, w⃗] = (u⃗ ∧ v⃗) · w⃗. Dans un repère orthonormé direct, c’est le déterminant des trois vecteurs.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')), 14, 'transformations-de-l-espace', 'Transformations de l’espace', 'Translations, homothéties, réflexions, rotations autour d’un axe et leurs composées.', 14, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'transformations-de-l-espace'), 1, 'translations-homotheties-et-reflexions-de-l-espace', 'Translations, homothéties et réflexions de l’espace', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'transformations-de-l-espace') and slug = 'translations-homotheties-et-reflexions-de-l-espace'), $html$<table><thead><tr><th scope="col">Transformation</th><th scope="col">Définition (M a pour image M’)</th></tr></thead><tbody><tr><td>Translation de vecteur u⃗</td><td>MM’⃗ = u⃗</td></tr><tr><td>Homothétie de centre Ω et de rapport k ≠ 0</td><td>ΩM’⃗ = kΩM⃗</td></tr><tr><td>Réflexion de plan P</td><td>P est le plan médiateur de [MM’] (M’ = M si M ∈ P)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'transformations-de-l-espace'), 2, 'rotations-et-demi-tours-de-l-espace', 'Rotations et demi-tours de l’espace', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'transformations-de-l-espace') and slug = 'rotations-et-demi-tours-de-l-espace'), $html$<p>Soit Δ une droite orientée (l’<strong>axe</strong>) et θ un réel. La <strong>rotation</strong> d’axe Δ et d’angle θ transforme M en M’ situé dans le plan perpendiculaire à Δ passant par M, avec, si H est le point de Δ de ce plan : HM’ = HM et (HM⃗, HM’⃗) = θ, l’angle étant orienté par l’orientation de Δ.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')), 15, 'courbes-parametrees', 'Courbes paramétrées', 'Vecteur dérivé, tangente, vitesse et accélération, cycloïde et astroïde.', 15, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'courbes-parametrees'), 1, 'courbes-parametrees-et-tangentes', 'Courbes paramétrées et tangentes', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'courbes-parametrees') and slug = 'courbes-parametrees-et-tangentes'), $html$<p>Quand t décrit un intervalle I, le point M(t) de coordonnées x(t) et y(t) décrit une <strong>courbe paramétrée</strong> : OM⃗(t) = x(t) i⃗ + y(t) j⃗.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'courbes-parametrees'), 2, 'vitesse-acceleration-et-courbes-remarquables', 'Vitesse, accélération et courbes remarquables', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'courbes-parametrees') and slug = 'vitesse-acceleration-et-courbes-remarquables'), $html$<p>Si t est le temps, M(t) est la position d’un mobile. Le <strong>vecteur vitesse</strong> est le vecteur dérivé v⃗(t) = (x’(t) ; y’(t)) ; le <strong>vecteur accélération</strong> est a⃗(t) = (x’’(t) ; y’’(t)). La vitesse scalaire est ‖v⃗(t)‖.</p>
