insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'champs-magnetiques') and slug = 'generalites-sur-le-champ-magnetique'), $html$<p>Un aimant ou un courant crée un <strong>champ magnétique</strong> B⃗ dans l’espace qui l’entoure. On le détecte avec une aiguille aimantée, qui s’oriente selon B⃗ (du pôle sud vers le pôle nord de l’aiguille).</p>
