insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'particule-chargee-dans-un-champ-magnetique-uniforme') and slug = 'applications-spectrographe-cyclotron-deflexion-magnetique'), $html$<ul><li><strong>Spectrographe de masse</strong> : des ions de même charge, accélérés sous la même tension, décrivent des demi-cercles de rayons différents selon leur masse (R ∝ √m) ; on sépare ainsi les isotopes.</li><li><strong>Cyclotron</strong> : la période T = 2πm/(|q|B) ne dépend pas de la vitesse ; une tension alternative de même période accélère la particule à chaque demi-tour.</li><li><strong>Déflexion magnétique</strong> : dans un tube de télévision ancien, des bobines dévient le faisceau d’électrons.</li></ul>
