insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'acide-fort-base-forte-et-dosage') and slug = 'acides-forts-et-bases-fortes'), $html$<p>Un <strong>acide fort</strong> réagit totalement avec l’eau : HCl + H₂O → H₃O⁺ + Cl⁻. Une <strong>base forte</strong> se dissocie totalement : NaOH → Na⁺ + OH⁻.</p>
