insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'acides-amines') and slug = 'structure-et-chiralite-des-acides-amines'), $html$<p>Un <strong>acide α-aminé</strong> a pour formule R−CH(NH₂)−COOH : le groupe amine et le groupe carboxyle sont portés par le même carbone. Ce sont les briques des protéines (glycine R = H, alanine R = CH₃…).</p>
