insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'acides-amines') and slug = 'amphion-et-liaison-peptidique'), $html$<p>En solution aqueuse, un acide α-aminé existe surtout sous forme d’<strong>amphion</strong> (ou zwitterion) : R−CH(NH₃⁺)−COO⁻. Il est à la fois acide (NH₃⁺) et basique (COO⁻) : c’est un <strong>ampholyte</strong>.</p>
