insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'resistance-des-materiaux-cisaillement-torsion-flexion') and slug = 'autres-sollicitations'), $html$<ul><li>cisaillement : τ = T ÷ S (goupilles, rivets) ;</li><li>torsion : un arbre qui transmet un couple se tord ; la contrainte est maximale à la surface ;</li><li>flexion : une poutre chargée fléchit ; les fibres d’un côté sont tendues, de l’autre comprimées ;</li><li>pour chaque sollicitation, on vérifie que la contrainte reste inférieure à la contrainte admissible.</li></ul>$html$);
