insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'TECH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'analyse-de-fabrication-et-gamme-d-usinage') and slug = 'preparer-une-fabrication'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Repérer les surfaces fonctionnelles et les cotes à respecter.</li><li>Choisir les surfaces de départ et la mise en position (6 points de contact au plus : isostatisme).</li><li>Ordonner les phases : ébauche avant finition, surfaces de référence d’abord.</li><li>Rédiger pour chaque phase un contrat de phase : machine, outils, conditions de coupe, cotes fabriquées.</li></ol></div>$html$);
