insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'TECH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'les-conditions-de-coupe') and slug = 'choisir-les-conditions-de-coupe'), $html$<ul><li>elles dépendent du matériau usiné, du matériau de l’outil (acier rapide, carbure) et de l’opération ;</li><li>un outil carbure accepte une vitesse de coupe plus élevée qu’un outil en acier rapide ;</li><li>en finition, l’avance et la profondeur de passe sont faibles pour un bon état de surface.</li></ul>
