insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'TECH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-grafcet') and slug = 'decrire-un-automatisme'), $html$<ul><li>le GRAFCET décrit le fonctionnement d’un système automatisé par des <strong>étapes</strong> (carrés) reliées par des <strong>transitions</strong> ;</li><li>une étape active déclenche des <strong>actions</strong> ; une transition est franchie quand l’étape précédente est active et que la <strong>réceptivité</strong> est vraie ;</li><li>l’étape initiale (double carré) est active au démarrage.</li></ul>
