insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'TECH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'capteurs-actionneurs-et-automates') and slug = 'la-chaine-d-un-systeme-automatise'), $html$<ul><li>chaîne d’information : acquérir (capteurs), traiter (automate), communiquer ;</li><li>chaîne d’énergie : alimenter, distribuer (préactionneurs), convertir (actionneurs : moteurs, vérins), transmettre ;</li><li>capteurs : fin de course mécanique, inductif (métaux), capacitif, photoélectrique ;</li><li>l’automate programmable (API) lit ses entrées, exécute son programme et commande ses sorties en boucle.</li></ul>$html$);
