insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'TECH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'qualite-et-maintenance') and slug = 'produire-bien-et-durablement'), $html$<ul><li>le contrôle qualité vérifie que les pièces respectent les spécifications ; une pièce hors tolérance est non conforme ;</li><li>maintenance corrective : réparer après une panne ; préventive : intervenir avant (graissage, remplacement planifié) ;</li><li>un carnet de maintenance trace les interventions.</li></ul>$html$);
