insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'les-fonctions-de-la-pensee-philosophique'), $html$<ul><li><strong>fonction critique</strong> : examiner les préjugés, les opinions et les pouvoirs ;</li><li><strong>fonction libératrice</strong> : apprendre à penser par soi-même ;</li><li><strong>fonction de synthèse</strong> : relier les savoirs dispersés et s’interroger sur leurs fondements ;</li><li><strong>fonction éthique</strong> : réfléchir à la manière de bien vivre et d’agir.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques'), 2, 'philosopher-aujourd-hui', 'Philosopher aujourd’hui', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'philosopher-aujourd-hui'), $html$<p>Les sciences ont pris à la philosophie beaucoup de ses anciens objets (la nature, la société, le psychisme). Mais de nouvelles questions apparaissent, que la science seule ne peut trancher :</p>
