insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'l-idee-d-une-philosophie-africaine') and slug = 'la-philosophie-africaine-debats-et-controverses'), $html$<p>L’approche de Tempels, appelée <strong>ethnophilosophie</strong>, a été vivement critiquée.</p>
