insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'nature-et-culture') and slug = 'langage-pensee-et-communication'), $html$<p>Le <strong>langage</strong> est la faculté de communiquer au moyen de signes. La langue est un système de signes propre à une communauté (wolof, pulaar, français…).</p>
