insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-roman') and slug = 'les-romans-au-programme'), $html$<table><thead><tr><th scope="col">Œuvre</th><th scope="col">Repères</th></tr></thead><tbody><tr><td>Abbé Prévost, <em>Manon Lescaut</em> (1731)</td><td>passion destructrice du chevalier Des Grieux pour Manon ; récit à la première personne</td></tr><tr><td>Albert Camus, <em>L’Étranger</em> (1942)</td><td>Meursault, indifférent au monde, tue un homme ; l’absurde ; style neutre, phrases courtes</td></tr><tr><td>Ahmadou Kourouma, <em>Les Soleils des indépendances</em> (1968)</td><td>Fama, prince malinké déchu après les indépendances ; désillusion politique ; français « malinkisé »</td></tr><tr><td>Amadou Hampâté Bâ, <em>L’Étrange Destin de Wangrin</em> (1973)</td><td>un interprète rusé sous la colonisation en Afrique de l’Ouest ; récit nourri de tradition orale</td></tr></tbody></table>
