insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-commentaire-de-texte'), 1, 'preparer-le-commentaire', 'Préparer le commentaire', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-commentaire-de-texte') and slug = 'preparer-le-commentaire'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Situer le texte : auteur, œuvre, genre, courant littéraire, époque.</li><li>Repérer le thème général et la situation d’énonciation (qui parle, à qui, quand, où ?).</li><li>Relever les procédés : lexique, figures de style, temps verbaux, ponctuation, rythme, versification.</li><li>Interpréter : quel effet chaque procédé produit-il ?</li></ol></div>
