insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'le-commentaire-de-texte') and slug = 'commentaire-suivi-et-commentaire-compose'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Commentaire suivi</th><th scope="col">Commentaire composé</th></tr></thead><tbody><tr><td>Démarche</td><td>suit le texte de la première à la dernière ligne, mouvement par mouvement</td><td>organise l’étude en centres d’intérêt (axes)</td></tr><tr><td>Plan</td><td>les mouvements du texte</td><td>deux ou trois axes de lecture</td></tr></tbody></table>
