insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S3')) and c.slug = 'economy') and slug = 'describing-graphs-and-making-comparisons'), $html$<table><thead><tr><th scope="col">Trend</th><th scope="col">Verbs</th><th scope="col">Adverbs</th></tr></thead><tbody><tr><td>going up</td><td>rise, increase, grow</td><td>sharply, steadily, slightly</td></tr><tr><td>going down</td><td>fall, decrease, drop</td><td>dramatically, gradually</td></tr><tr><td>no change</td><td>remain stable, level off</td><td></td></tr></tbody></table>
