insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques'), 2, 'suites-arithmetiques-et-geometriques', 'Suites arithmétiques et géométriques', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques') and slug = 'suites-arithmetiques-et-geometriques'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Suite arithmétique de raison r</th><th scope="col">Suite géométrique de raison q</th></tr></thead><tbody><tr><td>Définition</td><td>u<sub>n+1</sub> = u<sub>n</sub> + r</td><td>u<sub>n+1</sub> = q × u<sub>n</sub></td></tr><tr><td>Terme général</td><td>u<sub>n</sub> = u<sub>0</sub> + nr = u<sub>p</sub> + (n − p)r</td><td>u<sub>n</sub> = u<sub>0</sub> × q<sup>n</sup></td></tr><tr><td>Somme de termes consécutifs</td><td>(nombre de termes) × <span class="frac"><span>premier + dernier</span><span>2</span></span></td><td>premier × <span class="frac"><span>1 − q<sup>N</sup></span><span>1 − q</span></span> (N termes, q ≠ 1)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques'), 3, 'sens-de-variation-et-suites-bornees', 'Sens de variation et suites bornées', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques') and slug = 'sens-de-variation-et-suites-bornees'), $html$<p>Une suite (u<sub>n</sub>) est <strong>croissante</strong> si u<sub>n+1</sub> ≥ u<sub>n</sub> pour tout n, <strong>décroissante</strong> si u<sub>n+1</sub> ≤ u<sub>n</sub>, <strong>monotone</strong> si elle est l’un ou l’autre.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques'), 4, 'limites-de-suites-et-theoremes-de-convergence', 'Limites de suites et théorèmes de convergence', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques') and slug = 'limites-de-suites-et-theoremes-de-convergence'), $html$<p>Une suite <strong>converge</strong> vers ℓ si ses termes deviennent aussi proches de ℓ qu’on veut à partir d’un certain rang ; sinon elle <strong>diverge</strong> (limite infinie ou pas de limite). Les opérations sur les limites sont les mêmes que pour les fonctions.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques'), 5, 'suites-definies-par-u-n-1-f-u-n', 'Suites définies par u(n+1) = f(u(n))', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'suites-numeriques') and slug = 'suites-definies-par-u-n-1-f-u-n'), $html$<p>On représente une telle suite en traçant la courbe de f et la droite y = x : on place u<sub>0</sub> sur l’axe des abscisses, on « monte » à la courbe pour lire u<sub>1</sub> = f(u<sub>0</sub>), on le reporte sur l’axe grâce à la droite y = x, et ainsi de suite. Le dessin permet de conjecturer le sens de variation et la limite.</p>
