insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'calcul-integral') and slug = 'calcul-d-aires-et-de-volumes'), $html$<p>L’aire du domaine compris entre les courbes de f et g et les droites x = a et x = b (a &lt; b) vaut ∫<sub>a</sub><sup>b</sup> |f(x) − g(x)| dx unités d’aire. On découpe [a ; b] selon le signe de f − g.</p>
