insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reactions-nucleaires') and slug = 'fission-fusion-et-applications'), $html$<ul><li><strong>Fission</strong> : un noyau lourd (uranium 235) frappé par un neutron se casse en deux noyaux plus légers et libère 2 ou 3 neutrons : réaction en chaîne, contrôlée dans les centrales nucléaires ;</li><li><strong>Fusion</strong> : deux noyaux légers (isotopes de l’hydrogène) s’unissent ; c’est la source d’énergie du Soleil.</li></ul>
