insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'cinetique-chimique') and slug = 'facteurs-cinetiques'), $html$<ul><li><strong>concentration des réactifs</strong> : plus elle est grande, plus la réaction est rapide ;</li><li><strong>température</strong> : une élévation de température accélère la réaction (on chauffe pour accélérer, on refroidit brutalement par une « trempe » pour arrêter) ;</li><li><strong>catalyseur</strong> : il accélère la réaction sans être consommé et sans modifier l’état final (catalyse homogène, hétérogène ou enzymatique).</li></ul>
