insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'autoprotolyse-de-l-eau-ph-et-indicateurs-colores') and slug = 'autoprotolyse-de-l-eau-et-ph'), $html$<p>L’eau pure contient quelques ions provenant de la réaction d’<strong>autoprotolyse</strong> : 2 H₂O ⇌ H₃O⁺ + OH⁻.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'autoprotolyse-de-l-eau-ph-et-indicateurs-colores'), 2, 'indicateurs-colores', 'Indicateurs colorés', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'autoprotolyse-de-l-eau-ph-et-indicateurs-colores') and slug = 'indicateurs-colores'), $html$<p>Un <strong>indicateur coloré</strong> est un couple acide/base dont les deux formes n’ont pas la même couleur. Il change de teinte dans une <strong>zone de virage</strong>.</p>
