insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'acide-fort-base-forte-et-dosage'), 1, 'acides-forts-et-bases-fortes', 'Acides forts et bases fortes', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'acide-fort-base-forte-et-dosage') and slug = 'acides-forts-et-bases-fortes'), $html$<p>Un <strong>acide fort</strong> réagit totalement avec l’eau : HCl + H₂O → H₃O⁺ + Cl⁻. Une <strong>base forte</strong> se dissocie totalement : NaOH → Na⁺ + OH⁻.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'acide-fort-base-forte-et-dosage'), 2, 'reaction-acide-fort-base-forte-et-dosage', 'Réaction acide fort-base forte et dosage', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'acide-fort-base-forte-et-dosage') and slug = 'reaction-acide-fort-base-forte-et-dosage'), $html$<p class="formula">H₃O⁺ + OH⁻ → 2 H₂O (réaction rapide, totale, exothermique)</p>
