insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 5, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', 'Automatisme cardiaque, cycle cardiaque, régulation nerveuse et hormonale de la pression artérielle.', 5, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 1, 'l-automatisme-cardiaque', 'L’automatisme cardiaque', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'l-automatisme-cardiaque'), $html$<p>Un cœur isolé et irrigué continue à battre : il est <strong>automatique</strong>. Cette activité naît dans le <strong>tissu nodal</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 2, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), $html$<p>La <strong>pression artérielle</strong> est la pression du sang dans les artères. Elle varie entre une valeur maximale (systolique, environ 12 cmHg) et minimale (diastolique, environ 8 cmHg). Elle dépend du débit cardiaque et de la résistance des vaisseaux.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 6, 'le-milieu-interieur', 'Le milieu intérieur', 'Composition et rôles du milieu intérieur, homéostasie.', 6, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-milieu-interieur'), 1, 'composition-et-roles-du-milieu-interieur', 'Composition et rôles du milieu intérieur', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-milieu-interieur') and slug = 'composition-et-roles-du-milieu-interieur'), $html$<p>Le <strong>milieu intérieur</strong> est l’ensemble des liquides qui baignent les cellules : le <strong>plasma</strong> (partie liquide du sang), la <strong>lymphe</strong> et le <strong>liquide interstitiel</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-milieu-interieur'), 2, 'regulation-de-la-constance-du-milieu-interieur', 'Régulation de la constance du milieu intérieur', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-milieu-interieur') and slug = 'regulation-de-la-constance-du-milieu-interieur'), $html$<p>L’<strong>homéostasie</strong> est le maintien des constantes du milieu intérieur (glycémie, pression, température, pH, concentration en sels) malgré les variations extérieures.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 7, 'regulation-de-la-glycemie', 'Régulation de la glycémie', 'Insuline et glucagon, rôle du foie, diabète.', 7, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'regulation-de-la-glycemie'), 1, 'regulation-de-la-glycemie', 'Régulation de la glycémie', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'regulation-de-la-glycemie') and slug = 'regulation-de-la-glycemie'), $html$<p>La <strong>glycémie</strong> est le taux de glucose dans le sang : environ 1 g/L à jeun (0,8 à 1,2 g/L). Le glucose est la principale source d’énergie des cellules.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 8, 'immunologie', 'Immunologie', 'Soi et non-soi, réponses immunitaires, VIH-sida, vaccination et sérothérapie.', 8, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie'), 1, 'le-systeme-immunitaire', 'Le système immunitaire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie') and slug = 'le-systeme-immunitaire'), $html$<p>Le système immunitaire distingue le <strong>soi</strong> (ce qui appartient à l’organisme, marqué par les molécules du CMH à la surface des cellules) du <strong>non-soi</strong> (microbes, cellules étrangères, cellules anormales). Une molécule reconnue comme étrangère est un <strong>antigène</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie'), 2, 'la-reponse-immunitaire', 'La réponse immunitaire', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie') and slug = 'la-reponse-immunitaire'), $html$<h2>Réponse non spécifique (immédiate)</h2>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie'), 3, 'le-vih-et-le-sida', 'Le VIH et le sida', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie') and slug = 'le-vih-et-le-sida'), $html$<p>Le <strong>VIH</strong> (virus de l’immunodéficience humaine) est un rétrovirus qui infecte surtout les <strong>lymphocytes T4</strong>, chefs d’orchestre de la réponse immunitaire.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie'), 4, 'aides-a-la-reponse-immunitaire', 'Aides à la réponse immunitaire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'immunologie') and slug = 'aides-a-la-reponse-immunitaire'), $html$<table><thead><tr><th scope="col"></th><th scope="col">Vaccination</th><th scope="col">Sérothérapie</th></tr></thead><tbody><tr><td>Principe</td><td>injection d’un antigène rendu inoffensif</td><td>injection d’anticorps déjà fabriqués</td></tr><tr><td>Immunité</td><td>active, apparaît en quelques semaines</td><td>passive, immédiate</td></tr><tr><td>Durée</td><td>longue (cellules mémoire), avec rappels</td><td>courte (quelques semaines)</td></tr><tr><td>Rôle</td><td>prévention</td><td>traitement d’urgence (tétanos, venin de serpent)</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 9, 'reproduction-chez-les-mammiferes', 'Reproduction chez les mammifères', 'Gamétogenèse, fécondation, régulation hormonale, gestation, lactation et contraception.', 9, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes'), 1, 'appareils-reproducteurs-et-gametogenese', 'Appareils reproducteurs et gamétogenèse', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'appareils-reproducteurs-et-gametogenese'), $html$<p>Les <strong>gonades</strong> (testicules, ovaires) produisent les gamètes et des hormones sexuelles.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes'), 2, 'fecondation-et-problemes-lies-a-la-fecondation', 'Fécondation et problèmes liés à la fécondation', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'fecondation-et-problemes-lies-a-la-fecondation'), $html$<p>La <strong>fécondation</strong> a lieu dans le tiers supérieur de la trompe : un seul spermatozoïde traverse la zone pellucide grâce aux enzymes de son acrosome, puis son noyau fusionne avec celui de l’ovocyte. La cellule-œuf (2n = 46) est formée.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes'), 3, 'regulation-hormonale-des-appareils-reproducteurs', 'Régulation hormonale des appareils reproducteurs', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'regulation-hormonale-des-appareils-reproducteurs'), $html$<p>L’<strong>hypothalamus</strong> sécrète la GnRH, qui stimule l’<strong>hypophyse</strong>. Celle-ci libère deux hormones, FSH et LH, qui agissent sur les gonades.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes'), 4, 'gestation-et-accouchement', 'Gestation et accouchement', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'gestation-et-accouchement'), $html$<p>Après la nidation, l’embryon (puis le fœtus à partir du 3<sup>e</sup> mois) se développe dans l’utérus pendant 9 mois. Le <strong>placenta</strong> assure les échanges avec la mère : dioxygène et nutriments vers le fœtus, CO₂ et déchets vers la mère, sans mélange des sangs.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes'), 5, 'la-lactation', 'La lactation', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'la-lactation'), $html$<p>Pendant la grossesse, les œstrogènes et la progestérone développent les glandes mammaires. Après l’accouchement, la <strong>prolactine</strong> (hypophyse) déclenche la production de lait ; la tétée stimule la sécrétion d’<strong>ocytocine</strong>, qui provoque l’éjection du lait.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes'), 6, 'quelques-methodes-contraceptives', 'Quelques méthodes contraceptives', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-mammiferes') and slug = 'quelques-methodes-contraceptives'), $html$<table><thead><tr><th scope="col">Méthode</th><th scope="col">Principe</th></tr></thead><tbody><tr><td>pilule œstroprogestative</td><td>bloque l’ovulation par rétrocontrôle négatif sur l’hypophyse</td></tr><tr><td>implant, injection</td><td>libèrent un progestatif qui bloque l’ovulation et épaissit la glaire du col</td></tr><tr><td>dispositif intra-utérin (stérilet)</td><td>empêche la nidation et gêne les spermatozoïdes</td></tr><tr><td>préservatif masculin ou féminin</td><td>barrière mécanique ; protège aussi des IST et du VIH</td></tr><tr><td>méthodes naturelles (calendrier, températures)</td><td>abstinence autour de l’ovulation ; peu fiables</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 10, 'reproduction-chez-les-spermaphytes', 'Reproduction chez les spermaphytes', 'Fleur, pollinisation, double fécondation, graine et fruit.', 10, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-spermaphytes'), 1, 'reproduction-des-plantes-a-fleurs', 'Reproduction des plantes à fleurs', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'reproduction-chez-les-spermaphytes') and slug = 'reproduction-des-plantes-a-fleurs'), $html$<p>La <strong>fleur</strong> porte les organes reproducteurs : les <strong>étamines</strong> (organes mâles) produisent le pollen ; le <strong>pistil</strong> (organe femelle) contient les ovules dans l’ovaire.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 11, 'genetique', 'Génétique', 'Lois de Mendel, monohybridisme, dihybridisme, gènes liés et crossing-over.', 11, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'genetique'), 1, 'lois-statistiques-de-la-transmission-des-caracteres', 'Lois statistiques de la transmission des caractères', true, 'published', 20, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'genetique') and slug = 'lois-statistiques-de-la-transmission-des-caracteres'), $html$<p>Un <strong>gène</strong> occupe un locus sur un chromosome ; ses différentes versions sont les <strong>allèles</strong>. Un individu diploïde possède deux allèles de chaque gène : homozygote s’ils sont identiques, hétérozygote sinon. Un allèle <strong>dominant</strong> s’exprime chez l’hétérozygote, un allèle <strong>récessif</strong> non.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 12, 'heredite-humaine', 'Hérédité humaine', 'Arbres généalogiques, maladies héréditaires, groupes sanguins, anomalies chromosomiques.', 12, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'heredite-humaine'), 1, 'l-heredite-chez-l-espece-humaine', 'L’hérédité chez l’espèce humaine', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'heredite-humaine') and slug = 'l-heredite-chez-l-espece-humaine'), $html$<p>On étudie la transmission des caractères humains à l’aide d’<strong>arbres généalogiques</strong> (carrés pour les hommes, ronds pour les femmes, symboles pleins pour les atteints).</p>
