insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'la-fertilisation-des-sols') and slug = 'nourrir-le-sol-et-la-plante'), $html$<ul><li>engrais minéraux : la formule NPK 15-15-15 contient 15 kg d’azote, 15 kg de P₂O₅ et 15 kg de K₂O pour 100 kg ; l’urée contient 46 % d’azote ;</li><li>fumure organique : fumier, compost, parcage des animaux ; elle améliore la structure du sol ;</li><li>amendements : chaux ou phosphate naturel pour corriger l’acidité.</li></ul>
