insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-itineraire-technique-d-une-culture') and slug = 'conduire-une-culture'), $html$<div class="callout"><p class="callout-title">Itinéraire du mil</p><ol><li>Préparer le sol (nettoyage, labour ou grattage) et choisir des semences de qualité.</li><li>Semer à la bonne date et à la bonne densité ; démarier si besoin.</li><li>Entretenir : sarclage, fertilisation, protection contre les ravageurs.</li><li>Récolter à maturité, sécher, battre, stocker à l’abri de l’humidité et des insectes.</li></ol></div>$html$);
