insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'la-protection-des-cultures') and slug = 'proteger-les-recoltes'), $html$<ul><li>ravageurs : criquets, chenille légionnaire d’automne (arrivée en Afrique de l’Ouest en 2016), insectes des stocks ;</li><li>maladies : champignons, bactéries, virus ;</li><li>mauvaises herbes : le Striga, plante parasite du mil et du sorgho ;</li><li>lutte intégrée : rotations, variétés résistantes, lutte biologique, pesticides en dernier recours avec protection de l’utilisateur.</li></ul>$html$);
