insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'semences-et-amelioration-des-plantes') and slug = 'de-meilleures-varietes'), $html$<ul><li>la sélection choisit les plantes les plus productives, précoces ou résistantes à la sécheresse ;</li><li>au Sénégal, l’ISRA (Institut sénégalais de recherches agricoles) crée des variétés adaptées ;</li><li>une semence certifiée garantit la pureté variétale et une bonne germination.</li></ul>$html$);
