insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-alimentation-des-animaux') and slug = 'nourrir-le-betail'), $html$<ul><li>besoins d’entretien (vivre) et de production (croissance, lait, gestation) ;</li><li>aliments : fourrages (paille, fanes d’arachide), concentrés (tourteau d’arachide, son de mil, graines de coton), sels minéraux (pierre à lécher), eau ;</li><li>l’embouche engraisse des animaux en quelques mois, par exemple les moutons avant la Tabaski.</li></ul>$html$);
