insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRI' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'gestion-de-l-exploitation-agricole') and slug = 'une-exploitation-rentable'), $html$<ul><li>marge brute = produit brut (valeur de la récolte) − charges variables (semences, engrais, traitements) ;</li><li>les coopératives et organisations paysannes aident à acheter les intrants et à vendre ;</li><li>le crédit agricole (La Banque Agricole) finance les campagnes ;</li><li>transformer sur place augmente la valeur ajoutée.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')), 1, 'origines-et-specificite-de-la-reflexion-philosophique', 'Origines et spécificité de la réflexion philosophique', 'Définir la philosophie, rôle de la raison, grandes interrogations philosophiques.', 1, 'published', 'La réflexion philosophique', '[{"title":"Programme de philosophie des classes de Terminale (Commission nationale de philosophie, IGEN), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Philosophie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique'), 1, 'qu-est-ce-que-la-philosophie', 'Qu’est-ce que la philosophie ?', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'qu-est-ce-que-la-philosophie'), $html$<p>Étymologiquement, la philosophie est l’« amour de la sagesse » (en grec <em>philein</em>, aimer, et <em>sophia</em>, sagesse). Le philosophe n’est pas un sage qui possède la vérité : il la cherche.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique'), 2, 'philosophie-mythe-religion-et-science', 'Philosophie, mythe, religion et science', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'philosophie-mythe-religion-et-science'), $html$<p>La philosophie naît en Grèce au VI<sup>e</sup> siècle avant notre ère, quand des penseurs (Thalès, Héraclite, puis Socrate, Platon, Aristote) cherchent à expliquer le monde par des raisons et non plus par des récits sur les dieux. On parle du passage du <em>mythos</em> (récit) au <em>logos</em> (discours rationnel).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique'), 3, 'les-grandes-interrogations-philosophiques', 'Les grandes interrogations philosophiques', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'origines-et-specificite-de-la-reflexion-philosophique') and slug = 'les-grandes-interrogations-philosophiques'), $html$<p>Kant résume le champ de la philosophie en quatre questions :</p>
