insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'enjeux-finalites-et-perspectives-philosophiques') and slug = 'philosopher-aujourd-hui'), $html$<p>Les sciences ont pris à la philosophie beaucoup de ses anciens objets (la nature, la société, le psychisme). Mais de nouvelles questions apparaissent, que la science seule ne peut trancher :</p>
