insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'methodologie-de-la-dissertation-et-du-commentaire') and slug = 'la-dissertation-philosophique'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li><strong>Analyser le sujet</strong> : définir chaque mot, repérer les présupposés et la question posée.</li><li><strong>Problématiser</strong> : montrer pourquoi la question fait difficulté (deux réponses possibles qui s’opposent).</li><li><strong>Construire un plan</strong> : souvent dialectique (thèse, antithèse, dépassement) ou progressif.</li><li><strong>Rédiger</strong> : chaque partie défend une idée, appuyée sur des arguments, des auteurs et des exemples précis.</li></ol></div>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'methodologie-de-la-dissertation-et-du-commentaire'), 2, 'le-commentaire-de-texte-philosophique', 'Le commentaire de texte philosophique', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'methodologie-de-la-dissertation-et-du-commentaire') and slug = 'le-commentaire-de-texte-philosophique'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire le texte plusieurs fois et repérer son <strong>thème</strong> (de quoi il parle).</li><li>Dégager la <strong>thèse</strong> (ce que l’auteur affirme) et le <strong>problème</strong> auquel il répond.</li><li>Repérer la <strong>structure</strong> du texte (ses mouvements, les connecteurs logiques).</li><li><strong>Expliquer</strong> chaque mouvement : définir les concepts, éclairer les exemples, montrer l’enchaînement des idées.</li><li><strong>Discuter</strong> : intérêt philosophique, limites, autres auteurs.</li></ol></div>
