insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-surrealisme'), 1, 'le-mouvement-surrealiste', 'Le mouvement surréaliste', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-surrealisme') and slug = 'le-mouvement-surrealiste'), $html$<p>Né après la Première Guerre mondiale, dans le prolongement du mouvement Dada, le <strong>surréalisme</strong> est fondé par André Breton (<em>Manifeste du surréalisme</em>, 1924). Il veut libérer l’homme de la logique, de la morale bourgeoise et des conventions littéraires.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-surrealisme'), 2, 'surrealisme-et-poesie-de-la-negritude', 'Surréalisme et poésie de la négritude', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-surrealisme') and slug = 'surrealisme-et-poesie-de-la-negritude'), $html$<p>Les poètes de la négritude ont trouvé dans le surréalisme une arme contre la raison occidentale qui justifiait la colonisation, et une liberté d’images proche de l’oralité africaine.</p>
