insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990') and slug = 'les-consequences-de-la-guerre-et-les-reglements-du-conflit'), $html$<table><thead><tr><th scope="col">Conséquences</th><th scope="col">Faits essentiels</th></tr></thead><tbody><tr><td>humaines</td><td>environ 50 millions de morts, génocide des Juifs et des Tziganes, déplacés et réfugiés</td></tr><tr><td>matérielles</td><td>Europe et Japon dévastés ; les États-Unis deviennent la première puissance économique</td></tr><tr><td>politiques</td><td>déclin de l’Europe ; deux superpuissances, États-Unis et URSS ; affaiblissement des puissances coloniales</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990'), 2, 'les-relations-est-ouest-de-la-guerre-froide-a-la-chute-du-mur', 'Les relations Est-Ouest : de la guerre froide à la chute du mur', false, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990') and slug = 'les-relations-est-ouest-de-la-guerre-froide-a-la-chute-du-mur'), $html$<p>La <strong>guerre froide</strong> est l’affrontement indirect entre deux blocs, sans conflit armé direct entre les États-Unis et l’URSS.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990'), 3, 'la-chine-de-1945-aux-annees-1990', 'La Chine de 1945 aux années 1990', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990') and slug = 'la-chine-de-1945-aux-annees-1990'), $html$<table><thead><tr><th scope="col">Période</th><th scope="col">Faits essentiels</th></tr></thead><tbody><tr><td>1945-1949</td><td>guerre civile entre communistes (Mao Zedong) et nationalistes (Tchang Kaï-chek) ; la République populaire est proclamée le 1<sup>er</sup> octobre 1949</td></tr><tr><td>1949-1958</td><td>réforme agraire, alliance avec l’URSS, premier plan quinquennal</td></tr><tr><td>1958-1960</td><td>« Grand Bond en avant » : échec et famine meurtrière</td></tr><tr><td>1966-1976</td><td>Révolution culturelle : gardes rouges, culte de Mao</td></tr><tr><td>à partir de 1978</td><td>Deng Xiaoping : « quatre modernisations », ouverture économique, zones économiques spéciales</td></tr></tbody></table>
