insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-espace-europeen'), 1, 'milieux-naturels-et-populations', 'Milieux naturels et populations', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-espace-europeen') and slug = 'milieux-naturels-et-populations'), $html$<ul><li>milieux tempérés majoritaires, avec des nuances océaniques, continentales, méditerranéennes, montagnardes ;</li><li>un relief varié (plaines du Nord, Alpes) et des littoraux très découpés ;</li><li>une population nombreuse (environ 450 millions dans l’UE), vieillissante, avec une faible fécondité ;</li><li>l’Europe est devenue une terre d’immigration, notamment africaine : la question migratoire est un enjeu politique majeur.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-espace-europeen'), 2, 'la-construction-europeenne-realites-et-perspectives', 'La construction européenne : réalités et perspectives', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-espace-europeen') and slug = 'la-construction-europeenne-realites-et-perspectives'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Étape</th></tr></thead><tbody><tr><td>1951</td><td>CECA (charbon et acier) entre six pays</td></tr><tr><td>1957</td><td>traité de Rome : Communauté économique européenne (marché commun)</td></tr><tr><td>1992</td><td>traité de Maastricht : Union européenne</td></tr><tr><td>1999-2002</td><td>l’euro, monnaie unique</td></tr><tr><td>2004-2013</td><td>élargissements à l’Est</td></tr><tr><td>2020</td><td>sortie du Royaume-Uni (Brexit) : l’UE compte 27 membres</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-espace-europeen'), 3, 'la-france-et-l-allemagne-deux-puissances-de-l-union-europeenne', 'La France et l’Allemagne : deux puissances de l’Union européenne', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-espace-europeen') and slug = 'la-france-et-l-allemagne-deux-puissances-de-l-union-europeenne'), $html$<table><thead><tr><th scope="col"></th><th scope="col">France</th><th scope="col">Allemagne</th></tr></thead><tbody><tr><td>population</td><td>environ 68 millions</td><td>environ 84 millions, la plus peuplée de l’UE</td></tr><tr><td>points forts</td><td>agriculture (premier producteur de l’UE), aéronautique, nucléaire, tourisme, luxe</td><td>industrie (automobile, machines, chimie), premier exportateur de l’UE</td></tr><tr><td>faiblesses</td><td>chômage, dette publique</td><td>vieillissement, dépendance énergétique</td></tr></tbody></table>
