insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique'), 1, 'les-facteurs-d-emergence-de-l-asie-pacifique-et-leurs-limites', 'Les facteurs d’émergence de l’Asie-Pacifique et leurs limites', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique') and slug = 'les-facteurs-d-emergence-de-l-asie-pacifique-et-leurs-limites'), $html$<ul><li>une main-d’œuvre nombreuse, disciplinée et longtemps bon marché ;</li><li>des États interventionnistes et une stratégie d’industrialisation tournée vers l’exportation ;</li><li>un « effet de vol d’oies sauvages » : le Japon, puis les « dragons » (Corée du Sud, Taïwan, Hong Kong, Singapour), puis les « tigres » et la Chine ;</li><li>l’épargne élevée, l’éducation, les investissements étrangers.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique'), 2, 'le-modele-economique-japonais', 'Le modèle économique japonais', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique') and slug = 'le-modele-economique-japonais'), $html$<ul><li>un archipel montagneux, pauvre en ressources et exposé aux séismes et tsunamis ;</li><li>après 1945, le « miracle japonais » : forte croissance grâce à l’État (MITI), aux grands groupes (keiretsu), au travail et à l’innovation ;</li><li>points forts : automobile (Toyota), électronique, robotique ;</li><li>une population concentrée sur le littoral (mégalopole de Tokyo à Osaka).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique'), 3, 'la-chine-les-problemes-demographiques', 'La Chine : les problèmes démographiques', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique') and slug = 'la-chine-les-problemes-demographiques'), $html$<ul><li>environ 1,4 milliard d’habitants ; l’Inde l’a dépassée en 2023 ;</li><li>la politique de l’enfant unique (1979-2015) a freiné la croissance mais provoqué un vieillissement rapide et un déséquilibre entre garçons et filles ;</li><li>la Chine autorise deux enfants (2016), puis trois (2021) ;</li><li>fort exode rural vers les villes de l’Est : les « mingong » (travailleurs migrants).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique'), 4, 'la-chine-le-modele-de-developpement', 'La Chine : le modèle de développement', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S4')) and c.slug = 'l-asie-pacifique') and slug = 'la-chine-le-modele-de-developpement'), $html$<ul><li>depuis 1978, une « économie socialiste de marché » : ouverture, zones économiques spéciales, investissements étrangers ;</li><li>deuxième économie du monde, « atelier du monde », premier exportateur ;</li><li>investissements en Afrique (au Sénégal : Grand Théâtre, Musée des civilisations noires, autoroute Ila Touba) et « nouvelles routes de la soie » ;</li><li>montée en gamme : téléphonie, voitures électriques, espace.</li></ul>
