insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque') and slug = 'limites-operations-et-formes-indeterminees'), $html$<p>Les limites des fonctions de référence (x ↦ x<sup>n</sup>, <span class="frac"><span>1</span><span>x</span></span>, √x…) permettent de calculer les limites des sommes, produits et quotients.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque'), 2, 'asymptotes-et-branches-infinies', 'Asymptotes et branches infinies', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque') and slug = 'asymptotes-et-branches-infinies'), $html$<p>Les limites aux bornes de l’ensemble de définition décrivent l’allure de la courbe 𝒞 de f « à l’infini ».</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque'), 3, 'continuite-et-theoreme-des-valeurs-intermediaires', 'Continuité et théorème des valeurs intermédiaires', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque') and slug = 'continuite-et-theoreme-des-valeurs-intermediaires'), $html$<p>f est <strong>continue en a</strong> si lim<sub>x→a</sub> f(x) = f(a) : la courbe se trace « sans lever le crayon ». Les polynômes, les fonctions rationnelles, √x, sin, cos, ln et exp sont continues sur leur ensemble de définition, ainsi que leurs sommes, produits, quotients et composées.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque'), 4, 'fonction-reciproque', 'Fonction réciproque', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'limites-continuite-et-fonction-reciproque') and slug = 'fonction-reciproque'), $html$<p>Si f est <strong>continue et strictement monotone</strong> sur un intervalle I, elle réalise une <strong>bijection</strong> de I sur l’intervalle J = f(I) : tout y de J a un unique antécédent x dans I. On définit ainsi la fonction réciproque f<sup>−1</sup> : y = f(x) ⇔ x = f<sup>−1</sup>(y).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 2, 'derivees-et-primitives', 'Dérivées et primitives', 'Dérivée d’une composée, dérivées successives, points d’inflexion, inégalité des accroissements finis, primitives.', 2, 'published', null, '[{"title":"Programmes de mathématiques, Terminales L, S1-S3 et S2-S4 (MEN, 2006), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Maths-LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
