insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'derivees-et-primitives'), 4, 'primitives', 'Primitives', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'derivees-et-primitives') and slug = 'primitives'), $html$<p>F est une <strong>primitive</strong> de f sur un intervalle I si F’ = f sur I. Toute fonction continue sur I admet des primitives ; si F en est une, les autres sont les F + C (C constante). Une seule prend une valeur donnée en un point.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'derivees-et-primitives'), 5, 'etude-complete-d-une-fonction', 'Étude complète d’une fonction', false, 'published', 20, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'derivees-et-primitives') and slug = 'etude-complete-d-une-fonction'), $html$<div class="callout"><p class="callout-title">Plan d’étude</p><ol><li>Ensemble de définition D<sub>f</sub> ; parité ou périodicité pour réduire l’étude.</li><li>Limites aux bornes de D<sub>f</sub> et asymptotes.</li><li>Dérivée, signe de la dérivée, tableau de variations.</li><li>Éléments de symétrie, points particuliers (intersections avec les axes), tangentes utiles.</li><li>Tracé : asymptotes d’abord, puis points du tableau, puis la courbe.</li></ol></div>
