insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'probabilites') and slug = 'epreuve-de-bernoulli-et-loi-binomiale'), $html$<p>Une <strong>épreuve de Bernoulli</strong> a deux issues : succès (probabilité p) ou échec (1 − p). Si on répète n fois cette épreuve de façon <strong>indépendante</strong>, le nombre X de succès suit la <strong>loi binomiale</strong> B(n ; p) :</p>
