insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes'), 1, 'forme-algebrique-et-conjugue', 'Forme algébrique et conjugué', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes') and slug = 'forme-algebrique-et-conjugue'), $html$<p>L’ensemble ℂ des <strong>nombres complexes</strong> prolonge ℝ : il contient un nombre i tel que i² = −1. Tout complexe s’écrit de façon unique z = a + ib (a, b réels) : a = Re(z) est la partie réelle, b = Im(z) la partie imaginaire.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes'), 2, 'module-argument-et-forme-exponentielle', 'Module, argument et forme exponentielle', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes') and slug = 'module-argument-et-forme-exponentielle'), $html$<p>Pour z = a + ib ≠ 0, d’image M : le <strong>module</strong> |z| = √(a² + b²) = OM, et un <strong>argument</strong> θ est une mesure de l’angle (u⃗, OM⃗), avec cos θ = <span class="frac"><span>a</span><span>|z|</span></span> et sin θ = <span class="frac"><span>b</span><span>|z|</span></span>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes'), 3, 'equations-du-second-degre-dans', 'Équations du second degré dans ℂ', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes') and slug = 'equations-du-second-degre-dans'), $html$<p>Pour az² + bz + c = 0 (a ≠ 0), on calcule Δ = b² − 4ac.</p>
