insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'nombres-complexes-et-similitudes') and slug = 'similitudes-planes-directes'), $html$<p>Une <strong>similitude directe</strong> est une transformation du plan dont l’écriture complexe est z’ = az + b, avec a ≠ 0. Elle multiplie les distances par k = |a| et conserve les angles orientés.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 1, 'cinematique-du-point', 'Cinématique du point', 'Vecteurs position, vitesse et accélération ; mouvements rectilignes et circulaires.', 1, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'cinematique-du-point'), 1, 'position-vitesse-et-acceleration', 'Position, vitesse et accélération', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'cinematique-du-point') and slug = 'position-vitesse-et-acceleration'), $html$<p>Dans un repère lié au référentiel d’étude, la position d’un point mobile M est donnée par le <strong>vecteur position</strong> OM⃗(t) = x(t) i⃗ + y(t) j⃗ + z(t) k⃗.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'cinematique-du-point'), 2, 'mouvements-rectilignes', 'Mouvements rectilignes', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'cinematique-du-point') and slug = 'mouvements-rectilignes'), $html$<table><thead><tr><th scope="col">Mouvement</th><th scope="col">Accélération</th><th scope="col">Équations horaires</th></tr></thead><tbody><tr><td>rectiligne uniforme</td><td>a = 0</td><td>x = v t + x₀</td></tr><tr><td>rectiligne uniformément varié</td><td>a constante</td><td>v = a t + v₀ ; x = ½ a t² + v₀ t + x₀</td></tr><tr><td>rectiligne sinusoïdal</td><td>a = −ω² x</td><td>x = X<sub>m</sub> cos(ωt + φ)</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'cinematique-du-point'), 3, 'mouvements-circulaires', 'Mouvements circulaires', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'cinematique-du-point') and slug = 'mouvements-circulaires'), $html$<p>Sur un cercle de rayon R, on repère M par son abscisse angulaire θ(t). La vitesse angulaire est ω = <span class="frac"><span>dθ</span><span>dt</span></span> (rad/s) et la vitesse v = Rω.</p>
