insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'bases-de-la-dynamique'), 1, 'quantite-de-mouvement-et-referentiels-galileens', 'Quantité de mouvement et référentiels galiléens', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'bases-de-la-dynamique') and slug = 'quantite-de-mouvement-et-referentiels-galileens'), $html$<p>Le <strong>centre d’inertie</strong> G d’un solide est le point dont le mouvement est le plus simple. La <strong>quantité de mouvement</strong> d’un système de masse m est p⃗ = mv<sub>G</sub>⃗ (kg·m/s).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'bases-de-la-dynamique'), 2, 'relation-fondamentale-de-la-dynamique', 'Relation fondamentale de la dynamique', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'bases-de-la-dynamique') and slug = 'relation-fondamentale-de-la-dynamique'), $html$<p class="formula">Dans un référentiel galiléen : ΣF<sub>ext</sub>⃗ = <span class="frac"><span>dp⃗</span><span>dt</span></span> = ma<sub>G</sub>⃗</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 3, 'applications-des-bases-de-la-dynamique', 'Applications des bases de la dynamique', 'Chute libre, projectiles, chute dans un fluide, mouvements circulaires, particule dans un champ électrique.', 3, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique'), 1, 'chute-libre-et-plan-incline', 'Chute libre et plan incliné', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'chute-libre-et-plan-incline'), $html$<p>Un corps en <strong>chute libre</strong> n’est soumis qu’à son poids : la relation fondamentale donne a⃗ = g⃗ (g ≈ 9,8 m/s²), quelle que soit sa masse.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique'), 2, 'mouvement-d-un-projectile', 'Mouvement d’un projectile', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'mouvement-d-un-projectile'), $html$<p>Un projectile est lancé de O avec une vitesse v₀ faisant un angle α avec l’horizontale. On néglige l’air : a⃗ = g⃗.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique'), 3, 'chute-verticale-dans-un-fluide', 'Chute verticale dans un fluide', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'chute-verticale-dans-un-fluide'), $html$<p>Dans un fluide, un corps est soumis à son poids P⃗, à la <strong>poussée d’Archimède</strong> (verticale, vers le haut, égale au poids du fluide déplacé : ρ<sub>fluide</sub> V g) et à une force de frottement opposée à la vitesse, souvent modélisée par f = kv.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique'), 4, 'mouvements-circulaires-pendule-conique-virage-fronde', 'Mouvements circulaires : pendule conique, virage, fronde', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'mouvements-circulaires-pendule-conique-virage-fronde'), $html$<p>Pour un mouvement circulaire uniforme de rayon R, la somme des forces est <strong>centripète</strong> et vaut m<span class="frac"><span>v²</span><span>R</span></span>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique'), 5, 'particule-chargee-dans-un-champ-electrique-uniforme', 'Particule chargée dans un champ électrique uniforme', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'applications-des-bases-de-la-dynamique') and slug = 'particule-chargee-dans-un-champ-electrique-uniforme'), $html$<p>Entre deux plaques parallèles distantes de d et soumises à la tension U, le champ est uniforme : E = <span class="frac"><span>U</span><span>d</span></span> (V/m). Une particule de charge q et de masse m subit F⃗ = qE⃗ ; son poids est négligeable.</p>
