insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'gravitation-universelle') and slug = 'loi-de-la-gravitation-et-champ-de-gravitation'), $html$<p class="formula">F = G <span class="frac"><span>m m’</span><span>d²</span></span>, avec G = 6,67 × 10<sup>−11</sup> N·m²/kg²</p>
