insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'gravitation-universelle') and slug = 'mouvement-des-satellites'), $html$<p>Dans le référentiel géocentrique, un satellite en orbite circulaire de rayon r = R + h n’est soumis qu’à la gravitation. La relation fondamentale donne un mouvement <strong>circulaire uniforme</strong> :</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 5, 'champs-magnetiques', 'Champs magnétiques', 'Aimants, lignes de champ, champ terrestre, champs créés par un courant (fil, solénoïde).', 5, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'champs-magnetiques'), 1, 'generalites-sur-le-champ-magnetique', 'Généralités sur le champ magnétique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'champs-magnetiques') and slug = 'generalites-sur-le-champ-magnetique'), $html$<p>Un aimant ou un courant crée un <strong>champ magnétique</strong> B⃗ dans l’espace qui l’entoure. On le détecte avec une aiguille aimantée, qui s’oriente selon B⃗ (du pôle sud vers le pôle nord de l’aiguille).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'champs-magnetiques'), 2, 'champs-magnetiques-crees-par-des-courants', 'Champs magnétiques créés par des courants', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'champs-magnetiques') and slug = 'champs-magnetiques-crees-par-des-courants'), $html$<p>Le sens de B⃗ se trouve avec la règle de la main droite (ou du bonhomme d’Ampère : le courant entre par ses pieds et sort par sa tête, il regarde le point considéré ; B⃗ est dirigé vers sa gauche).</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 6, 'particule-chargee-dans-un-champ-magnetique-uniforme', 'Particule chargée dans un champ magnétique uniforme', 'Force de Lorentz, mouvement circulaire uniforme, spectrographe de masse et cyclotron.', 6, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'particule-chargee-dans-un-champ-magnetique-uniforme'), 1, 'force-de-lorentz-et-mouvement-circulaire', 'Force de Lorentz et mouvement circulaire', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'particule-chargee-dans-un-champ-magnetique-uniforme') and slug = 'force-de-lorentz-et-mouvement-circulaire'), $html$<p class="formula">Force de Lorentz : F⃗ = q v⃗ ∧ B⃗, de valeur F = |q| v B sin α</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'particule-chargee-dans-un-champ-magnetique-uniforme'), 2, 'applications-spectrographe-cyclotron-deflexion-magnetique', 'Applications : spectrographe, cyclotron, déflexion magnétique', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'particule-chargee-dans-un-champ-magnetique-uniforme') and slug = 'applications-spectrographe-cyclotron-deflexion-magnetique'), $html$<ul><li><strong>Spectrographe de masse</strong> : des ions de même charge, accélérés sous la même tension, décrivent des demi-cercles de rayons différents selon leur masse (R ∝ √m) ; on sépare ainsi les isotopes.</li><li><strong>Cyclotron</strong> : la période T = 2πm/(|q|B) ne dépend pas de la vitesse ; une tension alternative de même période accélère la particule à chaque demi-tour.</li><li><strong>Déflexion magnétique</strong> : dans un tube de télévision ancien, des bobines dévient le faisceau d’électrons.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 7, 'loi-de-laplace', 'Loi de Laplace', 'Force exercée par un champ magnétique sur un conducteur parcouru par un courant ; applications.', 7, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'loi-de-laplace'), 1, 'la-force-de-laplace', 'La force de Laplace', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'loi-de-laplace') and slug = 'la-force-de-laplace'), $html$<p>Un conducteur rectiligne de longueur ℓ, parcouru par un courant I et placé dans un champ magnétique B⃗, subit la <strong>force de Laplace</strong> :</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'loi-de-laplace'), 2, 'applications-de-la-loi-de-laplace', 'Applications de la loi de Laplace', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'loi-de-laplace') and slug = 'applications-de-la-loi-de-laplace'), $html$<ul><li><strong>rails de Laplace</strong> : une tige posée sur deux rails alimentés se met à rouler ;</li><li><strong>moteur électrique à courant continu</strong> : des forces de Laplace sur les côtés d’une bobine créent un couple qui la fait tourner ;</li><li><strong>haut-parleur</strong> : une bobine dans le champ d’un aimant fait vibrer la membrane au rythme du courant ;</li><li><strong>roue de Barlow</strong> : une roue conductrice tourne entre les pôles d’un aimant.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 8, 'induction-magnetique-et-dipole-r-l', 'Induction magnétique et dipôle (R, L)', 'Flux, loi de Faraday et de Lenz, auto-induction, établissement du courant dans une bobine.', 8, 'published', null, '[{"title":"Programmes de sciences physiques, Terminales S1-S2 et L2 (MEN, août 2008), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Sciences-Physiques_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
