insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'induction-magnetique-et-dipole-r-l') and slug = 'le-phenomene-d-induction'), $html$<p>Le <strong>flux magnétique</strong> à travers un circuit de N spires de surface S est Φ = N B S cos θ (en weber, Wb), θ étant l’angle entre B⃗ et la normale au circuit.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'induction-magnetique-et-dipole-r-l'), 2, 'auto-induction-et-dipole-r-l', 'Auto-induction et dipôle (R, L)', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'induction-magnetique-et-dipole-r-l') and slug = 'auto-induction-et-dipole-r-l'), $html$<p>Une bobine traversée par un courant variable crée elle-même un flux variable : Φ = L i, où L est l’<strong>inductance</strong> (henry, H). La tension à ses bornes (résistance r) est :</p>
