insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'acides-carboxyliques-et-derives') and slug = 'acides-carboxyliques-et-leurs-derives'), $html$<p>Un <strong>acide carboxylique</strong> possède le groupe carboxyle −COOH. Nom : « acide » + nom de l’alcane terminé par « oïque » (acide éthanoïque CH₃COOH, l’acide du vinaigre). C’est un acide faible.</p>
