insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'l-automatisme-cardiaque'), $html$<p>Un cœur isolé et irrigué continue à battre : il est <strong>automatique</strong>. Cette activité naît dans le <strong>tissu nodal</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), 2, 'activite-cardiaque-et-regulation-de-la-pression-arterielle', 'Activité cardiaque et régulation de la pression artérielle', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle') and slug = 'activite-cardiaque-et-regulation-de-la-pression-arterielle'), $html$<p>La <strong>pression artérielle</strong> est la pression du sang dans les artères. Elle varie entre une valeur maximale (systolique, environ 12 cmHg) et minimale (diastolique, environ 8 cmHg). Elle dépend du débit cardiaque et de la résistance des vaisseaux.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 6, 'le-milieu-interieur', 'Le milieu intérieur', 'Composition et rôles du milieu intérieur, homéostasie.', 6, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-milieu-interieur'), 1, 'composition-et-roles-du-milieu-interieur', 'Composition et rôles du milieu intérieur', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-milieu-interieur') and slug = 'composition-et-roles-du-milieu-interieur'), $html$<p>Le <strong>milieu intérieur</strong> est l’ensemble des liquides qui baignent les cellules : le <strong>plasma</strong> (partie liquide du sang), la <strong>lymphe</strong> et le <strong>liquide interstitiel</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-milieu-interieur'), 2, 'regulation-de-la-constance-du-milieu-interieur', 'Régulation de la constance du milieu intérieur', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'le-milieu-interieur') and slug = 'regulation-de-la-constance-du-milieu-interieur'), $html$<p>L’<strong>homéostasie</strong> est le maintien des constantes du milieu intérieur (glycémie, pression, température, pH, concentration en sels) malgré les variations extérieures.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 7, 'regulation-de-la-glycemie', 'Régulation de la glycémie', 'Insuline et glucagon, rôle du foie, diabète.', 7, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'regulation-de-la-glycemie'), 1, 'regulation-de-la-glycemie', 'Régulation de la glycémie', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'regulation-de-la-glycemie') and slug = 'regulation-de-la-glycemie'), $html$<p>La <strong>glycémie</strong> est le taux de glucose dans le sang : environ 1 g/L à jeun (0,8 à 1,2 g/L). Le glucose est la principale source d’énergie des cellules.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 8, 'immunologie', 'Immunologie', 'Soi et non-soi, réponses immunitaires, VIH-sida, vaccination et sérothérapie.', 8, 'published', null, '[{"title":"Programmes de SVT, Terminales L2, S1 et S2, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programmes_SVT_Tles_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'immunologie'), 1, 'le-systeme-immunitaire', 'Le système immunitaire', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'immunologie') and slug = 'le-systeme-immunitaire'), $html$<p>Le système immunitaire distingue le <strong>soi</strong> (ce qui appartient à l’organisme, marqué par les molécules du CMH à la surface des cellules) du <strong>non-soi</strong> (microbes, cellules étrangères, cellules anormales). Une molécule reconnue comme étrangère est un <strong>antigène</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'immunologie'), 2, 'la-reponse-immunitaire', 'La réponse immunitaire', true, 'published', 18, now());
