insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-conservation-par-la-chaleur') and slug = 'detruire-les-micro-organismes'), $html$<table><thead><tr><th scope="col">Traitement</th><th scope="col">Conditions</th><th scope="col">Effet</th></tr></thead><tbody><tr><td>pasteurisation</td><td>par exemple 72 °C pendant 15 s pour le lait</td><td>détruit les pathogènes ; produit à garder au froid</td></tr><tr><td>stérilisation</td><td>autour de 121 °C</td><td>détruit tous les micro-organismes</td></tr><tr><td>appertisation</td><td>stérilisation en récipient fermé (conserves)</td><td>conservation longue à température ambiante</td></tr></tbody></table>$html$);
