insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-conservation-par-le-froid'), 1, 'ralentir-les-microbes', 'Ralentir les microbes', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-conservation-par-le-froid') and slug = 'ralentir-les-microbes'), $html$<ul><li>réfrigération (0 à 4 °C) : ralentit la multiplication des micro-organismes ;</li><li>congélation et surgélation (−18 °C ou moins) : les arrête sans les détruire ;</li><li>la <strong>chaîne du froid</strong> ne doit jamais être rompue ; on ne recongèle pas un produit décongelé.</li></ul>$html$);
