insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'sechage-salage-et-fumage') and slug = 'conserver-en-retirant-l-eau'), $html$<ul><li>séchage, salage et fumage réduisent l’eau disponible pour les micro-organismes ;</li><li>produits halieutiques traditionnels : guedj (poisson fermenté et séché), kéthiakh (poisson braisé et séché), tambadiang (petits poissons salés-séchés) ;</li><li>séchage solaire de la mangue, des légumes, du poisson.</li></ul>$html$);
