insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'les-fermentations-alimentaires') and slug = 'des-microbes-au-service-de-l-aliment'), $html$<ul><li>fermentation lactique : les bactéries lactiques transforment le lactose en acide lactique (lait caillé, yaourt) ;</li><li>fermentation alcoolique : les levures transforment les sucres en éthanol et en CO₂ (pâte à pain) ;</li><li>fermentation acétique : l’éthanol devient acide acétique (vinaigre) ;</li><li>l’acidité produite protège l’aliment contre les micro-organismes pathogènes.</li></ul>$html$);
