insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-transformation-des-cereales-locales') and slug = 'du-grain-aux-produits-finis'), $html$<div class="callout"><p class="callout-title">Fabriquer du couscous de mil</p><ol><li>Nettoyer et décortiquer le grain.</li><li>Moudre en farine ou en semoule.</li><li>Rouler la farine humidifiée pour obtenir des granules (thiéré, arraw, thiakry).</li><li>Cuire à la vapeur, sécher et emballer.</li></ol></div>
