insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-transformation-des-fruits-et-legumes') and slug = 'jus-et-confitures'), $html$<ul><li>jus et boissons locales : bissap, bouye, gingembre ;</li><li>les jus sont pasteurisés puis conditionnés dans des bouteilles propres et fermées ;</li><li>dans une confiture, la forte teneur en sucre et la cuisson assurent la conservation ;</li><li>le °Brix mesure la teneur en sucres solubles (réfractomètre).</li></ul>$html$);
