insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'AGRO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'emballage-etiquetage-et-controle-qualite') and slug = 'mettre-un-produit-sur-le-marche'), $html$<ul><li>l’emballage protège, conserve, informe et attire le consommateur ;</li><li>étiquette : dénomination, liste des ingrédients, poids net, date limite, numéro de lot, nom et adresse du fabricant ;</li><li>contrôles : pH, °Brix, analyses microbiologiques ;</li><li>au Sénégal, l’Association sénégalaise de normalisation (ASN) élabore les normes.</li></ul>
