insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-idee-d-une-philosophie-africaine') and slug = 'la-philosophie-africaine-reperes-historiques'), $html$<table><thead><tr><th scope="col">Repère</th><th scope="col">Apport</th></tr></thead><tbody><tr><td>Placide Tempels, <em>La Philosophie bantoue</em> (1945)</td><td>affirme que les Bantous ont une philosophie, centrée sur la « force vitale »</td></tr><tr><td>Alexis Kagame, <em>La philosophie bantu-rwandaise de l’être</em> (1956)</td><td>dégage une philosophie à partir de la langue kinyarwanda</td></tr><tr><td>Cheikh Anta Diop, <em>Nations nègres et culture</em> (1954)</td><td>rattache l’Égypte ancienne au monde noir et en fait une source de la pensée</td></tr><tr><td>Léopold Sédar Senghor et la négritude</td><td>valorise les valeurs culturelles du monde noir</td></tr></tbody></table>
