insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'individu-et-societe'), 1, 'individu-personne-et-societe', 'Individu, personne et société', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'individu-et-societe') and slug = 'individu-personne-et-societe'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>individu</td><td>être unique, distinct des autres (« qui ne peut être divisé »)</td></tr><tr><td>personne</td><td>être humain doué de raison et de liberté, sujet de droits et de devoirs, qui a une dignité</td></tr><tr><td>société</td><td>groupe d’individus liés par des règles, des institutions et une culture communes</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PHILO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'individu-et-societe'), 2, 'les-normes-conformite-et-deviance', 'Les normes : conformité et déviance', true, 'published', 12, now());
