insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'decolonisation-et-affirmation-du-tiers-monde') and slug = 'les-formes-de-la-decolonisation'), $html$<table><thead><tr><th scope="col">Forme</th><th scope="col">Exemples</th></tr></thead><tbody><tr><td>négociée, pacifique</td><td>Gold Coast (Ghana, 1957), la plupart des colonies françaises d’Afrique noire (1960)</td></tr><tr><td>non-violente avec mobilisation de masse</td><td>Inde (Gandhi)</td></tr><tr><td>guerre de libération</td><td>Indochine, Algérie, Guinée-Bissau, Angola, Mozambique</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'decolonisation-et-affirmation-du-tiers-monde'), 3, 'bandoeng-et-l-emergence-du-tiers-monde', 'Bandoeng et l’émergence du tiers-monde', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'decolonisation-et-affirmation-du-tiers-monde') and slug = 'bandoeng-et-l-emergence-du-tiers-monde'), $html$<p>En avril 1955, 29 pays d’Asie et d’Afrique se réunissent à <strong>Bandoeng</strong> (Indonésie), autour de Nehru, Nasser, Zhou Enlai et Soekarno.</p>
