insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-decolonisation-en-asie-et-au-proche-orient'), 2, 'la-question-palestinienne-et-les-relations-israelo-arabes', 'La question palestinienne et les relations israélo-arabes', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'la-decolonisation-en-asie-et-au-proche-orient') and slug = 'la-question-palestinienne-et-les-relations-israelo-arabes'), $html$<table><thead><tr><th scope="col">Date</th><th scope="col">Événement</th></tr></thead><tbody><tr><td>1947</td><td>plan de partage de la Palestine par l’ONU (un État juif, un État arabe)</td></tr><tr><td>1948</td><td>création de l’État d’Israël (14 mai) ; première guerre israélo-arabe ; exode de centaines de milliers de Palestiniens</td></tr><tr><td>1956</td><td>crise de Suez</td></tr><tr><td>1964</td><td>création de l’OLP (Yasser Arafat la dirige à partir de 1969)</td></tr><tr><td>1967</td><td>guerre des Six Jours : Israël occupe la Cisjordanie, Gaza, le Golan et le Sinaï</td></tr><tr><td>1973</td><td>guerre du Kippour ; premier choc pétrolier</td></tr><tr><td>1978-1979</td><td>accords de Camp David : paix entre l’Égypte et Israël</td></tr><tr><td>1987</td><td>première Intifada (« soulèvement des pierres »)</td></tr><tr><td>1993</td><td>accords d’Oslo : reconnaissance mutuelle entre Israël et l’OLP, autonomie palestinienne</td></tr></tbody></table>
