insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal'), 1, 'problemes-et-perspectives-de-developpement-de-l-afrique', 'Problèmes et perspectives de développement de l’Afrique', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'problemes-et-perspectives-de-developpement-de-l-afrique'), $html$<table><thead><tr><th scope="col">Problèmes</th><th scope="col">Perspectives</th></tr></thead><tbody><tr><td>pauvreté, faible industrialisation, dépendance aux matières premières</td><td>ressources minières et énergétiques considérables</td></tr><tr><td>dette, instabilité politique, conflits</td><td>population jeune (environ 1,4 milliard d’habitants), urbanisation, marché intérieur</td></tr><tr><td>insuffisance des infrastructures et des services (santé, éducation)</td><td>intégration régionale : CEDEAO, Union africaine, ZLECAf</td></tr><tr><td>effets du changement climatique (désertification, sécheresses)</td><td>numérique (paiement mobile), énergies renouvelables</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal'), 2, 'le-senegal-milieux-naturels-et-populations', 'Le Sénégal : milieux naturels et populations', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'le-senegal-milieux-naturels-et-populations'), $html$<ul><li>196 722 km², 14 régions ; un relief plat (sauf le Sud-Est) ; climat tropical, du sahélien au nord au soudano-guinéen en Casamance ;</li><li>une saison des pluies (de juin-juillet à octobre) et une longue saison sèche ;</li><li>fleuves Sénégal, Gambie, Casamance, Saloum ;</li><li>environ 18 millions d’habitants (recensement de 2023), une population très jeune ;</li><li>une population inégalement répartie : forte concentration à Dakar et dans l’Ouest, faibles densités à l’Est ;</li><li>exode rural et émigration (vers l’Europe, les pays voisins).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal'), 3, 'la-question-de-l-eau-au-senegal', 'La question de l’eau au Sénégal', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'la-question-de-l-eau-au-senegal'), $html$<ul><li>des pluies faibles et irrégulières au nord, des sécheresses (années 1970-1980) ;</li><li>l’OMVS (Sénégal, Mali, Mauritanie, Guinée) a construit les barrages de Diama (contre la remontée de l’eau salée) et de Manantali (irrigation, électricité) ;</li><li>Dakar est alimentée en partie par le lac de Guiers, à plus de 200 km, et par des forages ; la nappe est menacée par la salinisation ;</li><li>l’agriculture irriguée se développe dans la vallée du fleuve (riz, tomate, oignon).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal'), 4, 'problemes-economiques-et-politiques-de-developpement-du-senegal', 'Problèmes économiques et politiques de développement du Sénégal', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'l-afrique-et-le-senegal') and slug = 'problemes-economiques-et-politiques-de-developpement-du-senegal'), $html$<table><thead><tr><th scope="col">Secteur</th><th scope="col">Situation</th></tr></thead><tbody><tr><td>agriculture</td><td>arachide, mil, riz, horticulture ; dépendance aux pluies ; importations de riz</td></tr><tr><td>pêche</td><td>première ressource d’exportation, menacée par la surpêche</td></tr><tr><td>mines et énergie</td><td>phosphates, or (Sabodala), zircon ; pétrole (Sangomar, depuis 2024) et gaz</td></tr><tr><td>services</td><td>port de Dakar, télécommunications, tourisme, transferts des émigrés</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 1, 'trade-professions-and-occupations', 'Trade, professions and occupations', 'Jobs, working conditions, unemployment, child labour ; obligation and the letter of application.', 1, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'trade-professions-and-occupations'), 1, 'the-world-of-work', 'The world of work', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'trade-professions-and-occupations') and slug = 'the-world-of-work'), $html$<h2>Reading: Looking for a job in Dakar</h2><p>Every year, thousands of young graduates arrive on the job market in Senegal. Some find a job in an office, a bank or a school, but many work in the informal sector as traders, tailors or drivers. Others choose vocational training to become electricians, mechanics or welders.</p><p>Unemployment pushes some young people to emigrate, sometimes at the risk of their lives. Creating jobs at home is one of the biggest challenges for African countries.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'trade-professions-and-occupations'), 2, 'obligation-necessity-and-the-letter-of-application', 'Obligation, necessity and the letter of application', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'trade-professions-and-occupations') and slug = 'obligation-necessity-and-the-letter-of-application'), $html$<table><thead><tr><th scope="col">Function</th><th scope="col">Structure</th><th scope="col">Example</th></tr></thead><tbody><tr><td>obligation</td><td>must / have to</td><td>Workers must wear a helmet.</td></tr><tr><td>absence of obligation</td><td>don’t have to / needn’t</td><td>You don’t have to wear a uniform.</td></tr><tr><td>prohibition</td><td>mustn’t / be not allowed to</td><td>Children mustn’t work in mines.</td></tr><tr><td>past obligation</td><td>had to</td><td>He had to work at the age of ten.</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 2, 'economy', 'Economy', 'Shopping, consumer society, poverty, development, agriculture and industry ; describing graphs.', 2, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'economy'), 1, 'poverty-and-development', 'Poverty and development', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'economy') and slug = 'poverty-and-development'), $html$<h2>Reading: From groundnuts to oil</h2><p>For decades, Senegal’s economy depended on groundnuts. Today, fishing, mining, services and tourism are also important, and the country started producing oil in 2024.</p><p>However, natural resources are not enough to fight poverty. Sustainable development means growing the economy while protecting the environment and giving everyone access to education, health and decent jobs.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'economy'), 2, 'describing-graphs-and-making-comparisons', 'Describing graphs and making comparisons', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'economy') and slug = 'describing-graphs-and-making-comparisons'), $html$<table><thead><tr><th scope="col">Trend</th><th scope="col">Verbs</th><th scope="col">Adverbs</th></tr></thead><tbody><tr><td>going up</td><td>rise, increase, grow</td><td>sharply, steadily, slightly</td></tr><tr><td>going down</td><td>fall, decrease, drop</td><td>dramatically, gradually</td></tr><tr><td>no change</td><td>remain stable, level off</td><td></td></tr></tbody></table>
