insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'science-and-technology') and slug = 'inventions-discoveries-and-icts'), $html$<h2>Reading: Mobile money</h2><p>A few years ago, sending money to a village meant travelling or trusting a driver. Today, thanks to mobile phones, money can be sent in seconds. Mobile money has changed the daily lives of millions of Africans.</p><p>Science and technology bring great benefits, but they also raise ethical questions: who controls our personal data? Should we use genetically modified crops?</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'science-and-technology'), 2, 'describing-a-process', 'Describing a process', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'science-and-technology') and slug = 'describing-a-process'), $html$<p>To describe how something is made or how it works, we use <strong>the passive</strong> and <strong>sequence words</strong>.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')), 5, 'information-and-communication', 'Information and communication', 'Media, ICTs, advertisements, the right to information ; reported speech.', 5, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'information-and-communication'), 1, 'the-media-and-the-information-explosion', 'The media and the information explosion', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'information-and-communication') and slug = 'the-media-and-the-information-explosion'), $html$<h2>Reading: Fake news</h2><p>With social networks, anyone can publish information. News travels faster than ever, but so do rumours and fake news. Before sharing a message, we should check its source and compare it with other reliable media.</p><p>Advertisements are everywhere too. They inform consumers but also try to make them buy things they do not need.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'information-and-communication'), 2, 'reported-speech', 'Reported speech', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'information-and-communication') and slug = 'reported-speech'), $html$<table><thead><tr><th scope="col">Direct speech</th><th scope="col">Reported speech</th></tr></thead><tbody><tr><td>“I am tired,” she said.</td><td>She said (that) she was tired.</td></tr><tr><td>“We will come,” they said.</td><td>They said they would come.</td></tr><tr><td>“I saw him yesterday,” he said.</td><td>He said he had seen him the day before.</td></tr><tr><td>“Where do you live?” he asked.</td><td>He asked me where I lived.</td></tr><tr><td>“Are you ready?” she asked.</td><td>She asked if I was ready.</td></tr></tbody></table>
