insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'reading-comprehension-strategies'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li><strong>Skim</strong> the text: read the title and the first lines of each paragraph to get the general idea.</li><li>Read the questions before reading the text in detail.</li><li><strong>Scan</strong> for specific information: names, dates, numbers, key words.</li><li>For “True or False”, always justify with a short quotation from the text.</li><li>Guess the meaning of new words from the context, the word family or prefixes and suffixes.</li></ol></div>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'exam-skills-reading-and-writing'), 2, 'writing-an-essay', 'Writing an essay', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'S5')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'writing-an-essay'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Read the subject carefully and underline the key words.</li><li>Brainstorm ideas and examples, then make a plan.</li><li><strong>Introduction</strong>: present the topic and announce your point of view or your plan.</li><li><strong>Body</strong>: one paragraph per idea, with an example; use linking words.</li><li><strong>Conclusion</strong>: sum up and give your opinion.</li><li>Check your grammar, spelling and the number of words required.</li></ol></div>
