insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'GEST' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-budget-de-tresorerie') and slug = 'prevoir-la-tresorerie'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lister les encaissements prévus mois par mois (ventes au comptant, règlements des clients).</li><li>Lister les décaissements prévus (achats, salaires, loyers, impôts, remboursements).</li><li>Calculer la trésorerie de fin de mois = trésorerie initiale + encaissements − décaissements.</li><li>Prévoir un financement si la trésorerie devient négative.</li></ol></div>$html$);
