insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'inflation-et-chomage'), 1, 'deux-desequilibres', 'Deux déséquilibres', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'inflation-et-chomage') and slug = 'deux-desequilibres'), $html$<ul><li>l’<strong>inflation</strong> est une hausse générale et durable des prix ; elle se mesure par un indice des prix à la consommation ;</li><li>causes : excès de demande, hausse des coûts (pétrole, importations), création monétaire excessive ;</li><li>le <strong>chômage</strong> touche les personnes sans emploi qui en cherchent un : conjoncturel, structurel, frictionnel ;</li><li>au Sénégal, le sous-emploi et le secteur informel occupent une grande partie des actifs.</li></ul>$html$);
