insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'les-politiques-economiques'), 1, 'agir-sur-l-economie', 'Agir sur l’économie', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'les-politiques-economiques') and slug = 'agir-sur-l-economie'), $html$<ul><li>objectifs (le « carré magique ») : croissance, plein emploi, stabilité des prix, équilibre extérieur ;</li><li>politique <strong>budgétaire</strong> : l’État agit par ses dépenses et ses impôts ;</li><li>politique <strong>monétaire</strong> : dans l’UEMOA, la BCEAO agit sur les taux directeurs et le crédit ;</li><li>une politique de relance stimule la demande ; une politique de rigueur freine l’inflation et les déficits.</li></ul>$html$);
