insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-commerce-international-et-la-balance-des-paiements'), 1, 'echanger-avec-le-monde', 'Échanger avec le monde', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-commerce-international-et-la-balance-des-paiements') and slug = 'echanger-avec-le-monde'), $html$<ul><li>selon Ricardo, chaque pays gagne à se spécialiser dans les productions où il a un avantage comparatif ;</li><li>le libre-échange supprime les obstacles au commerce ; le protectionnisme protège les productions nationales (droits de douane, quotas) ;</li><li>balance commerciale = exportations − importations de biens ; la balance des paiements enregistre toutes les opérations avec l’extérieur.</li></ul>
