insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'la-mondialisation-et-les-institutions-internationales') and slug = 'une-economie-mondialisee'), $html$<ul><li>la mondialisation est l’intégration croissante des économies par les échanges, les capitaux et l’information ;</li><li>les firmes multinationales produisent et vendent dans de nombreux pays ;</li><li>FMI (stabilité financière, prêts), Banque mondiale (financement du développement), OMC (règles du commerce) ;</li><li>l’endettement des pays du Sud pose la question de sa soutenabilité.</li></ul>$html$);
