insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ECO' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'l-economie-du-senegal') and slug = 'atouts-et-defis'), $html$<ul><li>les services dominent la production ; l’agriculture emploie encore beaucoup d’actifs ;</li><li>ressources : pêche, phosphates, or, zircon ; pétrole (Sangomar) et gaz (Grand Tortue Ahmeyim) en mer depuis 2024-2025 ;</li><li>les transferts des émigrés sont une source importante de revenus pour les ménages ;</li><li>défis : emploi des jeunes, secteur informel, dépendance alimentaire et énergétique, dette.</li></ul>$html$);
