insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'calcul-matriciel-et-programmation-lineaire'), 1, 'matrices-et-determinants', 'Matrices et déterminants', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'calcul-matriciel-et-programmation-lineaire') and slug = 'matrices-et-determinants'), $html$<ul><li>une matrice est un tableau de nombres à n lignes et p colonnes ; on additionne deux matrices de même format terme à terme ;</li><li>le produit AB existe si le nombre de colonnes de A égale le nombre de lignes de B ;</li><li>déterminant d’une matrice 2 × 2 : ad − bc ; d’une matrice 3 × 3 : règle de Sarrus ou développement par les cofacteurs ;</li><li>une matrice carrée est inversible si et seulement si son déterminant n’est pas nul.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'calcul-matriciel-et-programmation-lineaire'), 2, 'l-algorithme-du-simplexe', 'L’algorithme du simplexe', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'calcul-matriciel-et-programmation-lineaire') and slug = 'l-algorithme-du-simplexe'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Écrire le programme linéaire : variables, fonction économique à maximiser, contraintes.</li><li>Mettre sous forme standard en ajoutant une variable d’écart par contrainte.</li><li>Construire le tableau initial (solution de départ : variables d’écart égales aux seconds membres).</li><li>Choisir la variable entrante (plus grand coefficient positif de la fonction économique) et la variable sortante (plus petit rapport positif), puis pivoter.</li><li>Recommencer jusqu’à ce qu’aucun coefficient de la fonction économique ne soit positif : la solution est optimale.</li></ol></div>
