insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'fonction-logarithme-neperien') and slug = 'le-logarithme-neperien-definition-et-proprietes'), $html$<p>La <strong>fonction logarithme népérien</strong>, notée ln, est l’unique primitive de x ↦ <span class="frac"><span>1</span><span>x</span></span> sur ]0 ; +∞[ qui s’annule en 1.</p>
