insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-roman'), 1, 'les-outils-de-l-analyse-du-roman', 'Les outils de l’analyse du roman', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-roman') and slug = 'les-outils-de-l-analyse-du-roman'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Ce qu’on observe</th></tr></thead><tbody><tr><td>narrateur</td><td>interne (« je » personnage) ou externe (« il »)</td></tr><tr><td>focalisation</td><td>zéro (narrateur omniscient), interne (à travers un personnage), externe (de l’extérieur, comme une caméra)</td></tr><tr><td>personnages</td><td>portrait physique et moral, rôle dans l’action (schéma actanciel)</td></tr><tr><td>temps du récit</td><td>ordre (retour en arrière, anticipation), rythme (scène, sommaire, ellipse, pause)</td></tr><tr><td>discours rapporté</td><td>direct, indirect, indirect libre</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-roman'), 2, 'les-romans-au-programme', 'Les romans au programme', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-roman') and slug = 'les-romans-au-programme'), $html$<table><thead><tr><th scope="col">Œuvre</th><th scope="col">Repères</th></tr></thead><tbody><tr><td>Abbé Prévost, <em>Manon Lescaut</em> (1731)</td><td>passion destructrice du chevalier Des Grieux pour Manon ; récit à la première personne</td></tr><tr><td>Albert Camus, <em>L’Étranger</em> (1942)</td><td>Meursault, indifférent au monde, tue un homme ; l’absurde ; style neutre, phrases courtes</td></tr><tr><td>Ahmadou Kourouma, <em>Les Soleils des indépendances</em> (1968)</td><td>Fama, prince malinké déchu après les indépendances ; désillusion politique ; français « malinkisé »</td></tr><tr><td>Amadou Hampâté Bâ, <em>L’Étrange Destin de Wangrin</em> (1973)</td><td>un interprète rusé sous la colonisation en Afrique de l’Ouest ; récit nourri de tradition orale</td></tr></tbody></table>
