insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-theatre'), 1, 'le-texte-theatral', 'Le texte théâtral', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-theatre') and slug = 'le-texte-theatral'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>dialogue, réplique, tirade</td><td>échanges entre personnages ; une tirade est une longue réplique</td></tr><tr><td>monologue, aparté</td><td>personnage seul en scène ; parole adressée au public que les autres n’entendent pas</td></tr><tr><td>didascalies</td><td>indications de mise en scène (en italique)</td></tr><tr><td>double énonciation</td><td>les personnages se parlent, mais l’auteur s’adresse au public</td></tr><tr><td>exposition, nœud, dénouement</td><td>étapes de l’action</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-theatre'), 2, 'les-pieces-au-programme', 'Les pièces au programme', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-theatre') and slug = 'les-pieces-au-programme'), $html$<table><thead><tr><th scope="col">Genre</th><th scope="col">Œuvres de la liste officielle</th></tr></thead><tbody><tr><td>tragédie classique</td><td>Corneille, <em>Horace</em> (1640) : conflit entre amour et devoir patriotique</td></tr><tr><td>drame romantique</td><td>Victor Hugo, <em>Hernani</em> (1830) ; Alfred de Musset, <em>Lorenzaccio</em> (1834)</td></tr><tr><td>réécritures du mythe au XX<sup>e</sup> siècle</td><td>Jean Anouilh, <em>Antigone</em> (1944) ; Jean-Paul Sartre, <em>Les Mouches</em> (1943)</td></tr><tr><td>théâtre de l’absurde</td><td>Samuel Beckett, <em>En attendant Godot</em> (1952)</td></tr><tr><td>théâtre africain</td><td>Seydou Badian, <em>La Mort de Chaka</em> ; Cheik Aliou Ndao, <em>L’Exil d’Albouri</em> ; Bernard Dadié, <em>Monsieur Thôgô-gnini</em> ; Maxime N’Debeka, <em>Le Président</em></td></tr></tbody></table>
