insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'synthese-compte-rendu-et-correspondance'), 1, 'synthese-de-documents-et-compte-rendu', 'Synthèse de documents et compte rendu', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'synthese-compte-rendu-et-correspondance') and slug = 'synthese-de-documents-et-compte-rendu'), $html$<p>La <strong>synthèse</strong> rassemble les informations de plusieurs documents sur un même thème, de façon objective et organisée. Le <strong>compte rendu</strong> (ou rapport) relate un événement (réunion, visite, conférence).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'synthese-compte-rendu-et-correspondance'), 2, 'rediger-une-lettre', 'Rédiger une lettre', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'synthese-compte-rendu-et-correspondance') and slug = 'rediger-une-lettre'), $html$<ul><li>lettre <strong>formelle</strong> (demande, réclamation, candidature) : coordonnées, lieu et date, destinataire, objet, formule d’appel (« Monsieur le Proviseur »), corps du texte, formule de politesse, signature ;</li><li>lettre <strong>personnelle</strong> : ton familier, mais langue correcte.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')), 1, 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990', 'Le monde au lendemain de la Seconde Guerre mondiale (1945-1990)', 'Bilan et règlement de la guerre, relations Est-Ouest, la Chine de 1945 aux années 1990.', 1, 'published', 'Histoire', '[{"title":"Programme d’histoire, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Histoire_Tle.pdf","kind":"official"},{"title":"Programme de géographie, 6e à Terminale, Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Geographie_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990'), 1, 'les-consequences-de-la-guerre-et-les-reglements-du-conflit', 'Les conséquences de la guerre et les règlements du conflit', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990') and slug = 'les-consequences-de-la-guerre-et-les-reglements-du-conflit'), $html$<table><thead><tr><th scope="col">Conséquences</th><th scope="col">Faits essentiels</th></tr></thead><tbody><tr><td>humaines</td><td>environ 50 millions de morts, génocide des Juifs et des Tziganes, déplacés et réfugiés</td></tr><tr><td>matérielles</td><td>Europe et Japon dévastés ; les États-Unis deviennent la première puissance économique</td></tr><tr><td>politiques</td><td>déclin de l’Europe ; deux superpuissances, États-Unis et URSS ; affaiblissement des puissances coloniales</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990'), 2, 'les-relations-est-ouest-de-la-guerre-froide-a-la-chute-du-mur', 'Les relations Est-Ouest : de la guerre froide à la chute du mur', false, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990') and slug = 'les-relations-est-ouest-de-la-guerre-froide-a-la-chute-du-mur'), $html$<p>La <strong>guerre froide</strong> est l’affrontement indirect entre deux blocs, sans conflit armé direct entre les États-Unis et l’URSS.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990'), 3, 'la-chine-de-1945-aux-annees-1990', 'La Chine de 1945 aux années 1990', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'le-monde-au-lendemain-de-la-seconde-guerre-mondiale-1945-1990') and slug = 'la-chine-de-1945-aux-annees-1990'), $html$<table><thead><tr><th scope="col">Période</th><th scope="col">Faits essentiels</th></tr></thead><tbody><tr><td>1945-1949</td><td>guerre civile entre communistes (Mao Zedong) et nationalistes (Tchang Kaï-chek) ; la République populaire est proclamée le 1<sup>er</sup> octobre 1949</td></tr><tr><td>1949-1958</td><td>réforme agraire, alliance avec l’URSS, premier plan quinquennal</td></tr><tr><td>1958-1960</td><td>« Grand Bond en avant » : échec et famine meurtrière</td></tr><tr><td>1966-1976</td><td>Révolution culturelle : gardes rouges, culte de Mao</td></tr><tr><td>à partir de 1978</td><td>Deng Xiaoping : « quatre modernisations », ouverture économique, zones économiques spéciales</td></tr></tbody></table>
