insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'trade-professions-and-occupations'), 1, 'the-world-of-work', 'The world of work', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'trade-professions-and-occupations') and slug = 'the-world-of-work'), $html$<h2>Reading: Looking for a job in Dakar</h2><p>Every year, thousands of young graduates arrive on the job market in Senegal. Some find a job in an office, a bank or a school, but many work in the informal sector as traders, tailors or drivers. Others choose vocational training to become electricians, mechanics or welders.</p><p>Unemployment pushes some young people to emigrate, sometimes at the risk of their lives. Creating jobs at home is one of the biggest challenges for African countries.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'trade-professions-and-occupations'), 2, 'obligation-necessity-and-the-letter-of-application', 'Obligation, necessity and the letter of application', false, 'published', 15, now());
