insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'health-welfare-and-environment') and slug = 'health-and-environment'), $html$<h2>Reading: Plastic everywhere</h2><p>Plastic bags are cheap and practical, but they take hundreds of years to break down. They block drains, kill animals that eat them and pollute our beaches. Burning them releases toxic smoke.</p><p>Good hygiene, clean water and vaccination prevent many diseases such as cholera, malaria and measles. Keeping fit and eating a balanced diet are also important for our health.</p>
