insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'G')) and c.slug = 'science-and-technology') and slug = 'describing-a-process'), $html$<p>To describe how something is made or how it works, we use <strong>the passive</strong> and <strong>sequence words</strong>.</p>
