insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'CONST' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'analyse-fonctionnelle-et-cahier-des-charges') and slug = 'analyser-un-produit'), $html$<ul><li>on part du <strong>besoin</strong> : à qui le produit rend-il service ? sur quoi agit-il ? dans quel but ?</li><li>fonctions de service : principales (raison d’être du produit) et contraintes (sécurité, coût, environnement) ;</li><li>le diagramme pieuvre relie le produit à son environnement ; le FAST relie chaque fonction aux solutions techniques ;</li><li>le cahier des charges fixe pour chaque fonction des critères et des niveaux.</li></ul>$html$);
