insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'particule-chargee-dans-un-champ-magnetique-uniforme') and slug = 'force-de-lorentz-et-mouvement-circulaire'), $html$<p class="formula">Force de Lorentz : F⃗ = q v⃗ ∧ B⃗, de valeur F = |q| v B sin α</p>
