insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'le-surrealisme') and slug = 'le-mouvement-surrealiste'), $html$<p>Né après la Première Guerre mondiale, dans le prolongement du mouvement Dada, le <strong>surréalisme</strong> est fondé par André Breton (<em>Manifeste du surréalisme</em>, 1924). Il veut libérer l’homme de la logique, de la morale bourgeoise et des conventions littéraires.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'le-surrealisme'), 2, 'surrealisme-et-poesie-de-la-negritude', 'Surréalisme et poésie de la négritude', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'le-surrealisme') and slug = 'surrealisme-et-poesie-de-la-negritude'), $html$<p>Les poètes de la négritude ont trouvé dans le surréalisme une arme contre la raison occidentale qui justifiait la colonisation, et une liberté d’images proche de l’oralité africaine.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')), 2, 'la-poesie', 'La poésie', 'Versification, poésie classique et romantique, poésie de la négritude.', 2, 'published', 'Esthétique des genres', '[{"title":"Nouveaux programmes de français, enseignement secondaire général (Commission nationale de français, 2009), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Francais_Tle_LS.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'la-poesie'), 1, 'les-outils-de-la-versification', 'Les outils de la versification', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'la-poesie') and slug = 'les-outils-de-la-versification'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Définition</th></tr></thead><tbody><tr><td>vers</td><td>ligne de poème ; l’alexandrin compte 12 syllabes, le décasyllabe 10, l’octosyllabe 8</td></tr><tr><td>e muet</td><td>se prononce devant une consonne, s’élide devant une voyelle ou en fin de vers</td></tr><tr><td>diérèse, synérèse</td><td>prononcer une syllabe en deux (li-on) ou deux en une (lion)</td></tr><tr><td>rimes</td><td>plates (AABB), croisées (ABAB), embrassées (ABBA) ; pauvres, suffisantes ou riches</td></tr><tr><td>strophe</td><td>groupe de vers : quatrain (4), tercet (3)…</td></tr><tr><td>sonnet</td><td>deux quatrains et deux tercets</td></tr></tbody></table>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'la-poesie'), 2, 'poesie-classique-et-romantique', 'Poésie classique et romantique', false, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'la-poesie') and slug = 'poesie-classique-et-romantique'), $html$<table><thead><tr><th scope="col">Œuvre (liste officielle)</th><th scope="col">Ce qu’il faut savoir</th></tr></thead><tbody><tr><td>Boileau, <em>L’Art poétique</em> (1674)</td><td>texte théorique du classicisme : clarté, raison, imitation des Anciens, règles</td></tr><tr><td>La Fontaine, <em>Fables</em></td><td>récits en vers, souvent animaliers, qui instruisent en plaisant ; morale explicite ou implicite</td></tr><tr><td>Victor Hugo, <em>Les Contemplations</em> (1856)</td><td>poésie romantique et lyrique : souvenirs, deuil de sa fille Léopoldine, méditation</td></tr></tbody></table>
