insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'le-resume-de-texte-et-la-discussion') and slug = 'la-discussion'), $html$<p>Après le résumé, on discute une idée du texte : il s’agit d’un court essai argumenté.</p>
