insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T1')) and c.slug = 'information-and-communication') and slug = 'the-media-and-the-information-explosion'), $html$<h2>Reading: Fake news</h2><p>With social networks, anyone can publish information. News travels faster than ever, but so do rumours and fake news. Before sharing a message, we should check its source and compare it with other reliable media.</p><p>Advertisements are everywhere too. They inform consumers but also try to make them buy things they do not need.</p>
