insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-logarithme-neperien'), 1, 'le-logarithme-neperien-definition-et-proprietes', 'Le logarithme népérien : définition et propriétés', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-logarithme-neperien') and slug = 'le-logarithme-neperien-definition-et-proprietes'), $html$<p>La <strong>fonction logarithme népérien</strong>, notée ln, est l’unique primitive de x ↦ <span class="frac"><span>1</span><span>x</span></span> sur ]0 ; +∞[ qui s’annule en 1.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-logarithme-neperien'), 2, 'etude-de-la-fonction-logarithme-neperien', 'Étude de la fonction logarithme népérien', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-logarithme-neperien') and slug = 'etude-de-la-fonction-logarithme-neperien'), $html$<p>ln est dérivable sur ]0 ; +∞[ de dérivée <span class="frac"><span>1</span><span>x</span></span> &gt; 0 : elle est <strong>strictement croissante</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-logarithme-neperien'), 3, 'equations-inequations-et-logarithme-decimal', 'Équations, inéquations et logarithme décimal', true, 'published', 12, now());
