insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')), 5, 'fonction-exponentielle-et-fonctions-puissances', 'Fonction exponentielle et fonctions puissances', 'Exponentielle, dérivée et primitive de e^u, fonctions puissances, croissances comparées.', 5, 'published', null, '[{"title":"Programme de mathématiques des séries T, seconde à Terminale (MEN, 2006), APAMS","url":"https://apams.gouv.sn/sites/default/files/mathseriesT.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-exponentielle-et-fonctions-puissances'), 1, 'la-fonction-exponentielle-definition-et-proprietes', 'La fonction exponentielle : définition et propriétés', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-exponentielle-et-fonctions-puissances') and slug = 'la-fonction-exponentielle-definition-et-proprietes'), $html$<p>ln est une bijection de ]0 ; +∞[ sur ℝ. Sa réciproque est la <strong>fonction exponentielle</strong>, notée exp, avec exp(x) = e<sup>x</sup>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-exponentielle-et-fonctions-puissances'), 2, 'etude-de-l-exponentielle-et-derivee-de-e-u', 'Étude de l’exponentielle et dérivée de e^u', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-exponentielle-et-fonctions-puissances') and slug = 'etude-de-l-exponentielle-et-derivee-de-e-u'), $html$<p>exp est dérivable sur ℝ et (e<sup>x</sup>)’ = e<sup>x</sup> &gt; 0 : elle est strictement croissante.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-exponentielle-et-fonctions-puissances'), 3, 'exponentielle-de-base-a-et-fonctions-puissances', 'Exponentielle de base a et fonctions puissances', true, 'published', 12, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'fonction-exponentielle-et-fonctions-puissances') and slug = 'exponentielle-de-base-a-et-fonctions-puissances'), $html$<p>Pour a &gt; 0, on définit a<sup>x</sup> = e<sup>x ln a</sup> pour tout réel x. On retrouve les règles des puissances : a<sup>x + y</sup> = a<sup>x</sup> a<sup>y</sup>, (a<sup>x</sup>)<sup>y</sup> = a<sup>xy</sup>.</p>
