insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'produit-vectoriel-et-produit-mixte') and slug = 'orientation-de-l-espace-et-produit-vectoriel'), $html$<p>Un repère (O ; i⃗, j⃗, k⃗) est <strong>direct</strong> si un observateur debout sur k⃗ (le « bonhomme d’Ampère ») voit i⃗ tourner vers j⃗ dans le sens inverse des aiguilles d’une montre.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'produit-vectoriel-et-produit-mixte'), 2, 'applications-du-produit-vectoriel', 'Applications du produit vectoriel', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'produit-vectoriel-et-produit-mixte') and slug = 'applications-du-produit-vectoriel'), $html$<ul><li>Aire du parallélogramme ABDC : ‖AB⃗ ∧ AC⃗‖ ; aire du triangle ABC : <span class="frac"><span>1</span><span>2</span></span>‖AB⃗ ∧ AC⃗‖.</li><li>AB⃗ ∧ AC⃗ est un <strong>vecteur normal</strong> au plan (ABC) : il donne une équation du plan.</li><li>A, B, C sont alignés si et seulement si AB⃗ ∧ AC⃗ = 0⃗.</li><li>Distance d’un point M à la droite (AB) : d = <span class="frac"><span>‖AM⃗ ∧ AB⃗‖</span><span>AB</span></span>.</li></ul>
