insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'interferences-lumineuses') and slug = 'l-experience-des-fentes-de-young'), $html$<p>Deux fentes fines F₁ et F₂, distantes de a, sont éclairées par la même source monochromatique : ce sont deux sources <strong>cohérentes</strong>. Sur un écran à la distance D, on observe des franges alternativement brillantes et sombres, régulièrement espacées.</p>
