insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'interferences-lumineuses') and slug = 'interpretation-et-applications'), $html$<p>Les interférences ne s’expliquent que si la lumière est une <strong>onde</strong> : deux vibrations en phase s’ajoutent, deux vibrations en opposition de phase s’annulent. La diffraction par une fente fine en est un autre signe.</p>
