insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'le-roman') and slug = 'les-outils-de-l-analyse-du-roman'), $html$<table><thead><tr><th scope="col">Notion</th><th scope="col">Ce qu’on observe</th></tr></thead><tbody><tr><td>narrateur</td><td>interne (« je » personnage) ou externe (« il »)</td></tr><tr><td>focalisation</td><td>zéro (narrateur omniscient), interne (à travers un personnage), externe (de l’extérieur, comme une caméra)</td></tr><tr><td>personnages</td><td>portrait physique et moral, rôle dans l’action (schéma actanciel)</td></tr><tr><td>temps du récit</td><td>ordre (retour en arrière, anticipation), rythme (scène, sommaire, ellipse, pause)</td></tr><tr><td>discours rapporté</td><td>direct, indirect, indirect libre</td></tr></tbody></table>
