insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'le-resume-de-texte-et-la-discussion'), 1, 'resumer-un-texte', 'Résumer un texte', true, 'published', 18, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'le-resume-de-texte-et-la-discussion') and slug = 'resumer-un-texte'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Lire le texte et repérer son thème et la thèse de l’auteur.</li><li>Dégager sa structure logique (paragraphes, connecteurs) et distinguer idées principales, idées secondaires, exemples.</li><li>Reformuler chaque idée essentielle avec ses propres mots, dans l’ordre du texte, en gardant le point de vue de l’auteur.</li><li>Respecter le nombre de mots demandé (souvent le quart du texte, avec une marge de 10 %) et l’indiquer à la fin.</li><li>Relire : orthographe, enchaînements logiques, présentation.</li></ol></div>
