insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'synthese-compte-rendu-et-correspondance') and slug = 'synthese-de-documents-et-compte-rendu'), $html$<p>La <strong>synthèse</strong> rassemble les informations de plusieurs documents sur un même thème, de façon objective et organisée. Le <strong>compte rendu</strong> (ou rapport) relate un événement (réunion, visite, conférence).</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'synthese-compte-rendu-et-correspondance'), 2, 'rediger-une-lettre', 'Rédiger une lettre', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'synthese-compte-rendu-et-correspondance') and slug = 'rediger-une-lettre'), $html$<ul><li>lettre <strong>formelle</strong> (demande, réclamation, candidature) : coordonnées, lieu et date, destinataire, objet, formule d’appel (« Monsieur le Proviseur »), corps du texte, formule de politesse, signature ;</li><li>lettre <strong>personnelle</strong> : ton familier, mais langue correcte.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')), 1, 'trade-professions-and-occupations', 'Trade, professions and occupations', 'Jobs, working conditions, unemployment, child labour ; obligation and the letter of application.', 1, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'trade-professions-and-occupations'), 1, 'the-world-of-work', 'The world of work', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'trade-professions-and-occupations') and slug = 'the-world-of-work'), $html$<h2>Reading: Looking for a job in Dakar</h2><p>Every year, thousands of young graduates arrive on the job market in Senegal. Some find a job in an office, a bank or a school, but many work in the informal sector as traders, tailors or drivers. Others choose vocational training to become electricians, mechanics or welders.</p><p>Unemployment pushes some young people to emigrate, sometimes at the risk of their lives. Creating jobs at home is one of the biggest challenges for African countries.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'trade-professions-and-occupations'), 2, 'obligation-necessity-and-the-letter-of-application', 'Obligation, necessity and the letter of application', false, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'trade-professions-and-occupations') and slug = 'obligation-necessity-and-the-letter-of-application'), $html$<table><thead><tr><th scope="col">Function</th><th scope="col">Structure</th><th scope="col">Example</th></tr></thead><tbody><tr><td>obligation</td><td>must / have to</td><td>Workers must wear a helmet.</td></tr><tr><td>absence of obligation</td><td>don’t have to / needn’t</td><td>You don’t have to wear a uniform.</td></tr><tr><td>prohibition</td><td>mustn’t / be not allowed to</td><td>Children mustn’t work in mines.</td></tr><tr><td>past obligation</td><td>had to</td><td>He had to work at the age of ten.</td></tr></tbody></table>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')), 2, 'economy', 'Economy', 'Shopping, consumer society, poverty, development, agriculture and industry ; describing graphs.', 2, 'published', null, '[{"title":"Programmes de LV anglais, enseignement moyen et secondaire (CNA, 4e édition, 2017), Office du Bac","url":"https://officedubac.sn/wp-content/uploads/2026/01/Programme_Anglais_Tle.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
