insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'information-and-communication') and slug = 'the-media-and-the-information-explosion'), $html$<h2>Reading: Fake news</h2><p>With social networks, anyone can publish information. News travels faster than ever, but so do rumours and fake news. Before sharing a message, we should check its source and compare it with other reliable media.</p><p>Advertisements are everywhere too. They inform consumers but also try to make them buy things they do not need.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'information-and-communication'), 2, 'reported-speech', 'Reported speech', true, 'published', 15, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'information-and-communication') and slug = 'reported-speech'), $html$<table><thead><tr><th scope="col">Direct speech</th><th scope="col">Reported speech</th></tr></thead><tbody><tr><td>“I am tired,” she said.</td><td>She said (that) she was tired.</td></tr><tr><td>“We will come,” they said.</td><td>They said they would come.</td></tr><tr><td>“I saw him yesterday,” he said.</td><td>He said he had seen him the day before.</td></tr><tr><td>“Where do you live?” he asked.</td><td>He asked me where I lived.</td></tr><tr><td>“Are you ready?” she asked.</td><td>She asked if I was ready.</td></tr></tbody></table>
