insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = 'TLE' and p.series_id = (select id from public.series where code = 'T2')) and c.slug = 'exam-skills-reading-and-writing') and slug = 'writing-an-essay'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Read the subject carefully and underline the key words.</li><li>Brainstorm ideas and examples, then make a plan.</li><li><strong>Introduction</strong>: present the topic and announce your point of view or your plan.</li><li><strong>Body</strong>: one paragraph per idea, with an example; use linking words.</li><li><strong>Conclusion</strong>: sum up and give your opinion.</li><li>Check your grammar, spelling and the number of words required.</li></ol></div>
