insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q1', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E' and p.series_id is null) and c.slug = 'theoreme-de-thales'), 'single_choice', $html$<p>Dans un triangle ABC, M ∈ [AB], N ∈ [AC] et (MN) // (BC). Quelle égalité est vraie ?</p>$html$, $html$<p>Le théorème de Thalès compare les côtés du petit triangle AMN à ceux du grand triangle ABC, dans le même ordre : <span class="frac"><span>AM</span><span>AB</span></span> = <span class="frac"><span>AN</span><span>AC</span></span> = <span class="frac"><span>MN</span><span>BC</span></span>.</p>$html$, 3);
